(function (root) { root.WRG = root.WRG || {}; root.WRG.composeContent = {"frameworks":[{"id":"_defaults","letter":null,"name":"Shared defaults","text":{"acceptableWhy":"Dealing with <other> matters, but dealing with <first> has to come first.","redundantWhy":"<done|cap>, so that step is not needed and only delays dealing with <first>.","redundantClearWhy":"<done|cap>, so that step is not needed and only delays work that is ready to go ahead.","redundantMis":"Repeating a step that is already done is always the careful choice.","ignoreWhy":"Carrying on as if nothing were wrong leaves <short> unresolved.","proceedMis":"If the work can technically continue, it should continue.","orderMis":"Every real issue matters equally, so the order does not matter.","planReverseWhy":"Both steps are needed, but the order is backwards: dealing with <first> has to come before <other>.","planSecondWhy":"The first step is right, but the second step mishandles <short>."},"tiers":{"1":"Anything that could hurt someone comes before other work.","2":"Work cannot go ahead until it is allowed under the stated rules.","3":"Acting on missing or wrong information wastes everything that follows.","4":"The people affected need to hear about the problem before it grows.","5":"Improvements can wait until the immediate problems are handled."}},{"id":"critical-information","letter":"A","name":"Identify the critical information","engines":["state","defect"],"description":"The student decides which missing or unclear fact must be obtained before acting, and recognises when the fact is already in hand.","prompts":{"decision":["What is the most appropriate action?","What should you do?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan handles this situation best?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"competing-priorities","letter":"B","name":"Evaluate competing priorities","engines":["state","process"],"description":"Several demands compete; urgency, importance, dependencies and consequences decide which comes first.","prompts":{"decision":["What is the most appropriate action?","How should you handle this?"],"nextstep":["What should you do first?","What should you handle first?"],"plan":["Which plan handles these demands best?"],"order":["Put these tasks in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"safest-action","letter":"C","name":"Choose the safest appropriate action","engines":["state","process","defect"],"description":"The student separates safe responses from shortcuts that add risk, and recognises when a hazard is already controlled.","prompts":{"decision":["What is the safest appropriate action?","What should you do?"],"nextstep":["What should you do first?","What is the safest next step right now?"],"plan":["Which plan handles this situation safely?"],"order":["Put these steps in a safe order."],"find":["Which line is the safety problem?"]}},{"id":"conflicting-instructions","letter":"D","name":"Resolve conflicting instructions","engines":["state","defect"],"description":"Instructions disagree; the student works out which conflict matters and who is authorised to settle it.","prompts":{"decision":["What is the most appropriate action?","How should you handle these instructions?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan handles these instructions best?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"communication-failure","letter":"E","name":"Identify a communication failure","engines":["state","defect"],"description":"The student spots ambiguity, missing context, tone problems, incomplete handoffs or the wrong channel, and repairs them.","prompts":{"decision":["What is the most appropriate response?","What should you do?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan fixes the communication best?"],"order":["Put these steps in a sensible order."],"find":["Which line is the communication problem?"]}},{"id":"evidence-reliability","letter":"F","name":"Evaluate evidence and reliability","engines":["state","defect"],"description":"The student separates verified information from assumptions, outdated data and unreliable sources.","prompts":{"decision":["What is the most appropriate action?","What should you do with this information?"],"nextstep":["What should you do first?","What is the best next step before using this information?"],"plan":["Which plan uses the information most responsibly?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"process-dependency","letter":"G","name":"Identify a process dependency","engines":["process","state"],"description":"The student works out what must happen before another workplace action can proceed.","prompts":{"decision":["What is the most appropriate action?"],"nextstep":["What has to happen first?","What should you do first?"],"plan":["Which plan respects what each step depends on?"],"order":["Put these steps in an order that respects what each one depends on."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"numeric-decision","letter":"H","name":"Evaluate a numerical decision","engines":["numeric"],"description":"Calculations, rates, budgets, quantities and measurements decide the answer; the engine calculates it from the generated numbers.","prompts":{"decision":["Which choice is correct?","What is the best decision?"],"nextstep":["What should you do first?"],"find":["Which line contains the calculation error?"]}},{"id":"unexpected-change","letter":"I","name":"Respond to an unexpected change","engines":["state","process"],"description":"Resources, schedules, priorities or requirements change; the student adapts the plan and tells the right people.","prompts":{"decision":["What is the most appropriate response to the change?","What should you do?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan adapts to the change best?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"ethical-dilemma","letter":"J","name":"Evaluate an ethical dilemma","engines":["state","defect"],"description":"Honesty, confidentiality, fairness, professionalism and accountability pull against convenience or pressure.","prompts":{"decision":["What is the most appropriate action?","What should you do?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan handles this situation best?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"root-cause","letter":"K","name":"Identify a root cause","engines":["state","defect"],"description":"The student targets the underlying cause that the evidence points to rather than the visible symptom.","prompts":{"decision":["What is the most appropriate action?","What response gets at the real cause?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan deals with the real causes best?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}},{"id":"consequences","letter":"L","name":"Evaluate consequences","engines":["state","process"],"description":"Several plausible actions are compared by predicting which best meets the workplace objective under the stated conditions.","prompts":{"decision":["Which action best meets the goal?","What is the most appropriate action?"],"nextstep":["What should you do first?","What is the best next step right now?"],"plan":["Which plan leads to the best outcome?"],"order":["Put these steps in a sensible order."],"find":["Which line contains the problem?","Which line is the problem?"]}}],"slots":{"greenhouse-nursery":{"powered":"soil mixer","chemical":"fertilizer concentrate","ppe":"chemical-resistant gloves and goggles","private":"customer payment details","supply":{"text":"plant tray","plural":"plant trays"},"area":"potting area"},"dairy-farm":{"powered":"milk pump","chemical":"pipeline cleaner","ppe":"rubber gloves and goggles","private":"buyer contract prices","supply":{"text":"milk filter","plural":"milk filters"},"area":"milk room"},"repair-shop":{"powered":"bench grinder","chemical":"brake cleaner","ppe":"nitrile gloves and safety glasses","private":"customer payment details","supply":{"text":"oil filter","plural":"oil filters"},"area":"service bay"},"dealership-service":{"powered":"tire balancer","chemical":"parts-washer solvent","ppe":"nitrile gloves and safety glasses","private":"copies of customer driver's licenses","supply":{"text":"shop towel","plural":"shop towels"},"area":"service drive"},"community-bank":{"powered":"currency counter","chemical":"disinfectant spray","ppe":"disposable gloves","private":"customer account numbers","supply":{"text":"receipt paper roll","plural":"receipt paper rolls"},"area":"teller line"},"accounting-office":{"powered":"paper shredder","chemical":"disinfectant spray","ppe":"disposable gloves","private":"client tax files","supply":{"text":"toner cartridge","plural":"toner cartridges"},"area":"front office"},"framing-crew":{"powered":"circular saw","chemical":"construction adhesive","ppe":"work gloves and safety glasses","private":"homeowner's alarm code","supply":{"text":"box of nails","plural":"boxes of nails"},"area":"work site"},"remodel-company":{"powered":"miter saw","chemical":"wood stain","ppe":"chemical-resistant gloves and safety glasses","private":"customer's door code","supply":{"text":"box of screws","plural":"boxes of screws"},"area":"customer's kitchen"},"restaurant-kitchen":{"powered":"slicer","chemical":"oven cleaner","ppe":"rubber gloves and goggles","private":"staff phone list","supply":{"text":"food container","plural":"food containers"},"area":"prep station"},"catering-company":{"powered":"food processor","chemical":"degreaser","ppe":"rubber gloves and goggles","private":"client payment details","supply":{"text":"serving tray","plural":"serving trays"},"area":"loading area"},"elementary-school":{"powered":"laminator","chemical":"disinfectant spray","ppe":"disposable gloves","private":"student records","supply":{"text":"glue stick","plural":"glue sticks"},"area":"classroom"},"training-center":{"powered":"copier","chemical":"disinfectant spray","ppe":"disposable gloves","private":"learner records","supply":{"text":"binder","plural":"binders"},"area":"classroom"},"engineering-lab":{"powered":"drill press","chemical":"isopropyl alcohol","ppe":"nitrile gloves and safety glasses","private":"client test results","supply":{"text":"filament spool","plural":"filament spools"},"area":"test bench"},"design-firm":{"powered":"large-format plotter","chemical":"isopropyl alcohol","ppe":"nitrile gloves and safety glasses","private":"client project drawings","supply":{"text":"plotter paper roll","plural":"plotter paper rolls"},"area":"plotting room"},"outpatient-clinic":{"powered":"centrifuge","chemical":"surface disinfectant","ppe":"disposable gloves","private":"patient records","supply":{"text":"box of exam gloves","plural":"boxes of exam gloves"},"area":"exam room"},"dental-office":{"powered":"ultrasonic cleaner","chemical":"instrument disinfectant","ppe":"utility gloves and eye protection","private":"patient records","supply":{"text":"box of masks","plural":"boxes of masks"},"area":"treatment room"},"hotel":{"powered":"industrial vacuum","chemical":"bathroom cleaner","ppe":"rubber gloves","private":"guest room numbers","supply":{"text":"key card","plural":"key cards"},"area":"lobby"},"restaurant":{"powered":"commercial blender","chemical":"sanitizer concentrate","ppe":"rubber gloves and goggles","private":"guest credit card slips","supply":{"text":"to-go container","plural":"to-go containers"},"area":"dining room"},"help-desk":{"powered":"docking station","chemical":"contact cleaner","ppe":"nitrile gloves","private":"employee account details","supply":{"text":"network cable","plural":"network cables"},"area":"equipment room"},"school-district-it":{"powered":"charging cart","chemical":"screen cleaner concentrate","ppe":"nitrile gloves","private":"student account details","supply":{"text":"charging cable","plural":"charging cables"},"area":"storage room"},"assembly-plant":{"powered":"bench grinder","chemical":"thread-locking compound","ppe":"nitrile gloves and safety glasses","private":"production cost figures","supply":{"text":"box of fasteners","plural":"boxes of fasteners"},"area":"assembly line"},"packaging-facility":{"powered":"shrink-wrap machine","chemical":"adhesive cleaner","ppe":"nitrile gloves and safety glasses","private":"customer shipping lists","supply":{"text":"roll of shrink film","plural":"rolls of shrink film"},"area":"packing line"},"design-studio":{"powered":"color printer","chemical":"spray adhesive","ppe":"nitrile gloves","private":"unreleased client designs","supply":{"text":"poster board","plural":"poster boards"},"area":"print room"},"video-production":{"powered":"studio light","chemical":"contact cleaner","ppe":"nitrile gloves","private":"unreleased client footage","supply":{"text":"memory card","plural":"memory cards"},"area":"studio floor"},"grocery-store":{"powered":"cardboard baler","chemical":"floor cleaner concentrate","ppe":"rubber gloves and goggles","private":"special-order customer phone numbers","supply":{"text":"produce bag roll","plural":"produce bag rolls"},"area":"back stockroom"},"electronics-store":{"powered":"label printer","chemical":"adhesive remover","ppe":"nitrile gloves","private":"customer payment details","supply":{"text":"security tag","plural":"security tags"},"area":"sales floor"}},"kits":[{"id":"big-change-request","skill":"big-picture-thinking","family":"big-picture-thinking.cx-easy-change-wider-impact","familyName":"An easy change with wider effects","framework":"consequences","concepts":["big-picture-thinking:impacts-of-actions","big-picture-thinking:organization-structure","big-picture-thinking:role-in-mission"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. A {client} asks you to change how their {deliverable} is handled, and the change would be easy for you.","As {role|a} at {workplace|a}, you get a request from a {client} for a small change in how their {deliverable} is handled."],"pressure":["The {client} says other places do it this way without any fuss.","{coworker3} says to just do it and keep the {client} happy."],"detail":["The {client} has been coming here for years.","The request came in by phone."],"tiers":{"1":"A step that protects people outweighs convenience.","2":"The person the organization assigns to decide has to decide.","3":"The teams down the line need a say before their work changes.","4":"Flagging a possible precedent comes after the decision itself is in the right hands.","5":"Explaining the reason helps once the bigger questions are settled."},"issues":[{"id":"protects","tier":1,"rule":"protect-requirements","principle":"big.keep-protective-step","fact":["The change would skip a step that exists to protect {client.plural}."],"short":"the protective step","action":"Explain that the step protects {client.plural}, and offer an option that keeps it.","brief":"keep the protective step and offer an option","reason":"The step exists for everyone's protection. Offering an alternative meets the {client}'s need without removing it.","lesson":"Weigh a request against the purpose of the steps it would change.","shortcut":[{"text":"Skip the step just for this {client}, since it is only one order.","brief":"skip it for this one order","why":"The protection matters on every order. One exception can be the one that goes wrong.","mis":"A single exception has no wider effect."}]},{"id":"authority","tier":2,"rule":"route-to-decision-maker","principle":"big.route-to-assigned-decider","fact":["The posted chart of responsibilities says {lead|the} decides changes like this."],"clear":["{Lead|the} already approved changes like this one last week."],"done":"changes like this were already approved","short":"who decides this change","action":"Pass the request to {lead|the}, who decides changes like this.","brief":"pass it to {lead|the} to decide","reason":"Knowing who decides what is part of understanding how the organization works. It keeps decisions consistent.","lesson":"Know who is responsible for which decisions, and route requests to them.","shortcut":[{"text":"Make the change yourself, since you are the one the {client} asked.","brief":"make the change yourself","why":"Being asked does not give you authority. The chart says the lead decides.","mis":"Whoever gets a request can decide it."}]},{"id":"downstream","tier":3,"rule":"consult-affected-people","principle":"big.check-downstream-team","fact":["The change would add work for the team that handles the next step."],"clear":["The next team already said the change works for them."],"done":"the next team already agreed","short":"the extra work for the next team","action":"Check with the next team about the extra work before agreeing.","brief":"check with the next team","reason":"A change that is easy for you may be hard for the team after you. Checking first avoids surprising them.","lesson":"Think about how your actions affect the people who work after you.","shortcut":[{"text":"Agree to the change, since it does not make your own job harder.","brief":"agree since it is easy for you","why":"Judging a change only by your own work ignores its effect on the next team.","mis":"If it is easy for you, it is easy for everyone."}]},{"id":"precedent","tier":4,"rule":"flag-wider-impact","principle":"big.flag-precedent","fact":["If the change is made, other {client.plural} are likely to ask for the same thing."],"short":"the precedent the change would set","action":"Tell {lead|the} that making this change may lead others to expect it too.","brief":"flag the precedent to {lead|the}","reason":"Decisions often repeat. Flagging the wider effect helps the lead decide with the full picture.","lesson":"Consider whether a one-time decision will become an expectation.","shortcut":[{"text":"Ignore that, since you can deal with other requests when they come.","brief":"deal with other requests later","why":"Once a change is made for one {client}, refusing others becomes harder.","mis":"Each decision stands alone."}],"clear":["{Lead|the} already knows other {client.plural} may ask for the same change."],"done":"the lead already knows about the precedent"}],"proceed":{"text":"Make the change for the {client} and note it in {record|the}.","why":"The change is approved, others are on board and nothing is put at risk, so making and recording it is right.","lesson":"When a change is approved and its effects are understood, carry it out and record it."},"generic":[{"text":"Tell the {client} no without explaining why.","why":"A flat refusal with no explanation leaves the {client} confused and unhappy.","mis":"Saying no firmly is enough."},{"text":"Promise the {client} the change before checking anything.","why":"Promising first may commit the workplace to something it cannot or should not do.","mis":"A promise can always be undone later."}],"overcaution":[{"text":"Ask every department to review the change before you do anything.","why":"The change is already approved and agreed. A full review is unnecessary.","mis":"More reviews always make a decision better."}],"process":{"setup":["A {client} at {workplace|the} has asked for a change in how their {deliverable} is handled."],"because":{"authority":["The chart of responsibilities assigns this kind of decision to {lead|the}."],"downstream":["Another team handles the step after yours."]},"steps":[{"id":"understand","text":"Find out exactly what the {client} wants changed","core":true},{"id":"next","text":"Ask the next team how it affects them","issue":"downstream"},{"id":"decide","text":"Bring the request to {lead|the} for a decision","issue":"authority"},{"id":"tell","text":"Tell the {client} the outcome","core":true},{"id":"record","text":"Record the change","core":true}],"rel":[["understand","next","You need the details before asking about the effect."],["understand","decide","The lead needs the details to decide."],["next","decide","The decision should include the next team's view."],["decide","tell","The {client} hears the outcome after the decision."],["understand","tell","You respond after understanding the request."],["tell","record","You record what was agreed."]],"alternatesReviewed":true,"lesson":"Understand the request, gather the affected views, let the right person decide, then follow through."},"doc":{"type":"email","title":["Your reply to the {client}"],"intro":["You are about to reply to the {client}'s request. Check the message first."],"lesson":"Big-picture replies explain decisions in terms of their purpose and route them to the right people.","lines":[{"id":"thanks","text":"Thank you for your request about how your {deliverable} is handled.","fine":"Acknowledges the request."},{"id":"why","text":"The extra check you asked us to skip is there to protect every {client}.","fine":"Explains the purpose of the step."},{"id":"offer","text":"We can instead have your order ready an hour earlier.","fine":"Offers an alternative that keeps the check.","bad":[{"id":"offer-skip","level":"advanced","needs":["why"],"text":"So we will skip that check for your orders from now on.","why":"The same message says the check protects every {client}. Dropping it contradicts that reason.","principle":"big.doc-contradicts-stated-purpose"}]},{"id":"who","text":"I have passed your request to {lead|the}, who makes these decisions.","fine":"Routes the decision to the right person.","bad":[{"id":"who-self","level":"intermediate","text":"I have decided to change our process for everyone starting today.","why":"Changing the process for everyone is not an individual's decision; it belongs to the person responsible.","principle":"big.doc-overstepped-authority"}]},{"id":"time","text":"You will hear back by Friday.","fine":"Sets a clear expectation.","bad":[{"id":"time-never","level":"beginner","text":"We will get back to you whenever someone has time.","why":"A vague promise leaves the {client} unsure when to expect an answer.","principle":"big.doc-vague-timeline"}]},{"id":"close","text":"Thank you for your patience.","fine":"A courteous close.","bad":[{"id":"close-rude","level":"beginner","text":"Please stop asking for special treatment.","why":"This is rude and damages the relationship with the {client}.","principle":"big.doc-rude-close"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Organization structure stated via a posted chart of responsibilities."}},{"id":"big-closing-impacts","skill":"big-picture-thinking","family":"big-picture-thinking.cx-closing-impacts","familyName":"Small closing habits with wider effects","framework":"consequences","concepts":["big-picture-thinking:impacts-of-actions","big-picture-thinking:community-and-industry"],"contexts":"any","requires":["supply","powered"],"setup":["You work as {role|a} at {workplace|a}, and you are the last one closing up tonight.","As {role|a} at {workplace|a}, you are finishing the closing routine on your own."],"detail":["It has been a long day.","Everyone else left about ten minutes ago."],"issues":[{"id":"trash","tier":1,"rule":"honor-community-commitment","principle":"big.keep-promise-to-neighbors","onlyLevels":["beginner"],"fact":["Trash bags by the back door are spilling onto the sidewalk, and {workplace|the} promised neighbors to keep trash in closed bins."],"short":"the trash on the sidewalk","action":"Put the trash in the closed bins, keeping the promise made to the neighbors.","reason":"The workplace's reputation in the neighborhood depends on keeping its promises. A few minutes now protects that relationship.","lesson":"Your everyday actions shape how the community sees your workplace.","shortcut":[{"text":"Leave the bags for the morning crew, since it is late.","why":"Overnight, the trash stays on the sidewalk and breaks the promise to neighbors.","mis":"Small messes outside do not affect the business."}]},{"id":"power","tier":2,"rule":"reduce-waste","principle":"big.shut-down-unneeded-equipment","onlyLevels":["beginner"],"fact":["{Powered|the} is still running in an empty room, and the closing list says it should be off overnight."],"short":"the equipment left running","action":"Switch off {powered|the} using the normal shutdown steps.","reason":"Leaving equipment on wastes energy and money and adds wear. The closing list exists because those costs add up.","lesson":"Small wastes repeated every night become big costs for the organization.","shortcut":[{"text":"Leave it on, since one night of power costs almost nothing.","why":"Habits repeat. One night becomes every night, and the cost adds up.","mis":"Small costs do not matter to a business."}]},{"id":"materials","tier":3,"rule":"reduce-waste","principle":"big.rescue-usable-materials","onlyLevels":["beginner"],"fact":["A sealed box of unused {supply.plural} has been thrown in the trash."],"short":"the sealed box in the trash","action":"Take the sealed box out of the trash and return it to the supply shelf.","reason":"Unused supplies cost money to replace. Returning them protects the budget everyone depends on.","lesson":"Treat the organization's resources as if your own budget depended on them.","shortcut":[{"text":"Leave it, since someone must have had a reason to throw it out.","why":"A sealed, unused box has value. If there is a reason, it can be checked tomorrow.","mis":"Whatever is in the trash must be waste."}]},{"id":"pattern","tier":4,"rule":"flag-wider-impact","principle":"big.report-repeating-closing-gap","onlyLevels":["beginner"],"fact":["This is the third night this week the closing list has been left half done."],"short":"the repeated half-done closing","action":"Finish the list, then let {lead|the} know it keeps happening so the routine can be fixed.","reason":"Fixing tonight's gaps helps once. Telling the lead about the pattern helps fix the routine for every night.","lesson":"Look beyond the single incident to the pattern behind it.","shortcut":[{"text":"Finish the list again and say nothing, since it is easier.","why":"Quietly covering a repeated gap leaves the cause in place.","mis":"Covering a problem is the same as solving it."}]}],"proceed":{"text":"Lock up and head home, since tonight's closing is someone else's job.","why":"Closing is your responsibility tonight, so leaving things undone is not an option.","lesson":"Every closing task protects something bigger than the task itself."},"generic":[{"text":"Write a note about it and leave everything as it is.","why":"A note does not fix a problem you can handle in minutes.","mis":"Writing a note is the same as handling it."},{"text":"Text {coworker} to come back and handle it.","why":"You are the one closing. Calling someone back is not necessary for a task you can do.","mis":"Closing problems belong to whoever caused them."}],"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Beginner-only issues; the promise to neighbors and the closing list are stated in the scenario."}},{"id":"big-supplier-switch","skill":"big-picture-thinking","family":"big-picture-thinking.cx-supplier-switch","familyName":"Weighing a cheaper supplier","framework":"consequences","concepts":["big-picture-thinking:impacts-of-actions","big-picture-thinking:community-and-industry","big-picture-thinking:organization-structure"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to look into switching to a cheaper supplier for {supply.plural}.","As {role|a} at {workplace|a}, you are comparing the current supplier of {supply.plural} with a cheaper one for {lead|the}."],"pressure":["{coworker3} says cheaper is always better and to just switch.","{Lead|the} wants a recommendation this week."],"detail":["The cheaper supplier sent free samples.","The current supplier has been used for years."],"tiers":{"1":"A safety concern stops the change until it is resolved.","2":"Commitments the workplace already made have to be checked before changing.","3":"The people whose work changes need a say.","4":"A fair comparison needs the full cost.","5":"Wider effects belong in the summary once the facts are in."},"issues":[{"id":"safety","tier":1,"rule":"protect-safety","principle":"big.flag-safety-concern","fact":["The cheaper {supply.plural} failed a safety test at another workplace."],"short":"the failed safety test","action":"Report the failed safety test to {lead|the} before the switch goes further.","brief":"report the failed safety test","reason":"A cheaper product that may be unsafe could cost far more than it saves.","lesson":"Weigh safety before savings.","shortcut":[{"text":"Switch anyway, since the test was at a different workplace.","brief":"switch suppliers anyway","why":"A failed test elsewhere is a warning the lead needs to hear.","mis":"Problems elsewhere do not apply here."}]},{"id":"contract","tier":2,"rule":"check-commitments","principle":"big.check-existing-agreement","fact":["The agreement with the current supplier, kept by {lead|the}, may require notice before switching."],"short":"the possible notice requirement","action":"Ask {lead|the} to check the agreement before anything changes.","brief":"have {lead|the} check the agreement","reason":"Breaking an agreement can cost money and trust. The lead holds the agreement.","lesson":"Check existing commitments before changing course.","shortcut":[{"text":"Assume the agreement does not matter, since the switch saves money.","brief":"ignore the agreement","why":"Savings do not cancel a commitment the workplace made.","mis":"Agreements do not matter if money is saved."}],"clear":["{Lead|the} checked, and the agreement allows switching at any time."],"done":"the agreement was already checked"},{"id":"nextteam","tier":3,"rule":"consult-affected-people","principle":"big.consult-team-using-supply","fact":["The cheaper version would mean the next team changes how they work."],"short":"the effect on the next team","action":"Ask the next team how the change would affect their work.","brief":"ask the next team about the effect","reason":"Savings in one place can create costs in another. The next team knows their side.","lesson":"Look at how a change affects the whole operation.","shortcut":[{"text":"Leave them out, since purchasing is not their job.","brief":"leave the next team out","why":"They will live with the change; leaving them out risks hidden costs.","mis":"Only the buyer's view matters."}],"clear":["The next team tested the samples and said they work fine."],"done":"the next team already tested the samples"},{"id":"shipping","tier":4,"rule":"full-cost","principle":"big.compare-total-cost","fact":["The cheaper price does not include shipping, which the current supplier covers."],"short":"the missing shipping cost","action":"Compare the total cost with shipping included, not just the price.","brief":"compare totals with shipping","reason":"A lower price can become a higher total once all costs are counted.","lesson":"Compare total costs, not sticker prices.","shortcut":[{"text":"Compare the prices only, since shipping is a small extra.","brief":"compare prices only","why":"Shipping can erase the savings.","mis":"Extra costs are too small to matter."}],"clear":["You already compared both options with shipping included."],"done":"the full costs were already compared"},{"id":"local","tier":5,"rule":"weigh-community","principle":"big.consider-local-relationship","fact":["The current supplier is a local business that many {client.plural} know."],"short":"the local relationship","action":"Mention the local relationship in your summary for {lead|the}.","brief":"mention the local relationship","reason":"Community relationships affect reputation. The lead should weigh them with the numbers.","lesson":"Consider how decisions affect the community.","shortcut":[{"text":"Leave it out, since only the price matters.","brief":"leave it out","why":"Leaving out a real factor gives the lead an incomplete picture.","mis":"Business decisions are only about price."}],"noProceed":true}],"proceed":{"text":"Recommend the option that comes out best, with your comparison, to {lead|the}.","why":"The facts are in and nothing blocks a decision, so a clear recommendation is the next step.","lesson":"Recommend a change once its effects across the organization are understood."},"generic":[{"text":"Switch suppliers yourself today to save time.","why":"The lead asked for a recommendation, not a decision.","mis":"Being asked to look into something means you decide."},{"text":"Tell {lead|the} the current supplier is fine without looking further.","why":"Skipping the comparison leaves the lead without the information requested.","mis":"Keeping things the same never needs a reason."}],"overcaution":[{"text":"Ask for three more months to study the options.","why":"The facts are already in; more delay adds no value.","mis":"More study always improves a decision."}],"process":{"setup":["{Lead|the} at {workplace|the} asked you to compare a cheaper supplier of {supply.plural} with the current one."],"because":{"contract":["The current supplier agreement may have conditions."],"nextteam":["Another team uses these supplies after you."],"shipping":["The two suppliers handle shipping differently."]},"steps":[{"id":"agree","text":"Have {lead|the} check the current agreement","issue":"contract"},{"id":"team","text":"Ask the next team to test samples","issue":"nextteam"},{"id":"costs","text":"Add up the total cost of each option","issue":"shipping"},{"id":"compare","text":"Compare the options side by side","core":true},{"id":"recommend","text":"Send {lead|the} a recommendation","core":true}],"rel":[["agree","recommend","The recommendation depends on whether switching is allowed."],["team","compare","The comparison needs the next team's results."],["costs","compare","The comparison uses total costs."],["compare","recommend","Recommend after comparing."]],"alternatesReviewed":true,"lesson":"Check commitments, gather affected views and full costs, compare, then recommend."},"doc":{"type":"note","title":["Supplier comparison for {lead|the}"],"intro":["Check your supplier comparison before sending it."],"lesson":"A big-picture recommendation counts safety, commitments, other teams, full cost and community effects.","lines":[{"id":"price","text":"Price: the new supplier is 12 percent cheaper per item.","fine":"A fact for comparison."},{"id":"ship","text":"Shipping: the new supplier adds a fee; the total saving is 4 percent.","fine":"Counts the full cost.","bad":[{"id":"ship-ignore","level":"beginner","text":"Shipping: not considered.","why":"Leaving out shipping can hide costs that erase the savings.","principle":"big.doc-ignores-full-cost"}]},{"id":"team","text":"The next team tested samples and found no problems.","fine":"Includes the affected team's view.","bad":[{"id":"team-skip","level":"intermediate","text":"The next team was not asked, since it is not their decision.","why":"The team that uses the supplies should be consulted.","principle":"big.doc-skips-affected-team"}]},{"id":"agree","text":"The current agreement allows switching with 30 days' notice.","fine":"Checks the existing commitment."},{"id":"local","text":"The current supplier is a long-time local business.","fine":"Notes a community factor."},{"id":"rec","text":"Recommendation: switch after giving 30 days' notice.","fine":"Consistent with the facts above.","bad":[{"id":"rec-now","level":"advanced","needs":["agree"],"text":"Recommendation: switch starting tomorrow.","why":"The agreement requires 30 days' notice, so switching tomorrow breaks it.","principle":"big.doc-recommendation-breaks-agreement"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Agreement terms are stated as facts in the scenario; no legal claims."}},{"id":"car-next-step","skill":"career-and-life-management","family":"career-and-life-management.cx-planning-next-career-step","familyName":"Planning the next career step","framework":"process-dependency","concepts":["career-and-life-management:qualifications-and-advancement","career-and-life-management:smart-goals","career-and-life-management:benefits-and-resources","career-and-life-management:wellness-and-finances"],"contexts":"any","setup":["You work as {role|a} at {workplace|a} and want to move up to a higher-level job within a year.","As {role|a} at {workplace|a}, you have decided you want a promotion in the next year."],"pressure":["{coworker3} says promotions mostly come down to luck.","A friend says you should just apply everywhere and see what happens."],"detail":["You have worked here for about a year.","Your current job is going well."],"tiers":{"1":"Your health has to be sustainable before you add new goals.","2":"Knowing what your supervisor thinks you need shapes every other step.","3":"A clear, measurable goal turns a wish into a plan.","4":"A required qualification has to be planned for early.","5":"Using available benefits makes the plan easier once it is set."},"issues":[{"id":"burnout","tier":1,"rule":"protect-wellness","principle":"car.sustainable-schedule-first","fact":["You have worked extra shifts for six weeks straight and feel exhausted most days."],"short":"your exhaustion","action":"Talk with {lead|the} about a more sustainable schedule before taking on new goals.","brief":"ask {lead|the} about a sustainable schedule","reason":"Exhaustion makes every other goal harder and can harm your health. A sustainable schedule comes first.","lesson":"Take care of your wellness so your career goals are sustainable.","shortcut":[{"text":"Add evening classes on top of the extra shifts to move up faster.","brief":"add evening classes on top","why":"Piling more onto an exhausting schedule risks your health and your performance.","mis":"Working harder always speeds up a career."}]},{"id":"feedback","tier":2,"rule":"seek-feedback","principle":"car.ask-what-to-develop","fact":["You do not know what {lead|the} thinks you would need to improve to be promoted."],"clear":["{Lead|the} told you last week that leading a small project is your next step."],"done":"{lead|the} already told you what to work on","short":"not knowing what to improve","action":"Ask {lead|the} for specific feedback on what you would need to develop.","brief":"ask {lead|the} what to develop","reason":"Your supervisor knows what the next job requires. Their feedback points your effort where it counts.","lesson":"Ask for specific feedback about what advancement requires.","shortcut":[{"text":"Guess what matters and start working on that.","brief":"guess what matters","why":"Guessing may spend months on the wrong skills.","mis":"You already know what your supervisor values."}]},{"id":"vague","tier":3,"rule":"set-smart-goal","principle":"car.make-goal-smart","fact":["Your written goal says only \"get better at my job.\""],"clear":["You already wrote a goal with a specific measure and a date."],"done":"your goal is already specific, measurable and dated","short":"the vague goal","action":"Rewrite the goal so it is specific, measurable, realistic and has a deadline.","brief":"rewrite the goal as a SMART goal","reason":"A vague goal gives you nothing to plan or measure. A SMART goal shows what to do and when you have succeeded.","lesson":"Write goals that are specific, measurable, achievable, relevant and time-bound.","shortcut":[{"text":"Keep the goal broad so you cannot fail it.","brief":"keep the goal broad","why":"A goal you cannot fail is also a goal you cannot measure or plan for.","mis":"Broad goals are safer than specific ones."}]},{"id":"cert","tier":4,"rule":"plan-for-qualification","principle":"car.plan-required-certification","fact":["The posting for the higher-level job lists a certification you do not have yet."],"short":"the missing certification","action":"Find out what the certification takes and add it to your plan with dates.","brief":"plan for the certification with dates","reason":"Required qualifications can take months. Planning early means you can be ready when a position opens.","lesson":"Learn what qualifications advancement requires and plan to earn them.","shortcut":[{"text":"Apply anyway and hope the certification is not checked.","brief":"apply and hope it is not checked","why":"Listed requirements are usually checked. Applying without a plan wastes the opportunity.","mis":"Requirements in job postings are only suggestions."}],"clear":["You already enrolled in the certification course that starts next month."],"done":"you are already enrolled in the course"},{"id":"benefit","tier":5,"rule":"use-available-resources","principle":"car.use-course-benefit","fact":["The employee handbook says the company pays for job-related courses, but you have not looked into it."],"clear":["You already confirmed the company will pay for your course."],"done":"the course benefit was already confirmed","short":"the unused course benefit","action":"Read that handbook section and ask {lead|the} how to apply for the benefit.","brief":"check the course benefit","reason":"A benefit you do not use is money left on the table. It may cover a course you need.","lesson":"Know the benefits and resources your employer offers, and use them.","shortcut":[{"text":"Pay for courses yourself, since asking about benefits seems pushy.","brief":"pay for it yourself","why":"Benefits are part of your pay. Asking about them is normal and professional.","mis":"Using benefits makes you look demanding."}]}],"proceed":{"text":"Follow your written plan and check your progress each month.","why":"Your plan is clear, supported and sustainable, so steady progress and regular check-ins are next.","lesson":"With a clear plan in place, act on it and track your progress."},"generic":[{"text":"Quit and look for a higher-level job somewhere else right away.","why":"Leaving without a plan or the needed qualifications does not solve the gap.","mis":"Moving up means moving out."},{"text":"Wait for {lead|the} to offer you a promotion.","why":"Advancement usually takes planning and asking. Waiting leaves your career to chance.","mis":"Good work is always noticed and rewarded without asking."}],"overcaution":[{"text":"Put the plan on hold until you feel completely ready.","why":"The plan is ready now. Waiting for a perfect moment delays progress.","mis":"You should feel completely ready before starting."}],"process":{"setup":["You are {role|a} at {workplace|a}, planning how to earn a promotion within a year."],"because":{"feedback":["You have not asked {lead|the} what you would need to improve."],"cert":["The higher-level job lists a certification you have not earned."],"benefit":["The handbook mentions a course benefit you have not checked."]},"steps":[{"id":"ask","text":"Get feedback from {lead|the}","issue":"feedback"},{"id":"goal","text":"Write a SMART goal","core":true},{"id":"benefit","text":"Check the course benefit","issue":"benefit"},{"id":"enroll","text":"Enroll in the certification course","issue":"cert"},{"id":"act","text":"Work on the plan each week","core":true},{"id":"review","text":"Review progress with {lead|the}","core":true}],"rel":[["ask","goal","Feedback tells you what the goal should target."],["goal","act","You act on the plan once the goal is set."],["goal","enroll","The certification fits into the goal's plan."],["benefit","enroll","Check whether the course is paid for before enrolling."],["enroll","act","The course is part of the weekly work."],["act","review","You review progress after working on the plan."]],"alternatesReviewed":true,"lesson":"Get feedback, set a SMART goal, line up resources, act, and review."},"doc":{"type":"note","title":["Your one-year career plan"],"intro":["You are reviewing your draft career plan before sharing it with {lead|the}."],"lesson":"A strong career plan has a measurable goal, realistic steps and dates, and uses available support.","lines":[{"id":"goal","text":"Goal: be ready to apply for the higher-level job by next September.","fine":"Specific and time-bound."},{"id":"measure","text":"Measure: complete the required certification and lead one project.","fine":"Measurable targets tied to the job requirements.","bad":[{"id":"measure-vague","level":"beginner","text":"Measure: feel more confident at work.","why":"A feeling cannot be measured. The plan needs concrete targets.","principle":"car.doc-unmeasurable-goal"}]},{"id":"course","text":"Step 1: enroll in the certification course in January.","fine":"A dated step.","bad":[{"id":"course-someday","level":"beginner","text":"Step 1: enroll in a course someday.","why":"\"Someday\" is not a step anyone can plan around; the plan needs a date.","principle":"car.doc-undated-step"}]},{"id":"pay","text":"Cost: covered by the company course benefit, confirmed with {lead|the}.","fine":"Uses an available benefit."},{"id":"time","text":"Time: about three hours a week, which fits my current schedule.","fine":"A realistic time commitment.","bad":[{"id":"time-impossible","level":"advanced","needs":["goal"],"text":"Time: finish the whole certification this weekend.","why":"A certification that takes months cannot be finished in a weekend. The plan needs realistic steps.","principle":"car.doc-unrealistic-timeline"}]},{"id":"check","text":"Check-in: review progress with {lead|the} every two months.","fine":"Regular review keeps the plan on track.","bad":[{"id":"check-none","level":"intermediate","text":"Check-in: none needed until I apply.","why":"Without check-ins, problems are not caught until it is too late.","principle":"car.doc-no-progress-check"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Course benefit stated as a handbook policy. No claims about laws or specific benefit rules."}},{"id":"car-paycheck","skill":"career-and-life-management","family":"career-and-life-management.cx-paycheck-and-wellness","familyName":"Managing pay, benefits and wellness","framework":"competing-priorities","concepts":["career-and-life-management:wellness-and-finances","career-and-life-management:benefits-and-resources"],"contexts":"any","setup":["You work as {role|a} at {workplace|a} and just got your second paycheck.","As {role|a} at {workplace|a}, you are sorting out your pay and benefits after your first month."],"pressure":["A friend says budgeting is only for people with big paychecks.","{coworker3} says benefits paperwork can wait."],"detail":["You get paid every two weeks.","You started this job a month ago."],"tiers":{"1":"A benefit deadline that is about to pass comes first.","2":"Understand your pay before you plan with it.","3":"A budget turns a paycheck into a plan.","4":"A costly credit decision deserves careful thought before smaller daily habits.","5":"Daily wellness habits matter once the urgent money questions are handled."},"issues":[{"id":"enroll","tier":1,"rule":"meet-benefit-deadline","principle":"car.enroll-before-deadline","fact":["Enrollment for the workplace health plan closes Friday, and you have not chosen yet."],"short":"the enrollment deadline","action":"Review the plan options and enroll before Friday's deadline.","brief":"enroll before Friday","reason":"Missing the enrollment deadline can mean waiting months for coverage.","lesson":"Know your benefit deadlines and act before they pass.","shortcut":[{"text":"Wait until you get sick to decide about the plan.","brief":"wait until you need it","why":"Coverage usually has to be chosen before you need it.","mis":"Benefits can be picked up anytime."}],"clear":["You already enrolled in the health plan last week."],"done":"you are already enrolled"},{"id":"stub","tier":2,"rule":"understand-pay","principle":"car.read-pay-stub","fact":["Your paycheck is lower than you expected, and you have not read the deductions."],"short":"the unexplained smaller paycheck","action":"Read the deductions on your pay stub and ask payroll about anything unclear.","brief":"read the deductions and ask payroll","reason":"Deductions such as taxes and benefits explain the difference. Understanding them prevents surprises.","lesson":"Read your pay stub and understand each deduction.","shortcut":[{"text":"Assume payroll made a mistake and complain to {lead|the}.","brief":"assume it is a mistake","why":"Most differences come from normal deductions; read the stub first.","mis":"A smaller check always means an error."}],"clear":["Payroll already explained each deduction on your stub."],"done":"the deductions were already explained"},{"id":"budget","tier":3,"rule":"plan-finances","principle":"car.write-simple-budget","fact":["You have no plan for how your pay covers rent, food and savings."],"short":"the missing budget","action":"Write a simple monthly budget for needs, savings and wants.","brief":"write a simple budget","reason":"A budget shows whether your pay covers your needs and helps you save on purpose.","lesson":"Plan how your pay will be spent and saved.","shortcut":[{"text":"Spend as you go and see what is left at the end of the month.","brief":"spend as you go","why":"Without a plan, savings and bills can come up short.","mis":"Budgets are only needed when money runs out."}],"clear":["You already wrote a simple monthly budget."],"done":"you already have a budget"},{"id":"card","tier":4,"rule":"avoid-high-cost-credit","principle":"car.weigh-high-interest-card","fact":["A store offers a credit card with high interest in exchange for 10 percent off today."],"short":"the high-interest card offer","action":"Skip the card unless you are sure you can pay the full balance each month.","brief":"skip the card unless you pay in full","reason":"High interest can quickly cost more than the one-time discount saves.","lesson":"Compare the long-term cost of credit with the short-term savings.","shortcut":[{"text":"Sign up, since 10 percent off is free money.","brief":"sign up for the discount","why":"The discount is one-time; interest on any unpaid balance keeps adding up.","mis":"Store discounts make credit cards free."}]},{"id":"breaks","tier":5,"rule":"protect-wellness","principle":"car.take-scheduled-breaks","fact":["You have been skipping breaks to finish work faster."],"short":"the skipped breaks","action":"Take your scheduled breaks so you stay healthy and focused.","brief":"take your scheduled breaks","reason":"Breaks help you stay healthy and focused, which supports good work over time.","lesson":"Build habits that keep you healthy at work.","shortcut":[{"text":"Keep skipping breaks, since it shows dedication.","brief":"keep skipping breaks","why":"Skipping breaks wears you down and can lower your work quality.","mis":"Skipping breaks impresses supervisors."}],"noProceed":true}],"proceed":{"text":"Stick with the budget and benefit choices you have made.","why":"Your benefits, pay and budget are in order, so following your plan is next.","lesson":"Once your plan is set, follow it and review it now and then."},"generic":[{"text":"Borrow money from coworkers until the next paycheck.","why":"Borrowing from coworkers strains relationships and does not fix the plan.","mis":"Coworkers are a good source of loans."},{"text":"Ignore the paperwork until someone reminds you.","why":"Deadlines and deductions do not wait for reminders.","mis":"Someone will always remind you."}],"overcaution":[{"text":"Ask payroll to explain your stub again every pay period.","why":"The deductions were already explained; repeating the question wastes time.","mis":"You can never ask about pay too often."}],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Enrollment deadline stated in the scenario. General personal-finance guidance, no tax or legal claims."}},{"id":"con-shared-task-dispute","skill":"conflict-resolution","family":"conflict-resolution.cx-shared-task-dispute","familyName":"A disagreement over a shared task","framework":"communication-failure","concepts":["conflict-resolution:diplomatic-negotiation","conflict-resolution:work-style-differences","conflict-resolution:when-to-escalate"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You and {coworker} share responsibility for {task|the}, and you disagree about how to do it.","As {role|a} at {workplace|a}, you and {coworker} keep clashing over how to handle {task|the}."],"pressure":["{coworker3} says you should just stand your ground.","{Lead|the} expects {task|the} to be finished today."],"detail":["You have worked with {coworker} for about six months.","The disagreement started this morning."],"tiers":{"1":"When a conflict turns aggressive, safety and a supervisor come first.","2":"A conflict in front of others should move somewhere private first.","3":"You cannot resolve a disagreement you do not yet understand.","4":"A fair compromise comes once both sides are understood."},"issues":[{"id":"aggressive","tier":1,"rule":"escalate-aggression","principle":"con.step-away-and-escalate","fact":["{coworker} starts shouting and slams a tool down on the counter next to you."],"short":"{coworker}'s aggressive behavior","action":"Step away calmly and get {lead|the} involved right away.","brief":"step away and bring in {lead|the}","reason":"Aggressive behavior is beyond what coworkers should handle alone. Stepping away keeps you safe, and the lead can deal with the behavior.","lesson":"When a conflict becomes aggressive, step back and involve a supervisor.","shortcut":[{"text":"Raise your voice too, so {coworker} knows you will not be pushed around.","brief":"raise your voice back","why":"Matching aggression makes the situation more dangerous and harder to resolve.","mis":"Standing up for yourself means matching the other person's anger."}]},{"id":"public","tier":2,"rule":"move-conflict-private","principle":"con.take-dispute-private","fact":["The argument is happening in front of several {client.plural}."],"short":"arguing in front of {client.plural}","action":"Suggest that the two of you talk it over somewhere private.","brief":"suggest moving somewhere private","reason":"Arguing in front of {client.plural} embarrasses everyone and hurts the workplace's reputation. A private space makes calm discussion easier.","lesson":"Move disagreements out of public view before trying to settle them.","shortcut":[{"text":"Finish the argument quickly right there so it is settled.","brief":"settle it right there","why":"Continuing in front of {client.plural} is unprofessional and makes a calm resolution less likely.","mis":"Settling a dispute fast matters more than where it happens."}],"clear":["You and {coworker} have already stepped into the break room to talk."],"done":"you have already moved somewhere private"},{"id":"unclear","tier":3,"rule":"seek-to-understand","principle":"con.understand-the-objection","fact":["You are not actually sure what {coworker} objects to."],"clear":["{coworker} explained the concern clearly: your method slows down their part of the job."],"done":"{coworker} already explained the concern","short":"not knowing what {coworker} objects to","action":"Ask {coworker} to explain the concern, and listen without interrupting.","brief":"ask {coworker} to explain, and listen","reason":"Many disagreements shrink once each side understands the other. Listening first also lowers the tension.","lesson":"Understand the other person's concern before trying to resolve a disagreement.","shortcut":[{"text":"Explain again why your way is better until {coworker} agrees.","brief":"repeat why your way is better","why":"Repeating your own view does not address {coworker}'s concern, which you still do not know.","mis":"Conflicts end when the other person is convinced."}]},{"id":"style","tier":4,"rule":"blend-work-styles","principle":"con.compromise-on-work-style","noProceed":true,"fact":["{coworker} likes to plan every detail first, while you prefer to start quickly and adjust."],"short":"your different work styles","action":"Suggest a short planning step first, then starting the work and adjusting as you go.","brief":"suggest a short plan, then start and adjust","reason":"Both styles have strengths. A plan that uses some of each respects both of you and gets the task moving.","lesson":"Treat work-style differences as something to combine, not a contest to win.","shortcut":[{"text":"Insist on doing it your way, since starting fast gets more done.","brief":"insist on your way","why":"Dismissing a coworker's style ignores its strengths and keeps the conflict going.","mis":"Your own work style is the right one."}]},{"id":"repeat","tier":4,"rule":"escalate-recurring-conflict","principle":"con.involve-lead-in-recurring-dispute","fact":["This is the third time this month that the same disagreement has come up."],"short":"the recurring disagreement","action":"Suggest asking {lead|the} to help set a clear process for {task|the}.","brief":"ask {lead|the} to help set a process","reason":"A disagreement that keeps returning needs a lasting fix. The lead can set a process both of you follow.","lesson":"When the same conflict keeps coming back, involve someone who can set a clear process.","shortcut":[{"text":"Keep sorting it out between the two of you each time it comes up.","brief":"keep handling it between you","why":"Handling the same conflict over and over wastes time and wears down the relationship.","mis":"Involving a supervisor means you failed."}]}],"proceed":{"text":"Work with {coworker} on a solution that addresses both of your concerns.","why":"You understand the concern and nothing else needs handling first, so working out a joint solution is the next step.","lesson":"Once both sides are understood, work together toward a solution that meets both needs."},"generic":[{"text":"Avoid {coworker} for the rest of the week until things cool off.","why":"Avoiding a shared-task partner leaves the task and the conflict unresolved.","mis":"Conflicts fade if you avoid the person."},{"text":"Complain about {coworker} to other teammates during lunch.","why":"Complaining to others spreads the conflict and damages trust without solving anything.","mis":"Getting others on your side helps resolve a conflict."}],"overcaution":[{"text":"Ask {lead|the} to decide every detail for the two of you.","why":"You already understand each other's concern. Handing every decision to the lead is unnecessary.","mis":"A supervisor should settle every disagreement."}],"process":{"setup":["You and {coworker} at {workplace|the} need to settle a disagreement about {task|the}."],"because":{"public":["The disagreement started out on the floor in front of {client.plural}."],"repeat":["The same disagreement has come up several times this month."]},"steps":[{"id":"move","text":"Move to a private place to talk","issue":"public"},{"id":"listen","text":"Each person explains their view while the other listens","core":true},{"id":"options","text":"List options that could work for both","core":true},{"id":"lead","text":"Bring {lead|the} in to help set a process","issue":"repeat"},{"id":"agree","text":"Agree on the plan and how to check it","core":true}],"rel":[["move","listen","A calm conversation needs a private place."],["listen","options","Options should come from understanding both views."],["options","agree","You agree on a plan after listing options."],["listen","lead","The lead needs to hear both views to help."],["lead","agree","The process the lead helps set becomes part of the plan."]],"alternatesReviewed":true,"lesson":"Go private, listen to both sides, look for options, and agree on a plan."},"doc":{"type":"chat","title":["Your message to {coworker}"],"intro":["You are about to send {coworker} a message after this morning's disagreement. Check it first."],"prompt":["Which line is likely to make the conflict worse?","Which line is the problem?"],"lesson":"Messages after a conflict should be respectful, specific and focused on a shared solution.","lines":[{"id":"open","text":"Hi {coworker}, I would like to sort out how we handle {task|the}.","fine":"A calm, direct opening."},{"id":"own","text":"I could have listened better this morning.","fine":"Owns your part without blaming."},{"id":"view","text":"I think starting quickly saves time, and I know you prefer to plan first.","fine":"States both views fairly.","bad":[{"id":"view-insult","level":"beginner","text":"Honestly, your way of planning everything is just slow and pointless.","why":"Dismissing the other person's approach is insulting and will deepen the conflict.","principle":"con.doc-dismissive-language"}]},{"id":"idea","text":"Could we plan for ten minutes, then start and adjust as we go?","fine":"Proposes a compromise that respects both styles.","bad":[{"id":"idea-ultimatum","level":"intermediate","text":"From now on we do it my way, or I will just do the whole thing myself.","why":"An ultimatum ends the discussion rather than solving it and ignores the other person's needs.","principle":"con.doc-ultimatum"}]},{"id":"private","text":"Want to talk in the break room at 2?","fine":"Suggests a private, specific time.","bad":[{"id":"private-public","level":"advanced","needs":["open"],"text":"I am also posting this in the team chat so everyone can weigh in.","why":"Making a two-person disagreement public invites others to take sides and embarrasses your coworker.","principle":"con.doc-made-dispute-public"}]},{"id":"close","text":"Thanks for working through this with me.","fine":"A respectful close."}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Style and repeat share tier 4 (exclusive by tier) because their order is debatable."}},{"id":"con-performance-concern","skill":"conflict-resolution","family":"conflict-resolution.cx-performance-concern","familyName":"Raising a concern about a coworker's work","framework":"conflicting-instructions","concepts":["conflict-resolution:performance-concerns","conflict-resolution:when-to-escalate","conflict-resolution:personality-and-culture"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. There may be a problem with how {coworker} leaves {equipment|the} at the end of each shift.","As {role|a} at {workplace|a}, you are concerned about how {coworker}, who works the shift before yours, leaves {equipment|the}."],"pressure":["{coworker3} says you should report {coworker} and be done with it."],"detail":["You usually see {coworker} only during the shift change."],"tiers":{"1":"A safety problem has to be dealt with today, not saved for a talk.","2":"Raise only what you know firsthand.","3":"A coworker deserves a direct conversation before you go over their head.","4":"When talking has not worked, it is time to involve the supervisor."},"issues":[{"id":"unsafe","tier":1,"rule":"control-hazard-first","principle":"con.report-unsafe-handoff","fact":["This morning, {equipment|the} was left in a state that could injure the next person who used it."],"short":"the unsafe state of the equipment","action":"Make the equipment safe or mark it, and tell {lead|the} about it today.","brief":"make it safe and tell {lead|the} today","reason":"A safety risk cannot wait for a friendly conversation. The lead needs to know the same day.","lesson":"Safety concerns about a coworker's work go to the supervisor right away.","shortcut":[{"text":"Fix it quietly every morning so {coworker} does not feel criticized.","brief":"fix it quietly each morning","why":"Quietly fixing a safety risk leaves it in place for anyone who gets there before you.","mis":"Avoiding criticism matters more than reporting a hazard."}]},{"id":"secondhand","tier":2,"rule":"check-facts-first","principle":"con.verify-secondhand-complaint","fact":["You have not seen it yourself; {coworker2} told you about it."],"clear":["You saw how {equipment|the} was left yourself on Monday and Tuesday."],"done":"you already saw the problem yourself","short":"only having secondhand information","action":"Check the equipment yourself for a few days before raising anything.","brief":"check it yourself before raising it","reason":"A concern based on hearsay may be wrong or exaggerated. Seeing it yourself lets you describe it fairly.","lesson":"Base a concern about someone's work on what you have seen yourself.","shortcut":[{"text":"Repeat what {coworker2} told you as if you had seen it yourself.","brief":"repeat it as if you saw it","why":"Passing on secondhand claims as fact is unfair to {coworker} and may be inaccurate.","mis":"If a coworker said it, it must be true."}]},{"id":"nevertold","tier":3,"rule":"talk-directly-first","principle":"con.raise-concern-directly","fact":["You have never mentioned the problem to {coworker}."],"short":"never having told {coworker}","action":"Talk with {coworker} privately and describe the specific problem.","brief":"talk with {coworker} privately","reason":"{coworker} may not know the setup causes problems. A private, specific conversation gives them the chance to fix it.","lesson":"Raise a work concern with the person directly before going to a supervisor.","shortcut":[{"text":"Complain to {lead|the} without saying anything to {coworker} first.","brief":"complain to {lead|the}","why":"Going over a coworker's head on a minor issue, without talking first, damages trust and skips the simplest fix.","mis":"Supervisors should handle every complaint."}]},{"id":"unchanged","tier":3,"rule":"escalate-after-trying","principle":"con.escalate-after-direct-talk-fails","fact":["You talked with {coworker} about it two weeks ago, and nothing has changed."],"short":"the problem continuing after your talk","action":"Explain the situation to {lead|the} with specific examples.","brief":"tell {lead|the} with specific examples","reason":"You tried the direct approach. Specific examples let the lead address it fairly.","lesson":"If a direct conversation does not fix the problem, involve the supervisor with specifics.","shortcut":[{"text":"Keep fixing it yourself and stop expecting {coworker} to change.","brief":"keep fixing it yourself","why":"The problem costs time every day. Silently absorbing it leaves the cause untouched.","mis":"Escalating after talking makes you a troublemaker."}]},{"id":"culture","tier":4,"rule":"adapt-to-person","principle":"con.adapt-feedback-to-person","noProceed":true,"fact":["{coworker} is new and has said that blunt criticism in front of others feels humiliating."],"short":"how {coworker} prefers to hear feedback","action":"Plan to raise it one-on-one, in a calm and specific way.","brief":"plan a calm one-on-one talk","reason":"Adapting how you give feedback to the person makes it easier to hear and act on.","lesson":"Give feedback in a way that respects the person's background and preferences.","shortcut":[{"text":"Bring it up at the team meeting so everyone hears the standard.","brief":"raise it at the team meeting","why":"Public criticism humiliates {coworker} and makes a defensive reaction more likely.","mis":"Public feedback is more efficient."}]}],"exclusive":[["unsafe","secondhand"]],"proceed":{"text":"Talk with {coworker} about it in a calm, specific way.","why":"You have firsthand information and nothing more urgent applies, so a direct conversation is the right next step.","lesson":"Raise concerns directly and specifically once you know the facts."},"generic":[{"text":"Leave {coworker} an anonymous note telling them to do better.","why":"An anonymous note is vague and feels like an attack. A direct conversation works better.","mis":"Anonymous criticism avoids conflict."},{"text":"Set up {equipment|the} wrong on purpose so {coworker} sees how it feels.","why":"Getting even creates new problems and makes the conflict personal.","mis":"Teaching someone a lesson solves the problem."}],"overcaution":[{"text":"Keep a secret log for another month before saying anything.","why":"You already have firsthand facts. Waiting a month lets the problem continue.","mis":"More evidence is always needed before speaking up."}],"process":{"setup":["You want to address how {coworker} leaves {equipment|the} at the end of each shift at {workplace|the}."],"because":{"secondhand":["So far you have only heard about the problem from {coworker2}."],"unchanged":["An earlier talk with {coworker} has not changed anything."]},"steps":[{"id":"see","text":"Check the equipment yourself for a few days","issue":"secondhand"},{"id":"examples","text":"Write down specific examples","core":true},{"id":"talk","text":"Talk privately with {coworker}","core":true},{"id":"lead","text":"Share the examples with {lead|the}","issue":"unchanged"},{"id":"followup","text":"Check whether the setup improves","core":true}],"rel":[["see","examples","Examples should come from what you saw yourself."],["examples","talk","Specific examples make the conversation clear and fair."],["talk","followup","You check for improvement after raising it."],["talk","lead","The supervisor comes in after a direct talk."],["examples","lead","The lead needs specific examples."]],"alternatesReviewed":true,"lesson":"Get firsthand facts, talk directly, then escalate with specifics if needed."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"'nevertold' and 'unchanged' share tier 3 and contradict each other, so they never co-occur."},"doc":{"type":"note","title":["Your notes for the talk with {coworker}"],"intro":["You wrote these notes before talking with {coworker}. Check them first."],"prompt":["Which note would make the conversation go badly?","Which line is the problem?"],"lesson":"Raising a concern works best when it is private, specific, factual and focused on a fix.","lines":[{"id":"where","text":"Talk privately at the start of my shift.","fine":"A private setting.","bad":[{"id":"where-public","level":"beginner","text":"Bring it up in front of the whole team so everyone hears.","why":"Raising a concern in public embarrasses the coworker and makes them defensive.","principle":"con.doc-public-criticism"}]},{"id":"facts","text":"On Monday and Tuesday, the guide was left loose.","fine":"Specific, firsthand facts.","bad":[{"id":"facts-always","level":"beginner","text":"You always mess up the equipment.","why":"\"Always\" is an exaggeration and an attack, not a specific fact.","principle":"con.doc-generalized-blame"}]},{"id":"effect","text":"It takes me 15 minutes to reset it each morning.","fine":"Explains the impact.","bad":[{"id":"effect-exagg","level":"beginner","text":"You are ruining everyone's mornings on purpose.","why":"Accusing someone of acting on purpose is an attack, not a description of the impact.","principle":"con.doc-accuses-intent"}]},{"id":"ask","text":"Ask whether something makes the end of the shift rushed.","fine":"Seeks to understand the other side.","bad":[{"id":"ask-assume","level":"intermediate","text":"Tell {coworker} the problem is laziness.","why":"Assuming a motive is unfair and shuts down the conversation.","principle":"con.doc-assumes-motive"}]},{"id":"fix","text":"Suggest a two-minute checklist at shift change.","fine":"Proposes a practical fix."},{"id":"next","text":"If nothing changes in two weeks, talk to {lead|the}.","fine":"A sensible escalation plan.","bad":[{"id":"next-now","level":"advanced","needs":["fix"],"text":"Report {coworker} to {lead|the} today, before trying the checklist idea.","why":"The notes plan a direct fix first; escalating today skips it for a non-safety issue.","principle":"con.doc-escalates-before-trying-fix"}]}]}},{"id":"cla-new-system","skill":"continuous-learning-and-adaptability","family":"continuous-learning-and-adaptability.cx-switching-systems","familyName":"Adapting to a new system","framework":"unexpected-change","concepts":["continuous-learning-and-adaptability:changing-requirements","continuous-learning-and-adaptability:learning-resources","continuous-learning-and-adaptability:acting-on-feedback"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. The team is switching from the old way of keeping {record|the} to a new version of {system|the}.","As {role|a} at {workplace|a}, you have to start using a new version of {system|the} for {record|the}."],"pressure":["{coworker3} says nobody will check whether you actually use the new system.","The switch is happening during a busy week."],"detail":["The new screens use a different color scheme.","Most of the team is new to it too."],"tiers":{"1":"A new requirement affects every entry, so it comes first.","2":"Feedback on errors you are making now should be acted on right away.","3":"A hard deadline for the change shapes your schedule.","4":"Using the available training makes practice count.","5":"Encouraging others matters once your own adjustment is on track."},"issues":[{"id":"field","tier":1,"rule":"meet-new-requirement","principle":"cla.learn-new-required-field","fact":["The new system requires an extra field on every entry that the old way never asked for."],"short":"the new required field","action":"Find out what the new field needs, and fill it in on every entry.","brief":"learn the new field and fill it in","reason":"A changed requirement applies to every entry from now on. Learning it now prevents a pile of incomplete records.","lesson":"When requirements change, learn the new expectation and apply it consistently.","shortcut":[{"text":"Leave the new field blank until someone explains why it matters.","brief":"leave the field blank","why":"Blank required fields make records incomplete. You can find out what it needs now.","mis":"Requirements you do not understand can be ignored."}]},{"id":"errors","tier":2,"rule":"act-on-feedback","principle":"cla.correct-practice-after-feedback","fact":["{Lead|the} pointed out two errors you made in the new system yesterday."],"clear":["{Lead|the} already walked you through the right steps after yesterday's errors."],"done":"{lead|the} already showed you the correct steps","short":"yesterday's errors","action":"Ask {lead|the} to show you the correct steps, and practice them.","brief":"get shown the right steps and practice","reason":"Feedback only helps if you act on it. Learning the correct steps now stops the errors from repeating.","lesson":"Act on feedback quickly by learning and practicing the correction.","shortcut":[{"text":"Explain that the old way was easier and the errors were not your fault.","brief":"defend the old way","why":"Defending yourself does not prevent the errors from happening again.","mis":"Feedback is something to defend against."}]},{"id":"deadline","tier":3,"rule":"plan-for-change-deadline","principle":"cla.practice-before-cutover","fact":["The old way ends on Friday, and you have not tried the new version yet."],"clear":["You practiced in the new version for an hour on Monday."],"done":"you already practiced in the new version","short":"Friday's cutover","action":"Schedule time this week to practice in the new version before Friday.","brief":"schedule practice before Friday","reason":"Practicing before the cutover lets you learn without the pressure of real work.","lesson":"Prepare for a change before it arrives, not after.","shortcut":[{"text":"Wait until Friday and learn it as you go.","brief":"learn it on Friday","why":"Learning under deadline pressure leads to errors and stress.","mis":"You learn best under pressure."}]},{"id":"training","tier":4,"rule":"use-learning-resources","principle":"cla.use-posted-training","fact":["Training videos and a help guide are posted, but you have not opened them."],"short":"the unused training","action":"Work through the posted training before asking others for help.","brief":"work through the posted training","reason":"The training answers most common questions. Using it first saves your coworkers' time.","lesson":"Use the learning resources available before relying on others.","shortcut":[{"text":"Ask {coworker} to walk you through everything from scratch.","brief":"have {coworker} teach you everything","why":"Asking for a full walkthrough ignores the training already posted and takes a coworker's time.","mis":"Asking someone is always faster than training materials."}]},{"id":"resist","tier":5,"rule":"model-adaptability","principle":"cla.support-change-with-coworkers","noProceed":true,"fact":["{coworker3} plans to keep using paper notes instead of the new version."],"short":"{coworker3}'s resistance","action":"Keep using the new version yourself and offer to share what you have learned.","brief":"keep using it and offer to share tips","reason":"Modeling the change and offering help supports a coworker without lecturing them.","lesson":"Adapt to change yourself and help others adapt.","shortcut":[{"text":"Join {coworker3} with paper notes until the new version improves.","brief":"join {coworker3} with paper","why":"Avoiding the new version leaves records incomplete and delays your own learning.","mis":"If others resist a change, it is fine to resist too."}]}],"proceed":{"text":"Keep entering {record|the} in the new version and build your speed.","why":"You are prepared and on track, so regular use is the best way to become fluent.","lesson":"Once you are prepared, regular practice makes a new system second nature."},"generic":[{"text":"Complain to {lead|the} that the change was unnecessary.","why":"Complaining does not help you learn the system the team now uses.","mis":"Objecting to a change makes it go away."},{"text":"Keep a private paper copy of everything just in case.","why":"A separate copy creates two sets of records that may not match.","mis":"Duplicating records is always safer."}],"overcaution":[{"text":"Ask {lead|the} to approve each entry you make in the new version.","why":"You are prepared and on track. Approving every entry would waste the lead's time.","mis":"New systems need supervisor approval for every step."}],"process":{"setup":["{Workplace|the} is switching {record|the} over to an updated {system}."],"because":{"training":["Training videos for the new version are available."],"errors":["You have already made a few errors in the new version."]},"steps":[{"id":"watch","text":"Watch the posted training videos","issue":"training"},{"id":"practice","text":"Practice with sample entries","core":true},{"id":"fix","text":"Review the errors {lead|the} pointed out","issue":"errors"},{"id":"real","text":"Enter real records in the updated system","core":true},{"id":"check","text":"Ask {lead|the} to spot-check your first entries","core":true}],"rel":[["watch","practice","Training shows you what to practice."],["practice","real","Practice comes before real records."],["fix","real","Correct your errors before entering real records."],["real","check","Spot-checks happen after real entries are made."]],"alternatesReviewed":true,"lesson":"Learn from the training, practice, fix your errors, then work for real and get checked."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Adapting to changed requirements."}},{"id":"cla-review-feedback","skill":"continuous-learning-and-adaptability","family":"continuous-learning-and-adaptability.cx-acting-on-review","familyName":"Acting on a performance review","framework":"critical-information","concepts":["continuous-learning-and-adaptability:acting-on-feedback","continuous-learning-and-adaptability:credentials","continuous-learning-and-adaptability:learning-resources"],"contexts":"any","setup":["You work as {role|a} at {workplace|a} and just had your yearly review with {lead|the}.","As {role|a} at {workplace|a}, you are thinking about what {lead|the} said in your review this week."],"pressure":["{coworker3} says reviews are just paperwork.","You feel a little discouraged after the review."],"detail":["Most of the review was positive.","The review took about half an hour."],"tiers":{"1":"A credential your job requires cannot be allowed to lapse.","2":"Understand feedback before deciding what to do about it.","3":"Specific feedback calls for a specific plan.","4":"A skill gap for upcoming work needs a learning plan.","5":"Checking your progress is useful once the work is underway."},"issues":[{"id":"credential","tier":1,"rule":"maintain-credential","principle":"cla.renew-required-credential","fact":["A certification your job requires expires next month, and renewal takes three weeks."],"clear":["You already signed up for the renewal course that starts Monday."],"done":"the renewal is already scheduled","short":"the expiring certification","action":"Sign up for the renewal course now so the certification does not lapse.","brief":"sign up for renewal now","reason":"If a required credential lapses, you may not be allowed to do your job. Renewal takes time, so it cannot wait.","lesson":"Keep required credentials current by renewing well before they expire.","shortcut":[{"text":"Renew it after it expires, since it is just paperwork.","brief":"renew it after it expires","why":"An expired required credential can keep you from working until it is renewed.","mis":"Credentials can be renewed whenever convenient."}]},{"id":"defensive","tier":2,"rule":"understand-feedback","principle":"cla.ask-questions-about-feedback","noProceed":true,"fact":["Part of the feedback felt unfair, and you are not sure what {lead|the} meant by it."],"short":"the feedback you are unsure about","action":"Ask {lead|the} questions to understand that feedback before deciding what to do.","brief":"ask questions about the feedback","reason":"Feedback that feels unfair often makes more sense with an example. Understanding it first lets you respond well.","lesson":"Seek to understand feedback before reacting to it.","shortcut":[{"text":"Ignore that part of the review, since it felt unfair.","brief":"ignore that part","why":"Ignoring feedback you do not like may leave a real issue unaddressed.","mis":"Feedback that feels unfair is not worth considering."}]},{"id":"summaries","tier":3,"rule":"act-on-feedback","principle":"cla.practice-specific-improvement","fact":["{Lead|the} said your written reports need clearer summaries."],"short":"the feedback about summaries","action":"Ask for an example of a strong summary and practice that style.","brief":"get an example and practice","reason":"An example shows exactly what clear looks like, and practice turns feedback into a habit.","lesson":"Turn specific feedback into a specific practice plan.","shortcut":[{"text":"Make your reports longer so nothing is left out.","brief":"make reports longer","why":"Longer is not clearer. The feedback was about summaries, not length.","mis":"More detail always means better writing."}]},{"id":"gap","tier":4,"rule":"close-skill-gap","principle":"cla.learn-skill-for-new-task","fact":["Next month you will take on a task that needs spreadsheet skills you do not have."],"short":"the spreadsheet skill gap","action":"Find a free online course or ask {coworker} to show you the basics before next month.","brief":"learn spreadsheet basics before next month","reason":"Learning before the task arrives lets you start strong instead of struggling.","lesson":"Identify the skills upcoming work requires and learn them ahead of time.","shortcut":[{"text":"Hope the task turns out simpler than expected.","brief":"hope it is simple","why":"Hoping does not build the skill. You know the gap now and can close it.","mis":"Skill gaps solve themselves on the job."}],"clear":["You finished a free spreadsheet course last month."],"done":"you already learned the spreadsheet basics"},{"id":"progress","tier":5,"rule":"check-progress","principle":"cla.ask-whether-improvement-shows","fact":["You have practiced a new skill for a month but have not checked whether it shows in your work."],"short":"the unchecked progress","action":"Ask {lead|the} whether the change is showing in your work.","brief":"ask whether it shows","reason":"Checking in confirms you are improving in the way that matters and shows you took the feedback seriously.","lesson":"Close the loop on feedback by checking whether your improvement shows.","shortcut":[{"text":"Assume it is fine, since {lead|the} has not said anything.","brief":"assume it is fine","why":"Silence is not confirmation. A quick check gives you real information.","mis":"No news means good news."}]}],"exclusive":[["summaries","progress"],["defensive","progress"]],"proceed":{"text":"Keep working on the goals from your review and note your progress.","why":"Nothing urgent needs handling, so steady work on the review goals is the right next step.","lesson":"Make growth a steady habit after every review."},"generic":[{"text":"Put the review in a drawer and forget about it until next year.","why":"A review only helps if you act on it during the year.","mis":"Reviews are a once-a-year event."},{"text":"Ask {coworker2} to compare their review with yours.","why":"Comparing reviews does not help you act on your own feedback.","mis":"Your review only means something compared with others."}],"overcaution":[{"text":"Ask {lead|the} for a second full review before doing anything.","why":"You already have clear feedback. A second review delays action.","mis":"More reviews give better direction."}],"doc":{"type":"note","title":["Your learning plan after the review"],"intro":["You wrote this learning plan after your review. Check it before sharing it with {lead|the}."],"lesson":"A good learning plan responds to specific feedback with specific actions, resources and dates.","lines":[{"id":"feedback","text":"Feedback: my report summaries need to be clearer.","fine":"States the feedback accurately."},{"id":"action","text":"Action: study two strong example summaries and rewrite mine in that style.","fine":"A specific action tied to the feedback.","bad":[{"id":"action-unrelated","level":"advanced","needs":["feedback"],"text":"Action: take a course on public speaking.","why":"The feedback was about written summaries. A speaking course does not address it.","principle":"cla.doc-action-misses-feedback"}]},{"id":"resource","text":"Resource: ask {coworker} for examples; use the posted writing guide.","fine":"Names available learning resources."},{"id":"cert","text":"Certification renewal: course booked for next week, before it expires.","fine":"Keeps a required credential current.","bad":[{"id":"cert-late","level":"beginner","text":"Certification renewal: will deal with it after it expires.","why":"Letting a required credential lapse can stop you from working.","principle":"cla.doc-lets-credential-lapse"}]},{"id":"check","text":"Check-in: ask {lead|the} in six weeks whether summaries have improved.","fine":"Plans to check progress.","bad":[{"id":"check-never","level":"intermediate","text":"Check-in: none; I will assume it worked.","why":"Without checking, you cannot know whether the change is showing.","principle":"cla.doc-no-progress-check"}]},{"id":"attitude","text":"I am glad to get specific feedback I can act on.","fine":"A constructive attitude toward feedback.","bad":[{"id":"attitude-dismiss","level":"beginner","text":"I do not agree with the feedback, so this plan is mostly for show.","why":"A plan written only for show does not lead to improvement.","principle":"cla.doc-plan-for-show"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Credential timing is stated in the scenario; no claims about specific licensing rules."}},{"id":"cre-process-idea","skill":"creativity-and-innovation","family":"creativity-and-innovation.cx-putting-an-idea-to-work","familyName":"Putting a process idea to work","framework":"consequences","concepts":["creativity-and-innovation:improve-processes","creativity-and-innovation:contribute-ideas"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to find a faster way to handle {task|the}, and you have an idea.","As {role|a} at {workplace|a}, you were asked by {lead|the} to speed up {task|the}. You have come up with a new method."],"pressure":["{coworker3} says you should just start the new method today and sort out details later."],"detail":["The idea came to you while restocking the {area}.","You sketched the idea on a notepad during lunch."],"tiers":{"1":"A required quality check protects people, so it comes before speed.","2":"Knowing why the last attempt failed shapes everything else about the idea.","3":"The people whose work changes need a say before the change happens.","4":"A purchase request is stronger once the idea itself is settled."},"issues":[{"id":"quality","tier":1,"rule":"protect-requirements","principle":"cre.keep-required-checks","fact":["Your new method skips a quality check that {lead|the} requires on every {deliverable}."],"clear":["{Lead|the} looked over your method and confirmed it keeps every required check."],"done":"the method was already confirmed to keep the required checks","short":"the skipped quality check","action":"Rework the method so the required quality check stays in place.","brief":"rework the method to keep the quality check","reason":"A faster process that drops a required check trades reliability for speed. Keeping the check protects the people who depend on the work.","lesson":"Improve a process without removing the steps that protect quality and safety.","shortcut":[{"text":"Try the faster method on today's work and see whether anything goes wrong.","brief":"try it on today's work and see","why":"Testing on real work without the required check puts that work, and the people relying on it, at risk.","mis":"The only way to know if a shortcut is safe is to try it on real work."}]},{"id":"history","tier":2,"rule":"gather-missing-information","principle":"cre.learn-from-earlier-attempt","fact":["{coworker} mentions that a similar change was tried last year and dropped, but nobody remembers why."],"clear":["{coworker} found the old notes: the earlier change was dropped only because a supplier closed."],"done":"you already know why the earlier attempt was dropped","short":"the unexplained earlier attempt","action":"Find out why the earlier attempt was dropped before going further with yours.","brief":"find out why the earlier attempt was dropped","reason":"Learning why the last attempt was dropped lets you fix that problem in your version instead of repeating it.","lesson":"Learn from earlier attempts before pushing a similar change.","shortcut":[{"text":"Drop your idea, since something similar already failed once.","brief":"drop the idea because it failed before","why":"A past failure may have had a fixable cause. Dropping the idea without knowing why may waste a good improvement.","mis":"If something failed once, it will always fail."}]},{"id":"others","tier":3,"rule":"consult-affected-people","principle":"cre.involve-affected-coworkers","fact":["The change would also alter how {coworker2} prepares work for you each morning."],"clear":["{coworker2} has already looked at your method and is glad to try it."],"done":"{coworker2} has already agreed to the change","short":"the effect on {coworker2}'s work","action":"Talk with {coworker2} about how the change would affect that morning work.","brief":"talk it through with {coworker2}","reason":"People whose work changes can spot problems you cannot, and they deserve a say before their routine changes.","lesson":"Involve the people a change affects before you put it in place.","shortcut":[{"text":"Start the new method and let {coworker2} adjust as needed.","brief":"start it and let {coworker2} adjust","why":"Changing someone's routine without talking to them causes confusion and misses their useful input.","mis":"People will adapt to a better process without being asked."}]},{"id":"cost","tier":4,"rule":"seek-approval-with-case","principle":"cre.make-the-case-for-resources","fact":["The method needs a new storage rack, and purchases need approval from {lead|the}."],"clear":["{Lead|the} has already approved buying the new storage rack."],"done":"the purchase was already approved","short":"the unapproved purchase","action":"Give {lead|the} a short note on the rack's cost and the time it saves.","brief":"give {lead|the} a note on cost and time saved","reason":"Purchases need approval, and a clear cost-and-benefit note helps the lead decide quickly.","lesson":"Back an idea that needs resources with a short case for its cost and benefit.","shortcut":[{"text":"Buy the rack yourself and ask to be paid back later.","brief":"buy the rack yourself and ask for repayment","why":"Purchases need approval first. Buying it yourself skips that decision and may not be repaid.","mis":"Paying for something yourself means you do not need approval."}]}],"proceed":{"text":"Put the new method into use and track how much time it saves.","why":"The lead asked for this improvement and nothing in the situation stands in the way. Tracking the time saved shows whether it works.","lesson":"Once an idea has been checked, shared and cleared, put it to work and measure the result."},"generic":[{"text":"Keep the idea to yourself until you are sure it is perfect.","why":"Waiting for a perfect idea delays the improvement the lead asked for. Ideas improve through sharing and testing.","mis":"An idea should be perfect before anyone hears it."},{"text":"Ask {lead|the} to come up with a different idea instead.","why":"The lead asked you for an idea. Handing the task back without working through the issues wastes your idea.","mis":"Problems with an idea mean someone else should solve it."}],"overcaution":[{"text":"Hold off until every coworker on every shift has reviewed the method.","why":"Nothing in the situation calls for more review, and waiting on everyone stalls an improvement that is ready.","mis":"More review always makes an idea safer."}],"process":{"setup":["You are {role|a} at {workplace|a}, and {lead|the} asked you to improve how {task|the} is done."],"steps":[{"id":"observe","text":"Time how long the current process takes","core":true},{"id":"history","text":"Ask why the earlier change was dropped","issue":"history"},{"id":"consult","text":"Go over the plan with {coworker2}","issue":"others"},{"id":"approve","text":"Get the rack purchase approved","issue":"cost"},{"id":"trial","text":"Try the new method for one week","core":true},{"id":"compare","text":"Compare the new times with the old ones","core":true}],"rel":[["observe","trial","You need the starting time to measure any improvement."],["history","trial","Fix the earlier problem before trying the method again."],["consult","trial","Affected coworkers should agree before their routine changes."],["approve","trial","The rack has to be approved before the method can run."],["trial","compare","There is nothing to compare until the trial has run."]],"alternatesReviewed":true,"lesson":"Measure first, clear the obstacles, test the idea, then compare results."},"doc":{"type":"email","title":["Proposal: a faster way to handle {task|the}"],"intro":["You drafted this proposal for {lead|the}. Read it once more before sending."],"lesson":"A strong proposal states the problem, the evidence and the cost, and keeps the safeguards.","lines":[{"id":"problem","text":"Right now, {task|the} takes about 40 minutes each day.","fine":"Stating the current situation with a measurement sets up the comparison."},{"id":"idea","text":"I suggest keeping the supplies for it together on one rack.","fine":"The idea is stated plainly."},{"id":"trial","text":"In a one-week trial at my station, it took about 25 minutes a day.","fine":"A small trial with measured results is good evidence.","bad":[{"id":"trial-guess","level":"intermediate","text":"I have not tried it yet, but I am sure it will save at least an hour a day.","why":"The claim has no evidence behind it, and an hour is more than the whole task takes. Proposals should rest on measured results.","principle":"cre.doc-claim-without-evidence"}]},{"id":"check","text":"The required quality check stays in place at the end.","fine":"The proposal keeps the safeguard that protects the work.","bad":[{"id":"check-drop","level":"beginner","text":"To save time, we would stop doing the quality check at the end.","why":"Dropping a required check trades quality for speed. An improvement should keep the safeguards.","principle":"cre.doc-drops-safeguard"}]},{"id":"cost","text":"The rack costs about $60, which I would like your approval to buy.","fine":"The cost is stated and approval is requested before buying.","bad":[{"id":"cost-bought","level":"beginner","text":"I already bought the rack with the store account, so it is ready to go.","why":"Purchases need approval first. Spending without it bypasses the person responsible for the budget.","principle":"cre.doc-spent-without-approval"}]},{"id":"team","text":"{coworker2}, whose morning work this changes, helped plan it and supports it.","fine":"The proposal shows the affected coworker was involved.","bad":[{"id":"team-ignore","level":"advanced","needs":["idea"],"text":"{coworker2} will have to reorganize the morning prep, but I have not mentioned it yet.","why":"The change alters a coworker's routine without involving them. That person should be consulted before the proposal goes forward.","principle":"cre.doc-affected-person-not-consulted"}]},{"id":"ask","text":"Could we talk about it this week?","fine":"A clear, polite request for a next step."}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Approval requirement for purchases is stated in the scenario. Tiers: required check > learning from history > consulting affected people > purchase case."},"requires":["area"]},{"id":"cre-team-brainstorm","skill":"creativity-and-innovation","family":"creativity-and-innovation.cx-team-brainstorm","familyName":"Contributing in a team brainstorm","framework":"competing-priorities","concepts":["creativity-and-innovation:contribute-ideas","creativity-and-innovation:value-of-creativity","creativity-and-innovation:allocate-resources"],"contexts":"any","requires":["area"],"setup":["Your team at {workplace|the} is meeting to brainstorm ways to reduce crowding in the {area}.","You are {role|a} at {workplace|a}, in a team meeting about how to make the {area} less crowded."],"pressure":["{coworker3} says the meeting has to end in five minutes.","{coworker3} keeps saying the team should just pick something."],"detail":["The meeting is being held in the break room.","Someone brought coffee for the group."],"tiers":{"1":"An idea that blocks an emergency exit cannot go forward in any form.","2":"The stated budget limit decides which ideas are even possible.","3":"Hearing every voice comes before choosing among ideas.","4":"Comparing options leads to a better choice than taking the first one.","5":"Giving credit matters, but it can wait until the ideas are settled."},"issues":[{"id":"exit","tier":1,"rule":"protect-safety","principle":"cre.reject-idea-blocking-exit","fact":["The most popular suggestion so far would put shelving in front of the emergency exit."],"short":"the blocked exit","action":"Point out that the shelving would block the exit and suggest moving it elsewhere.","brief":"point out the blocked exit and suggest another spot","reason":"An emergency exit must stay clear. Raising the problem while suggesting an alternative keeps the idea alive without the danger.","lesson":"Creative ideas still have to keep people safe; adapt the idea rather than accept the risk.","shortcut":[{"text":"Go along with the shelving idea, since most of the team likes it.","brief":"go along with the popular shelving idea","why":"Popularity does not make a blocked exit safe. Someone needs to raise the problem now.","mis":"If most people like an idea, it must be fine."}]},{"id":"budget","tier":2,"rule":"work-within-constraints","principle":"cre.ideas-within-stated-budget","fact":["{Lead|the} has said the fix must use only furniture and supplies already on hand."],"short":"the no-spending limit","action":"Suggest ideas that rearrange or reuse what the team already has.","brief":"suggest ideas that reuse what you already have","reason":"The lead set a clear limit. Ideas that fit it can actually happen, and creativity with existing resources is still creativity.","lesson":"Work within stated limits; constraints are a prompt for creative reuse.","shortcut":[{"text":"Push for new shelving units, since buying them would work best.","brief":"push for buying new shelving","why":"The lead ruled out new purchases. An idea that ignores the limit cannot be used.","mis":"The best idea is the one with the best result, whatever the limits."}]},{"id":"quiet","tier":3,"rule":"include-every-voice","principle":"cre.invite-quiet-contributor","fact":["{coworker} works in the {area} every day but has not had a chance to speak."],"clear":["{coworker} has already shared an idea, and the group wrote it on the board."],"done":"{coworker} has already had a turn to share","short":"the unheard coworker","action":"Invite {coworker} to share ideas before the group moves on.","brief":"invite {coworker} to share","reason":"The person who works in the space daily may know what causes the crowding. Inviting that input makes the solution better.","lesson":"Draw out ideas from everyone, especially the people closest to the problem.","shortcut":[{"text":"Assume {coworker} would have spoken up if there were a good idea.","brief":"assume {coworker} has nothing to add","why":"People stay quiet for many reasons. Missing the daily user's view can mean missing the real fix.","mis":"Quiet people have nothing to contribute."}]},{"id":"first","tier":4,"rule":"compare-alternatives","principle":"cre.compare-before-choosing","fact":["The group is about to adopt the first idea mentioned without hearing any others."],"clear":["The group has already listed and compared five ideas on the board."],"done":"the group already compared several ideas","short":"the rush to the first idea","action":"Suggest listing a few more ideas and comparing them before choosing.","brief":"suggest comparing a few more ideas","reason":"The first idea is rarely the best one. A few minutes of comparison often turns up a simpler or cheaper option.","lesson":"Generate several options and compare them before committing to one.","shortcut":[{"text":"Agree to the first idea so the meeting can end on time.","brief":"agree to the first idea to finish early","why":"Ending on time is nice, but choosing without comparing may lock in a weak solution.","mis":"The first workable idea is good enough."}]},{"id":"credit","tier":5,"rule":"give-credit","principle":"cre.credit-earlier-suggestion","fact":["The idea you plan to share builds on a suggestion {coworker2} made last month."],"short":"credit for {coworker2}'s earlier suggestion","action":"Share your idea and mention that it builds on {coworker2}'s earlier suggestion.","brief":"share it and credit {coworker2}","reason":"Naming where an idea came from is honest and encourages others to keep contributing.","lesson":"Give credit for the ideas you build on; it keeps people contributing.","shortcut":[{"text":"Present the idea as entirely your own to make a strong impression.","brief":"present the idea as entirely yours","why":"Taking credit for a coworker's thinking is unfair and discourages future ideas.","mis":"Getting noticed matters more than giving credit."}]}],"proceed":{"text":"Help the group choose an idea and agree on who will try it first.","why":"The ideas have been heard and compared, so the next useful step is a decision and a plan to act on it.","lesson":"Once ideas are heard and compared, move the group to a decision and next steps."},"generic":[{"text":"Stay quiet so the meeting does not get any longer.","why":"Holding back your input deprives the team of ideas and leaves problems unraised.","mis":"Speaking up only slows a meeting down."},{"text":"Criticize each idea as soon as it is suggested.","why":"Shooting down ideas immediately makes people stop sharing. Evaluation works better after ideas are collected.","mis":"Finding flaws early saves time."}],"overcaution":[{"text":"Suggest scheduling another meeting so everyone can think longer.","why":"The ideas are already heard and compared. Another meeting delays a decision the group is ready to make.","mis":"More time always produces better ideas."}],"process":{"setup":["Your team at {workplace|the} is running a short brainstorm about crowding in the {area}."],"steps":[{"id":"define","text":"Agree on the problem the group is solving","core":true},{"id":"limits","text":"Review the no-spending limit","issue":"budget"},{"id":"collect","text":"Collect ideas from every person","core":true},{"id":"invite","text":"Ask {coworker} for ideas","issue":"quiet"},{"id":"choose","text":"Compare the ideas and choose one","core":true}],"rel":[["define","collect","People need to know the problem before suggesting fixes."],["limits","collect","Knowing the limits keeps ideas realistic."],["define","limits","The limit applies to a defined problem."],["invite","choose","All ideas, including the quiet person's, come in before choosing."],["define","invite","The invitation comes once the problem is clear."],["collect","choose","You can only compare ideas once they are collected."]],"alternatesReviewed":true,"lesson":"Define the problem and the limits, gather ideas from everyone, then compare and choose."},"doc":{"type":"note","title":["Brainstorm notes: crowding in the {area}"],"intro":["You took these notes at the team brainstorm. Check them before sharing with the group."],"lesson":"Brainstorm notes should capture every idea fairly and record decisions that respect the limits.","lines":[{"id":"goal","text":"Goal: reduce crowding in the {area} during busy times.","fine":"A clear statement of the problem."},{"id":"limit","text":"Limit: use only furniture and supplies already on hand.","fine":"The stated constraint is recorded."},{"id":"ideas","text":"Ideas: stagger break times, move the supply cart, add a second entry lane.","fine":"Several options are recorded for comparison."},{"id":"voices","text":"Ideas came from all five people at the meeting.","fine":"The notes show every voice was included.","bad":[{"id":"voices-skip","level":"intermediate","text":"Ideas came from the three most experienced people; the others did not need to add anything.","why":"Leaving out newer people's ideas wastes their view of the problem and discourages participation.","principle":"cre.doc-excluded-voices"}]},{"id":"exit","text":"Any change must keep the emergency exit clear.","fine":"Safety requirement recorded.","bad":[{"id":"exit-block","level":"beginner","text":"Decision: stack the extra boxes in front of the side exit door.","why":"Blocking an exit creates a serious danger in an emergency. No space-saving idea is worth that.","principle":"cre.doc-blocks-exit"}]},{"id":"decision","text":"Decision: stagger break times for two weeks, then review.","fine":"A decision with a trial period and review.","bad":[{"id":"decision-buy","level":"advanced","needs":["limit"],"text":"Decision: order two new storage cabinets this week.","why":"The notes already say only items on hand may be used. Ordering cabinets breaks the stated limit.","principle":"cre.doc-decision-breaks-limit"}]},{"id":"credit","text":"The staggered-break idea was first raised by {coworker2} last month.","fine":"Credit is given for the original idea.","bad":[{"id":"credit-steal","level":"beginner","text":"The staggered-break idea is credited only to the note taker.","why":"The idea came from a coworker. Notes should credit people fairly.","principle":"cre.doc-wrong-credit"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Budget limit stated by the lead; exit-safety tier is general practice, stated without legal claims."}},{"id":"ctp-deadline-obstacles","skill":"critical-thinking-and-problem-solving","family":"critical-thinking-and-problem-solving.cx-deadline-obstacles","familyName":"What is really blocking the deadline","framework":"critical-information","concepts":["critical-thinking-and-problem-solving:analyze-problems","critical-thinking-and-problem-solving:logical-decisions"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}. You are responsible for {deliverable|the}, which is due at 3 p.m. today.","As {role|a} at {workplace|a}, you are responsible for {deliverable|the}, due at 3 p.m."],"pressure":["{coworker3} says {lead|the} hates late work and you need to finish no matter what.","It is already 1:30 p.m."],"detail":["The rest of the team is busy with their own work.","It has been a quiet afternoon so far."],"tiers":{"1":"A safety step is never traded for speed.","2":"Wrong work has to be stopped before it reaches anyone.","3":"You need to know which job matters most before planning your time.","4":"The job cannot be finished correctly without what is missing.","5":"New ideas can wait until urgent problems are handled."},"issues":[{"id":"safety","tier":1,"rule":"keep-safety-step","principle":"ctp.no-skipping-safety-for-deadline","fact":["Finishing by 3 p.m. would mean skipping the safety check that {lead|the} requires at the end."],"short":"the required safety check","action":"Keep the safety check and let {lead|the} know the work will be late.","brief":"keep the safety check and warn {lead|the} it will be late","reason":"A late delivery is a smaller problem than an unsafe one. Telling the lead early lets them adjust plans.","lesson":"When a deadline and a safety step collide, keep the safety step and communicate the delay.","shortcut":[{"text":"Skip the safety check this once so {deliverable|the} is on time.","brief":"skip the safety check this once","why":"Skipping a required safety check puts people at risk. Being on time does not make that acceptable.","mis":"Meeting a deadline justifies skipping a step once."}]},{"id":"error","tier":2,"rule":"stop-wrong-work","principle":"ctp.correct-error-before-delivery","fact":["While reviewing, you find a mistake in the part of the job you already completed."],"short":"the mistake in the finished part","action":"Correct the mistake, or report it to {lead|the}, before anything is delivered.","brief":"correct or report the mistake before delivery","reason":"Delivering work you know is wrong passes the problem to the people relying on it. Stopping it now is cheaper than fixing it later.","lesson":"Stop known errors before work is delivered, even if it costs time.","shortcut":[{"text":"Deliver {deliverable|the} on time and fix the mistake in the next version.","brief":"deliver on time and fix it next time","why":"Sending work you know is wrong spreads the error to everyone who uses it.","mis":"On time matters more than correct."}]},{"id":"priorities","tier":3,"rule":"clarify-priorities","principle":"ctp.clarify-conflicting-deadlines","fact":["{Lead|the} also asked you to finish a second job by 3 p.m., and there is not time for both."],"clear":["{Lead|the} told you this morning that the second job can wait until tomorrow."],"done":"the lead already said which job comes first","short":"the two overlapping deadlines","action":"Explain the conflict to {lead|the} and ask which job should come first.","brief":"ask {lead|the} which job comes","reason":"Only the lead can decide which deadline matters more. Raising the conflict early gives them time to choose or find help.","lesson":"When deadlines overlap, raise the conflict and let the person in charge set the priority.","shortcut":[{"text":"Split your time between both jobs and hope both get done.","brief":"split your time between both jobs","why":"Without a priority you may finish neither. The lead needs to decide which job matters more.","mis":"Doing a little of everything is the safest plan."}]},{"id":"missing","tier":4,"rule":"obtain-missing-information","principle":"ctp.obtain-missing-measurement","fact":["A measurement you need from {coworker} has not arrived yet."],"clear":["{coworker} sent the measurement you needed an hour ago."],"done":"the measurement already arrived","short":"the missing measurement","action":"Contact {coworker} to get the measurement, and keep working on other parts meanwhile.","brief":"get the measurement from {coworker}","reason":"The job depends on that number. Asking for it directly is fast, and working on other parts meanwhile saves time.","lesson":"Identify the missing information the job depends on and go get it.","shortcut":[{"text":"Estimate the measurement from a similar past job and keep going.","brief":"estimate the measurement from an old job","why":"A guessed number can make the whole job wrong. Getting the real figure is quick compared with redoing work.","mis":"A reasonable guess is as good as the real number."}]},{"id":"supplies","tier":4,"rule":"approved-alternative","principle":"ctp.approved-substitute-for-missing-supply","fact":["The {supply.plural} the job needs are out of stock."],"clear":["A delivery of {supply.plural} arrived this morning."],"done":"the supplies were already delivered","short":"the missing supplies","action":"Ask {lead|the} about an approved substitute and explain how it affects the deadline.","brief":"ask {lead|the} about an approved substitute","reason":"The lead knows which substitutes meet the job's requirements. Asking also warns them about the possible delay.","lesson":"When a resource runs out, check approved alternatives and say how it affects the schedule.","shortcut":[{"text":"Use whatever similar supply is on the shelf without asking anyone.","brief":"use a similar supply without asking","why":"An unapproved substitute may not meet the job's requirements, and nobody will know it was changed.","mis":"If it looks the same, it works the same."}]},{"id":"idea","tier":5,"rule":"suggest-improvement-after","principle":"ctp.note-improvement-for-later","noProceed":true,"fact":["You notice a way the job could be done faster next time."],"short":"the idea for next time","action":"Write the idea down and share it once today's job is delivered.","brief":"note the idea for after the deadline","reason":"The idea is worth keeping, but trying a new method under a deadline adds risk. Noting it protects both the deadline and the idea.","lesson":"Capture improvement ideas without letting them derail urgent work.","shortcut":[{"text":"Switch to the new method right now to save time.","brief":"switch methods mid-job","why":"Changing methods halfway through a deadline job risks new mistakes.","mis":"A faster idea should always be used immediately."}]}],"exclusive":[["missing","supplies"]],"proceed":{"text":"Keep working on {deliverable|the} so it is ready by 3 p.m.","why":"Nothing in the situation blocks the work, so the best move is to keep going and finish on time.","lesson":"When the information, resources and priorities are in place, focus on finishing the work."},"generic":[{"text":"Stop working and wait for someone to notice there is a problem.","why":"Waiting silently lets the deadline pass without anyone being able to help.","mis":"Problems get solved if you wait."},{"text":"Complain about the deadline to {coworker2} but keep it from {lead|the}.","why":"Venting to a coworker changes nothing. The lead needs to hear about problems to help.","mis":"Telling someone is the same as telling the right person."}],"overcaution":[{"text":"Ask {lead|the} to recheck the whole job before you continue.","why":"Nothing in the situation calls for a full recheck. Asking for one delays work that is ready to continue.","mis":"Asking for extra checks is always the responsible choice."}],"process":{"setup":["You are {role|a} at {workplace|a}, responsible for {deliverable|the} due at 3 p.m."],"steps":[{"id":"review","text":"Review what the job requires","core":true},{"id":"measure","text":"Get the measurement from {coworker}","issue":"missing"},{"id":"priority","text":"Ask {lead|the} which job comes first","issue":"priorities"},{"id":"substitute","text":"Get an approved substitute for the {supply}","issue":"supplies"},{"id":"work","text":"Complete the work","core":true},{"id":"check","text":"Check the finished work before handing it in","core":true}],"rel":[["review","work","You need to know the requirements before doing the work."],["review","measure","Reviewing the requirements shows what is missing."],["review","substitute","The requirements tell you what a substitute must match."],["measure","work","The work depends on the measurement."],["priority","work","You need to know which job to work on first."],["substitute","work","The work cannot be done without the supplies."],["work","check","You can only check work once it is done."]],"alternatesReviewed":true,"lesson":"Know the requirements, clear what blocks the work, do it, then check it."},"doc":{"type":"email","title":["Update on {deliverable|the}"],"intro":["You are about to send {lead|the} this status update. Check it first."],"lesson":"A status update should be accurate, early and honest about what is at risk.","lines":[{"id":"open","text":"Here is an update on {deliverable|the}, which is due at 3 p.m.","fine":"States what the update is about and the deadline."},{"id":"done","text":"The first half is finished and I checked it against the job requirements.","fine":"Reports progress and that it was checked.","bad":[{"id":"done-unchecked","level":"intermediate","text":"The first half is finished; I did not check it, but it should be fine.","why":"Unchecked work reported as done hides a risk. Check it or say clearly that it has not been checked.","principle":"ctp.doc-unchecked-work-reported-done"}]},{"id":"waiting","text":"I am waiting on a measurement from {coworker}, which I requested at 10 a.m.","fine":"Names exactly what is missing and what was done about it.","bad":[{"id":"waiting-guess","level":"beginner","text":"The measurement never arrived, so I used my best guess for now.","why":"A guessed number can make the job wrong. The real measurement should be obtained, or the guess flagged as a risk.","principle":"ctp.doc-guessed-missing-data"}]},{"id":"safety","text":"I will keep the final safety check, even if it takes extra time.","fine":"Commits to the safety step.","bad":[{"id":"safety-skip","level":"beginner","text":"To stay on time, I will skip the final safety check.","why":"A deadline never justifies skipping a required safety check.","principle":"ctp.doc-skips-safety-check"}]},{"id":"second","text":"You also asked me to finish the second job by 3 p.m.","fine":"Accurately restates the competing request."},{"id":"ask","text":"Could you tell me which job should come first?","fine":"Asks the person in charge to set the priority.","bad":[{"id":"ask-both","level":"advanced","needs":["second"],"text":"I will work on both jobs at once until 3 p.m.","why":"Both jobs are due at the same time. Splitting effort risks finishing neither; the lead should choose which comes first.","principle":"ctp.doc-no-priority-decision"}]},{"id":"next","text":"I will send another update at noon.","fine":"Promises the next update before the deadline.","bad":[{"id":"next-late","level":"intermediate","text":"I will let you know after 3 p.m. if anything went wrong.","why":"Reporting after the deadline removes the lead's chance to help. Problems should be raised before the deadline.","principle":"ctp.doc-reports-after-deadline"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Mirrors the five obstacle types (missing information, conflicting priorities, safety, resources, incorrect work). Missing information and missing supplies share a tier and are exclusive because their order is a matter of judgment."}},{"id":"ctp-recurring-errors","skill":"critical-thinking-and-problem-solving","family":"critical-thinking-and-problem-solving.cx-recurring-errors","familyName":"Finding the cause of recurring errors","framework":"root-cause","concepts":["critical-thinking-and-problem-solving:analyze-problems","critical-thinking-and-problem-solving:evaluate-solutions","critical-thinking-and-problem-solving:implement-action"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. For weeks, {record|the} has kept coming back with errors, and {lead|the} asked you to help fix it.","At {workplace|the}, errors keep showing up in {record|the}. {Lead|the} asked you, {role|a}, to help solve the problem."],"pressure":["{coworker3} says the team just needs to act fast and stop talking about it.","{Lead|the} wants a recommendation by tomorrow."],"detail":["The errors are not dangerous, but they waste time.","It is a busy week at {workplace|the}."],"tiers":{"1":"Without evidence about the errors, every fix is a guess.","2":"Checking whether the last fix worked comes before adding another.","3":"Blame without evidence can be unfair and can hide the real cause.","4":"Extra checking treats the symptom, so it comes after understanding the cause."},"issues":[{"id":"nodata","tier":1,"rule":"gather-evidence","principle":"ctp.collect-data-before-fixing","fact":["Nobody has written down when or where the errors happen."],"clear":["{coworker} has logged every error, with the time and shift, for the past two weeks."],"done":"the errors were already logged for two weeks","short":"the lack of any record of the errors","action":"Start logging when and where each error happens before choosing a fix.","brief":"start logging when and where errors happen","reason":"Without a record, any fix is a guess. A short log shows patterns that point to the real cause.","lesson":"Collect evidence about a problem before deciding how to fix it.","shortcut":[{"text":"Pick the fix most coworkers prefer, since there is no data anyway.","brief":"pick the most popular fix","why":"Popularity is not evidence. A fix chosen without data may miss the cause entirely.","mis":"When there is no data, opinion is good enough."}]},{"id":"pattern","tier":1,"rule":"follow-the-evidence","principle":"ctp.investigate-pattern-in-data","fact":["{coworker}'s log shows nearly every error happens during the evening shift."],"short":"the evening-shift pattern","action":"Find out what is different about the evening shift before changing anything.","brief":"find out what is different about evenings","reason":"The pattern points to something about the evening shift, such as training, staffing or equipment. Targeting that difference addresses the cause.","lesson":"Let patterns in the evidence point you toward the cause.","shortcut":[{"text":"Retrain staff on every shift, just to be safe.","brief":"retrain every shift","why":"The evidence points to one shift. Retraining everyone spends effort where there is no problem.","mis":"Treating everyone the same is the fairest fix, whatever the data show."}]},{"id":"followup","tier":2,"rule":"evaluate-previous-solution","principle":"ctp.check-whether-fix-worked","fact":["A new checklist was introduced last week, but nobody has checked whether it reduced the errors."],"clear":["You compared the records: errors dropped by half after last week's checklist."],"done":"you already confirmed the checklist cut errors in half","short":"the unchecked effect of last week's fix","action":"Compare errors before and after last week's checklist to see whether it helped.","brief":"check whether last week's checklist helped","reason":"Knowing whether the first fix worked tells you whether to keep it, adjust it or try something else.","lesson":"After putting a fix in place, check whether it actually worked.","shortcut":[{"text":"Assume the checklist worked, since nobody has complained this week.","brief":"assume the checklist worked","why":"A quiet week is not evidence. The records show whether errors actually went down.","mis":"No complaints means the problem is solved."}]},{"id":"blame","tier":3,"rule":"evidence-before-blame","principle":"ctp.no-blame-without-evidence","fact":["{coworker2} says the newest employee must be careless and should get a warning."],"short":"the blame aimed at the newest employee","action":"Point out that the records should show the cause before anyone is blamed.","brief":"ask for evidence before blaming anyone","reason":"Blaming a person without evidence can be unfair and can hide a cause in the process itself.","lesson":"Look at the evidence before blaming a person for a problem.","shortcut":[{"text":"Agree that the new employee should be warned to be more careful.","brief":"agree to warn the new employee","why":"There is no evidence the new employee causes the errors. A warning may be unfair and leave the real cause in place.","mis":"The newest person is usually the cause of new problems."}]},{"id":"quickfix","tier":4,"rule":"address-cause-not-symptom","principle":"ctp.compare-symptom-fix-to-cause-fix","fact":["{coworker3} proposes having a second person double-check every {record}."],"short":"the double-check proposal","action":"Compare the double-check idea with fixes that would remove the cause of the errors.","brief":"weigh the double-check against fixing the cause","reason":"Double-checking catches errors but adds work forever. A fix that removes the cause may cost less over time.","lesson":"Prefer solutions that remove a problem's cause over ones that only catch its symptoms.","shortcut":[{"text":"Support the double-check right away, since it is sure to catch errors.","brief":"adopt the double-check right away","why":"Catching errors is not the same as preventing them. The extra work never ends if the cause stays.","mis":"More checking is the best way to stop mistakes."}]}],"exclusive":[["nodata","followup"],["pattern","followup"]],"proceed":{"text":"Use the logged evidence to choose a fix aimed at the cause, then track the results.","why":"The evidence is in place and the earlier fix has been measured, so the next step is a targeted fix and follow-up.","lesson":"When the evidence is in, act on the cause it points to and keep measuring."},"generic":[{"text":"Tell {lead|the} the errors are just bad luck and will stop on their own.","why":"Errors that keep happening for weeks have a cause. Calling them luck leaves the problem in place.","mis":"Repeated problems happen by chance."},{"text":"Fix each error yourself as it comes in, so nobody else is bothered.","why":"Fixing each case hides the problem and adds to your workload. The cause stays in place.","mis":"Fixing each case is the same as solving the problem."}],"overcaution":[{"text":"Collect another month of data before making any recommendation.","why":"There is already enough evidence to act. Waiting a month lets the errors continue.","mis":"More data is always better than acting."}],"process":{"setup":["{Lead|the} asked you to help solve a recurring problem with {record|the} at {workplace|the}."],"steps":[{"id":"log","text":"Record the time and shift of each mistake","issue":"nodata"},{"id":"pattern","text":"Look for a pattern in those records","core":true},{"id":"past","text":"Measure what last week's checklist changed","issue":"followup"},{"id":"fix","text":"Try a fix aimed at the likely cause","core":true},{"id":"track","text":"Count mistakes again after the fix","core":true}],"rel":[["log","pattern","You need logged errors before you can find a pattern."],["pattern","fix","The pattern tells you what the fix should target."],["past","fix","Knowing whether the earlier fix worked shapes the next one."],["fix","track","You can only measure a fix after it is in place."]],"alternatesReviewed":true,"lesson":"Gather evidence, find the pattern, fix the cause, then measure the result.","because":{"nodata":["So far, nobody has kept any record of the mistakes."],"followup":["A change made a few days ago has never been evaluated."]}},"doc":{"type":"note","title":["Problem analysis: errors in {record|the}"],"intro":["{Lead|the} asked you to review this draft analysis before it goes to the team."],"lesson":"A good problem analysis separates evidence from assumptions and aims the fix at the cause.","lines":[{"id":"problem","text":"Problem: errors in {record|the} have come back every week for a month.","fine":"A clear description of the problem and how long it has lasted."},{"id":"evidence","text":"Evidence: the two-week log shows 18 of 20 errors happened on the evening shift.","fine":"Specific evidence from records."},{"id":"cause","text":"Likely cause: the evening shift uses an older version of the form.","fine":"A cause that fits the evidence.","bad":[{"id":"cause-person","level":"intermediate","text":"Likely cause: the newest employee is careless.","why":"Nothing in the evidence points to one person. The errors cluster on a shift, which suggests a process or tool cause.","principle":"ctp.doc-blame-not-supported"}]},{"id":"fix","text":"Proposed fix: replace the old forms on the evening shift.","fine":"The fix targets the likely cause.","bad":[{"id":"fix-symptom","level":"advanced","needs":["cause"],"text":"Proposed fix: have a second person recheck every form on every shift.","why":"The analysis names an old form as the cause, but this fix only catches errors after they happen and adds work on every shift.","principle":"ctp.doc-fix-ignores-cause"}]},{"id":"measure","text":"Follow-up: compare error counts for two weeks after the change.","fine":"Plans to measure whether the fix worked.","bad":[{"id":"measure-none","level":"beginner","text":"Follow-up: none needed, since the fix will obviously work.","why":"Without follow-up, no one will know whether the fix worked.","principle":"ctp.doc-no-follow-up"}]},{"id":"owner","text":"Owner: {coworker} will track the counts and report to {lead|the}.","fine":"Someone is responsible for follow-up."},{"id":"data","text":"Data source: error log kept by {coworker}.","fine":"Names the source of the evidence.","bad":[{"id":"data-rumor","level":"beginner","text":"Data source: what people in the break room have been saying.","why":"Break-room talk is not reliable evidence. The analysis needs recorded data.","principle":"ctp.doc-unreliable-data-source"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Root-cause kit. Ambiguous pairings (no data vs follow-up, pattern vs follow-up) are exclusive."}},{"id":"cus-counter-request","skill":"customer-service-orientation","family":"customer-service-orientation.cx-counter-request","familyName":"Handling a request in person","framework":"competing-priorities","concepts":["customer-service-orientation:prioritize-service","customer-service-orientation:courteous-knowledgeable","customer-service-orientation:anticipate-needs"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}. A {client} comes to you for help with {deliverable|the}.","As {role|a} at {workplace|a}, you are helping a {client} who has a question about {deliverable|the}."],"pressure":["Two more {client.plural} are waiting behind this one.","{coworker3} says you are taking too long with each person."],"detail":["It is the busiest hour of the day.","The {client} has been here before."],"tiers":{"1":"Keeping the {client} safe comes before the request.","2":"A frustrated {client} needs to feel heard before anything else lands.","3":"You can only promise what the policy and your authority allow.","4":"Give accurate answers, even if that means checking first.","5":"Pointing out a needed item helps the {client} more than a feedback question does.","6":"Inviting feedback is welcome once the request is handled."},"issues":[{"id":"hazard","tier":1,"rule":"control-hazard-first","principle":"cus.protect-client-from-hazard","fact":["You notice {hazard} right where the {client} is standing."],"short":"the hazard by the {client}","action":"Guide the {client} away from the hazard, then make sure it gets marked and reported.","brief":"move the {client} away and report the hazard","reason":"Service starts with the {client}'s safety. Moving them away prevents an injury, and reporting gets the hazard fixed.","lesson":"Protect the people you serve from hazards before handling their request.","shortcut":[{"text":"Help the {client} quickly so they can move on before anything happens.","brief":"help quickly and hope nothing happens","why":"Hurrying does not remove the hazard. The {client} could be hurt while you help.","mis":"Fast service makes a hazard less dangerous."}]},{"id":"upset","tier":2,"rule":"acknowledge-feelings","principle":"cus.acknowledge-frustration-first","noProceed":true,"fact":["The {client} is frustrated after waiting twenty minutes."],"short":"the {client}'s frustration","action":"Apologize for the wait and acknowledge the frustration before you start helping.","brief":"apologize and acknowledge the frustration","reason":"A frustrated person listens better once they feel heard. A sincere apology sets up the rest of the conversation.","lesson":"Acknowledge a customer's frustration before solving the problem.","shortcut":[{"text":"Explain that the wait was not your fault and get straight to business.","brief":"say it was not your fault","why":"Deflecting blame makes the {client} feel dismissed, even if it is true.","mis":"Explaining whose fault it was calms people down."}]},{"id":"refund","tier":3,"rule":"stay-within-authority","principle":"cus.get-approval-for-refund","fact":["The {client} wants a refund, and the posted policy says refunds over $50 need approval from {lead|the}."],"clear":["{Lead|the} already approved this refund by phone."],"done":"the refund was already approved","short":"the refund that needs approval","action":"Explain the policy politely and ask {lead|the} to approve the refund.","brief":"ask {lead|the} to approve the refund","reason":"The policy sets who can approve larger refunds. Following it, politely, is fair to everyone.","lesson":"Serve customers within the limits of your authority, and explain those limits politely.","shortcut":[{"text":"Give the refund yourself, since the {client} is a regular.","brief":"give the refund yourself","why":"The policy requires approval for refunds over $50, whoever the {client} is.","mis":"Good customers can be treated as exceptions to policy."}]},{"id":"unknown","tier":4,"rule":"find-accurate-answer","principle":"cus.find-out-instead-of-guessing","fact":["The {client} asks a detailed question about {deliverable|the} that you cannot answer."],"clear":["{coworker} already gave you the answer to the {client}'s question."],"done":"you already have the answer from {coworker}","short":"the question you cannot answer","action":"Say you will find out, and check with {coworker}, who knows the answer.","brief":"find out from {coworker}","reason":"A wrong answer can cost the {client} time and money. Saying you will check is honest and professional.","lesson":"When you do not know, find out rather than guess.","shortcut":[{"text":"Give your best guess so the {client} is not kept waiting.","brief":"give your best guess","why":"A guess that turns out wrong damages trust more than a short wait.","mis":"Any answer is better than saying you need to check."}]},{"id":"extra","tier":5,"rule":"anticipate-needs","principle":"cus.mention-related-need","noProceed":true,"fact":["From the request, you can tell the {client} will also need {supply.plural} to use it."],"short":"the {supply.plural} the {client} will need","action":"Handle the request, and mention that they will likely need {supply.plural} too.","brief":"mention the {supply.plural} they will need","reason":"Pointing out a need before the {client} discovers it later saves them a second trip.","lesson":"Anticipate what customers will need next and tell them.","shortcut":[{"text":"Say nothing, since the {client} did not ask about {supply.plural}.","brief":"say nothing about it","why":"The {client} will likely have to come back. A quick mention prevents that.","mis":"Good service means answering only what was asked."}]},{"id":"feedback","tier":6,"rule":"invite-feedback","principle":"cus.share-feedback-channel","noProceed":true,"fact":["The {client} asks how to give feedback about the visit."],"short":"the request to give feedback","action":"Tell the {client} how to leave feedback, and thank them for asking.","brief":"explain how to leave feedback","reason":"Feedback helps the workplace improve. Making it easy shows you value the {client}'s view.","lesson":"Welcome customer feedback and make it easy to give.","shortcut":[{"text":"Say feedback is not really necessary.","brief":"say feedback is unnecessary","why":"Brushing off feedback suggests the {client}'s view does not matter.","mis":"Feedback only means complaints."}]}],"exclusive":[["refund","unknown"]],"proceed":{"text":"Help the {client} with the request promptly and politely.","why":"Nothing else needs handling first, so prompt, courteous help is exactly what the {client} needs.","lesson":"Courteous, prompt help is the core of good service."},"generic":[{"text":"Send the {client} to another location that might be less busy.","why":"Sending a {client} away without trying to help is poor service.","mis":"Passing someone along is the same as helping them."},{"text":"Help the {client} while texting a friend under the counter.","why":"Divided attention feels disrespectful and leads to mistakes.","mis":"Customers do not notice when you are distracted."}],"overcaution":[{"text":"Ask {lead|the} to come and handle the {client} personally.","why":"Nothing in the situation is beyond your role. Calling the lead in delays service.","mis":"A supervisor always gives better service."}],"process":{"setup":["A {client} at {workplace|the} needs help with {deliverable|the}."],"because":{"upset":["The {client} has been waiting a long time and is frustrated."],"refund":["The {client} is asking for a refund that is larger than you can approve."],"unknown":["The {client} has a question you cannot answer yourself."]},"steps":[{"id":"greet","text":"Greet the {client} by making eye contact","core":true},{"id":"sorry","text":"Apologize for the long wait","issue":"upset"},{"id":"listen","text":"Listen to the full request","core":true},{"id":"approve","text":"Get approval from {lead|the}","issue":"refund"},{"id":"check","text":"Check the answer with {coworker}","issue":"unknown"},{"id":"resolve","text":"Complete the request and confirm it is right","core":true}],"rel":[["greet","sorry","The apology comes as part of the greeting."],["sorry","listen","Acknowledge the wait before asking them to explain."],["greet","listen","Greet before getting into the request."],["listen","approve","You need the details before asking for approval."],["listen","check","You need to know the question before checking the answer."],["approve","resolve","The refund can only be completed once approved."],["check","resolve","You complete the request with the right answer."],["listen","resolve","You resolve the request after hearing it."]],"alternatesReviewed":true,"lesson":"Greet, acknowledge, listen, get what you need, then resolve and confirm."},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Refund limit stated as a posted policy. Refund and unknown-answer are exclusive because either order is reasonable."}},{"id":"cus-callback","skill":"customer-service-orientation","family":"customer-service-orientation.cx-callback","familyName":"Following through on a promised callback","framework":"communication-failure","concepts":["customer-service-orientation:internal-and-external","customer-service-orientation:prioritize-service","customer-service-orientation:courteous-knowledgeable"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. This morning you promised a {client} a call back by 3 p.m. about a problem with {deliverable|the}.","As {role|a} at {workplace|a}, you told a {client} you would call back by 3 p.m. with an answer about {deliverable|the}."],"pressure":["It is already 2:45 p.m.","{coworker3} says {client.plural} never notice if a callback is a little late."],"detail":["The {client} left a mobile number.","You wrote the promise on a sticky note."],"tiers":{"1":"Account details are shared only after identity is confirmed.","2":"A promise you cannot keep should be updated before it is broken.","3":"Getting the {client} to the right team beats a slow answer from the wrong one.","4":"Coworkers who serve the {client} deserve the same prompt help.","5":"Following up on a fix is valuable once nothing is pending."},"issues":[{"id":"identity","tier":1,"rule":"verify-identity","principle":"cus.confirm-identity-per-policy","fact":["The person who answers asks about the account but has not confirmed their identity, which the posted policy requires."],"clear":["The person on the phone already confirmed their identity using the security questions."],"done":"the caller's identity was already confirmed","short":"the unconfirmed identity","action":"Confirm the person's identity, as the policy requires, before sharing any details.","brief":"confirm their identity","reason":"The policy protects the {client}'s information. Confirming identity first keeps it from reaching the wrong person.","lesson":"Follow identity checks before sharing account information, even when you are in a hurry.","shortcut":[{"text":"Share the details, since the person sounds like the {client}.","brief":"share details because they sound right","why":"Sounding familiar is not confirmation. The policy exists to protect the {client}.","mis":"You can tell who someone is by their voice."}]},{"id":"late","tier":2,"rule":"communicate-delay-early","principle":"cus.update-before-missing-promise","fact":["You will not have the answer by 3 p.m. as you promised."],"short":"the callback promise you cannot keep","action":"Call the {client} before 3 p.m. to explain and give a new time.","brief":"call before 3 to give a new time","reason":"A quick update keeps your word in spirit and shows the {client} you have not forgotten them.","lesson":"If you cannot keep a promise, update the customer before the deadline passes.","shortcut":[{"text":"Wait until you have the answer, even if that means calling tomorrow.","brief":"wait until you have the answer","why":"Silence after a promised call feels like being ignored. A short update prevents that.","mis":"Calling without an answer is pointless."}]},{"id":"wrongteam","tier":3,"rule":"route-to-right-team","principle":"cus.warm-handoff-to-right-team","fact":["You learn that the question really belongs to the billing team, not yours."],"short":"the question belonging to billing","action":"Connect the {client} with billing and pass along what they already told you.","brief":"connect them to billing with the details","reason":"Passing along the details means the {client} does not have to explain everything again.","lesson":"When handing a customer to another team, pass along what you know.","shortcut":[{"text":"Give the {client} the billing number and let them start over.","brief":"give them the billing number","why":"Making the {client} repeat everything is frustrating and wastes their time.","mis":"Giving a phone number is the same as a handoff."}]},{"id":"internal","tier":4,"rule":"serve-internal-customer","principle":"cus.respond-to-internal-request","fact":["{coworker} in billing asks you for the order details so they can help the {client}."],"short":"{coworker}'s request for the order details","action":"Send {coworker} the order details promptly, as you would for any {client}.","brief":"send {coworker} the details promptly","reason":"Coworkers who depend on you are internal customers. Helping them quickly helps the {client} too.","lesson":"Treat coworkers who need your help as customers too.","shortcut":[{"text":"Tell {coworker} you will get to it after your own callbacks.","brief":"make {coworker} wait","why":"Delaying the details delays the {client}'s answer.","mis":"Internal requests matter less than external ones."}],"clear":["You already sent {coworker} the order details this morning."],"done":"the details were already sent to {coworker}"},{"id":"follow","tier":5,"rule":"follow-up-on-fix","principle":"cus.confirm-fix-satisfied-client","noProceed":true,"fact":["The problem was fixed yesterday, but nobody has checked whether the {client} is happy with the result."],"short":"the unconfirmed fix","action":"Ask the {client} whether the fix worked and whether anything else is needed.","brief":"ask whether the fix worked","reason":"A short follow-up confirms the problem is really solved and shows you care about the result.","lesson":"Follow up to make sure a fix actually worked for the customer.","shortcut":[{"text":"Assume the {client} is happy, since nobody has complained.","brief":"assume they are happy","why":"Silence does not mean satisfaction. A short check catches problems early.","mis":"No complaint means a happy customer."}]}],"exclusive":[["late","follow"],["wrongteam","follow"],["wrongteam","internal"]],"proceed":{"text":"Call the {client} back at the promised time with the answer.","why":"You have the answer and nothing else needs handling, so keeping the promise is the right move.","lesson":"Keep your service promises on time."},"generic":[{"text":"Email the {client} a long explanation instead of calling as promised.","why":"You promised a call. Changing the format without asking can feel like avoidance.","mis":"Any form of contact keeps the promise."},{"text":"Ask {coworker2} to make the call so you can leave early.","why":"The promise was yours. Handing it off to leave early is unreliable service.","mis":"Anyone can keep a promise you made."}],"overcaution":[{"text":"Check with {lead|the} before making the call.","why":"You have everything needed. Checking with the lead first could make you late.","mis":"Every customer call needs supervisor approval."}],"doc":{"type":"email","title":["Your follow-up email to the {client}"],"intro":["You are about to email the {client} after this morning's call. Check the message first."],"lesson":"Service messages should be courteous, accurate and clear about what happens next.","lines":[{"id":"thanks","text":"Thank you for your patience while we looked into the problem.","fine":"Courteous and acknowledges the wait."},{"id":"status","text":"Our billing team has the details you gave me, so you will not need to repeat them.","fine":"Explains a warm handoff.","bad":[{"id":"status-repeat","level":"intermediate","text":"Please call billing and explain the whole problem to them from the beginning.","why":"Making the {client} repeat everything is frustrating. The details should be passed along.","principle":"cus.doc-cold-handoff"}]},{"id":"when","text":"You can expect a call from {coworker} in billing by noon tomorrow.","fine":"Gives a specific next step and time.","bad":[{"id":"when-vague","level":"beginner","text":"Someone will probably get back to you at some point.","why":"A vague promise leaves the {client} unsure what happens next.","principle":"cus.doc-vague-next-step"}]},{"id":"contact","text":"If you have questions before then, reply to this email.","fine":"Offers a way to follow up.","bad":[{"id":"contact-none","level":"beginner","text":"Please do not reply to this email.","why":"Cutting off replies leaves the {client} no way to ask questions.","principle":"cus.doc-blocks-replies"}]},{"id":"tone","text":"We are sorry for the trouble this caused.","fine":"A sincere apology.","bad":[{"id":"tone-blame","level":"beginner","text":"This would have been simpler if you had read the instructions.","why":"Blaming the {client} is discourteous and damages the relationship.","principle":"cus.doc-blames-client"}]},{"id":"account","text":"For your security, we will not include account numbers in email.","fine":"Protects the {client}'s information.","bad":[{"id":"account-sent","level":"advanced","text":"Your full account number and security answers are listed below for reference.","why":"Sending account numbers and security answers by email puts the {client}'s information at risk.","principle":"cus.doc-exposes-account-details"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Identity check stated as posted policy."}},{"id":"eff-morning-plan","skill":"efficiency-and-productivity","family":"efficiency-and-productivity.cx-planning-the-day","familyName":"Planning a crowded workday","framework":"competing-priorities","concepts":["efficiency-and-productivity:work-plan","efficiency-and-productivity:prioritize-tasks","efficiency-and-productivity:adapt-goals"],"contexts":"any","setup":["You work as {role|a} at {workplace|a} and have a long list of tasks for today.","As {role|a} at {workplace|a}, you are planning a day with more tasks than usual."],"pressure":["{coworker3} says to just start at the top of the list and keep going.","You have already lost 20 minutes to a late start."],"detail":["The list is written on the whiteboard.","Your lunch break is at noon."],"tiers":{"1":"The task with the nearest fixed deadline has to come first.","2":"Work that is blocked should be moved, not waited on.","3":"A large task due later needs a start today.","4":"Protecting focused time makes every task faster.","5":"Grouping similar tasks saves time once the order is set."},"issues":[{"id":"due10","tier":1,"rule":"prioritize-deadline","principle":"eff.nearest-deadline-first","fact":["One task on the list is due to a {client} by 10 a.m."],"clear":["You finished the 10 a.m. task before leaving yesterday."],"done":"the 10 a.m. task is already finished","short":"the 10 a.m. deadline","action":"Do the task that is due at 10 a.m. first.","brief":"do the 10 a.m. task","reason":"A fixed deadline in a few hours outranks tasks with more time. Missing it affects a {client}.","lesson":"Put the tasks with the nearest fixed deadlines first.","shortcut":[{"text":"Start with the quick, easy tasks to build momentum.","brief":"start with the easy tasks","why":"Easy tasks feel productive, but they can push the urgent task past its deadline.","mis":"Easy tasks first is always efficient."}]},{"id":"blocked","tier":2,"rule":"reorder-around-blocker","principle":"eff.work-around-blocked-task","fact":["One task cannot start until {coworker} sends a file this afternoon."],"clear":["{coworker} already sent the file you were waiting for."],"done":"the file already arrived","short":"the blocked task","action":"Move that task to the afternoon and work on tasks you can do now.","brief":"move it later and do what you can now","reason":"Waiting on a blocked task wastes the morning. Reordering keeps you productive.","lesson":"Plan around blocked tasks instead of waiting on them.","shortcut":[{"text":"Wait at your desk until {coworker} sends the file.","brief":"wait for the file","why":"Waiting all morning wastes time that other tasks could use.","mis":"You should do tasks strictly in list order."}]},{"id":"large","tier":3,"rule":"break-down-large-task","principle":"eff.start-large-task-early","fact":["A large task due Friday has not been started yet."],"short":"the unstarted large task","action":"Break the large task into steps and schedule the first step today.","brief":"break it into steps and start one today","reason":"Large tasks left until the end become rushed. Small scheduled steps make Friday realistic.","lesson":"Break big tasks into steps and start them early.","shortcut":[{"text":"Leave the large task until Thursday, when there is more time.","brief":"leave it until Thursday","why":"Waiting until Thursday leaves no room for problems.","mis":"Big tasks are best done all at once at the end."}],"clear":["You already broke the Friday task into steps and scheduled them this week."],"done":"the large task is already broken into scheduled steps"},{"id":"interrupt","tier":4,"rule":"protect-focus-time","principle":"eff.batch-messages","noProceed":true,"fact":["Messages keep interrupting you every few minutes."],"short":"the constant interruptions","action":"Set aside blocks of focused time and check messages between them.","brief":"check messages between focus blocks","reason":"Constant switching slows every task. Checking at set times keeps you responsive and focused.","lesson":"Protect focused time by handling messages in batches.","shortcut":[{"text":"Answer every message the moment it arrives.","brief":"answer every message instantly","why":"Answering instantly breaks your focus every few minutes.","mis":"Instant replies are always the most productive."}]},{"id":"batch","tier":5,"rule":"group-similar-tasks","principle":"eff.group-setup-tasks","noProceed":true,"fact":["Three small tasks on the list all need {equipment|the} set up."],"short":"the three tasks that share a setup","action":"Group the three tasks so {equipment|the} is set up only once.","brief":"group the three tasks","reason":"Setting up once instead of three times saves real time.","lesson":"Group tasks that share setup or tools.","shortcut":[{"text":"Do the three tasks at different times as they come up on the list.","brief":"do them at separate times","why":"Setting up three separate times wastes effort.","mis":"Task order on the list is the most efficient order."}]}],"proceed":{"text":"Work through the tasks in order of importance and deadline.","why":"Nothing on the list needs special handling, so working by importance and deadline is the efficient plan.","lesson":"Order work by importance and deadline, and adjust as things change."},"generic":[{"text":"Spend the first hour making a detailed color-coded schedule.","why":"A short plan helps, but an hour of planning eats time the tasks need.","mis":"More planning always means more productivity."},{"text":"Ask {coworker2} to take half of your list without checking with {lead|the}.","why":"Shifting work without checking can overload a coworker and confuse the plan.","mis":"Handing off work is the fastest fix for a full list."}],"overcaution":[{"text":"Ask {lead|the} to rank every task for you before starting.","why":"The priorities are clear. Asking the lead to rank everything delays the start.","mis":"Only a supervisor can set your priorities."}],"process":{"setup":["You are {role|a} at {workplace|a}, organizing a full day of tasks."],"because":{"due10":["Something on the list is due to a {client} this morning."],"large":["A big task due later this week has not been started."],"batch":["Several small tasks need the same equipment."]},"steps":[{"id":"list","text":"List every task with its deadline","core":true},{"id":"urgent","text":"Finish the 10 a.m. task","issue":"due10"},{"id":"group","text":"Group the tasks that share a setup","issue":"batch"},{"id":"split","text":"Split the big task into steps","issue":"large"},{"id":"work","text":"Work through the rest of the plan","core":true},{"id":"review","text":"Review what is left at the end of the day","core":true}],"rel":[["list","urgent","You need the full list to confirm what is most urgent."],["urgent","work","The deadline task comes before the rest."],["list","group","Grouping happens once you see all the tasks."],["group","work","Grouped tasks are planned before you start them."],["list","split","You see the big task when you list everything."],["split","work","The first step of the big task goes into today's plan."],["list","work","Plan before working."],["work","review","You review once the work is done."]],"alternatesReviewed":true,"lesson":"List everything, handle deadlines, organize the rest, work, then review."},"doc":{"type":"schedule","title":["Your plan for today"],"intro":["You drafted today's plan. Check it before you start."],"lesson":"An efficient plan puts fixed deadlines first and works around blocked tasks.","lines":[{"id":"a","text":"8:00 - Finish the {client} task due at 10 a.m.","fine":"The nearest deadline comes first."},{"id":"b","text":"9:30 - Set up {equipment|the} and do all three tasks that need it.","fine":"Groups tasks that share a setup.","bad":[{"id":"b-split","level":"intermediate","text":"9:30 - Set up {equipment|the} for one task; set it up again at 1:00 and 3:00 for the others.","why":"Setting up three times wastes time when the tasks could be grouped.","principle":"eff.doc-repeated-setup"}]},{"id":"c","text":"11:00 - First step of the large Friday task.","fine":"Starts the big task early.","bad":[{"id":"c-later","level":"beginner","text":"11:00 - Leave the large Friday task until Thursday night.","why":"Waiting until the last night leaves no room for problems.","principle":"eff.doc-delays-large-task"}]},{"id":"d","text":"1:00 - Task that needs {coworker}'s file, which arrives after lunch.","fine":"Schedules the blocked task after the file arrives.","bad":[{"id":"d-early","level":"advanced","needs":["a"],"text":"8:00 - Task that needs {coworker}'s file, which arrives this afternoon.","why":"The file will not arrive until the afternoon, and 8:00 is already set aside for the 10 a.m. deadline.","principle":"eff.doc-schedules-blocked-task-early"}]},{"id":"e","text":"Check messages at 9:30, 11:30, 1:30 and 3:30.","fine":"Batches messages to protect focus.","bad":[{"id":"e-constant","level":"beginner","text":"Answer every message the moment it arrives, all day.","why":"Constant interruptions slow every task.","principle":"eff.doc-constant-interruptions"}]},{"id":"f","text":"4:30 - Review what is left and plan tomorrow.","fine":"Ends with a review.","bad":[{"id":"f-none","level":"beginner","text":"4:30 - Leave without checking what is left.","why":"Skipping the review means unfinished tasks are forgotten.","principle":"eff.doc-no-end-review"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Prioritization by deadline, dependency and effort."}},{"id":"eff-resources","skill":"efficiency-and-productivity","family":"efficiency-and-productivity.cx-using-resources-well","familyName":"Using people, tools and materials well","framework":"consequences","concepts":["efficiency-and-productivity:human-resources","efficiency-and-productivity:capital-resources","efficiency-and-productivity:natural-resources"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you and the team to finish a large job for a {client} by tomorrow.","As {role|a} at {workplace|a}, you are coordinating today's work on a big job for a {client}."],"pressure":["{coworker3} says the fastest way is to just throw everything at it.","The job is the biggest one this month."],"detail":["The team has four people today.","The work area is clean and ready."],"tiers":{"1":"Equipment that is failing has to be dealt with before it wastes the whole order.","2":"Matching tasks to people's skills makes the team faster.","3":"Materials wasted now cost money the order cannot recover.","4":"Idle time is a resource too.","5":"Saving energy is worthwhile once the work is organized."},"issues":[{"id":"machine","tier":1,"rule":"maintain-equipment","principle":"eff.report-failing-equipment","fact":["{Equipment|the} has started making a grinding noise and slowing down."],"short":"the failing equipment","action":"Stop using {equipment|the} and report the noise to {lead|the} so it can be checked.","brief":"stop and report the equipment noise","reason":"Running failing equipment can break it completely and ruin work in progress. Reporting it early protects the order.","lesson":"Care for equipment by reporting problems before they become breakdowns.","shortcut":[{"text":"Keep running it until the order is done, then report it.","brief":"run it until the order is done","why":"Failing equipment can break mid-order and damage more work.","mis":"Equipment problems can wait until the job is finished."}]},{"id":"skills","tier":2,"rule":"match-tasks-to-people","principle":"eff.assign-by-skill","fact":["{coworker} is fastest at the detailed step, but has been assigned to stocking."],"short":"the mismatched assignments","action":"Suggest switching assignments so {coworker} does the detailed step.","brief":"suggest moving {coworker} to the detailed step","reason":"Putting people where their skills fit speeds up the whole team.","lesson":"Use people's strengths when assigning work.","shortcut":[{"text":"Keep the assignments, since changing them might upset people.","brief":"keep the assignments","why":"A quick, respectful suggestion is unlikely to upset anyone and saves real time.","mis":"Assignments should never change once made."}]},{"id":"waste","tier":3,"rule":"reduce-waste","principle":"eff.cut-material-waste","fact":["You notice the team is opening new {supply.plural} while half-used ones sit on the shelf."],"short":"the wasted {supply.plural}","action":"Point out the half-used {supply.plural} and suggest using those first.","brief":"use the half-used supplies","reason":"Using what is already open saves materials and money without slowing the work.","lesson":"Use materials fully before opening new ones.","shortcut":[{"text":"Ignore it, since new {supply.plural} are faster to grab.","brief":"ignore the waste","why":"Small waste repeated across a big order adds up.","mis":"Speed always outweighs saving materials."}]},{"id":"idle","tier":4,"rule":"use-idle-time","principle":"eff.fill-idle-time","fact":["{coworker2} is waiting with nothing to do until the next batch is ready."],"short":"{coworker2}'s idle time","action":"Suggest {coworker2} prepare the labels for the next batch while waiting.","brief":"have {coworker2} prep labels while waiting","reason":"Idle time is a lost resource. Useful prep work keeps the whole order moving.","lesson":"Find useful work for idle time.","shortcut":[{"text":"Let {coworker2} wait, since the batch will be ready soon.","brief":"let {coworker2} wait","why":"Waiting time adds up across the day when useful prep work is available.","mis":"Short waits do not matter."}]},{"id":"energy","tier":5,"rule":"reduce-waste","principle":"eff.switch-off-unused-equipment","noProceed":true,"fact":["Two machines in the area are running even though nobody is using them."],"short":"the idle machines","action":"Switch off the unused machines, following their normal shutdown steps.","brief":"switch off the unused machines","reason":"Idle machines waste energy and add wear for no benefit.","lesson":"Conserve energy by switching off equipment that is not in use.","shortcut":[{"text":"Leave them running, since turning them back on takes time.","brief":"leave them running","why":"If they are not needed, leaving them on only wastes energy.","mis":"Equipment should always stay on in case it is needed."}]}],"proceed":{"text":"Keep the team working through the order as planned.","why":"People, equipment and materials are being used well, so the plan should continue.","lesson":"When resources are used well, keep the work moving as planned."},"generic":[{"text":"Ask {lead|the} to bring in extra staff right away.","why":"Extra staff costs money and may not be needed if current resources are used well.","mis":"More people always means faster work."},{"text":"Order extra {supply.plural} just in case.","why":"Ordering extra without checking needs ties up money and space.","mis":"Having extra is always efficient."}],"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Human, capital and natural resources."}},{"id":"ili-finding-answer","skill":"information-literacy","family":"information-literacy.cx-checking-sources","familyName":"Checking sources before answering a question","framework":"evidence-reliability","concepts":["information-literacy:evaluate-credibility","information-literacy:judge-relevance","information-literacy:locate-sources"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to find out how {supply.plural} should be stored, and you found an answer online.","As {role|a} at {workplace|a}, you are researching the right way to store {supply.plural} for {lead|the}."],"pressure":["{coworker3} says the first search result is usually good enough.","{Lead|the} wants an answer by the end of the day."],"detail":["You searched on the break-room computer.","The answer will be posted in the stockroom."],"issues":[{"id":"ad","tier":1,"rule":"check-source-bias","principle":"ili.check-seller-claim","onlyLevels":["beginner"],"fact":["The answer you found comes from a company advertising its own storage cabinets."],"short":"the source selling a product","action":"Compare the answer with the manufacturer's instructions or another independent source.","reason":"A company selling a product has a reason to slant its advice. An independent source tells you whether the claim holds up.","lesson":"Consider whether a source benefits from what it tells you.","shortcut":[{"text":"Use the answer, since the company knows a lot about storage.","why":"Expertise does not remove the interest in selling. The claim still needs checking.","mis":"A company's advertising is a neutral source."}]},{"id":"old","tier":2,"rule":"check-currency","principle":"ili.find-current-version","onlyLevels":["beginner"],"fact":["The guide you found was published eight years ago."],"clear":["You checked, and the guide was updated earlier this year."],"done":"the guide was already confirmed as current","short":"the eight-year-old guide","action":"Look for a current version before relying on it.","reason":"Products and guidance change. An eight-year-old guide may no longer be correct.","lesson":"Check that information is current before using it.","shortcut":[{"text":"Use it, since storage advice does not really change.","why":"Product formulas and packaging change. You need to confirm the advice is still current.","mis":"Older information is as good as new."}]},{"id":"forum","tier":3,"rule":"verify-unsourced-claim","principle":"ili.verify-forum-claim","onlyLevels":["beginner"],"fact":["The answer comes from an anonymous forum post that cites no source."],"clear":["The forum post links to the manufacturer's official storage instructions."],"done":"the post already links to the official instructions","short":"the unsourced forum post","action":"Check the claim against an official or expert source before using it.","reason":"Anyone can post anything. An unsourced claim needs confirming before you rely on it.","lesson":"Verify claims that have no identifiable author or source.","shortcut":[{"text":"Use the post, since it has many likes.","why":"Popularity is not evidence. Many people can agree with a wrong claim.","mis":"Popular posts are accurate."}]},{"id":"home","tier":4,"rule":"judge-relevance","principle":"ili.match-source-to-question","onlyLevels":["beginner"],"fact":["The source explains storage for home use, but your question is about storing large amounts at work."],"short":"the source about home use","action":"Find a source that covers storing large amounts at a workplace.","reason":"A reliable source can still be irrelevant. Storage at work may have different requirements.","lesson":"Make sure a source actually answers your question.","shortcut":[{"text":"Use the home advice, since storage is storage.","why":"Large amounts at work can raise issues home advice does not cover.","mis":"Any reliable source answers any related question."}]},{"id":"cite","tier":5,"rule":"credit-source","principle":"ili.include-source-with-answer","onlyLevels":["beginner"],"noProceed":true,"fact":["You plan to post the answer without saying where it came from."],"short":"the missing source","action":"Include where the information came from when you share it.","reason":"Naming the source lets others check it and trust the answer.","lesson":"Share information with its source so others can check it.","shortcut":[{"text":"Leave out the source, since nobody will ask.","why":"Without the source, nobody can check the answer or update it later.","mis":"Sources only matter in school."}]}],"proceed":{"text":"Share the answer with {lead|the}, along with where it came from.","why":"The source is current, credible and relevant, so it is ready to share.","lesson":"Share information once it is checked, and say where it came from."},"generic":[{"text":"Ask {coworker2} what they think and post that instead.","why":"A coworker's opinion is not a checked source.","mis":"A coworker's guess is as good as research."},{"text":"Post several different answers so people can choose.","why":"Conflicting answers confuse people. Your job is to find the reliable one.","mis":"Giving every answer is the safest choice."}],"overcaution":[{"text":"Keep searching for another hour to be completely certain.","why":"The source already checks out. More searching delays the answer for little gain.","mis":"You can never check a source enough."}],"process":{"setup":["{Lead|the} at {workplace|the} asked you to find reliable storage guidance for {supply.plural}."],"steps":[{"id":"define","text":"Write down exactly what you need to know","core":true},{"id":"search","text":"Search for sources","core":true},{"id":"evaluate","text":"Check each source's author, date and purpose","core":true},{"id":"share","text":"Share the answer with its source","core":true}],"rel":[["define","search","A clear question makes searching faster and more relevant."],["search","evaluate","You evaluate sources after finding them."],["evaluate","share","Only share information that passed your checks."]],"alternatesReviewed":true,"lesson":"Define the question, search, evaluate the sources, then share with credit."},"doc":{"type":"note","title":["Posted note: storing {supply.plural}"],"intro":["You are checking this note before it is posted in the stockroom."],"prompt":["Which statement is not supported by reliable information?","Which line is the problem?"],"lesson":"Information you share should be current, relevant, credible and credited.","lines":[{"id":"store","text":"Store {supply.plural} in a cool, dry place off the floor.","fine":"Common, sensible storage guidance."},{"id":"source","text":"Source: manufacturer's storage instructions, updated this year.","fine":"Credible, current and credited.","bad":[{"id":"source-forum","level":"intermediate","text":"Source: a forum post with no author listed.","why":"An anonymous post with no source is not reliable enough to post as guidance.","principle":"ili.doc-unreliable-source"}]},{"id":"stack","text":"Do not stack more than four boxes high, per the instructions.","fine":"A specific claim tied to the source."},{"id":"date","text":"Use older stock first.","fine":"Standard stock rotation.","bad":[{"id":"date-claim","level":"advanced","needs":["source"],"text":"{supply.plural|cap} never expire, so dates do not matter.","why":"Nothing in the cited instructions supports this, and many supplies do expire.","principle":"ili.doc-unsupported-claim"}]},{"id":"home","text":"Keep the storage area labeled and organized.","fine":"General good practice.","bad":[{"id":"home-tip","level":"beginner","text":"Tip from a home-organizing blog: store them under the kitchen sink.","why":"Home advice does not fit workplace storage, and the source is not relevant.","principle":"ili.doc-irrelevant-source"}]},{"id":"contact","text":"Questions: ask {lead|the}.","fine":"Tells readers where to go with questions.","bad":[{"id":"contact-none","level":"beginner","text":"Questions: just do what seems right.","why":"Readers need someone to ask when the guidance is unclear.","principle":"ili.doc-no-contact"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Source-evaluation criteria are not strictly ordered, so state issues are beginner-only; intermediate and advanced come from the data kit and document."}},{"id":"ili-report-data","skill":"information-literacy","family":"information-literacy.cx-using-data-in-a-report","familyName":"Using data accurately in a report","framework":"evidence-reliability","concepts":["information-literacy:use-information","information-literacy:evaluate-credibility","information-literacy:locate-sources"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to write a short report on last month's numbers for {task|the}.","As {role|a} at {workplace|a}, you are putting together a report on how {task|the} went last month."],"pressure":["{coworker3} says the report just needs to look good.","The report is due at the morning meeting."],"detail":["The data is in a shared spreadsheet.","The report will be one page long."],"tiers":{"1":"Using the wrong data makes every number in the report wrong.","2":"Gaps in the data have to be understood before you calculate.","3":"The report can only claim what the data shows.","4":"Readers need to know where the numbers came from."},"issues":[{"id":"wrongfile","tier":1,"rule":"verify-data-source","principle":"ili.confirm-correct-dataset","fact":["The spreadsheet you were sent has last year's dates on every row."],"clear":["{coworker} confirmed the spreadsheet is last month's data."],"done":"the spreadsheet was already confirmed as current","short":"the spreadsheet with last year's dates","action":"Ask {coworker} for the correct, current spreadsheet before you start.","brief":"get the current spreadsheet","reason":"A report built on the wrong year's data is wrong from the start.","lesson":"Make sure you have the right data before analyzing it.","shortcut":[{"text":"Use it anyway, since last year was probably similar.","brief":"use last year's data","why":"Last year's numbers do not describe last month, which is what the report is about.","mis":"Similar data is good enough."}]},{"id":"blanks","tier":2,"rule":"investigate-gaps","principle":"ili.understand-missing-data","fact":["Several days in the spreadsheet are blank."],"clear":["{coworker} explained that the blank days were when {workplace|the} was closed."],"done":"you already know why the days are blank","short":"the blank days","action":"Find out why those days are blank before calculating any totals.","brief":"find out why days are blank","reason":"Blanks could mean closures or missing records. The answer changes how you calculate the totals.","lesson":"Understand gaps in data before drawing conclusions from it.","shortcut":[{"text":"Count the blank days as zero and keep going.","brief":"count blanks as zero","why":"If the blanks are missing records, counting them as zero makes the totals wrong.","mis":"Blank always means zero."}]},{"id":"overclaim","tier":3,"rule":"report-what-data-shows","principle":"ili.no-claims-beyond-data","fact":["{coworker2} wants the report to say results doubled, but the data shows a 20 percent rise."],"short":"the claim that results doubled","action":"Report the 20 percent rise the data actually shows.","brief":"report the actual 20 percent rise","reason":"A report has to match its data. Overstating results misleads the people who decide based on it.","lesson":"Claim only what your data supports.","shortcut":[{"text":"Say results nearly doubled, since that sounds more impressive.","brief":"say results nearly doubled","why":"A 20 percent rise is nowhere near double. The claim would mislead readers.","mis":"Rounding up results is harmless."}]},{"id":"nosource","tier":4,"rule":"credit-source","principle":"ili.cite-data-source","noProceed":true,"fact":["Your draft does not say where any of the numbers came from."],"short":"the missing data source","action":"Add a line naming the spreadsheet and the dates it covers.","brief":"name the data source","reason":"Naming the source lets readers check the numbers and trust the report.","lesson":"Say where your numbers come from.","shortcut":[{"text":"Leave it out, since everyone trusts your numbers.","brief":"leave the source out","why":"Trust is not a substitute for a source that others can check.","mis":"Good reputations make sources unnecessary."}],"clear":["Your draft already names the spreadsheet and the dates it covers."],"done":"the source line is already in the draft"}],"proceed":{"text":"Write the report from the data and send it to {lead|the}.","why":"The data is correct and understood, so the report can be written and shared.","lesson":"Once the data checks out, report it accurately and clearly."},"generic":[{"text":"Write the report from memory to save time.","why":"Memory is not data. The report needs the real numbers.","mis":"You remember the numbers well enough."},{"text":"Copy last month's report and change the date.","why":"Old numbers do not describe the new month.","mis":"Reports from month to month are interchangeable."}],"overcaution":[{"text":"Ask {lead|the} to recheck the whole spreadsheet before you begin.","why":"The data is already confirmed. A full recheck delays the report.","mis":"Data always needs a supervisor's check."}],"process":{"setup":["You are preparing a short report on last month's numbers at {workplace|the}."],"because":{"blanks":["Some days in the data have no entries."],"nosource":["The report must say where its figures came from."]},"steps":[{"id":"confirm","text":"Confirm you have last month's spreadsheet","core":true},{"id":"gaps","text":"Find out why some days are empty","issue":"blanks"},{"id":"calc","text":"Calculate the totals","core":true},{"id":"write","text":"Write what the totals show","core":true},{"id":"cite","text":"Add a line naming the data source","issue":"nosource"}],"rel":[["confirm","gaps","You check gaps in the right data."],["gaps","calc","How you treat the gaps changes the totals."],["confirm","calc","You calculate from the confirmed data."],["calc","write","The writing reports the totals."],["confirm","cite","You can only name the source once it is confirmed."],["write","cite","The source line goes into the finished report."]],"alternatesReviewed":true,"lesson":"Confirm the data, understand its gaps, calculate, report, and cite."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Use of information; numbers are qualitative (20 percent vs doubled)."}},{"id":"ili-service-schedule","skill":"information-literacy","family":"information-literacy.cx-conflicting-guidance","familyName":"Sorting out conflicting guidance","framework":"evidence-reliability","concepts":["information-literacy:evaluate-credibility","information-literacy:judge-relevance","information-literacy:use-information","information-literacy:locate-sources"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to find out how often {equipment|the} should be serviced.","As {role|a} at {workplace|a}, you are researching the right service schedule for {equipment|the}."],"pressure":["{coworker3} says to just pick whichever answer sounds right.","{Lead|the} wants the answer today."],"detail":["The current schedule was set years ago.","You have about an hour for this."],"tiers":{"1":"The most authoritative source should settle a disagreement.","2":"A source has to match your exact equipment.","3":"Guidance has to be current.","4":"A coworker's memory should be checked against the source.","5":"Share the answer with where it came from."},"issues":[{"id":"websites","tier":1,"rule":"seek-authoritative-source","principle":"ili.use-manufacturer-source","fact":["Two websites give different service schedules for {equipment|the}."],"short":"the conflicting websites","action":"Check the manufacturer's manual for {equipment|the}, the most authoritative source.","brief":"check the manufacturer's manual","reason":"The manufacturer knows the equipment best. Its manual settles what random websites disagree about.","lesson":"When sources conflict, go to the most authoritative one.","shortcut":[{"text":"Pick the website that appears first in the search.","brief":"use the top search result","why":"Search ranking is not a measure of accuracy.","mis":"The first result is the most reliable."}]},{"id":"model","tier":2,"rule":"judge-relevance","principle":"ili.match-exact-model","fact":["The manual you found is for a different model of {equipment}."],"short":"the manual for a different model","action":"Find the manual for your exact model before using its schedule.","brief":"find your exact model's manual","reason":"Different models can need different service schedules.","lesson":"Make sure a source fits your exact situation.","shortcut":[{"text":"Use it, since the models are probably similar.","brief":"use the other model's manual","why":"Similar is not the same; schedules can differ by model.","mis":"Close enough is good enough."}],"clear":["You confirmed the manual matches the model number on {equipment|the}."],"done":"the manual already matches your model"},{"id":"old","tier":3,"rule":"check-currency","principle":"ili.check-manual-revision","fact":["The manual page you are using is from an older printing."],"short":"the older printing","action":"Check whether an updated version of the manual exists.","brief":"check for an updated manual","reason":"Manufacturers update schedules; an older printing may be out of date.","lesson":"Check that guidance is current.","shortcut":[{"text":"Use it, since manuals rarely change.","brief":"use the older printing","why":"Schedules do get revised. A quick check prevents relying on old guidance.","mis":"Manuals never change."}],"clear":["The manufacturer's site shows this is the latest version of the manual."],"done":"the manual is already confirmed as the latest"},{"id":"memory","tier":4,"rule":"verify-against-source","principle":"ili.check-coworker-memory","fact":["{coworker} insists the schedule learned years ago is still right."],"short":"{coworker}'s remembered schedule","action":"Thank {coworker}, and compare that schedule with the current manual.","brief":"compare {coworker}'s schedule with the manual","reason":"Experience is valuable but memory can be outdated; the manual confirms it.","lesson":"Check remembered information against a reliable source.","shortcut":[{"text":"Go with {coworker}'s schedule, since experience beats manuals.","brief":"go with {coworker}'s memory","why":"Memory can be outdated or mistaken; it needs checking.","mis":"Experience is always right."}]},{"id":"cite","tier":5,"rule":"credit-source","principle":"ili.cite-manual-page","fact":["You plan to tell the team the schedule without saying where it came from."],"short":"the unnamed source","action":"Share the schedule along with the manual page it came from.","brief":"share it with the source","reason":"Naming the source lets others check it and update it later.","lesson":"Share information with its source.","shortcut":[{"text":"Just tell everyone the schedule, since the source does not matter.","brief":"share it without a source","why":"Without the source, nobody can verify or update the schedule.","mis":"Sources only matter in school."}],"noProceed":true}],"exclusive":[["websites","model"],["websites","old"]],"proceed":{"text":"Share the manual's schedule, and where it came from, with {lead|the}.","why":"The source is authoritative, relevant and current, so the answer is ready.","lesson":"Share information once you know it is reliable, relevant and current."},"generic":[{"text":"Average the different schedules you found.","why":"Averaging conflicting sources produces a number nobody recommended.","mis":"Averaging conflicting information makes it accurate."},{"text":"Ask {lead|the} to decide without telling them what you found.","why":"The lead asked you to research it; withholding the findings wastes the work.","mis":"Research should end with someone else deciding blind."}],"overcaution":[{"text":"Call the manufacturer to confirm the manual says what it says.","why":"The manual is already current and matches your model; calling adds nothing.","mis":"No written source can be trusted."}],"doc":{"type":"note","title":["Service schedule note for {equipment|the}"],"intro":["Check this note before it is posted next to {equipment|the}."],"prompt":["Which statement is not supported by reliable information?","Which line is the problem?"],"lesson":"Posted guidance should come from the authoritative, current source for your exact equipment.","lines":[{"id":"sched","text":"Service every 90 days, per the manufacturer's manual.","fine":"Authoritative and credited."},{"id":"model","text":"Manual matches the model number on the label.","fine":"Confirms relevance.","bad":[{"id":"model-other","level":"intermediate","text":"Manual is for a similar model; ours should be about the same.","why":"A different model's manual may not apply.","principle":"ili.doc-wrong-model-source"}]},{"id":"date","text":"Manual version: latest, checked this month.","fine":"Confirms currency.","bad":[{"id":"date-old","level":"beginner","text":"Manual version: an old printing we found in a drawer.","why":"An old printing may have outdated guidance.","principle":"ili.doc-outdated-source"}]},{"id":"log","text":"Record each service in {record|the}.","fine":"Useful practice."},{"id":"forum","text":"Questions: see the manual or ask {lead|the}.","fine":"Points to reliable help.","bad":[{"id":"forum-web","level":"beginner","text":"Questions: search online and use any answer that sounds right.","why":"Unvetted online answers are not reliable guidance.","principle":"ili.doc-unvetted-web-help"}]},{"id":"sched2","text":"Next service due: 90 days after the last entry in the log.","fine":"Consistent with the schedule.","bad":[{"id":"sched2-conflict","level":"advanced","needs":["sched"],"text":"Next service due: once a year.","why":"This contradicts the manual's 90-day schedule stated above.","principle":"ili.doc-contradicts-source"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Source evaluation with an explicit priority: authority, relevance, currency, corroboration, citation."}},{"id":"ise-suspicious-email","skill":"information-security","family":"information-security.cx-suspicious-email","familyName":"An email that might be a scam","framework":"evidence-reliability","concepts":["information-security:cyber-threats","information-security:security-procedures"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. An email arrives that appears to come from {lead|the}, asking you to handle something right away.","As {role|a} at {workplace|a}, you get an email that looks like it is from {lead|the}."],"pressure":["{coworker3} says these warnings are overblown and to just get it done.","You are in the middle of a busy afternoon."],"detail":["The email arrived at 2:14 p.m.","The email has the workplace logo at the top."],"tiers":{"1":"Handing over a password can expose every system you can reach.","2":"Confirming who sent a message comes before acting on it.","3":"An unexpected attachment stays closed until the sender is confirmed.","4":"Spreading a suspicious email puts more people at risk."},"issues":[{"id":"password","tier":1,"rule":"protect-credentials","principle":"ise.never-enter-password-from-email-link","fact":["The email asks you to confirm your password through a link, and the security policy says never to do that."],"short":"the request for your password","action":"Leave the link alone and report the email the way the security policy describes.","brief":"skip the link and report the email","reason":"Password requests through email links are a common scam. Reporting it protects you and warns the security team.","lesson":"Never enter your password through a link in an unexpected email; report it instead.","shortcut":[{"text":"Click the link just to see whether the page looks real.","brief":"click to see if it looks real","why":"Fake login pages are designed to look real, and clicking can itself cause harm.","mis":"You can spot a fake page by looking at it."}]},{"id":"sender","tier":2,"rule":"verify-sender","principle":"ise.verify-sender-out-of-band","fact":["The sender's address is spelled slightly differently from {lead|the}'s usual address."],"clear":["You called {lead|the} at the usual number, and {lead|the} confirmed sending the email."],"done":"the sender was already confirmed by phone","short":"the odd sender address","action":"Check with {lead|the} by phone or in person, not by replying, before doing anything.","brief":"check with {lead|the} by phone","reason":"A lookalike address is a warning sign. Replying goes to the scammer, so confirm another way.","lesson":"Confirm a suspicious message's sender through a separate, known channel.","shortcut":[{"text":"Reply to the email and ask whether it is really from {lead|the}.","brief":"reply and ask if it is real","why":"A reply goes straight to whoever sent it, who will simply say yes.","mis":"Replying is a good way to verify a sender."}]},{"id":"attachment","tier":3,"rule":"avoid-unexpected-attachment","principle":"ise.hold-unexpected-attachment","fact":["The email includes an attachment called \"invoice\" that you were not expecting."],"short":"the unexpected attachment","action":"Leave the attachment unopened until the sender is confirmed.","brief":"leave the attachment unopened","reason":"Unexpected attachments are a common way to deliver harmful software.","lesson":"Do not open unexpected attachments until you confirm who sent them.","shortcut":[{"text":"Open the attachment, since invoices are normal at work.","brief":"open it since invoices are normal","why":"An invoice you were not expecting is exactly the kind of file scammers use.","mis":"Ordinary-looking files are always safe."}]},{"id":"forward","tier":4,"rule":"contain-threat","principle":"ise.report-instead-of-forwarding","fact":["{coworker} suggests forwarding the email to the whole team to ask if anyone thinks it is real."],"short":"the idea of forwarding it to everyone","action":"Report the email through the security process instead of forwarding it.","brief":"report it instead of forwarding","reason":"Forwarding spreads the risk to everyone who receives it. The security team is the right audience.","lesson":"Report suspicious messages to security rather than spreading them.","shortcut":[{"text":"Forward it to the team so everyone can vote on it.","brief":"forward it to the team","why":"Forwarding gives every coworker a chance to click the harmful link.","mis":"Sharing a threat helps everyone stay safe."}]}],"exclusive":[["password","forward"]],"proceed":{"text":"Go ahead with the request in the email.","why":"The sender is confirmed and nothing in the email raises a warning, so the request can be handled.","lesson":"Act on requests once you have confirmed they are real."},"generic":[{"text":"Delete the email and say nothing to anyone.","why":"Deleting without reporting leaves others exposed to the same scam.","mis":"Deleting a scam is the same as reporting it."},{"text":"Turn off your computer and leave it off for the day.","why":"Turning off your computer does not deal with the email or warn anyone.","mis":"Shutting down solves security problems."}],"overcaution":[{"text":"Refuse to handle any email from {lead|the} for the rest of the week.","why":"The sender is confirmed. Refusing real requests stops your work for no reason.","mis":"Every email is a threat."}],"process":{"setup":["An unexpected email at {workplace|the} asks you to take action quickly."],"because":{"sender":["The sender's address looks almost, but not exactly, right."],"attachment":["The email has an attachment you did not expect."]},"steps":[{"id":"stop","text":"Stop before clicking anything","core":true},{"id":"call","text":"Call {lead|the} at the usual number","issue":"sender"},{"id":"hold","text":"Leave the file unopened","issue":"attachment"},{"id":"report","text":"Report it through the security process","core":true},{"id":"delete","text":"Delete it once it has been reported","core":true}],"rel":[["stop","call","Pause first, then verify."],["stop","hold","Pausing is what keeps the file closed."],["call","report","Your report should include what you learned."],["hold","report","The report covers the unopened file."],["stop","report","Report after pausing to look."],["report","delete","Security may need the email, so report first."]],"alternatesReviewed":true,"lesson":"Pause, verify through a known channel, report, and only then delete."},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Security policy stated in the password fact. General phishing guidance, no legal claims."}},{"id":"ise-workstation","skill":"information-security","family":"information-security.cx-workstation-habits","familyName":"Everyday security at your workstation","framework":"ethical-dilemma","concepts":["information-security:confidentiality","information-security:acceptable-use","information-security:security-procedures","information-security:information-formats"],"contexts":"any","requires":["private"],"setup":["You work as {role|a} at {workplace|a}, where your computer gives you access to {private}.","As {role|a} at {workplace|a}, you handle {private} on the computer at your station."],"detail":["Your station is near the front.","It is a normal weekday."],"issues":[{"id":"screen","tier":1,"rule":"protect-confidential-data","principle":"ise.lock-screen-when-away","onlyLevels":["beginner"],"fact":["You need to step away, and {private} are open on your screen where others could see."],"short":"the information open on your screen","action":"Lock your screen before you step away.","reason":"Anyone walking by could see confidential information. Locking takes a second and protects it.","lesson":"Lock your screen whenever you step away.","shortcut":[{"text":"Turn the monitor slightly away and step out quickly.","why":"Angling the screen does not stop someone from seeing or using it.","mis":"Partly hiding a screen is enough."}]},{"id":"misdirected","tier":1,"rule":"report-security-mistake","principle":"ise.report-misdirected-email","onlyLevels":["beginner"],"fact":["You realize you just emailed a file with {private} to the wrong person."],"short":"the email sent to the wrong person","action":"Tell {lead|the} right away so the mistake can be handled quickly.","reason":"Quick reporting gives the workplace the best chance to limit the harm, such as asking for the email to be deleted.","lesson":"Report security mistakes immediately, even your own.","shortcut":[{"text":"Say nothing and hope the person deletes it.","why":"Hiding the mistake removes the chance to limit the damage.","mis":"Small security mistakes are best kept quiet."}]},{"id":"login","tier":2,"rule":"protect-credentials","principle":"ise.no-shared-logins","onlyLevels":["beginner"],"fact":["{coworker} asks to use your login because theirs is locked, and the policy says logins are never shared."],"short":"the request to share your login","action":"Decline, and suggest {coworker} contact the help desk to unlock the account.","reason":"Shared logins break the policy and make it impossible to know who did what.","lesson":"Never share your login, even with a trusted coworker.","shortcut":[{"text":"Log in for {coworker} and stay nearby while they work.","why":"Logging in for someone is still sharing access, which the policy forbids.","mis":"Sharing is fine if you watch what they do."}]},{"id":"usb","tier":3,"rule":"avoid-unknown-device","principle":"ise.hand-in-found-drive","onlyLevels":["beginner"],"fact":["You find an unlabeled USB drive in the parking lot."],"short":"the unknown USB drive","action":"Hand the drive to {lead|the} or the help desk without plugging it in.","reason":"Unknown drives can carry harmful software. Handing it in lets the right people deal with it safely.","lesson":"Never plug in devices you find; hand them in.","shortcut":[{"text":"Plug it in to see whose it is so you can return it.","why":"Plugging in an unknown drive can install harmful software.","mis":"Plugging in a drive is harmless."}]},{"id":"download","tier":4,"rule":"follow-acceptable-use","principle":"ise.follow-acceptable-use-policy","onlyLevels":["beginner"],"fact":["You want to download a game on the work computer during break, which the acceptable-use policy forbids."],"short":"the forbidden download","action":"Skip the download, since the acceptable-use policy does not allow it.","reason":"Acceptable-use rules exist because downloads can bring in harmful software and use work resources.","lesson":"Follow acceptable-use rules on work devices, even on your break.","shortcut":[{"text":"Download it, since it is your break and not work time.","why":"The policy applies to the work computer at all times.","mis":"Work rules do not apply during breaks."}]}],"proceed":{"text":"Carry on with your work, since none of this is a real risk.","why":"Each of these situations is a real security risk that needs a response.","lesson":"Small security habits protect confidential information every day."},"generic":[{"text":"Ask {coworker2} what they usually do and copy that.","why":"A coworker's habit is not the policy, and it may be unsafe.","mis":"Common practice is always safe practice."},{"text":"Write your password on a note under the keyboard to save time later.","why":"Written passwords near a computer are easy for others to find.","mis":"Hidden notes are a safe place for passwords."}],"doc":{"type":"procedure","title":["Workstation security reminders"],"intro":["You are checking this reminder sheet before it is posted at every station."],"prompt":["Which line gives unsafe advice?","Which line is the problem?"],"lesson":"Security reminders must protect logins, devices and confidential information.","lines":[{"id":"lock","text":"Lock your screen every time you leave your station.","fine":"Protects information when you are away."},{"id":"share","text":"Never share your login; the help desk can unlock accounts.","fine":"Keeps each login tied to one person.","bad":[{"id":"share-ok","level":"beginner","text":"Share your login with trusted coworkers when theirs is locked.","why":"Sharing logins breaks security and accountability, no matter how trusted the person is.","principle":"ise.doc-share-login"}]},{"id":"usb","text":"Hand in any device you find; never plug it in.","fine":"Avoids malware from unknown devices.","bad":[{"id":"usb-plug","level":"intermediate","text":"Plug in found USB drives to identify the owner.","why":"Unknown drives can carry malware. They should be handed in, not plugged in.","principle":"ise.doc-plug-in-unknown-drive"}]},{"id":"email","text":"Report suspicious emails to the help desk.","fine":"Routes threats to the right team."},{"id":"mistake","text":"If you send confidential information to the wrong person, tell {lead|the} right away.","fine":"Encourages quick reporting of mistakes.","bad":[{"id":"mistake-hide","level":"advanced","needs":["email"],"text":"If you send confidential information to the wrong person, wait to see if they notice.","why":"Waiting removes the chance to limit the harm. Mistakes should be reported immediately.","principle":"ise.doc-hide-data-mistake"}]},{"id":"password","text":"Use a long passphrase and keep it to yourself.","fine":"Good password practice.","bad":[{"id":"password-note","level":"beginner","text":"Write your password on a sticky note so you do not forget it.","why":"Written passwords are easy for others to find and use.","principle":"ise.doc-written-password"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Login-sharing and acceptable-use rules stated as policy. Beginner-only issues because these would not naturally co-occur."}},{"id":"ise-data-request","skill":"information-security","family":"information-security.cx-request-for-records","familyName":"A request for confidential records","framework":"conflicting-instructions","concepts":["information-security:confidentiality","information-security:security-procedures","information-security:information-formats"],"contexts":"any","requires":["private"],"setup":["You work as {role|a} at {workplace|a}. A caller says they work for a partner company and asks you to send them {private}.","As {role|a} at {workplace|a}, you get a phone request to send {private} to someone outside the team."],"pressure":["The caller says their boss needs it within the hour.","{coworker3} says it is easier to just send it."],"detail":["The call came in on the main line.","It is a busy morning."],"tiers":{"1":"Identity must be confirmed before confidential information goes anywhere.","2":"Only the person the policy names can approve sharing.","3":"Share only the information that is actually needed.","4":"The sending method has to protect the information.","5":"Keeping a record of what was shared comes last."},"issues":[{"id":"identity","tier":1,"rule":"verify-identity","principle":"ise.verify-outside-requester","fact":["You have never heard of the caller, and the policy says outside requests must be verified first."],"clear":["You called the partner company's listed number, and they confirmed the caller works there."],"done":"the caller was already verified","short":"the unverified caller","action":"Verify the caller through the company's listed number before sharing anything.","brief":"verify the caller","reason":"Scammers often pose as partners. Checking through a number you find yourself confirms who is asking.","lesson":"Verify who is asking before sharing confidential information.","shortcut":[{"text":"Trust the caller, since they know details about the account.","brief":"trust the caller","why":"Scammers often know a few details. That is not verification.","mis":"Knowing details proves who someone is."}]},{"id":"approval","tier":2,"rule":"route-to-decision-maker","principle":"ise.get-approval-to-share","fact":["The policy says {lead|the} must approve any sharing of {private} outside the team."],"clear":["{Lead|the} already approved sharing these records with this partner."],"done":"the sharing was already approved","short":"the missing approval","action":"Ask {lead|the} to approve the request before sending anything.","brief":"get {lead|the}'s approval","reason":"The policy puts this decision with the lead, who knows whether the partner should receive the records.","lesson":"Follow the approval steps before sharing protected information.","shortcut":[{"text":"Send it, since partners usually get this kind of information.","brief":"send it because partners usually do","why":"Usual practice is not approval. The policy requires the lead's approval.","mis":"Past practice replaces approval."}]},{"id":"extra","tier":3,"rule":"minimum-necessary","principle":"ise.share-only-what-is-needed","fact":["The caller asks for the full file, but the request only needs two items from it."],"short":"the request for more than is needed","action":"Offer to share only the two items the request actually needs.","brief":"share only what is needed","reason":"Sharing only what is needed limits the harm if the information is lost or misused.","lesson":"Share the minimum information needed for the task.","shortcut":[{"text":"Send the full file so they do not have to ask again.","brief":"send the full file","why":"Extra information adds risk without any benefit.","mis":"Sharing more saves time."}]},{"id":"channel","tier":4,"rule":"use-approved-channel","principle":"ise.use-secure-channel","fact":["The caller asks you to text the information to a personal phone."],"clear":["The partner has an approved secure portal set up for these files."],"done":"a secure portal is already set up","short":"the request to text it","action":"Send it only through the approved secure method, not by text.","brief":"use the approved secure method","reason":"Text messages to personal phones are not protected. Approved channels keep the information secure.","lesson":"Send confidential information only through approved, secure channels.","shortcut":[{"text":"Text it, since it is faster and the caller asked.","brief":"text it as asked","why":"Speed does not make an unprotected channel safe.","mis":"The requester decides how information is sent."}]},{"id":"log","tier":5,"rule":"keep-records","principle":"ise.log-what-was-shared","noProceed":true,"fact":["The policy says every outside sharing must be noted in {record|the}."],"short":"the sharing record","action":"Note in {record|the} what you shared, with whom and when.","brief":"record what was shared","reason":"A sharing record lets the workplace track where confidential information has gone.","lesson":"Record what confidential information you share and with whom.","shortcut":[{"text":"Skip the note, since the email shows what was sent.","brief":"skip the record","why":"The policy requires the record, and emails are not always kept or searchable.","mis":"Emails are a complete record."}]}],"proceed":{"text":"Send the requested information through the usual approved method.","why":"The requester is verified, sharing is approved and the method is secure, so the request can be completed.","lesson":"Share protected information only after verification, approval and a secure method are in place."},"generic":[{"text":"Put the caller on hold and hope they hang up.","why":"Avoiding the request does not resolve it and is unprofessional.","mis":"Ignoring a hard request makes it go away."},{"text":"Read the information aloud over the phone to save time.","why":"Reading confidential information aloud bypasses every check the policy requires.","mis":"Saying something aloud is safer than sending it."}],"overcaution":[{"text":"Refuse the request and tell the caller never to call again.","why":"The request is verified and approved; refusing blocks legitimate work.","mis":"Every outside request is a threat."}],"process":{"setup":["A partner company has asked {workplace|the} for {private}."],"because":{"identity":["You do not recognize the person asking."],"approval":["Sharing these records needs {lead|the}'s approval."],"log":["The policy requires a record of every outside sharing."]},"steps":[{"id":"verify","text":"Call back on the company's listed number","issue":"identity"},{"id":"approve","text":"Get {lead|the}'s approval","issue":"approval"},{"id":"select","text":"Pick out only the items needed","core":true},{"id":"send","text":"Send them through the secure method","core":true},{"id":"note","text":"Record what was shared","issue":"log"}],"rel":[["verify","approve","The lead needs to know who is really asking."],["verify","send","Nothing is sent before the requester is verified."],["approve","send","Sharing needs approval first."],["select","send","Choose what to send before sending."],["send","note","You record what was actually sent."]],"alternatesReviewed":true,"lesson":"Verify, approve, limit, send securely, then record."},"doc":{"type":"email","title":["Your reply to the partner company"],"intro":["You are about to reply to the partner company's request. Check the message first."],"lesson":"Replies about confidential information must follow verification, approval, minimum sharing and secure delivery.","lines":[{"id":"thanks","text":"Thank you for your request.","fine":"A courteous opening."},{"id":"verify","text":"We confirmed your request through your company's main number.","fine":"Shows the requester was verified."},{"id":"items","text":"Attached through our secure portal are the two items you need.","fine":"Minimum necessary, secure channel.","bad":[{"id":"items-all","level":"beginner","text":"I attached the full file of {private} in case it helps.","why":"Sending the whole file shares far more than needed.","principle":"ise.doc-overshares"}]},{"id":"approved","text":"{Lead|the} approved this sharing on Monday.","fine":"Records the approval."},{"id":"method","text":"Please download them from the portal within 7 days.","fine":"Secure delivery with a time limit.","bad":[{"id":"method-text","level":"intermediate","text":"I will also text the same files to your personal phone.","why":"Personal phones and texts are not approved, secure channels.","principle":"ise.doc-insecure-channel"}]},{"id":"close","text":"Let me know if you have trouble with the portal.","fine":"Offers help.","bad":[{"id":"close-forward","level":"advanced","needs":["items"],"text":"Feel free to forward them to anyone on your team.","why":"The approval covered this requester; inviting wider forwarding defeats the limits.","principle":"ise.doc-invites-forwarding"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Verification, approval and logging stated as workplace policy."}},{"id":"ite-printer-trouble","skill":"information-technology","family":"information-technology.cx-troubleshooting-a-device","familyName":"Troubleshooting a device that will not work","framework":"root-cause","concepts":["information-technology:troubleshooting","information-technology:hardware-and-devices"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. The shared printer will not print the {document} you need for a {client}.","As {role|a} at {workplace|a}, you need to print {document|a}, but the shared printer is not working."],"pressure":["The {client} is waiting for the printout.","{coworker3} says to just keep hitting print until it works."],"detail":["The printer is in the back hallway.","It printed fine this morning."],"tiers":{"1":"A device that smells like it is burning is a safety problem first.","2":"Start with the simplest physical checks.","3":"The exact error message tells you where to look next.","4":"Knowing whether others are affected narrows down the cause.","5":"When basic checks do not fix it, escalate with the details."},"issues":[{"id":"burning","tier":1,"rule":"control-hazard-first","principle":"ite.stop-using-overheating-device","fact":["You notice a smell of burning plastic coming from the printer."],"short":"the burning smell","action":"Stop using the printer, keep people back, and tell {lead|the} right away.","brief":"stop using it and tell {lead|the}","reason":"A burning smell can mean overheating or an electrical fault. Safety comes before printing.","lesson":"Treat smoke or burning smells from devices as a safety issue first.","shortcut":[{"text":"Open the printer to see what is burning.","brief":"open it up to look","why":"Opening an overheating device risks burns or shock.","mis":"Finding the cause yourself is the fastest fix."}]},{"id":"power","tier":2,"rule":"check-simple-causes","principle":"ite.check-power-first","fact":["The printer's power light is off."],"short":"the dark power light","action":"Check that the printer is plugged in and switched on.","brief":"check the plug and power switch","reason":"The simplest cause is often the real one. Checking power takes seconds.","lesson":"Start troubleshooting with the simplest physical checks.","shortcut":[{"text":"Reinstall the printer software on your computer.","brief":"reinstall the printer software","why":"Software cannot fix a printer that has no power, and reinstalling takes far longer.","mis":"Computer problems always need software fixes."}],"clear":["You already checked that the printer is plugged in and switched on."],"done":"the power was already checked"},{"id":"message","tier":3,"rule":"read-the-error","principle":"ite.read-error-message","fact":["A message flashed on the printer screen, but you did not read it."],"short":"the unread error message","action":"Read the message on the printer screen and write down exactly what it says.","brief":"read and note the error message","reason":"Error messages often say what is wrong, such as a jam or low toner.","lesson":"Read and record error messages; they point to the cause.","shortcut":[{"text":"Turn the printer off and on without reading the message.","brief":"restart without reading it","why":"Restarting may clear the message without fixing the cause.","mis":"Restarting fixes everything."}],"clear":["You already wrote down the error code shown on the printer screen."],"done":"the error code is already written down"},{"id":"others","tier":4,"rule":"narrow-down-cause","principle":"ite.check-if-others-affected","fact":["You do not know whether other people can print."],"clear":["{coworker} printed to the same printer five minutes ago without a problem."],"done":"you already know others can print","short":"not knowing if others are affected","action":"Ask a coworker whether they can print, to narrow down the cause.","brief":"ask if others can print","reason":"If others can print, the problem is likely your computer; if not, it is the printer.","lesson":"Narrow down a problem by checking whether others are affected.","shortcut":[{"text":"Assume the printer is broken and stop trying.","brief":"assume the printer is broken","why":"You do not know yet whether the printer or your computer is the problem.","mis":"The first suspect is the cause."}]},{"id":"stuck","tier":5,"rule":"escalate-with-details","principle":"ite.ticket-with-steps-tried","fact":["The basic checks are done, and the problem is still there."],"short":"the problem that basic checks did not fix","action":"Submit a help desk ticket with the error and what you already tried.","brief":"submit a ticket with what you tried","reason":"The help desk can solve it faster when they know what has already been ruled out.","lesson":"When basic troubleshooting fails, escalate with clear details.","shortcut":[{"text":"Submit a ticket that just says the printer is broken.","brief":"submit a ticket saying it is broken","why":"A vague ticket makes the help desk repeat checks you already did.","mis":"Details do not matter in a help request."}]}],"exclusive":[["power","stuck"],["power","message"]],"proceed":{"text":"Send the job to the printer again and wait for it to print.","why":"Sending the job again without understanding the problem will not fix it.","lesson":"Troubleshoot step by step instead of repeating what failed."},"generic":[{"text":"Unplug other equipment and move things around until something works.","why":"Random changes can create new problems and make the cause harder to find.","mis":"Trying random fixes is a good strategy."},{"text":"Tell the {client} that printing is impossible today.","why":"Giving up before troubleshooting leaves the {client} without help.","mis":"If a device fails once, it cannot be fixed today."}],"process":{"setup":["The shared printer at {workplace|the} will not print your job."],"steps":[{"id":"power","text":"Check the power and cables","core":true},{"id":"read","text":"Read the error on the printer screen","core":true},{"id":"others","text":"Ask whether others can print","issue":"others"},{"id":"fix","text":"Try the fix the error points to","core":true},{"id":"ticket","text":"Submit a ticket listing the steps tried","core":true}],"because":{"others":["You are not sure if the problem is only on your computer."]},"rel":[["power","read","The screen only shows a message when the printer has power."],["read","fix","The message tells you what to try."],["others","fix","Knowing who is affected tells you where to aim the fix."],["fix","ticket","You escalate after your own attempts fail."]],"alternatesReviewed":true,"lesson":"Check the simple things, read the error, narrow it down, try a fix, then escalate."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Troubleshooting order. Power-off contradicts a readable screen and a completed basic check, so those pairs are exclusive."}},{"id":"ite-sharing-file","skill":"information-technology","family":"information-technology.cx-sharing-a-file","familyName":"Sharing a file with a client","framework":"process-dependency","concepts":["information-technology:cloud-and-file-sharing","information-technology:software-and-applications"],"contexts":"any","requires":["private"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asked you to share a project file with a {client} today.","As {role|a} at {workplace|a}, you need to send a {client} a file from the team's shared folder."],"pressure":["The {client} has asked twice for the file.","{coworker3} says to just send it any way you can."],"detail":["The file is in the team's shared folder.","The {client} prefers email."],"tiers":{"1":"Private information has to come out before anything is shared.","2":"The sharing setting decides who can see the file.","3":"Sending the wrong version wastes the {client}'s time.","4":"The right tool depends on the file's size.","5":"Software updates can follow the normal process."},"issues":[{"id":"private","tier":1,"rule":"protect-confidential-data","principle":"ite.remove-private-data-before-sharing","fact":["The file includes a page with {private} that the {client} should not see."],"short":"the private page in the file","action":"Remove the page with private information before sharing the file.","brief":"remove the private page","reason":"Once a file is shared, you cannot take it back. Private information has to be removed first.","lesson":"Check files for private information before sharing them.","shortcut":[{"text":"Send it and ask the {client} to ignore that page.","brief":"ask them to ignore that page","why":"The private information would already be exposed.","mis":"Asking someone to ignore information protects it."}]},{"id":"link","tier":2,"rule":"limit-access","principle":"ite.restrict-sharing-link","fact":["The file's sharing setting is \"anyone with the link can view.\""],"clear":["{coworker} already set the file so only the {client} can open it."],"done":"the sharing was already limited to the {client}","short":"the open sharing link","action":"Change the setting so only the {client} can open the file.","brief":"limit access to the {client}","reason":"An open link can be forwarded to anyone. Limiting access keeps the file where it belongs.","lesson":"Share files with only the people who need them.","shortcut":[{"text":"Leave the open link, since only the {client} will get it.","brief":"leave the link open","why":"Links can be forwarded or posted. An open link is not limited to one person.","mis":"A link only reaches the person you send it to."}]},{"id":"version","tier":3,"rule":"confirm-correct-version","principle":"ite.confirm-final-version","fact":["There are two versions of the file with almost the same name."],"clear":["{coworker} labeled the final version clearly this morning."],"done":"the final version is already labeled","short":"the two similar versions","action":"Confirm which version is final before sharing.","brief":"confirm the final version","reason":"Sending a draft can confuse the {client} and make the team look careless.","lesson":"Confirm you have the right version before sharing a file.","shortcut":[{"text":"Send both versions and let the {client} figure it out.","brief":"send both versions","why":"Sending both pushes your job onto the {client} and risks the wrong one being used.","mis":"More files are more helpful."}]},{"id":"size","tier":4,"rule":"choose-right-tool","principle":"ite.use-approved-sharing-tool","fact":["The file is too large to attach to an email."],"short":"the oversized file","action":"Share it through {system|the} instead of email.","brief":"share it through {system|the}","reason":"The approved system handles large files and keeps sharing under control.","lesson":"Use the approved tool that fits the job.","shortcut":[{"text":"Upload it to your personal cloud account and send that link.","brief":"use your personal cloud account","why":"Personal accounts are outside the workplace's control and may break its rules.","mis":"Any cloud service is fine for work files."}]},{"id":"update","tier":5,"rule":"maintain-software","principle":"ite.install-update-normally","noProceed":true,"fact":["The software asks you to install an update before it opens the file."],"short":"the pending software update","action":"Install the update through the normal process, or ask the help desk if unsure.","brief":"install the update normally","reason":"Updates fix problems and security holes. The normal process keeps them safe.","lesson":"Keep software updated through approved channels.","shortcut":[{"text":"Download an older version from a free website instead.","brief":"download an old version elsewhere","why":"Unofficial downloads can carry malware.","mis":"Free download sites are safe sources of software."}]}],"proceed":{"text":"Share the file with the {client} the usual approved way.","why":"The file is checked, limited and ready, so sharing it is the right step.","lesson":"Share files once they are checked and access is set correctly."},"generic":[{"text":"Print the file and mail it to save the trouble.","why":"Mailing a printout is slow and still needs the same checks.","mis":"Paper avoids all technology problems."},{"text":"Ask the {client} to come in and copy it from your screen.","why":"That wastes the {client}'s time when the file can be shared properly.","mis":"Showing a screen is safer than sharing a file."}],"overcaution":[{"text":"Ask {lead|the} to check the file again before sending.","why":"The file is already checked and set up. Another review delays the {client}.","mis":"Every file needs a supervisor's review."}],"doc":{"type":"procedure","title":["Steps for sharing files with {client.plural}"],"intro":["You are reviewing the team's file-sharing steps before they are posted."],"lesson":"File-sharing steps must protect private information and limit access.","lines":[{"id":"check","text":"Check the file for private information and remove it.","fine":"Protects private information first."},{"id":"version","text":"Confirm you have the final version.","fine":"Avoids sending drafts."},{"id":"tool","text":"Share through {system|the}, not personal accounts.","fine":"Uses the approved tool.","bad":[{"id":"tool-personal","level":"intermediate","text":"Use any free file-sharing site you like.","why":"Personal or random services are outside the workplace's control.","principle":"ite.doc-unapproved-tool"}]},{"id":"access","text":"Set access so only the intended {client} can open it.","fine":"Limits access.","bad":[{"id":"access-open","level":"beginner","text":"Set access to anyone with the link so it is easy to open.","why":"Open links can be forwarded to anyone.","principle":"ite.doc-open-link"}]},{"id":"confirm","text":"Ask the {client} to confirm they received it.","fine":"Confirms delivery.","bad":[{"id":"confirm-assume","level":"beginner","text":"Assume the {client} got it; no need to check.","why":"Without confirming, a failed share can go unnoticed.","principle":"ite.doc-no-delivery-check"}]},{"id":"remove","text":"Remove access when the project ends.","fine":"Closes access when no longer needed.","bad":[{"id":"remove-keep","level":"advanced","needs":["access"],"text":"Leave access on forever so the {client} can always find old files.","why":"Access that never ends keeps files open long after they are needed.","principle":"ite.doc-permanent-access"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Cloud sharing and software updates."}},{"id":"ini-finished-early","skill":"initiative-and-self-direction","family":"initiative-and-self-direction.cx-finished-early","familyName":"Using time well after finishing early","framework":"competing-priorities","concepts":["initiative-and-self-direction:proactive-decisions","initiative-and-self-direction:identify-needs","initiative-and-self-direction:minimal-supervision"],"contexts":"any","requires":["area"],"setup":["You work as {role|a} at {workplace|a}. You finished your assigned tasks an hour early, and {lead|the} is in a long meeting.","As {role|a} at {workplace|a}, you have finished everything on your list early. {Lead|the} is in a meeting for the next hour."],"pressure":["{coworker3} says nobody will notice if you just take it easy.","{coworker3} jokes that finishing early means you earned a long break."],"detail":["The {area} is quieter than usual today.","It is the middle of the shift."],"tiers":{"1":"A hazard someone could walk into comes before any other task.","2":"Your own error should be fixed before it causes problems for others.","3":"Stay within what you are allowed to do, even when trying to help.","4":"Helping a teammate who is behind comes before improvements.","5":"Ideas for improvement can be raised once the urgent needs are met."},"issues":[{"id":"hazard","tier":1,"rule":"control-hazard-first","principle":"ini.act-on-spotted-hazard","fact":["On your way back from the break room, you notice {hazard}."],"short":"the hazard you noticed","action":"Mark off the hazard so nobody walks into it, and report it right away.","brief":"mark off the hazard and report it","reason":"Taking initiative includes acting on hazards you notice. Marking it off protects people until it is fixed.","lesson":"When you spot a hazard, protect people from it and report it; do not assume someone else will.","shortcut":[{"text":"Mention the hazard to {lead|the} after the meeting ends.","brief":"mention the hazard after the meeting","why":"Someone could be hurt in the next hour. A hazard needs action now, not later.","mis":"Problems can wait until the supervisor is free."}]},{"id":"ownerror","tier":2,"rule":"correct-own-error","principle":"ini.fix-own-error-unprompted","fact":["You realize an entry you made in {record|the} this morning has the wrong date."],"short":"the wrong date in your entry","action":"Correct your entry in {record|the} the usual way and note that you changed it.","brief":"correct your entry and note the change","reason":"Fixing your own mistake without being asked keeps the record reliable and shows self-direction.","lesson":"Correct your own mistakes as soon as you find them, without waiting to be told.","shortcut":[{"text":"Leave the wrong date, since nobody has noticed it.","brief":"leave the wrong date alone","why":"Others rely on the record. An error left in place can cause confusion later.","mis":"A mistake nobody noticed does not need fixing."}]},{"id":"outside","tier":3,"rule":"stay-within-authority","principle":"ini.choose-task-within-role","fact":["The obvious next task needs a certification you do not have."],"short":"the task that needs certification","action":"Leave the certified task for qualified staff and pick another useful task.","brief":"leave the certified task and pick another","reason":"Initiative means finding useful work within what you are allowed to do. Certified tasks are restricted for good reasons.","lesson":"Take initiative within the limits of your role and training.","shortcut":[{"text":"Do the certified task anyway, since you have watched it done many times.","brief":"do the certified task anyway","why":"Watching is not certification. Doing restricted work can cause harm and break workplace rules.","mis":"Having seen a task done is enough to do it."}]},{"id":"unclear","tier":3,"rule":"find-needed-work","principle":"ini.find-what-needs-doing","fact":["Nobody has told you what to do next."],"clear":["{Lead|the} left a list of extra tasks for anyone who finishes early."],"done":"a task list was already left for you","short":"not knowing what to do next","action":"Check the task board or ask {coworker} what needs doing.","brief":"check the task board or ask {coworker}","reason":"Finding out what needs doing, instead of waiting to be told, is the core of self-direction.","lesson":"When your work is done, look for what needs doing instead of waiting to be told.","shortcut":[{"text":"Wait at your station until {lead|the} comes out of the meeting.","brief":"wait at your station for {lead|the}","why":"An hour of waiting wastes time that could help the team. You can find work without your supervisor.","mis":"You should only work on what you are told to do."}]},{"id":"teammate","tier":4,"rule":"help-where-needed","principle":"ini.offer-help-to-busy-teammate","fact":["{coworker2} is falling behind on a rush order that you know how to help with."],"short":"{coworker2}'s rush order","action":"Offer to help {coworker2} with the rush order.","brief":"offer to help {coworker2}","reason":"Seeing where help is needed and offering it moves the team's work forward.","lesson":"Notice where your help is needed and offer it.","shortcut":[{"text":"Leave {coworker2} to it, since your own work is finished.","brief":"leave {coworker2} to it","why":"The team's work is not finished. Helping a teammate who is behind is a good use of spare time.","mis":"Once your own work is done, the rest is not your concern."}]},{"id":"pattern","tier":5,"rule":"suggest-improvement-after","principle":"ini.note-recurring-problem","fact":["You notice that {equipment|the} jams at about the same time every afternoon."],"short":"the repeated jams","action":"Write down when the jams happen and share the pattern with {lead|the} later.","brief":"write down when it jams and share the pattern","reason":"Noticing a pattern and recording it gives the right people what they need to fix the cause.","lesson":"Record patterns you notice so the right person can act on them.","shortcut":[{"text":"Take {equipment|the} apart yourself to find out what is wrong.","brief":"take the equipment apart yourself","why":"Repairs may need training or permission. Recording and reporting the pattern is the useful step.","mis":"Initiative means fixing everything yourself."}],"noProceed":true}],"proceed":{"text":"Start another useful task and tell {lead|the} what you picked up.","why":"Nothing more urgent needs attention, so starting useful work and keeping the lead informed is the best use of the time.","lesson":"Use spare time on useful work and keep your supervisor informed."},"generic":[{"text":"Spend the hour on your phone, since your assigned work is done.","why":"The workday is not over. Using spare time well is part of being dependable and self-directed.","mis":"Finishing your list early means the rest of the time is yours."},{"text":"Interrupt {lead|the}'s meeting to ask what to do next.","why":"Interrupting a meeting for something you can figure out yourself is not necessary.","mis":"Only a supervisor can say what needs doing."}],"overcaution":[{"text":"Wait until {lead|the} confirms the list is still current before starting.","why":"The list was left for exactly this situation. Waiting wastes the time it was meant to fill.","mis":"Instructions always need to be reconfirmed."}],"process":{"setup":["You are {role|a} at {workplace|a}. You finished your work early, and {lead|the} is unavailable."],"because":{"unclear":["You are not sure what is most needed right now."],"ownerror":["You spot a mistake in something you filled out this morning."],"teammate":["{coworker2} is struggling with a rush order."]},"steps":[{"id":"fixown","text":"Fix the mistake you made earlier","issue":"ownerror"},{"id":"find","text":"Check the task board for what is needed","issue":"unclear"},{"id":"help","text":"Offer {coworker2} a hand","issue":"teammate"},{"id":"do","text":"Work on the extra task","core":true},{"id":"tell","text":"Tell {lead|the} what you did with the time","core":true}],"rel":[["fixown","do","Your own mistake should be fixed before you move on."],["find","do","You need to know which task is needed before starting it."],["help","do","A teammate's rush order comes before optional extra tasks."],["do","tell","You report what you did after doing it."],["fixown","tell","Your report should include the correction."]],"alternatesReviewed":true,"lesson":"Fix your own errors, find what is needed, help where it counts, then report."},"doc":{"type":"note","title":["Your note to {lead|the}"],"intro":["You are leaving {lead|the} a note about what you did after finishing early. Check it first."],"lesson":"A self-directed worker reports what they did, stays within their role and flags what needs attention.","lines":[{"id":"done","text":"I finished my assigned list about an hour early.","fine":"A clear, factual start."},{"id":"help","text":"I helped {coworker2} finish the rush order.","fine":"Reports help given where it was needed."},{"id":"task","text":"Then I restocked the {area} from the extra-tasks list.","fine":"Chose a useful task from the list.","bad":[{"id":"task-cert","level":"intermediate","text":"Then I did the certified equipment check, since I have watched it many times.","why":"Certified tasks are restricted to qualified staff. Watching does not qualify you.","principle":"ini.doc-acted-outside-role"}]},{"id":"hazard","text":"I marked off {hazard} and reported it to {coworker3}, who was in charge while you were out.","fine":"Acted on a hazard and reported it to the person covering.","bad":[{"id":"hazard-later","level":"beginner","text":"I noticed {hazard}, but I left it for you to deal with later.","why":"A hazard can hurt someone before the supervisor returns. It needed to be marked off and reported right away.","principle":"ini.doc-left-hazard"}]},{"id":"jam","text":"{Equipment|the} jammed three afternoons this week around 2 p.m.; I wrote down the times.","fine":"Records a pattern for the right person to act on.","bad":[{"id":"jam-repair","level":"advanced","text":"{Equipment|the} kept jamming, so I took it apart to look; it is in pieces on the bench.","why":"Taking equipment apart without permission or training can damage it and leave it out of service. Recording the pattern is the right step.","principle":"ini.doc-unauthorized-repair"}]},{"id":"fix","text":"I corrected the wrong date I had entered in {record|the} and initialed the change.","fine":"Fixed own mistake and marked the change.","bad":[{"id":"fix-hide","level":"beginner","text":"I noticed a wrong date I had entered, but left it, since nobody had spotted it.","why":"Leaving a known error in a record is not acceptable; it should be corrected.","principle":"ini.doc-left-own-error"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Uses the bundle hazard slot (recognizable hazards). 'outside' and 'unclear' share tier 3 and never co-occur."}},{"id":"ini-new-task-solo","skill":"initiative-and-self-direction","family":"initiative-and-self-direction.cx-new-task-solo","familyName":"Working through a new task with little supervision","framework":"critical-information","concepts":["initiative-and-self-direction:minimal-supervision","initiative-and-self-direction:apply-solutions","initiative-and-self-direction:proactive-decisions"],"contexts":"any","setup":["You are {role|a} at {workplace|a}. {Lead|the} gave you written instructions for a task you have never done and will be out until the end of the day.","As {role|a} at {workplace|a}, you are doing a new task alone from written instructions while {lead|the} is out."],"pressure":["{coworker3} tells you to just do your best and not bother anyone.","{coworker3} says asking questions makes new people look weak."],"detail":["The instructions are two pages long.","You have the work area to yourself today."],"tiers":{"1":"A step that could damage equipment comes before everything else.","2":"A schedule problem should be raised as early as possible.","3":"Fill gaps in the instructions before they cause rework.","4":"After real effort, asking for help beats staying stuck.","5":"Routine updates come after urgent questions."},"issues":[{"id":"risk","tier":1,"rule":"stop-and-ask-on-risk","principle":"ini.ask-before-risky-step","fact":["One step could damage {equipment|the} if done wrong, and you do not understand how to do it."],"short":"the risky step you do not understand","action":"Pause at that step and call or message {lead|the} for guidance before doing it.","brief":"pause and contact {lead|the} about that step","reason":"Working independently does not mean guessing on a step that could cause damage. A quick question prevents an expensive mistake.","lesson":"Work independently, but ask before a step where a mistake could cause damage.","shortcut":[{"text":"Try the step carefully and see what happens.","brief":"try the step and see what happens","why":"Experimenting on a step that could damage equipment risks a costly mistake. A quick question is cheaper.","mis":"Figuring it out alone is always the self-directed choice."}]},{"id":"behind","tier":2,"rule":"communicate-delay-early","principle":"ini.report-delay-early","fact":["At your current pace, the task will not be done by the end of the day as {lead|the} expects."],"clear":["{Lead|the} already moved the due time to tomorrow morning."],"done":"the due time was already moved to tomorrow","short":"the expected delay","action":"Message {lead|the} now that the task is running behind and why.","brief":"tell {lead|the} the task is running behind","reason":"Early warning lets the lead plan around the delay or send help. Waiting until the end of the day removes those options.","lesson":"Tell your supervisor about delays as soon as you see them coming.","shortcut":[{"text":"Say nothing and hope you can speed up later.","brief":"say nothing and try to speed up","why":"If you cannot catch up, the lead learns about the delay too late to adjust.","mis":"Raising a delay makes you look bad, so it is better to hide it."}]},{"id":"gap","tier":3,"rule":"apply-known-solution","principle":"ini.use-past-example-for-gap","fact":["The written instructions do not say how the finished work should be labeled."],"clear":["{coworker} showed you how past finished work was labeled."],"done":"you already found out how past work was labeled","short":"the missing labeling instructions","action":"Look at how similar past work was labeled and follow that example.","brief":"follow how past work was labeled","reason":"Using an existing example is a sensible, independent way to fill a gap in the instructions.","lesson":"Fill gaps in instructions by applying solutions that already exist.","shortcut":[{"text":"Leave the work unlabeled until {lead|the} returns tomorrow.","brief":"leave it unlabeled until tomorrow","why":"Unlabeled work can get lost or mixed up. A past example gives you a reasonable answer now.","mis":"If the instructions do not say, the step can be skipped."}]},{"id":"stuck","tier":4,"rule":"ask-for-help-after-trying","principle":"ini.ask-help-after-trying","fact":["You have tried two ways to fix a formatting problem, and neither worked."],"short":"the formatting problem you are stuck on","action":"Ask {coworker} for help, explaining what you have already tried.","brief":"ask {coworker} for help with what you tried","reason":"You have made a real effort. Asking for help now, with what you tried, saves time and respects the helper's time.","lesson":"Try on your own first, then ask for help and explain what you tried.","shortcut":[{"text":"Keep trying new things on your own for the rest of the day.","brief":"keep trying alone all day","why":"Spending the day stuck wastes time. Self-direction includes knowing when to ask.","mis":"Asking for help means you are not self-directed."}]},{"id":"update","tier":5,"rule":"keep-supervisor-informed","principle":"ini.send-requested-update","fact":["{Lead|the} asked for a short update when you reached the halfway point, and you just did."],"clear":["You already sent {lead|the} the halfway update."],"done":"the halfway update was already sent","short":"the requested halfway update","action":"Send {lead|the} a short message saying you have reached the halfway point.","brief":"send {lead|the} the halfway update","reason":"The lead asked for this update. Sending it keeps them informed without needing to check on you.","lesson":"Keep your supervisor informed the way they asked, especially when working alone.","shortcut":[{"text":"Skip the update, since things are going fine.","brief":"skip the update","why":"The lead asked for it. Skipping it leaves them wondering how the task is going.","mis":"Updates only matter when something is wrong."}]}],"proceed":{"text":"Continue through the instructions on your own, step by step.","why":"Nothing in the situation needs a question or a warning, so steady independent work is exactly what the lead expects.","lesson":"When the path is clear, keep working independently and steadily."},"generic":[{"text":"Stop and wait for {lead|the} to return before doing anything else.","why":"Stopping all work for a whole day wastes time when much of the task can go ahead.","mis":"Without a supervisor present, it is safer to do nothing."},{"text":"Ask {coworker3} to finish the task for you.","why":"The task was given to you. Handing it off without a reason skips the chance to learn and may overload a coworker.","mis":"Handing off unfamiliar work is a good way to avoid mistakes."}],"overcaution":[{"text":"Message {lead|the} for approval before each step.","why":"Nothing in the situation needs a question. Asking at every step defeats the purpose of working independently.","mis":"More check-ins are always better."}],"process":{"setup":["You are {role|a} at {workplace|a}, doing an unfamiliar task from written instructions while {lead|the} is out."],"because":{"gap":["The instructions leave out how to label the finished work."],"update":["{Lead|the} wants a message once you are halfway done."]},"steps":[{"id":"read","text":"Read all of the instructions first","core":true},{"id":"example","text":"Find an example of past labeling","issue":"gap"},{"id":"first","text":"Complete the first half of the task","core":true},{"id":"update","text":"Send {lead|the} a halfway message","issue":"update"},{"id":"finish","text":"Finish and label the work","core":true}],"rel":[["read","first","Reading the whole set first helps you spot problems early."],["read","example","Reading the instructions is how you notice what they leave out."],["example","finish","You need the labeling example before you label."],["first","update","The halfway message comes once you are halfway done."],["update","finish","The update is meant to arrive before the task is complete."],["first","finish","The second half follows the first."]],"alternatesReviewed":true,"lesson":"Read everything first, fill gaps with existing examples, and keep your supervisor updated along the way."},"doc":{"type":"chat","title":["Your message to {lead|the}"],"intro":["You are about to message {lead|the} about the new task. Check the message first."],"lesson":"Good independent work includes clear, timely, honest messages about progress and problems.","lines":[{"id":"status","text":"Halfway update: the first half is finished.","fine":"Gives the requested update."},{"id":"label","text":"I labeled the finished pieces the same way as last month's work.","fine":"Filled a gap by following an existing example.","bad":[{"id":"label-skip","level":"beginner","text":"The instructions did not say how to label things, so I skipped labeling.","why":"Skipping a needed step because instructions are unclear can cause lost or mixed-up work. An existing example would have filled the gap.","principle":"ini.doc-skipped-unclear-step"}]},{"id":"pace","text":"At this pace I will need about an hour tomorrow morning to finish.","fine":"Warns about a delay early and specifically."},{"id":"risky","text":"Before step 6, could you tell me how to set the guide? I do not want to damage it.","fine":"Asks before a step that could cause damage.","bad":[{"id":"risky-tried","level":"intermediate","text":"I was not sure how to do step 6, so I tried a few settings until one seemed to work.","why":"Guessing on a step that could damage equipment risks costly harm. That step called for a question first.","principle":"ini.doc-guessed-risky-step"}]},{"id":"stuck","text":"{coworker} helped with the formatting after I had tried two fixes.","fine":"Asked for help after real effort and says so.","bad":[{"id":"stuck-hours","level":"advanced","needs":["pace"],"text":"I spent three hours alone on the formatting so I would not bother anyone.","why":"The task is already running behind. Hours stuck without asking made the delay worse; asking earlier was the better choice.","principle":"ini.doc-stayed-stuck"}]},{"id":"close","text":"I will keep going with the second half now.","fine":"States the next step."}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Self-direction with appropriate help-seeking; tiers favour preventing damage and early communication."}},{"id":"int-closing-count","skill":"integrity","family":"integrity.cx-closing-count","familyName":"An honest closing count","framework":"ethical-dilemma","concepts":["integrity:honesty-and-fairness","integrity:policies-and-procedures","integrity:importance-of-integrity"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a} and are doing the closing count of {supply.plural}. Your count is 6 lower than the log shows.","As {role|a} at {workplace|a}, you are counting {supply.plural} at closing. You count 6 fewer than the log says there should be."],"pressure":["{coworker3} says everyone wants to go home and you should just wrap it up.","It is already past closing time."],"detail":["The {supply.plural} are stored on the top shelf.","The rest of the closing tasks are done."],"tiers":{"1":"A false record cannot be fixed later; honesty comes first.","2":"The procedure's check confirms the problem before it is reported.","3":"Your own part in the problem belongs in the report.","4":"The report has to reach the person the procedure names."},"issues":[{"id":"hide","tier":1,"rule":"refuse-to-falsify","principle":"int.no-falsified-count","fact":["{coworker} suggests changing the count sheet to match the log so nobody gets questioned."],"short":"the suggestion to change the count","action":"Record the real count, and decline to change the numbers.","brief":"record the real count and decline to change it","reason":"A count sheet that hides a shortage is a false record. Accurate numbers are what let the team find the cause.","lesson":"Record what you actually find, even when the honest number leads to questions.","shortcut":[{"text":"Change the count to match the log, since a few items are not worth the trouble.","brief":"change the count to match the log","why":"Changing the numbers creates a false record and hides a real problem from the people who need to know.","mis":"Small differences are not worth reporting honestly."}],"noProceed":true},{"id":"recount","tier":2,"rule":"follow-procedure-check","principle":"int.second-count-before-report","fact":["The posted closing procedure says a second person must recount any shortage."],"clear":["{coworker2} already recounted, and the second count matched yours."],"done":"the second count was already done","short":"the required second count","action":"Ask {coworker2} to do the second count that the procedure requires.","brief":"ask {coworker2} for the second count","reason":"The procedure's second count confirms the shortage is real before it is reported.","lesson":"Follow the procedure's check steps before reporting a problem.","shortcut":[{"text":"Skip the recount, since you are sure your own count is right.","brief":"skip the recount","why":"The procedure requires a second count. Skipping it breaks the procedure and leaves room for error.","mis":"Your own count is accurate enough to skip the procedure."}]},{"id":"owncause","tier":3,"rule":"disclose-own-role","principle":"int.disclose-own-unlogged-handouts","fact":["You remember handing out several {supply.plural} today without writing them in the log."],"short":"the items you handed out without logging","action":"Include the items you handed out without logging when you report the count.","brief":"report the items you did not log","reason":"Your unlogged handouts may explain the shortage. Being open about your own slip helps solve it and keeps your word trustworthy.","lesson":"Be open about your own mistakes, especially when they may explain a problem.","shortcut":[{"text":"Leave out the unlogged items so the shortage does not look like your fault.","brief":"leave out your unlogged items","why":"Hiding your part leaves the team chasing the wrong cause and damages trust if it comes out later.","mis":"Admitting a mistake will only get you in trouble."}]},{"id":"oncall","tier":4,"rule":"report-to-designated-person","principle":"int.report-to-on-call-manager","fact":["{Lead|the} has gone home, and the posted procedure says the on-call manager handles shortages after hours."],"short":"who should receive the report tonight","action":"Report the shortage to the manager on call, as the procedure says.","brief":"report it to the manager on call","reason":"The procedure names who receives shortage reports when the lead is out. Following it gets the report to someone who can act tonight.","lesson":"Send reports to the person the procedure names, even when it is not your usual supervisor.","shortcut":[{"text":"Leave a note for {lead|the} to read in the morning instead.","brief":"leave a note for the morning","why":"The procedure says the on-call manager handles shortages tonight. A morning note delays the report.","mis":"Your usual supervisor is always the right person to tell."}]}],"proceed":{"text":"Report the real count, including the shortage, to {lead|the}.","why":"The count is confirmed and nothing else needs handling first, so the honest next step is to report it.","lesson":"Report accurate results to the person responsible, even when they show a problem."},"generic":[{"text":"Leave the count sheet blank and let the morning shift sort it out.","why":"An empty count sheet hides the problem and passes your job to someone else.","mis":"If a result is awkward, it is better not to record it."},{"text":"Keep recounting until your number matches the log.","why":"Counting until you get the answer you want is not an honest count.","mis":"The log is always right, so the count must be wrong."}],"overcaution":[{"text":"Hold the count sheet until {lead|the} can recount everything personally tomorrow.","why":"The count has already been checked. Holding it back delays a report the team expects tonight.","mis":"Only a supervisor's count can be trusted."}],"process":{"setup":["You are {role|a} at {workplace|a}, counting {supply.plural} at closing, and the count is lower than the log."],"because":{"recount":["The posted procedure requires a second person to recount shortages."],"owncause":["You handed out some items today without logging them."],"oncall":["{Lead|the} has left, and shortages go to whoever is on call."]},"steps":[{"id":"count","text":"Count every item on the shelf","core":true},{"id":"second","text":"Have {coworker2} count them again","issue":"recount"},{"id":"write","text":"Write the real number on the sheet","core":true},{"id":"note","text":"Add a note about the unlogged handouts","issue":"owncause"},{"id":"lookup","text":"Check who is on call tonight","issue":"oncall"},{"id":"report","text":"Report the shortage","core":true}],"rel":[["count","second","The recount checks a first count, so the first count comes first."],["second","write","The confirmed number is what goes on the sheet."],["count","write","You write down the number after counting."],["write","note","The note explains the number on the sheet."],["note","report","The report should include your note."],["lookup","report","You need to know who to report to before reporting."],["write","report","The report is based on the written count."]],"alternatesReviewed":true,"lesson":"Count, confirm, record honestly, explain your part, then report to the right person."},"doc":{"type":"note","title":["Closing count report: {supply.plural}"],"intro":["You are checking this closing count report before it is filed."],"lesson":"An honest report records what was found, follows the check steps and sticks to facts.","lines":[{"id":"count","text":"Closing count: 44.","fine":"The actual count is recorded."},{"id":"log","text":"Log total: 50.","fine":"The log figure is recorded for comparison."},{"id":"diff","text":"Difference: 6 short.","fine":"The difference is stated accurately.","bad":[{"id":"diff-none","level":"intermediate","needs":["count","log"],"text":"Difference: none.","why":"The report shows 44 counted against 50 in the log. Saying there is no difference makes the record false.","principle":"int.doc-difference-misstated"}]},{"id":"second","text":"Second count by {coworker2}: 44, which matches.","fine":"The required second count is recorded.","bad":[{"id":"second-skip","level":"beginner","text":"Second count: skipped, since the first count was probably right.","why":"The procedure requires a second count for shortages. Skipping it breaks the procedure.","principle":"int.doc-skipped-second-count"}]},{"id":"note","text":"Note: I handed out 4 without logging them earlier today.","fine":"Honestly discloses a possible cause.","bad":[{"id":"note-blame","level":"advanced","text":"Note: the shortage was most likely caused by the new hire.","why":"Nothing in the report supports blaming a person. A report should state facts, not guesses about who is responsible.","principle":"int.doc-unsupported-blame"}]},{"id":"reported","text":"Reported to the manager on call at 9:15 p.m.","fine":"Records who received the report and when.","bad":[{"id":"reported-changed","level":"beginner","text":"Changed the count to 50 so it matches the log.","why":"Changing the count falsifies the record and hides the shortage.","principle":"int.doc-falsified-count"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Recount and on-call reporting are stated as posted procedures. No legal claims."}},{"id":"int-everyday-requests","skill":"integrity","family":"integrity.cx-everyday-requests","familyName":"Everyday requests that test integrity","framework":"ethical-dilemma","concepts":["integrity:policies-and-procedures","integrity:respect-for-property","integrity:honesty-and-fairness"],"contexts":"any","requires":["supply"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}, partway through a normal shift."],"pressure":["Nobody else is around to see what you do."],"detail":["It is a slow afternoon.","You have about an hour left in your shift."],"issues":[{"id":"lookup","tier":1,"rule":"use-records-for-work-only","principle":"int.no-personal-record-lookups","onlyLevels":["beginner"],"fact":["A friend asks you to use {system|the} to look up a neighbor's contact details."],"short":"the request to look up a neighbor","action":"Decline, and explain that work records are only used for work.","reason":"Looking up someone's details for personal reasons misuses access you were given for your job.","lesson":"Use access to records only for the work it was given for.","shortcut":[{"text":"Look it up quickly, since the friend will not share it with anyone.","why":"The access is for work only. Using it for a friend is a misuse, whatever happens next.","mis":"Access is fine to use as long as nothing bad happens."}]},{"id":"discount","tier":2,"rule":"follow-stated-policy","principle":"int.staff-discount-for-staff-only","onlyLevels":["beginner"],"fact":["A friend asks you for the staff discount, which the posted policy limits to employees."],"short":"the request for the staff discount","action":"Politely explain that the staff discount is only for employees.","reason":"The policy is clear, and applying it the same way for everyone is fair. A polite explanation keeps the friendship and the rule intact.","lesson":"Apply workplace policies the same way for friends as for everyone else.","shortcut":[{"text":"Give the discount quietly, since it is only a few dollars.","why":"The amount does not change the policy. Bending rules for friends is unfair to others.","mis":"Small rule-breaking does not count."}]},{"id":"supplies","tier":3,"rule":"respect-property","principle":"int.supplies-stay-at-work","onlyLevels":["beginner"],"fact":["{coworker} suggests you both take home some {supply.plural}, since there are plenty."],"short":"the suggestion to take supplies home","action":"Leave the supplies, and point out that they belong to the workplace.","reason":"Workplace supplies are not personal property, even when there are extras.","lesson":"Treat workplace property as belonging to the workplace, even when there is plenty.","shortcut":[{"text":"Take a few, since nobody will miss them.","why":"Whether anyone notices does not change who owns the supplies.","mis":"If nobody notices, it is not really taking."}]},{"id":"gift","tier":4,"rule":"follow-stated-policy","principle":"int.decline-cash-gift-per-handbook","onlyLevels":["beginner"],"fact":["A {client} offers you $20 in cash as thanks, and the handbook says staff may not accept cash gifts."],"short":"the cash gift","action":"Thank the {client} warmly and politely decline the cash.","reason":"The handbook does not allow cash gifts. A warm thank-you honors the gesture while following the rule.","lesson":"Follow gift rules politely; you can accept thanks without accepting the gift.","shortcut":[{"text":"Accept the cash quietly so the {client} is not offended.","why":"The handbook rule applies even when declining feels awkward. A sincere thank-you avoids offense.","mis":"Refusing a gift is always rude."}]},{"id":"timesheet","tier":5,"rule":"keep-accurate-records","principle":"int.correct-own-time-record","onlyLevels":["beginner"],"fact":["Your time sheet shows 30 minutes you did not work, because you forgot to clock out yesterday."],"short":"the extra 30 minutes on your time sheet","action":"Ask {lead|the} to correct your time sheet to the time you actually left.","reason":"Being paid for time you did not work is not fair to the employer. Fixing it yourself shows honesty.","lesson":"Correct records in your favor as readily as records against you.","shortcut":[{"text":"Leave the time sheet alone, since the clock made the mistake.","why":"You know the time is wrong. Keeping pay for time not worked is not honest, whoever made the error.","mis":"A mistake in your favor is not your responsibility."}]}],"proceed":{"text":"Go along with it this once to keep things friendly.","why":"Going along with the request would only be fine if no rule or fairness issue were involved.","lesson":"Integrity means doing the right thing even when going along would be easier."},"generic":[{"text":"Ask {coworker3} what they usually do and copy that.","why":"A coworker's habit is not the rule. The stated policy and honesty decide.","mis":"Whatever coworkers do must be acceptable."},{"text":"Say you will think about it and avoid the person for the rest of the day.","why":"Avoiding the question leaves it unresolved and is awkward for everyone. A clear, polite answer is better.","mis":"Avoiding a hard conversation makes it go away."}],"doc":{"type":"chat","title":["Tips from {coworker3} for your first week"],"intro":["{coworker3} sent you these first-week tips. One of them is bad advice."],"prompt":["Which tip is the problem?","Which line gives bad advice?"],"lesson":"Good workplace habits keep records accurate, property respected and rules applied fairly.","lines":[{"id":"hello","text":"Welcome to the team! Here are a few tips for your first week.","fine":"A friendly opening."},{"id":"clock","text":"Clock in and out at the times you actually start and stop.","fine":"Accurate time records are basic honesty.","bad":[{"id":"clock-even","level":"beginner","text":"If you forget to clock out, just leave it; it all evens out.","why":"Time records must be accurate. Leaving a wrong time means being paid for time not worked.","principle":"int.doc-inaccurate-time-record"}]},{"id":"supplies","text":"Supplies stay here, even when there are extras.","fine":"Workplace property stays at work.","bad":[{"id":"supplies-take","level":"beginner","text":"Extra {supply.plural} are fair game to take home.","why":"Workplace supplies are not personal property, even extras.","principle":"int.doc-taking-supplies"}]},{"id":"records","text":"Only look up records you need for your own work.","fine":"Access is for work purposes only.","bad":[{"id":"records-curious","level":"intermediate","text":"You can look up anyone in {system|the} if you are curious, as long as you keep it to yourself.","why":"Looking at records without a work reason is a misuse of access, even if nothing is shared.","principle":"int.doc-curious-lookups"}]},{"id":"handbook","text":"The handbook in the break room says staff may not accept cash gifts.","fine":"Accurately points to the written rule."},{"id":"gift","text":"If a {client} offers cash as thanks, thank them and politely decline.","fine":"Follows the handbook rule politely.","bad":[{"id":"gift-keep","level":"advanced","needs":["handbook"],"text":"If a {client} hands you cash as thanks, keep it quietly.","why":"This contradicts the handbook rule mentioned in the same message. Cash gifts must be declined.","principle":"int.doc-contradicts-gift-rule"}]},{"id":"ask","text":"Ask {lead|the} whenever a rule is unclear.","fine":"Encourages checking with the supervisor."}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario"],"notes":"Each rule (discount, gifts) is stated as workplace policy in the scenario. Issues are beginner-only because these requests would not naturally arrive together."}},{"id":"int-shared-report","skill":"integrity","family":"integrity.cx-shared-report","familyName":"Honesty and credit on a shared report","framework":"ethical-dilemma","concepts":["integrity:honesty-and-fairness","integrity:importance-of-integrity","integrity:respect-for-property"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You and {coworker} prepared {document|a} that {lead|the} will review tomorrow.","As {role|a} at {workplace|a}, you are finishing {document|a} with {coworker} for {lead|the} to review tomorrow."],"pressure":["{coworker3} says nobody checks these details anyway.","The review is first thing tomorrow morning."],"detail":["The document is saved in the shared folder.","You worked on it for about a week."],"tiers":{"1":"Accurate information comes before everything else.","2":"Fair credit has to be set right before the review.","3":"Your own errors should be fixed and admitted.","4":"Borrowed wording needs credit.","5":"Being honest about what is unchecked comes once the content is right."},"issues":[{"id":"number","tier":1,"rule":"refuse-to-falsify","principle":"int.no-adjusted-results","fact":["{coworker2} suggests changing one number so the results look better."],"short":"the suggestion to change a number","action":"Keep the real number and explain that the results must stay accurate.","brief":"keep the real number","reason":"Changed results mislead everyone who relies on the report.","lesson":"Report results as they are, even when they disappoint.","shortcut":[{"text":"Change the number slightly, since it is only one figure.","brief":"change the number slightly","why":"Changing even one number makes the report false.","mis":"Small changes to data are harmless."}],"noProceed":true},{"id":"credit","tier":2,"rule":"give-credit","principle":"int.correct-credit","fact":["{Lead|the} has thanked only you, though {coworker} did half the work."],"short":"the missing credit for {coworker}","action":"Tell {lead|the} that {coworker} did half the work.","brief":"credit {coworker} to {lead|the}","reason":"Letting someone else's work be credited to you is unfair and dishonest.","lesson":"Give credit where it is due, even when nobody would notice.","shortcut":[{"text":"Accept the thanks, since {coworker} did not mention it.","brief":"accept the thanks quietly","why":"Staying silent takes credit for work you did not do.","mis":"Credit belongs to whoever is thanked."}],"clear":["{Lead|the} already knows {coworker} did half the work."],"done":"the lead already knows who did the work"},{"id":"error","tier":3,"rule":"correct-own-error","principle":"int.fix-and-disclose-own-error","fact":["You find a mistake you made in your section."],"short":"your mistake","action":"Fix the mistake and tell {coworker} what you changed.","brief":"fix it and tell {coworker}","reason":"Fixing it openly keeps the report accurate and keeps your partner informed.","lesson":"Correct your own mistakes openly.","shortcut":[{"text":"Fix it quietly so nobody knows there was a mistake.","brief":"fix it quietly","why":"Fixing it is good, but hiding the change leaves your partner unaware of what changed.","mis":"Mistakes are best hidden."}]},{"id":"copied","tier":4,"rule":"credit-sources","principle":"int.credit-borrowed-wording","fact":["Part of your section copies a supplier's wording without saying where it came from."],"short":"the uncredited wording","action":"Credit the supplier's wording, or rewrite it in your own words.","brief":"credit or rewrite the wording","reason":"Presenting someone else's words as your own is dishonest, even in a work document.","lesson":"Credit wording you borrow.","shortcut":[{"text":"Leave it, since suppliers want their wording used.","brief":"leave the wording as is","why":"Even if allowed, the words should be credited, not presented as yours.","mis":"Borrowed wording does not need credit at work."}],"clear":["You already added a note crediting the supplier's wording."],"done":"the wording is already credited"},{"id":"unchecked","tier":5,"rule":"disclose-limits","principle":"int.disclose-unchecked-part","fact":["You will not finish checking the last section before the review."],"short":"the unchecked section","action":"Tell {lead|the} which section has not been checked yet.","brief":"tell {lead|the} what is unchecked","reason":"Being upfront about what is unchecked lets the lead judge how much to rely on it.","lesson":"Be honest about the limits of your work.","shortcut":[{"text":"Say the whole report is checked, since it probably is fine.","brief":"say it is all checked","why":"Claiming checks you did not do is dishonest and risky.","mis":"Probably right is close enough to checked."}]}],"proceed":{"text":"Send {document|the} to {lead|the} for tomorrow's review.","why":"The report is accurate, credited and checked, so it is ready to send.","lesson":"Send work forward once it is honest, accurate and fairly credited."},"generic":[{"text":"Ask {coworker3} to send it under their name instead.","why":"Changing who sends it does not fix any problem and misrepresents who did the work.","mis":"Whoever sends a document gets the credit."},{"text":"Delay the review by saying the file was lost.","why":"Making up an excuse is dishonest.","mis":"A small lie is fine if it buys time."}],"overcaution":[{"text":"Ask {lead|the} to recheck every number before you send it.","why":"The report is already checked and accurate; a full recheck is unnecessary.","mis":"Nothing is honest until a supervisor checks it."}],"process":{"setup":["You and {coworker} are finishing {document|a} at {workplace|the} for a review tomorrow."],"because":{"error":["You spotted a mistake in your own section."],"copied":["Some wording in your section came from a supplier."],"unchecked":["You will not have time to check the last section."]},"steps":[{"id":"fix","text":"Correct your mistake","issue":"error"},{"id":"cite","text":"Credit the supplier's wording","issue":"copied"},{"id":"tellco","text":"Tell {coworker} what you changed","core":true},{"id":"note","text":"Note which section is unchecked","issue":"unchecked"},{"id":"send","text":"Send it to {lead|the}","core":true}],"rel":[["fix","tellco","Tell your partner after you make the change."],["cite","tellco","Your partner should know about the added credit."],["tellco","send","Your partner should see the final version first."],["note","send","The note goes in with the report."]],"alternatesReviewed":true,"lesson":"Fix, credit, share changes, disclose limits, then send."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"policyNotNeeded":true,"notes":"Honesty and credit; no rules beyond general ethics are assumed."}},{"id":"jst-equipment-use","skill":"job-specific-tools-and-technologies","family":"job-specific-tools-and-technologies.cx-using-job-equipment","familyName":"Using the equipment the job calls for","framework":"safest-action","concepts":["job-specific-tools-and-technologies:safe-use","job-specific-tools-and-technologies:select-right-tool"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. Today's job calls for {equipment|the}.","As {role|a} at {workplace|a}, you are about to use {equipment|the} for the next job."],"pressure":["{coworker3} says the job should have been done an hour ago.","{coworker3} says experienced workers skip the paperwork."],"detail":["The job is routine.","You have about two hours left in your shift."],"tiers":{"1":"Damaged equipment comes out of use before anything else.","2":"The protective gear the instructions call for goes on before you start.","3":"Using equipment for a job it was not made for adds risk.","4":"Unfamiliar models need their instructions read first.","5":"Signing equipment out keeps track of who used what.","6":"Clean-up comes after the job, once everything else is in order."},"issues":[{"id":"damaged","tier":1,"rule":"control-hazard-first","principle":"jst.tag-out-damaged-equipment","fact":["A part of {equipment|the} is cracked, and someone has covered the crack with tape."],"short":"the cracked, taped part","action":"Tag {equipment|the} out of service and report the cracked part to {lead|the}.","brief":"tag it out and report the crack","reason":"Tape hides damage without fixing it. Equipment with a cracked part can fail during use.","lesson":"Damaged equipment is taken out of service and reported, even if someone patched it.","shortcut":[{"text":"Use it carefully, since someone already taped the crack.","brief":"use it since it was taped","why":"Tape is not a repair. The cracked part can still fail.","mis":"A temporary patch makes equipment safe."}]},{"id":"gear","tier":2,"rule":"wear-required-gear","principle":"jst.wear-gear-instructions-require","fact":["The operating instructions call for gloves and eye protection, and you are not wearing either."],"clear":["You are already wearing the gloves and eye protection the instructions call for."],"done":"you are already wearing the required gear","short":"the missing gloves and eye protection","action":"Put on the gloves and eye protection the instructions call for.","brief":"put on the required gear","reason":"The instructions list protective gear because the equipment can cause injuries without it.","lesson":"Wear the protective gear the equipment instructions require.","shortcut":[{"text":"Skip the gear, since the job only takes a minute.","brief":"skip the gear for a quick job","why":"Injuries can happen in seconds. Quick jobs still need the gear.","mis":"Short jobs do not need protection."}]},{"id":"substitute","tier":3,"rule":"use-right-tool","principle":"jst.avoid-improvised-tool","fact":["{Equipment|the} is busy, so {coworker} suggests using a different machine that was not made for this job."],"short":"the machine not made for this job","action":"Wait for {equipment|the}, or ask {lead|the} about an approved alternative.","brief":"wait or ask about an approved alternative","reason":"Equipment used for the wrong job can damage the work, the machine or you.","lesson":"Use the right tool for the job, even if it means waiting.","shortcut":[{"text":"Use the other machine, since it is close enough.","brief":"use the other machine","why":"Close enough is not the right tool. It may not be safe or accurate for this job.","mis":"Any similar tool will do the job."}],"ignore":"{Equipment|the} is busy right now, so starting the job on it is not an option yet."},{"id":"model","tier":4,"rule":"read-instructions","principle":"jst.read-instructions-for-new-model","fact":["This is a newer model of {equipment} that you have not used before."],"clear":["You used this exact model many times last month."],"done":"you already know this model well","short":"the unfamiliar model","action":"Review the operating instructions for this model before using it.","brief":"review this model's instructions","reason":"Controls and limits can change between models. A quick review prevents mistakes.","lesson":"Learn a new model's instructions before using it.","shortcut":[{"text":"Use it like the old model, since they are probably the same.","brief":"use it like the old model","why":"Newer models often change controls or limits.","mis":"All models of a tool work the same way."}]},{"id":"signout","tier":5,"rule":"follow-tracking-procedure","principle":"jst.sign-out-equipment","fact":["The posted rule says equipment use must be signed for in {record|the}."],"short":"the sign-out requirement","action":"Sign for {equipment|the} in {record|the} before you start.","brief":"sign for it before starting","reason":"Sign-out records show who used equipment and when, which matters if a problem turns up.","lesson":"Follow equipment tracking procedures every time.","shortcut":[{"text":"Sign for it at the end of the day with everything else.","brief":"sign at the end of the day","why":"Signing later breaks the posted rule and can leave the record wrong.","mis":"Paperwork can always wait until later."}],"clear":["You already signed for {equipment|the} in {record|the}."],"done":"you already signed for it"},{"id":"cleanup","tier":6,"rule":"care-for-equipment","principle":"jst.clean-and-return-equipment","noProceed":true,"fact":["The posted rule says {equipment|the} must be cleaned and returned to its spot after use."],"short":"the clean-and-return rule","action":"Plan to clean {equipment|the} and return it to its spot when you finish.","brief":"plan to clean and return it","reason":"Cleaning and returning equipment keeps it working and ready for the next person.","lesson":"Care for shared equipment so it is ready for the next person.","shortcut":[{"text":"Leave it out for whoever uses it next.","brief":"leave it out","why":"Leaving equipment dirty or out of place breaks the rule and slows the next person.","mis":"The next user can clean up."}]}],"proceed":{"text":"Use {equipment|the} for the job, following its instructions.","why":"The equipment, gear and paperwork all check out, so the job can go ahead.","lesson":"When the right equipment is ready and checked, use it as instructed."},"generic":[{"text":"Ask {coworker2} to do the job instead, without telling {lead|the}.","why":"Passing the job on quietly confuses who is responsible for it.","mis":"Handing off a job avoids the problem."},{"text":"Adjust the settings to their highest level to finish faster.","why":"Running above normal settings can damage the work or the equipment.","mis":"Higher settings always mean faster, better work."}],"overcaution":[{"text":"Wait for {lead|the} to watch you use {equipment|the} the first time today.","why":"You know the model and are prepared. Waiting for supervision wastes time.","mis":"Every use needs supervision."}],"process":{"setup":["You are {role|a} at {workplace|a}, about to use {equipment|the} for a job."],"because":{"model":["The {equipment} here is a model you have not used before."],"signout":["Equipment use must be signed for in {record|the}."]},"steps":[{"id":"sign","text":"Sign for it in the log","issue":"signout"},{"id":"read","text":"Review the instructions for this model","issue":"model"},{"id":"inspect","text":"Inspect it for damage","core":true},{"id":"gear","text":"Put on the protective gear","core":true},{"id":"use","text":"Do the job","core":true}],"rel":[["read","inspect","The instructions tell you what to check on this model."],["read","gear","The instructions list the gear you need."],["inspect","use","Damage has to be found before use."],["gear","use","Gear goes on before you start."],["sign","use","The rule says to sign before using it."]],"alternatesReviewed":true,"lesson":"Sign out, learn the model, inspect, gear up, then do the job."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Sign-out rule stated as posted policy; gear requirement attributed to the equipment instructions."}},{"id":"jst-pick-the-tool","skill":"job-specific-tools-and-technologies","family":"job-specific-tools-and-technologies.cx-choosing-the-right-tool","familyName":"Choosing the right tool for the task","framework":"consequences","concepts":["job-specific-tools-and-technologies:select-right-tool"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}, working on a task for {lead|the}."],"detail":["It is a regular workday.","The task needs to be done by the end of the day."],"issues":[{"id":"total","tier":1,"rule":"use-right-tool","principle":"jst.spreadsheet-for-totals","onlyLevels":["beginner"],"fact":["You need to total 200 numbers from {record|the}, and you were about to add them by hand."],"short":"adding 200 numbers by hand","action":"Put the numbers in a spreadsheet and let it calculate the total.","reason":"A spreadsheet is faster and far less error-prone than adding hundreds of numbers by hand.","lesson":"Choose tools that make the task faster and more accurate.","shortcut":[{"text":"Add them by hand twice to make sure the total is right.","why":"Doing it twice by hand doubles the time and still risks errors.","mis":"Doing it by hand is more reliable."}]},{"id":"measure","tier":2,"rule":"use-right-tool","principle":"jst.measure-instead-of-estimate","onlyLevels":["beginner"],"fact":["The job needs an exact measurement, and you were going to estimate it by eye."],"short":"estimating by eye","action":"Use a proper measuring tool so the measurement is exact.","reason":"An estimate can be off enough to ruin the work. A measuring tool gives the exact number.","lesson":"Use measuring tools when a job needs exact numbers.","shortcut":[{"text":"Estimate carefully, since you have a good eye.","why":"Even a good eye is not exact. The job needs a real measurement.","mis":"Experience replaces measuring."}]},{"id":"calendar","tier":3,"rule":"use-right-tool","principle":"jst.shared-calendar-for-scheduling","onlyLevels":["beginner"],"fact":["You need to find a meeting time for ten people, and you planned to message each one separately."],"short":"scheduling ten people one message at a time","action":"Use the shared calendar to find a time that works for everyone.","reason":"The shared calendar shows everyone's availability at once and saves dozens of messages.","lesson":"Use shared tools for tasks that involve many people.","shortcut":[{"text":"Pick a time yourself and hope most people can come.","why":"Guessing a time may leave people out when the calendar could show what works.","mis":"Picking a time is faster than checking."}]},{"id":"template","tier":4,"rule":"use-right-tool","principle":"jst.use-existing-template","onlyLevels":["beginner"],"fact":["You need to make {document|a}, and the shared folder already has an approved template for it."],"short":"starting from a blank page","action":"Start from the approved template in the shared folder.","reason":"The template has the approved layout and required parts, which saves time and avoids missing pieces.","lesson":"Use approved templates instead of starting from scratch.","shortcut":[{"text":"Design a new layout from scratch so it looks fresh.","why":"A new layout may miss required parts and takes longer.","mis":"Original layouts are always better."}]},{"id":"scan","tier":5,"rule":"use-right-tool","principle":"jst.scanner-for-item-entry","onlyLevels":["beginner"],"fact":["You need to enter 80 item codes, and {system|the} can read them with a scanner."],"short":"typing 80 codes by hand","action":"Use the scanner to enter the item codes.","reason":"Scanning is faster and avoids typing errors.","lesson":"Use the technology built for the task.","shortcut":[{"text":"Type each code by hand, since you type quickly.","why":"Typing 80 codes is slow and invites mistakes the scanner would avoid.","mis":"Fast typing beats the right tool."}]},{"id":"label","tier":6,"rule":"use-right-tool","principle":"jst.label-printer-for-labels","onlyLevels":["beginner"],"fact":["You need 50 matching labels, and you were about to write each one by hand."],"short":"writing 50 labels by hand","action":"Use the label printer or a template to make all 50 labels.","reason":"A printer makes the labels faster, neater and identical.","lesson":"Use the tool built for repeated tasks.","shortcut":[{"text":"Write them by hand, since handwriting is more personal.","why":"Fifty handwritten labels take far longer and may be hard to read.","mis":"Doing it by hand is always better quality."}]}],"proceed":{"text":"Do the task by hand the way you always have.","why":"A better tool for this task is available, so the old way wastes time.","lesson":"Picking the right tool is part of doing the job well."},"generic":[{"text":"Ask {coworker} to do it, since they like that kind of task.","why":"Handing off the task avoids learning the tool you need.","mis":"Someone else's preference is a reason to hand off work."},{"text":"Skip the task and tell {lead|the} it was too slow to finish.","why":"The right tool makes the task manageable. Skipping it leaves the work undone.","mis":"Slow tasks can be skipped."}],"doc":{"type":"procedure","title":["Tool tips for new staff"],"intro":["You are checking these tool tips before they go into the new-staff packet."],"prompt":["Which tip is the problem?","Which line gives bad advice?"],"lesson":"Good tool guidance matches each task with the right, safe tool.","lines":[{"id":"spread","text":"Use the spreadsheet for totals and calculations.","fine":"Matches the task to the right tool.","bad":[{"id":"spread-hand","level":"beginner","text":"Add long lists of numbers by hand to avoid computer mistakes.","why":"Adding by hand is slower and more error-prone than a spreadsheet.","principle":"jst.doc-hand-totals"}]},{"id":"measure","text":"Measure with the proper tool; do not estimate by eye.","fine":"Exact measurement for exact jobs.","bad":[{"id":"measure-eye","level":"beginner","text":"Estimate measurements by eye; it is faster.","why":"Estimates can be off enough to ruin the job; measure instead.","principle":"jst.doc-estimate-by-eye"}]},{"id":"templates","text":"Start documents from the approved templates.","fine":"Uses approved tools.","bad":[{"id":"templates-blank","level":"beginner","text":"Start every document from a blank page.","why":"Approved templates contain required parts and save time.","principle":"jst.doc-ignores-templates"}]},{"id":"improvise","text":"If a tool is busy, wait or ask {lead|the} about an approved alternative.","fine":"Avoids improvised tools.","bad":[{"id":"improvise-any","level":"beginner","text":"If a tool is busy, use whatever is nearby that looks similar.","why":"Similar-looking tools may not be safe or accurate for the job.","principle":"jst.doc-improvised-tool"}]},{"id":"manual","text":"Read the instructions before using a model you do not know.","fine":"Learns new equipment safely.","bad":[{"id":"manual-skip","level":"intermediate","text":"All models work the same, so you can skip the instructions.","why":"Models differ in controls and limits; instructions should be read.","principle":"jst.doc-skip-instructions"}]},{"id":"damage","text":"Report damaged tools and tag them out of service.","fine":"Keeps damaged tools out of use.","bad":[{"id":"damage-tape","level":"advanced","needs":["improvise"],"text":"Tape over cracks on tools so they can keep being used.","why":"Taping a crack hides damage. The tool should be tagged out and reported.","principle":"jst.doc-tape-damaged-tool"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Tool-selection situations are beginner-only single decisions."}},{"id":"lis-spoken-instructions","skill":"listening-and-speaking","family":"listening-and-speaking.cx-spoken-instructions","familyName":"Taking in spoken instructions","framework":"critical-information","concepts":["listening-and-speaking:active-listening","listening-and-speaking:nonverbal-cues"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. At the start of the shift, {lead|the} quickly explains a rush job to you and two coworkers.","As {role|a} at {workplace|a}, you are in a quick huddle where {lead|the} explains today's rush job."],"pressure":["{Lead|the} says the team needs to get moving in two minutes.","{coworker3} whispers that it will all make sense once you start."],"detail":["The huddle is happening next to the time clock.","Two other coworkers are listening too."],"tiers":{"1":"A safety warning you did not fully hear has to be cleared up first.","2":"Signs that a teammate disagrees are worth raising while everyone is still together.","3":"A missing detail you need for the job should be confirmed before you start.","4":"Losing track of the instructions calls for a recap before work begins.","5":"Checking your understanding is useful once the gaps are filled."},"issues":[{"id":"warning","tier":1,"rule":"confirm-safety-information","principle":"lis.confirm-misheard-warning","fact":["Over the noise, you only partly heard a warning {lead|the} gave about {equipment|the}."],"clear":["{Lead|the} also handed out the warning about {equipment|the} in writing."],"done":"the warning was already given in writing","short":"the warning you only partly heard","action":"Ask {lead|the} to repeat the warning about {equipment|the} before you start.","brief":"ask {lead|the} to repeat the warning","reason":"A safety warning only protects you if you heard all of it. Asking now takes seconds.","lesson":"If you did not fully hear a safety warning, ask for it again before you act.","shortcut":[{"text":"Ask {coworker} later what the warning was about.","brief":"ask {coworker} about it later","why":"{coworker} may not have heard it fully either, and you need it before using the equipment.","mis":"A coworker's memory is as good as the original instructions."}]},{"id":"body","tier":2,"rule":"respond-to-nonverbal-cue","principle":"lis.check-on-nonverbal-disagreement","fact":["{coworker} says the plan is fine but crosses both arms and frowns."],"short":"{coworker}'s mixed signals","action":"Ask {coworker} gently whether something about the plan seems off.","brief":"gently ask {coworker} about the plan","reason":"Body language that does not match the words often means an unspoken concern. Asking now may surface a real problem.","lesson":"Notice when body language and words do not match, and check in.","shortcut":[{"text":"Take {coworker} at their word, since they said the plan is fine.","brief":"take {coworker} at their word","why":"The crossed arms and frown suggest a concern. Ignoring the signal may leave a problem unspoken.","mis":"Only spoken words matter in a conversation."}]},{"id":"time","tier":3,"rule":"confirm-missed-detail","principle":"lis.confirm-missed-deadline","fact":["You missed the deadline {lead|the} mentioned for finishing the job."],"clear":["{Lead|the} wrote the ready time on the board."],"done":"the ready time is already written on the board","short":"the ready time you missed","action":"Ask {lead|the} to confirm what time the job must be ready.","brief":"confirm the ready time with {lead|the}","reason":"The deadline shapes how you plan the job. Confirming it now prevents a costly misunderstanding.","lesson":"Confirm key details you missed instead of guessing.","shortcut":[{"text":"Assume the job is due at the usual end-of-shift time.","brief":"assume the usual deadline","why":"A rush job may have a different deadline. Guessing risks finishing too late.","mis":"The usual answer is probably the right one."}]},{"id":"lost","tier":4,"rule":"request-recap","principle":"lis.ask-for-recap","fact":["{coworker2} keeps cutting in with side comments, and you are losing track of the steps."],"short":"losing track of the steps","action":"At the next pause, ask {lead|the} to recap the key steps.","brief":"ask {lead|the} for a quick recap","reason":"A short recap fixes gaps caused by interruptions, and waiting for a pause is respectful.","lesson":"When interruptions break your understanding, politely ask for a recap.","shortcut":[{"text":"Nod along and figure out the steps once the work starts.","brief":"nod along and figure it out later","why":"Pretending to understand hides the gap until it causes a mistake.","mis":"Nodding along is the polite thing to do."}]},{"id":"check","tier":5,"rule":"summarize-back","principle":"lis.paraphrase-to-confirm","noProceed":true,"fact":["{Lead|the} asks whether everyone understands the plan."],"short":"checking your understanding","action":"Briefly summarize the plan back to {lead|the} to check you have it right.","brief":"summarize the plan back","reason":"Repeating the plan in your own words is the quickest way to catch a misunderstanding before work starts.","lesson":"Paraphrase instructions back to confirm you understood them.","shortcut":[{"text":"Say yes, since asking questions might slow everyone down.","brief":"just say yes","why":"A quick yes skips the chance to catch a misunderstanding.","mis":"Saying you understand is the same as understanding."}]}],"proceed":{"text":"Start the rush job the way {lead|the} described it.","why":"You have the details you need, so starting the job as described is the right move.","lesson":"Once you have heard and understood the instructions, act on them."},"generic":[{"text":"Look at your phone during the huddle and catch up afterward.","why":"Not paying attention during instructions guarantees you will miss something.","mis":"You can catch up on instructions later."},{"text":"Interrupt {lead|the} mid-sentence to ask about something unrelated.","why":"Cutting in with an unrelated question breaks everyone's focus.","mis":"Any question is worth asking right away."}],"overcaution":[{"text":"Ask {lead|the} to repeat all of the instructions from the start.","why":"You already have the details. Asking for a full repeat holds up the whole team.","mis":"Hearing everything twice is always safer."}],"process":{"setup":["{Lead|the} at {workplace|the} is about to explain a rush job to your team."],"because":{"warning":["Part of a warning about {equipment|the} was drowned out by noise."],"time":["You did not catch when the job is due."]},"steps":[{"id":"listen","text":"Listen closely without interrupting","core":true},{"id":"warn","text":"Ask to hear the warning again","issue":"warning"},{"id":"due","text":"Confirm the ready time","issue":"time"},{"id":"recap","text":"Repeat the plan back in your own words","core":true},{"id":"begin","text":"Begin the rush job","core":true}],"rel":[["listen","warn","You ask about what you missed once the explanation ends."],["listen","due","You ask about the missed detail after the explanation."],["listen","recap","You can only repeat back what you have heard."],["warn","begin","The warning has to be clear before work starts."],["due","recap","Your recap should include the ready time."],["recap","begin","Confirm your understanding before starting."]],"alternatesReviewed":true,"lesson":"Listen first, clear up what you missed, confirm your understanding, then begin."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Active listening and nonverbal cues; all issues occur during one huddle."}},{"id":"lis-group-update","skill":"listening-and-speaking","family":"listening-and-speaking.cx-group-update","familyName":"Preparing a short spoken update","framework":"communication-failure","concepts":["listening-and-speaking:presenting","listening-and-speaking:audience-and-setting"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. Tomorrow you will give a short spoken update about a change to {task|the}.","As {role|a} at {workplace|a}, you have been asked to present a change to {task|the} at tomorrow's meeting."],"pressure":["{coworker3} says nobody really listens to these updates anyway.","You have only tonight to prepare."],"detail":["You wrote your notes on index cards.","This is your first time presenting at work."],"tiers":{"1":"Getting a fact wrong in front of a group misleads everyone at once.","2":"The time limit decides how much you can say.","3":"Words the audience does not know make the message useless.","4":"A setting where people cannot hear needs fixing before the content.","5":"Slide design matters less than accuracy, timing and clarity."},"issues":[{"id":"number","tier":1,"rule":"verify-before-presenting","principle":"lis.verify-figure-before-presenting","fact":["One number in your notes is from last month, and you are not sure it is still right."],"clear":["{coworker} confirmed this morning that the number is still current."],"done":"the number was already confirmed","short":"the possibly outdated number","action":"Check that number with {coworker} or the records before you present it.","brief":"check the number before presenting","reason":"Presenting a wrong figure misleads everyone in the room. Checking it first protects your credibility.","lesson":"Verify the facts you plan to present before you speak.","shortcut":[{"text":"Leave the number in, since it is probably close enough.","brief":"keep the number as it is","why":"A wrong number spoken to a group spreads quickly and is hard to correct.","mis":"Numbers in a talk do not need to be exact."}]},{"id":"long","tier":2,"rule":"fit-the-time","principle":"lis.cut-to-time-limit","fact":["You have three minutes, but your notes would take about ten."],"short":"notes that run three times too long","action":"Cut the update down to the three points people most need to know.","brief":"cut it to the three key points","reason":"Going over time loses the audience and the meeting. Choosing the key points makes the message stick.","lesson":"Fit your message to the time you have by focusing on what matters most.","shortcut":[{"text":"Plan to talk faster so everything fits into three minutes.","brief":"plan to talk faster","why":"Rushing makes the update harder to follow. Cutting content works better than speeding up.","mis":"Speaking faster lets you say more."}]},{"id":"jargon","tier":3,"rule":"match-audience","principle":"lis.plain-words-for-audience","fact":["Some of the audience will be {client.plural} who do not know the team's shorthand terms."],"short":"terms the {client.plural} will not know","action":"Replace the shorthand terms with plain words everyone will know.","brief":"swap the shorthand for plain words","reason":"An audience cannot act on words it does not understand. Plain language reaches everyone in the room.","lesson":"Choose words that fit your audience, not just your team.","shortcut":[{"text":"Keep the shorthand, since it sounds more professional.","brief":"keep the shorthand terms","why":"Jargon the audience does not know sounds confusing, not professional.","mis":"Technical terms make a speaker sound more credible."}],"clear":["You already replaced the shorthand terms with plain words."],"done":"the shorthand was already replaced"},{"id":"noisy","tier":4,"rule":"fit-the-setting","principle":"lis.fix-setting-before-speaking","fact":["The meeting is in a noisy {area}, and there is no microphone."],"clear":["{Lead|the} already moved the meeting to a quiet room."],"done":"the meeting was already moved to a quiet room","short":"the noisy room","action":"Ask {lead|the} whether the meeting can move somewhere quieter.","brief":"ask {lead|the} about a quieter room","reason":"A message nobody can hear accomplishes nothing. Fixing the setting makes everything else work.","lesson":"Make sure the setting lets your audience hear you.","shortcut":[{"text":"Plan to shout over the noise so everyone can hear.","brief":"plan to speak over the noise","why":"Speaking over loud noise strains your voice and still leaves people missing parts.","mis":"Louder always means clearer."}]},{"id":"slides","tier":5,"rule":"simplify-visuals","principle":"lis.simplify-crowded-slides","fact":["Your one slide is packed with small text."],"short":"the crowded slide","action":"Simplify the slide to a few large words that support what you say.","brief":"simplify the slide","reason":"People cannot read small text and listen at the same time. A simple slide supports your words.","lesson":"Use visuals that support your talk rather than compete with it.","shortcut":[{"text":"Read the slide aloud word for word so nothing is missed.","brief":"read the slide aloud","why":"Reading a crowded slide aloud is slow and loses the audience.","mis":"Reading the slide is the safest way to present."}]}],"proceed":{"text":"Give the update as planned, speaking clearly and looking at the group.","why":"The content, timing and setting are ready, so delivering the update clearly is all that is left.","lesson":"When the message is accurate and fits the audience, deliver it clearly and confidently."},"generic":[{"text":"Ask {coworker2} to give the update for you.","why":"The update is your assignment. Handing it off without a reason avoids a useful skill.","mis":"Avoiding a presentation avoids the risk."},{"text":"Skip preparing and speak off the top of your head tomorrow.","why":"Unprepared talks ramble and miss key points.","mis":"Speaking naturally does not need preparation."}],"overcaution":[{"text":"Ask to postpone the update until next week to prepare more.","why":"The update is ready. Postponing delays information people need.","mis":"More preparation time always helps."}],"doc":{"type":"note","title":["Your speaking notes"],"intro":["These are your notes for tomorrow's three-minute update to staff and {client.plural}. Check them."],"prompt":["Which line of the notes is the problem?","Which line should you change?"],"lesson":"Good speaking notes are accurate, fit the time and use words the audience knows.","lines":[{"id":"hook","text":"Start: one sentence on why the change matters.","fine":"A short, clear opening."},{"id":"what","text":"Point 1: what is changing about {task|the}, in plain words.","fine":"Uses plain language for a mixed audience.","bad":[{"id":"what-jargon","level":"intermediate","text":"Point 1: explain the change using our internal codes and abbreviations.","why":"{client.plural} in the audience will not know internal codes. Plain words reach everyone.","principle":"lis.doc-jargon-for-mixed-audience"}]},{"id":"when","text":"Point 2: the change starts Monday.","fine":"A specific date."},{"id":"who","text":"Point 3: who to ask with questions.","fine":"Tells the audience what to do next."},{"id":"time","text":"Keep the whole update under three minutes.","fine":"Respects the time limit.","bad":[{"id":"time-over","level":"advanced","needs":["hook"],"text":"Add Points 4 through 9 with the full history of the old process.","why":"Six more points will not fit in a three-minute update and bury the three that matter.","principle":"lis.doc-overloaded-short-talk"}]},{"id":"eye","text":"Look up from the notes and speak to the room.","fine":"Encourages eye contact and connection.","bad":[{"id":"eye-read","level":"beginner","text":"Read the notes word for word without looking up.","why":"Reading without looking up loses the audience's attention.","principle":"lis.doc-no-eye-contact"}]},{"id":"end","text":"End: ask whether there are any questions.","fine":"Invites questions.","bad":[{"id":"end-rush","level":"beginner","text":"End: leave right away without taking questions.","why":"Skipping questions leaves confusion unresolved.","principle":"lis.doc-no-questions"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Presenting and audience/setting; issues are all preparation-time facts."},"requires":["area"]},{"skill":"mathematics","engine":"numeric","framework":"numeric-decision","contexts":"any","requires":["supply","area"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}."],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","numbers-oracle-verified"],"notes":"Answers are calculated from generated numbers; distractors are named calculation misconceptions; policies (overtime, tip pool, reorder) are stated in the scenario. Verified by tests/compose-numeric-oracle.test.js."},"id":"mat-purchasing","family":"mathematics.cx-purchasing-math","familyName":"Purchasing and pricing math","concepts":["mathematics:basic-calculations","mathematics:job-task-math"],"configs":[{"id":"unit-price","level":"beginner","principle":"mat.unit-price-division","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A pack of {n|int} {supply.plural} costs {p|money}."],"prompt":["What is the cost per item?"],"vars":{"n":{"type":"choice","values":[4,5,8,10,20,25]},"p":{"type":"int","min":12,"max":60,"step":1}},"derive":{"ans":"round2(p/n)","w1":"round2(n/p)","w2":"p","w3":"round2(p*n)"},"constraints":["ans >= 0.5","w1 >= 0.05","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The cost per item is {ans|money}.","ok":"1","why":"The price per item is the pack price divided by the number of items in the pack.","mis":"-"},{"key":"w1","text":"The cost per item is {w1|money}.","ok":"0","why":"This divides the number of items by the price, which is upside down.","mis":"Divide whichever way gives a small number."},{"key":"w2","text":"The cost per item is {w2|money}.","ok":"0","why":"That is the price of the whole pack, not one item.","mis":"The pack price is the item price."},{"key":"w3","text":"The cost per item is {w3|money}.","ok":"0","why":"This multiplies instead of dividing.","mis":"Multiply when you see two numbers."}],"lesson":"Price per item = pack price ÷ items in the pack."},{"id":"total-cost","level":"beginner","principle":"mat.total-cost-multiplication","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["You need {q|int} {supply.plural}, and each one costs {e|money}."],"prompt":["What is the total cost?"],"vars":{"q":{"type":"int","min":3,"max":15,"step":1},"e":{"type":"choice","values":[2.5,3.75,4.2,6.4,8.15,9.6]}},"derive":{"ans":"round2(q*e)","w1":"round2(q+e)","w2":"e","w3":"round2(q*e+e)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The total cost comes to {ans|money}.","ok":"1","why":"Multiply the number of items by the price of each one.","mis":"-"},{"key":"w1","text":"The total cost comes to {w1|money}.","ok":"0","why":"This adds the quantity to the price instead of multiplying.","mis":"Adding and multiplying give the same kind of total."},{"key":"w2","text":"The total cost comes to {w2|money}.","ok":"0","why":"That is the price of one item, not the total.","mis":"The listed price is the total."},{"key":"w3","text":"The total cost comes to {w3|money}.","ok":"0","why":"This counts one item too many.","mis":"Close counts are good enough."}],"lesson":"Total cost = quantity × price per item."},{"id":"change-due","level":"beginner","principle":"mat.change-due-subtraction","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A {client}'s purchase comes to {t|money}, and they pay with a {bill|money0} bill."],"prompt":["How much change is due?"],"vars":{"tc":{"type":"int","min":1105,"max":1895,"step":1},"bill":{"type":"choice","values":[20,50]}},"derive":{"t":"tc/100","ans":"round2(bill-t)","w1":"bill-floor(t)","w2":"bill-ceil(t)","w3":"round2(bill-t-1)"},"constraints":["tc % 100 != 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The change due is {ans|money}.","ok":"1","why":"Change is the amount paid minus the total, including the cents.","mis":"-"},{"key":"w1","text":"The change due is {w1|money}.","ok":"0","why":"This ignores the cents in the total.","mis":"Only the dollars matter when making change."},{"key":"w2","text":"The change due is {w2|money}.","ok":"0","why":"This rounds the total up before subtracting.","mis":"Rounding first is close enough."},{"key":"w3","text":"The change due is {w3|money}.","ok":"0","why":"This is one dollar short, a borrowing mistake.","mis":"Subtraction mistakes cancel out."}],"lesson":"Change due = amount paid − total."},{"id":"boxes-needed","level":"beginner","principle":"mat.round-up-for-whole-packs","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["You need {m|int} {supply.plural}, and they come {k|int} to a box."],"prompt":["How many boxes do you need to order?"],"vars":{"m":{"type":"int","min":25,"max":95,"step":1},"k":{"type":"choice","values":[6,8,12]}},"derive":{"ans":"ceil(m/k)","w1":"floor(m/k)","w2":"ceil(m/k)+1","w3":"round(m/k, 1)"},"constraints":["m % k != 0","round(m/k,1) != floor(m/k)","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You need to order {ans|int} boxes.","ok":"1","why":"Some items would be left out with fewer boxes, so round up to the next whole box.","mis":"-"},{"key":"w1","text":"You need to order {w1|int} boxes.","ok":"0","why":"Rounding down leaves you short of the items you need.","mis":"Always round to the nearest whole number."},{"key":"w2","text":"You need to order {w2|int} boxes.","ok":"0","why":"This orders one more box than needed.","mis":"An extra box is always safer."},{"key":"w3","text":"You need to order {w3|dec1} boxes.","ok":"0","why":"You cannot order part of a box.","mis":"The exact division is the answer."}],"lesson":"When items come in packs, round up to whole packs."},{"id":"percent-off","level":"beginner","principle":"mat.percent-discount","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["An item normally costs {pr|money0} and is on sale for {d|int} percent off."],"prompt":["What is the sale price?"],"vars":{"pr":{"type":"int","min":20,"max":120,"step":4},"d":{"type":"choice","values":[10,15,20,25,30]}},"derive":{"ans":"round2(pr*(1-d/100))","w1":"round2(pr*d/100)","w2":"pr-d","w3":"round2(pr*(1+d/100))"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The sale price is {ans|money}.","ok":"1","why":"Take the discount off the original price: price × (1 − percent off).","mis":"-"},{"key":"w1","text":"The sale price is {w1|money}.","ok":"0","why":"That is the amount saved, not the sale price.","mis":"The discount amount is the new price."},{"key":"w2","text":"The sale price is {w2|money}.","ok":"0","why":"This subtracts the percent as if it were dollars.","mis":"Percent and dollars can be subtracted directly."},{"key":"w3","text":"The sale price is {w3|money}.","ok":"0","why":"This adds the percent instead of taking it off.","mis":"Percent changes always add."}],"lesson":"Sale price = original price − (percent off × original price)."},{"id":"sales-tax","level":"beginner","principle":"mat.add-sales-tax","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["An order comes to {s|money0} before tax, and the tax rate is {t|int} percent."],"prompt":["What is the total with tax?"],"vars":{"s":{"type":"int","min":20,"max":90,"step":1},"t":{"type":"choice","values":[5,6,7,8]}},"derive":{"ans":"round2(s*(1+t/100))","w1":"s+t","w2":"round2(s*t/100)","w3":"round2(s*(1+t/10))"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The total with tax is {ans|money}.","ok":"1","why":"Tax is the rate times the price; add it to the price.","mis":"-"},{"key":"w1","text":"The total with tax is {w1|money}.","ok":"0","why":"This adds the percent as dollars.","mis":"A tax rate is a dollar amount."},{"key":"w2","text":"The total with tax is {w2|money}.","ok":"0","why":"That is only the tax, not the total.","mis":"The tax is the total."},{"key":"w3","text":"The total with tax is {w3|money}.","ok":"0","why":"This moves the decimal point one place, so the tax is ten times too big.","mis":"Percent means divide by ten."}],"lesson":"Total with tax = price + (tax rate × price)."}]},{"skill":"mathematics","engine":"numeric","framework":"numeric-decision","contexts":"any","requires":["supply","area"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}."],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","numbers-oracle-verified"],"notes":"Answers are calculated from generated numbers; distractors are named calculation misconceptions; policies (overtime, tip pool, reorder) are stated in the scenario. Verified by tests/compose-numeric-oracle.test.js."},"id":"mat-job-measures","family":"mathematics.cx-job-measures","familyName":"Measurement, rate and time math","concepts":["mathematics:job-task-math","mathematics:basic-calculations"],"configs":[{"id":"inches-feet","level":"beginner","principle":"mat.convert-inches-to-feet","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A piece you need to cut is {L|int} inches long."],"prompt":["How long is that in feet and inches?"],"vars":{"L":{"type":"int","min":30,"max":150,"step":1}},"derive":{"ft":"floor(L/12)","inch":"L%12","ans":"ft*100+inch","w1":"floor(L/10)*100+L%10","w2":"(ft+1)*100+inch","w3":"ft*100+12-inch","w1f":"floor(L/10)","w1i":"L%10","w2f":"ft+1","w3i":"12-inch"},"constraints":["L % 12 >= 2","L % 12 <= 10","L % 12 != 6","L % 10 >= 2","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The piece is {ft|int} feet {inch|int} inches.","ok":"1","why":"There are 12 inches in a foot: divide by 12 for the feet, and the remainder is inches.","mis":"-"},{"key":"w1","text":"The piece is {w1f|int} feet {w1i|int} inches.","ok":"0","why":"This uses 10 inches per foot instead of 12.","mis":"Measurements work in tens like money."},{"key":"w2","text":"The piece is {w2f|int} feet {inch|int} inches.","ok":"0","why":"This counts one foot too many.","mis":"Round the feet up."},{"key":"w3","text":"The piece is {ft|int} feet {w3i|int} inches.","ok":"0","why":"This gives the inches still needed to reach the next foot, not the leftover inches.","mis":"The remainder is what is missing."}],"lesson":"Feet = inches ÷ 12; the remainder is leftover inches."},{"id":"floor-area","level":"beginner","principle":"mat.rectangle-area","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A rectangular floor in the {area} is {w|int} feet by {l|int} feet."],"prompt":["What is the area of the floor?"],"vars":{"w":{"type":"int","min":6,"max":14,"step":1},"l":{"type":"int","min":8,"max":20,"step":1}},"derive":{"ans":"w*l","w1":"2*(w+l)","w2":"w+l","w3":"2*w*l"},"constraints":["w != l","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The floor area is {ans|int} square feet.","ok":"1","why":"Area of a rectangle is length times width.","mis":"-"},{"key":"w1","text":"The floor area is {w1|int} square feet.","ok":"0","why":"That is the perimeter, the distance around the edge.","mis":"Perimeter and area are the same thing."},{"key":"w2","text":"The floor area is {w2|int} square feet.","ok":"0","why":"This adds the sides instead of multiplying.","mis":"Area means adding the sides."},{"key":"w3","text":"The floor area is {w3|int} square feet.","ok":"0","why":"This doubles the area.","mis":"Count every side twice."}],"lesson":"Area = length × width."},{"id":"daily-average","level":"beginner","principle":"mat.mean-of-values","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["Over four days, you handled {a|int}, {b|int}, {c|int} and {d|int} orders."],"prompt":["What was the average number of orders per day?"],"vars":{"a":{"type":"int","min":10,"max":40,"step":1},"b":{"type":"int","min":10,"max":40,"step":1},"c":{"type":"int","min":10,"max":40,"step":1},"d":{"type":"int","min":10,"max":40,"step":1}},"derive":{"ans":"(a+b+c+d)/4","w1":"a+b+c+d","w2":"(a+d)/2","w3":"max(max(a,b),max(c,d))"},"constraints":["(a+b+c+d) % 4 == 0","(a+d) % 2 == 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The daily average is {ans|int} orders.","ok":"1","why":"Add the four days and divide by four.","mis":"-"},{"key":"w1","text":"The daily average is {w1|int} orders.","ok":"0","why":"That is the total for all four days, not the average.","mis":"The total is the average."},{"key":"w2","text":"The daily average is {w2|int} orders.","ok":"0","why":"This averages only the first and last days.","mis":"The first and last values are enough."},{"key":"w3","text":"The daily average is {w3|int} orders.","ok":"0","why":"That is the busiest day, not the average.","mis":"The biggest value is the typical one."}],"lesson":"Average = total ÷ number of values."},{"id":"percent-of-target","level":"beginner","principle":"mat.percent-complete","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["The goal is {T|int} units this week, and the team has finished {k|int}."],"prompt":["What percent of the goal is finished?"],"vars":{"T":{"type":"choice","values":[200,250,400,500]},"k":{"type":"int","min":40,"max":190,"step":2}},"derive":{"ans":"k*100/T","w1":"100-k*100/T","w2":"T-k","w3":"k/10"},"constraints":["(k*100) % T == 0","k < T","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The share finished is {ans|pct}.","ok":"1","why":"Percent finished = finished ÷ goal × 100.","mis":"-"},{"key":"w1","text":"The share finished is {w1|pct}.","ok":"0","why":"That is the percent still left to do.","mis":"The remaining part is the progress."},{"key":"w2","text":"The share finished is {w2|pct}.","ok":"0","why":"That is the number of units left, not a percent.","mis":"Counts and percents are interchangeable."},{"key":"w3","text":"The share finished is {w3|pct}.","ok":"0","why":"This does not compare the units to the goal.","mis":"Percent means divide by ten."}],"lesson":"Percent complete = finished ÷ goal × 100."},{"id":"budget-left","level":"beginner","principle":"mat.subtract-multiple-expenses","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["Your project budget is {B|money0}. You have spent {s1|money0} on materials and {s2|money0} on rentals."],"prompt":["How much of the budget is left?"],"vars":{"B":{"type":"int","min":300,"max":900,"step":50},"s1":{"type":"int","min":60,"max":200,"step":5},"s2":{"type":"int","min":40,"max":180,"step":5}},"derive":{"ans":"B-s1-s2","w1":"B-s1","w2":"s1+s2","w3":"B-s1+s2"},"constraints":["B-s1-s2 > 20","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The amount left is {ans|money0}.","ok":"1","why":"Subtract every expense from the budget.","mis":"-"},{"key":"w1","text":"The amount left is {w1|money0}.","ok":"0","why":"This subtracts only the materials.","mis":"One expense is enough to subtract."},{"key":"w2","text":"The amount left is {w2|money0}.","ok":"0","why":"That is how much was spent, not how much is left.","mis":"Spending and remaining are the same number."},{"key":"w3","text":"The amount left is {w3|money0}.","ok":"0","why":"This adds the rentals back instead of subtracting them.","mis":"Signs do not matter when subtracting."}],"lesson":"Remaining budget = budget − all spending."},{"id":"scale-batch","level":"beginner","principle":"mat.scale-quantity","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["One batch needs {q|int} scoops of mix, and you are making {n|int} batches."],"prompt":["How many scoops do you need?"],"vars":{"q":{"type":"int","min":3,"max":9,"step":1},"n":{"type":"int","min":3,"max":8,"step":1}},"derive":{"ans":"q*n","w1":"q+n","w2":"q*(n+1)","w3":"q*n-q"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You will need {ans|int} scoops.","ok":"1","why":"Multiply the amount for one batch by the number of batches.","mis":"-"},{"key":"w1","text":"You will need {w1|int} scoops.","ok":"0","why":"This adds instead of multiplying.","mis":"Scaling means adding."},{"key":"w2","text":"You will need {w2|int} scoops.","ok":"0","why":"This makes one batch too many.","mis":"Add a batch to be safe."},{"key":"w3","text":"You will need {w3|int} scoops.","ok":"0","why":"This makes one batch too few.","mis":"Close is good enough."}],"lesson":"To scale a recipe, multiply each amount by the number of batches."},{"id":"paid-hours","level":"beginner","principle":"mat.elapsed-time-minus-break","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["Your shift runs from {sh|int}:00 a.m. to {eh|int}:30 p.m., with an unpaid 30-minute lunch."],"prompt":["How many paid hours is the shift?"],"vars":{"sh":{"type":"int","min":6,"max":9,"step":1},"eh":{"type":"int","min":2,"max":5,"step":1}},"derive":{"ans":"eh+12+0.5-sh-0.5","w1":"eh+12+0.5-sh","w2":"eh+12-sh-0.5","w3":"eh+12-sh-1"},"constraints":["eh+12-sh <= 11","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The paid time is {ans|dec1} hours.","ok":"1","why":"Count from start to end (add 12 to the p.m. hour), then subtract the unpaid half hour.","mis":"-"},{"key":"w1","text":"The paid time is {w1|dec1} hours.","ok":"0","why":"This forgets to subtract the unpaid lunch.","mis":"Breaks are part of paid time."},{"key":"w2","text":"The paid time is {w2|dec1} hours.","ok":"0","why":"This drops the extra half hour at the end of the shift before subtracting lunch.","mis":"Shifts end on the hour."},{"key":"w3","text":"The paid time is {w3|dec1} hours.","ok":"0","why":"This drops the half hour at the end and subtracts a whole hour for lunch.","mis":"Half hours can be ignored."}],"lesson":"Paid time = end − start − unpaid breaks; add 12 to p.m. hours."},{"id":"split-bill","level":"beginner","principle":"mat.equal-share","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A team lunch costs {T|money0}, and {n|int} people are splitting it equally."],"prompt":["How much is each person's share?"],"vars":{"T":{"type":"int","min":48,"max":144,"step":6},"n":{"type":"choice","values":[3,4,6]}},"derive":{"ans":"T/n","w1":"round2(T/(n+1))","w2":"T*n","w3":"T-n"},"constraints":["T % n == 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Each person pays {ans|money}.","ok":"1","why":"Divide the total by the number of people.","mis":"-"},{"key":"w1","text":"Each person pays {w1|money}.","ok":"0","why":"This divides by one person too many.","mis":"Count the person paying twice."},{"key":"w2","text":"Each person pays {w2|money}.","ok":"0","why":"This multiplies instead of dividing.","mis":"Sharing means multiplying."},{"key":"w3","text":"Each person pays {w3|money}.","ok":"0","why":"This subtracts the number of people.","mis":"Subtracting people splits a bill."}],"lesson":"Equal share = total ÷ number of people."},{"id":"units-per-hour","level":"beginner","principle":"mat.rate-per-hour","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["You packed {m|int} {supply.plural} in {h|int} hours."],"prompt":["How many did you pack per hour?"],"vars":{"m":{"type":"int","min":40,"max":180,"step":4},"h":{"type":"choice","values":[2,4]}},"derive":{"ans":"m/h","w1":"m*h","w2":"m-h","w3":"m/h+h"},"constraints":["m % h == 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The packing rate is {ans|int} per hour.","ok":"1","why":"Rate per hour = amount ÷ hours.","mis":"-"},{"key":"w1","text":"The packing rate is {w1|int} per hour.","ok":"0","why":"This multiplies instead of dividing.","mis":"Rates come from multiplying."},{"key":"w2","text":"The packing rate is {w2|int} per hour.","ok":"0","why":"This subtracts the hours.","mis":"Subtract time from amount."},{"key":"w3","text":"The packing rate is {w3|int} per hour.","ok":"0","why":"This adds the hours after dividing.","mis":"Add the time back in."}],"lesson":"Rate = amount ÷ time."},{"id":"gross-pay","level":"beginner","principle":"mat.hours-times-rate","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["You worked {h|int} hours this week at {r|money} an hour."],"prompt":["What is your pay before deductions?"],"vars":{"h":{"type":"int","min":12,"max":32,"step":1},"r":{"type":"choice","values":[13.5,14.25,15,16.75,18]}},"derive":{"ans":"round2(h*r)","w1":"round2(h+r)","w2":"round2(40*r)","w3":"round2(h*r/2)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Your pay before deductions is {ans|money}.","ok":"1","why":"Pay before deductions is hours times the hourly rate.","mis":"-"},{"key":"w1","text":"Your pay before deductions is {w1|money}.","ok":"0","why":"This adds hours and rate instead of multiplying.","mis":"Pay is hours plus rate."},{"key":"w2","text":"Your pay before deductions is {w2|money}.","ok":"0","why":"This assumes a full 40-hour week.","mis":"Everyone works 40 hours."},{"key":"w3","text":"Your pay before deductions is {w3|money}.","ok":"0","why":"This halves the pay for no reason.","mis":"Pay is split into halves."}],"lesson":"Gross pay = hours × hourly rate."}]},{"skill":"mathematics","engine":"numeric","framework":"numeric-decision","contexts":"any","requires":["supply","area"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}."],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","numbers-oracle-verified"],"notes":"Answers are calculated from generated numbers; distractors are named calculation misconceptions; policies (overtime, tip pool, reorder) are stated in the scenario. Verified by tests/compose-numeric-oracle.test.js."},"id":"mat-applied","family":"mathematics.cx-applied-job-math","familyName":"Multi-step job math","concepts":["mathematics:job-task-math","mathematics:basic-calculations"],"configs":[{"id":"compare-unit-price","level":"intermediate","principle":"mat.compare-unit-not-pack-price","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["Supplier A sells {supply.plural} in packs of {na|int} for {pa|money0}. Supplier B sells packs of {nb|int} for {pb|money0}."],"prompt":["Which supplier has the lower price per item?"],"vars":{"na":{"type":"choice","values":[6,8,10]},"pa":{"type":"int","min":10,"max":40,"step":1},"nb":{"type":"choice","values":[12,20,24]},"pb":{"type":"int","min":18,"max":70,"step":1}},"derive":{"ua":"round2(pa/na)","ub":"round2(pb/nb)"},"constraints":["pa < pb","ua > ub + 0.05"],"options":[{"key":"a","text":"Supplier A, since its pack costs less","ok":"ua < ub","why":"A's pack is cheaper, but it holds fewer items, so each item costs more.","mis":"The cheaper pack is the better deal."},{"key":"b","text":"Supplier B, at {ub|money} per item","ok":"ub < ua","why":"Dividing each pack price by its size shows B costs less per item.","mis":"-"},{"key":"c","text":"Supplier A, at {ua|money} per item","ok":"0","why":"{ua|money} per item is higher than B's {ub|money}.","mis":"Any calculated price must be the best one."},{"key":"d","text":"Either one, since they cost about the same per item","ok":"ua == ub","why":"The prices per item are different; B is lower.","mis":"Similar pack prices mean similar value."}],"lesson":"Compare price per item, not price per pack."},{"id":"overtime-pay","level":"intermediate","principle":"mat.overtime-over-40","rule":"apply-stated-policy","kind":"numeric","mode":["decision"],"facts":["You worked {h|int} hours at {r|money0} an hour. The workplace pays 1.5 times the hourly rate for hours over 40."],"prompt":["What is your pay before deductions?"],"vars":{"h":{"type":"int","min":42,"max":50,"step":1},"r":{"type":"int","min":14,"max":22,"step":1}},"derive":{"ans":"round2(40*r + (h-40)*1.5*r)","w1":"h*r","w2":"round2(h*1.5*r)","w3":"round2(40*r + (h-40)*0.5*r)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Your pay before deductions is {ans|money}.","ok":"1","why":"The first 40 hours are at the regular rate; only the extra hours are at 1.5 times.","mis":"-"},{"key":"w1","text":"Your pay before deductions is {w1|money}.","ok":"0","why":"This pays every hour at the regular rate and forgets overtime.","mis":"Overtime does not change pay."},{"key":"w2","text":"Your pay before deductions is {w2|money}.","ok":"0","why":"This pays every hour at the overtime rate.","mis":"Overtime applies to the whole week."},{"key":"w3","text":"Your pay before deductions is {w3|money}.","ok":"0","why":"This pays only the extra half-rate for overtime hours, not 1.5 times.","mis":"Overtime means half pay extra only."}],"lesson":"Overtime pay = 40 × rate + extra hours × 1.5 × rate."},{"id":"net-pay","level":"intermediate","principle":"mat.gross-minus-percent-and-flat","rule":"apply-stated-policy","kind":"numeric","mode":["decision"],"facts":["Your weekly pay before deductions is {g|money0}. {t|int} percent is withheld for taxes, and a flat {f|money0} is deducted for parking."],"prompt":["What is your take-home pay?"],"vars":{"g":{"type":"int","min":400,"max":800,"step":10},"t":{"type":"choice","values":[10,12,15]},"f":{"type":"choice","values":[10,15,20]}},"derive":{"ans":"round2(g - g*t/100 - f)","w1":"g-t-f","w2":"round2(g - g*t/100)","w3":"round2(g - g*t/100 + f)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Your take-home pay is {ans|money}.","ok":"1","why":"Subtract the tax (a percent of the pay) and then the flat parking deduction.","mis":"-"},{"key":"w1","text":"Your take-home pay is {w1|money}.","ok":"0","why":"This subtracts the tax percent as dollars.","mis":"Percent deductions are dollar amounts."},{"key":"w2","text":"Your take-home pay is {w2|money}.","ok":"0","why":"This forgets the parking deduction.","mis":"Small deductions can be skipped."},{"key":"w3","text":"Your take-home pay is {w3|money}.","ok":"0","why":"This adds the parking deduction instead of subtracting it.","mis":"Deductions add to pay."}],"lesson":"Take-home pay = gross − percent deductions − flat deductions."},{"id":"boxes-with-waste","level":"intermediate","principle":"mat.add-waste-then-round-up","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["The job needs {m|int} square feet of flooring, plus 10 percent extra for waste. Each box covers {k|int} square feet."],"prompt":["How many boxes should you order?"],"vars":{"m":{"type":"int","min":120,"max":400,"step":10},"k":{"type":"choice","values":[15,20,24]}},"derive":{"ans":"ceil(m*1.1/k)","w1":"ceil(m/k)","w2":"floor(m*1.1/k)","w3":"ceil(m*1.1/k)+2"},"constraints":["(m*11) % (k*10) != 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You should order {ans|int} boxes.","ok":"1","why":"Add 10 percent for waste first, then divide by the coverage and round up.","mis":"-"},{"key":"w1","text":"You should order {w1|int} boxes.","ok":"0","why":"This forgets the 10 percent waste allowance.","mis":"Waste can be ignored in an estimate."},{"key":"w2","text":"You should order {w2|int} boxes.","ok":"0","why":"This rounds down, so the job runs short.","mis":"Round to the nearest box."},{"key":"w3","text":"You should order {w3|int} boxes.","ok":"0","why":"This orders more than the waste allowance requires.","mis":"Extra boxes are always better."}],"lesson":"Add the waste allowance, divide by coverage, then round up to whole boxes."},{"id":"discount-then-tax","level":"intermediate","principle":"mat.discount-before-tax","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["An item costs {pr|money0}. It is {d|int} percent off, and {t|int} percent tax is added to the sale price."],"prompt":["What is the final price?"],"vars":{"pr":{"type":"int","min":40,"max":200,"step":5},"d":{"type":"choice","values":[10,20,25]},"t":{"type":"choice","values":[5,6,8]}},"derive":{"ans":"round2(pr*(1-d/100)*(1+t/100))","w1":"round2(pr*(1-d/100))","w2":"round2(pr*(1+t/100))","w3":"round2(pr*(1-d/100+t/100))"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The final price is {ans|money}.","ok":"1","why":"Take the discount off first, then add tax on the sale price.","mis":"-"},{"key":"w1","text":"The final price is {w1|money}.","ok":"0","why":"This forgets the tax.","mis":"Sale prices include tax."},{"key":"w2","text":"The final price is {w2|money}.","ok":"0","why":"This forgets the discount.","mis":"Discounts only apply at the register."},{"key":"w3","text":"The final price is {w3|money}.","ok":"0","why":"This combines the percents into one step, which is not the same as taxing the sale price.","mis":"Percents can be added and subtracted directly."}],"lesson":"Apply percent changes in order: discount first, then tax on the new price."},{"id":"percent-change","level":"intermediate","principle":"mat.percent-change-from-original","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["Last month the team handled {L|int} orders. This month it handled {N|int}."],"prompt":["By what percent did orders increase?"],"vars":{"L":{"type":"choice","values":[40,50,80,100,200]},"N":{"type":"int","min":44,"max":260,"step":2}},"derive":{"ans":"(N-L)*100/L","w1":"round((N-L)*100/N, 1)","w2":"N-L","w3":"N*100/L"},"constraints":["N > L","((N-L)*100) % L == 0","(N-L)*100/L <= 60","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Orders went up by {ans|pct}.","ok":"1","why":"Percent change = change ÷ the original amount × 100.","mis":"-"},{"key":"w1","text":"Orders went up by {w1|pct}.","ok":"0","why":"This divides by the new amount instead of the original.","mis":"Either month works as the base."},{"key":"w2","text":"Orders went up by {w2|pct}.","ok":"0","why":"That is the number of extra orders, not a percent.","mis":"The difference is the percent."},{"key":"w3","text":"Orders went up by {w3|pct}.","ok":"0","why":"That is this month as a percent of last month, not the increase.","mis":"New ÷ old is the percent increase."}],"lesson":"Percent change = (new − original) ÷ original × 100."},{"id":"hours-to-finish","level":"intermediate","principle":"mat.remaining-work-over-rate","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["You have {R|int} {supply.plural} left to process, and you process {k|int} per hour."],"prompt":["How many more hours will it take?"],"vars":{"R":{"type":"int","min":60,"max":240,"step":6},"k":{"type":"choice","values":[12,15,20]}},"derive":{"ans":"R/k","w1":"R*k","w2":"R/k+1","w3":"R-k"},"constraints":["R % k == 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"It will take {ans|int} hours.","ok":"1","why":"Time = work left ÷ rate.","mis":"-"},{"key":"w1","text":"It will take {w1|int} hours.","ok":"0","why":"This multiplies instead of dividing.","mis":"More work means multiply."},{"key":"w2","text":"It will take {w2|int} hours.","ok":"0","why":"This adds an extra hour that the numbers do not call for.","mis":"Always add an hour."},{"key":"w3","text":"It will take {w3|int} hours.","ok":"0","why":"This subtracts the rate from the amount.","mis":"Subtracting the rate gives time."}],"lesson":"Time needed = amount left ÷ rate."},{"id":"dilution","level":"intermediate","principle":"mat.ratio-parts","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["The label says to mix 1 part concentrate with {w|int} parts water. You need {T|int} cups of mixed solution."],"prompt":["How many cups of concentrate do you need?"],"vars":{"w":{"type":"choice","values":[3,4,5,7]},"T":{"type":"int","min":16,"max":64,"step":4}},"derive":{"ans":"T/(w+1)","w1":"round(T/w,1)","w2":"T*w/(w+1)","w3":"T/(w+2)","w1p":"w+1"},"constraints":["T % (w+1) == 0","T % (w+2) == 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The concentrate needed is {ans|int} cups.","ok":"1","why":"The mix has 1 + {w|int} parts in all, so concentrate is the total ÷ {w1p|int}.","mis":"-"},{"key":"w1","text":"The concentrate needed is {w1|dec1} cups.","ok":"0","why":"This divides by the water parts only and forgets the concentrate part.","mis":"The ratio's second number is the whole."},{"key":"w2","text":"The concentrate needed is {w2|int} cups.","ok":"0","why":"That is the amount of water, not concentrate.","mis":"The bigger number is the concentrate."},{"key":"w3","text":"The concentrate needed is {w3|int} cups.","ok":"0","why":"This counts one part too many.","mis":"Add a part to be safe."}],"lesson":"In a 1-to-w mix, concentrate = total ÷ (1 + w)."},{"id":"area-minus-cutout","level":"intermediate","principle":"mat.composite-area","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A floor is {w|int} feet by {l|int} feet. A built-in counter covers a {a|int}-by-{b|int}-foot section that will not be tiled."],"prompt":["How many square feet need tile?"],"vars":{"w":{"type":"int","min":10,"max":16,"step":1},"l":{"type":"int","min":12,"max":20,"step":1},"a":{"type":"choice","values":[2,3]},"b":{"type":"choice","values":[4,5,6]}},"derive":{"ans":"w*l-a*b","w1":"w*l","w2":"w*l+a*b","w3":"2*(w+l)-a*b"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The area to tile is {ans|int} square feet.","ok":"1","why":"Find the whole floor's area, then subtract the area under the counter.","mis":"-"},{"key":"w1","text":"The area to tile is {w1|int} square feet.","ok":"0","why":"This forgets to subtract the counter.","mis":"Cutouts are too small to matter."},{"key":"w2","text":"The area to tile is {w2|int} square feet.","ok":"0","why":"This adds the counter area instead of subtracting it.","mis":"Every area gets added."},{"key":"w3","text":"The area to tile is {w3|int} square feet.","ok":"0","why":"This starts from the perimeter instead of the area.","mis":"Perimeter is the starting area."}],"lesson":"Composite area = whole area − cut-out area."},{"id":"minutes-cost","level":"intermediate","principle":"mat.minutes-to-hourly-cost","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A repair took {m|int} minutes, and labor is billed at {r|money0} per hour."],"prompt":["What is the labor charge?"],"vars":{"m":{"type":"choice","values":[15,30,45,90,105]},"r":{"type":"int","min":40,"max":96,"step":4}},"derive":{"ans":"round2(m/60*r)","w1":"m*r","w2":"round2(m/100*r)","w3":"r"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The labor charge is {ans|money}.","ok":"1","why":"Convert minutes to hours by dividing by 60, then multiply by the hourly rate.","mis":"-"},{"key":"w1","text":"The labor charge is {w1|money}.","ok":"0","why":"This bills each minute at the hourly rate.","mis":"Minutes and hours can be multiplied the same way."},{"key":"w2","text":"The labor charge is {w2|money}.","ok":"0","why":"This treats an hour as 100 minutes.","mis":"Time works in tens like money."},{"key":"w3","text":"The labor charge is {w3|money}.","ok":"0","why":"This bills a full hour no matter the time.","mis":"Any part of an hour is billed as one hour."}],"lesson":"Cost = minutes ÷ 60 × hourly rate."},{"id":"budget-percent-left","level":"intermediate","principle":"mat.percent-remaining","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["Your budget is {B|money0}, and you have spent {S|money0} so far."],"prompt":["What percent of the budget is left?"],"vars":{"B":{"type":"choice","values":[400,500,800,1000]},"S":{"type":"int","min":60,"max":380,"step":20}},"derive":{"ans":"100-S*100/B","w1":"S*100/B","w2":"B-S","w3":"round(S/B,2)"},"constraints":["(S*100) % B == 0","S < B","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The share left is {ans|pct}.","ok":"1","why":"Percent left = amount left ÷ budget × 100.","mis":"-"},{"key":"w1","text":"The share left is {w1|pct}.","ok":"0","why":"That is the percent spent, not the percent left.","mis":"Spent and left are the same percent."},{"key":"w2","text":"The share left is {w2|pct}.","ok":"0","why":"That is the dollar amount left, not a percent.","mis":"Dollars and percents are the same."},{"key":"w3","text":"The share left is {w3|pct}.","ok":"0","why":"This forgets to multiply by 100.","mis":"A decimal is already a percent."}],"lesson":"Percent remaining = (budget − spent) ÷ budget × 100."},{"id":"bulk-threshold-cheaper","level":"intermediate","principle":"mat.bulk-price-lowers-total","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["You need {q|int} {supply.plural}. They cost {e|money} each, or {e2|money} each when you buy 50 or more."],"prompt":["What is the cheapest way to get at least {q|int}?"],"vars":{"q":{"type":"int","min":40,"max":49,"step":1},"e":{"type":"choice","values":[2.5,3,3.6,4]},"e2":{"type":"choice","values":[1.9,2.2,2.4,2.8]}},"derive":{"regular":"round2(q*e)","bulk":"round2(50*e2)"},"constraints":["e2 < e","bulk < regular"],"options":[{"key":"a","text":"Buy exactly {q|int} at {e|money} each, for {regular|money}","ok":"regular < bulk","why":"{regular|money} is more than {bulk|money} for 50 at the bulk price.","mis":"Buying exactly what you need is always cheapest."},{"key":"b","text":"Buy 50 at the bulk price, for {bulk|money}","ok":"bulk < regular","why":"Fifty at the bulk price costs less than {q|int} at the regular price, and you get extras.","mis":"-"},{"key":"c","text":"Buy 25 at a time twice, for {regular|money}","ok":"0","why":"Two orders of 25 do not reach the bulk price and cost the regular total.","mis":"Splitting orders saves money."},{"key":"d","text":"Wait until you need 50 before ordering","ok":"0","why":"You need the items now; waiting does not get the job done.","mis":"Delaying a purchase is the same as saving."}],"lesson":"Compare total costs, including bulk prices, before deciding how many to buy."},{"id":"bulk-threshold-not-worth","level":"intermediate","principle":"mat.bulk-price-not-worth-it","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["You need {q|int} {supply.plural}. They cost {e|money} each, or {e2|money} each when you buy 50 or more."],"prompt":["What is the cheapest way to get at least {q|int}?"],"vars":{"q":{"type":"int","min":30,"max":38,"step":1},"e":{"type":"choice","values":[2.5,3,3.6,4]},"e2":{"type":"choice","values":[2.2,2.4,2.8,3.2]}},"derive":{"regular":"round2(q*e)","bulk":"round2(50*e2)"},"constraints":["e2 < e","regular < bulk"],"options":[{"key":"a","text":"Buy exactly {q|int} at {e|money} each, for {regular|money}","ok":"regular < bulk","why":"{regular|money} is less than {bulk|money}, so the bulk price is not worth it here.","mis":"-"},{"key":"b","text":"Buy 50 at the bulk price, for {bulk|money}","ok":"bulk < regular","why":"The lower price per item does not make up for buying many extras: {bulk|money} is more than {regular|money}.","mis":"A lower price per item always means a lower total."},{"key":"c","text":"Buy 25 at a time twice, for {regular|money}","ok":"0","why":"That buys 50 at the regular price, which costs more than buying exactly what you need.","mis":"Splitting orders saves money."},{"key":"d","text":"Wait until you need 50 before ordering","ok":"0","why":"You need the items now; waiting does not get the job done.","mis":"Delaying a purchase is the same as saving."}],"lesson":"A bulk price only helps if the total is lower for what you actually need."},{"id":"tip-share-by-hours","level":"intermediate","principle":"mat.proportional-share","rule":"apply-stated-policy","kind":"numeric","mode":["decision"],"facts":["The team's tip pool is {T|money0}, shared by hours worked. You worked {h1|int} hours, and two coworkers worked {h2|int} and {h3|int}."],"prompt":["What is your share?"],"vars":{"T":{"type":"int","min":120,"max":360,"step":12},"h1":{"type":"int","min":4,"max":8,"step":1},"h2":{"type":"int","min":4,"max":8,"step":1},"h3":{"type":"int","min":4,"max":8,"step":1}},"derive":{"ans":"round2(T*h1/(h1+h2+h3))","w1":"round2(T/3)","w2":"round2(T*h1/(h2+h3))","w3":"round2(T*h1/8)"},"constraints":["h1 != h2 || h1 != h3","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Your share is {ans|money}.","ok":"1","why":"Your share = your hours ÷ everyone's hours × the pool.","mis":"-"},{"key":"w1","text":"Your share is {w1|money}.","ok":"0","why":"This splits evenly, but the pool is shared by hours.","mis":"Every share is equal."},{"key":"w2","text":"Your share is {w2|money}.","ok":"0","why":"This leaves your own hours out of the total.","mis":"Compare to the others' hours only."},{"key":"w3","text":"Your share is {w3|money}.","ok":"0","why":"This divides by a standard 8-hour day, not the hours everyone actually worked.","mis":"Every shift is eight hours."}],"lesson":"A proportional share = your part ÷ the whole × the total."},{"id":"staff-needed","level":"intermediate","principle":"mat.round-up-staffing","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["About {cph|int} {client.plural} are expected each hour, and one worker can serve {k|int} per hour."],"prompt":["How many workers are needed?"],"vars":{"cph":{"type":"int","min":25,"max":90,"step":1},"k":{"type":"choice","values":[8,10,12]}},"derive":{"ans":"ceil(cph/k)","w1":"floor(cph/k)","w2":"round(cph/k, 1)","w3":"cph*k"},"constraints":["cph % k != 0","round(cph/k,1) != floor(cph/k)","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You will need {ans|int} workers.","ok":"1","why":"Divide the demand by what one worker can handle, and round up.","mis":"-"},{"key":"w1","text":"You will need {w1|int} workers.","ok":"0","why":"Rounding down leaves some {client.plural} unserved.","mis":"Round down to save money."},{"key":"w2","text":"You will need {w2|dec1} workers.","ok":"0","why":"You cannot schedule part of a worker.","mis":"The exact division is the answer."},{"key":"w3","text":"You will need {w3|int} workers.","ok":"0","why":"This multiplies instead of dividing.","mis":"More demand means multiply."}],"lesson":"Staff needed = demand ÷ capacity per person, rounded up."}]},{"skill":"mathematics","engine":"numeric","framework":"numeric-decision","contexts":"any","requires":["supply","area"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}."],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","numbers-oracle-verified"],"notes":"Answers are calculated from generated numbers; distractors are named calculation misconceptions; policies (overtime, tip pool, reorder) are stated in the scenario. Verified by tests/compose-numeric-oracle.test.js."},"id":"mat-decisions","family":"mathematics.cx-numeric-decisions","familyName":"Numbers that decide a choice","concepts":["mathematics:job-task-math","mathematics:personal-finance"],"configs":[{"id":"supplier-over-budget","level":"advanced","principle":"mat.budget-rules-out-cheaper-unit","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["You need {q|int} {supply.plural} and have a budget of {bud|money0}.","Supplier A sells packs of {na|int} for {pa|money0}. Supplier B sells packs of {nb|int} for {pb|money0}."],"prompt":["Which choice meets the need within the budget?"],"vars":{"q":{"type":"int","min":30,"max":70,"step":1},"na":{"type":"choice","values":[25,40]},"pa":{"type":"int","min":30,"max":60,"step":1},"nb":{"type":"choice","values":[10,12]},"pb":{"type":"int","min":14,"max":30,"step":1},"bud":{"type":"int","min":100,"max":260,"step":10}},"derive":{"ca":"ceil(q/na)*pa","cb":"ceil(q/nb)*pb","ua":"round2(pa/na)","ub":"round2(pb/nb)"},"constraints":["ua < ub","ca > bud","cb <= bud","q % na != 0"],"options":[{"key":"a","text":"Order from Supplier A, since it is cheaper per item ({ca|money0} total)","ok":"ca <= bud","why":"A is cheaper per item, but buying enough whole packs costs {ca|money0}, which is over the budget.","mis":"The lowest price per item always wins."},{"key":"b","text":"Order from Supplier B ({cb|money0} total)","ok":"cb <= bud","why":"B's whole packs cover the need for {cb|money0}, within the {bud|money0} budget.","mis":"-"},{"key":"c","text":"Ask {lead|the} to raise the budget so you can use Supplier A","ok":"0","why":"That could work, but B already meets the need within the current budget, so it is not necessary.","mis":"A better deal is always worth asking for more money.","acceptable":true},{"key":"d","text":"Order fewer items from A so it fits the budget","ok":"0","why":"Ordering fewer than {q|int} leaves the job short.","mis":"Cutting quantity is a fine way to save."}],"lesson":"Check total cost in whole packs against the budget, not just price per item."},{"id":"supplier-within-budget","level":"advanced","principle":"mat.cheaper-total-within-budget","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["You need {q|int} {supply.plural} and have a budget of {bud|money0}.","Supplier A sells packs of {na|int} for {pa|money0}. Supplier B sells packs of {nb|int} for {pb|money0}."],"prompt":["Which choice meets the need at the lowest cost?"],"vars":{"q":{"type":"int","min":30,"max":70,"step":1},"na":{"type":"choice","values":[25,40]},"pa":{"type":"int","min":30,"max":60,"step":1},"nb":{"type":"choice","values":[10,12]},"pb":{"type":"int","min":14,"max":30,"step":1},"bud":{"type":"int","min":160,"max":300,"step":10}},"derive":{"ca":"ceil(q/na)*pa","cb":"ceil(q/nb)*pb","ua":"round2(pa/na)","ub":"round2(pb/nb)"},"constraints":["ua < ub","ca <= bud","ca < cb","cb <= bud"],"options":[{"key":"a","text":"Order from Supplier A ({ca|money0} total)","ok":"ca < cb && ca <= bud","why":"A's packs cover the need for {ca|money0}, the lower total, within the budget.","mis":"-"},{"key":"b","text":"Order from Supplier B ({cb|money0} total)","ok":"cb < ca","why":"B also fits the budget, but {cb|money0} is more than A's {ca|money0}.","mis":"Smaller packs waste less, so they cost less."},{"key":"c","text":"Ask {lead|the} for a bigger budget before ordering","ok":"0","why":"Asking is harmless, but both options already fit; A is simply the better total.","mis":"Always ask for more budget.","acceptable":true},{"key":"d","text":"Split the order between both suppliers","ok":"0","why":"Splitting buys extra whole packs from both and costs more than A alone.","mis":"Splitting an order lowers the cost."}],"lesson":"When every option fits the budget, compare the totals."},{"id":"overtime-vs-temp","level":"advanced","principle":"mat.compare-labor-options","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["You need {H|int} extra hours of work this week. Staff overtime costs 1.5 times the {r|money0} hourly rate.","A temp agency charges {ta|money0} an hour plus a one-time {F|money0} fee."],"prompt":["Which option costs less?"],"vars":{"H":{"type":"int","min":10,"max":30,"step":2},"r":{"type":"int","min":16,"max":24,"step":1},"ta":{"type":"int","min":20,"max":30,"step":1},"F":{"type":"choice","values":[50,75,100]}},"derive":{"ot":"H*1.5*r","tmp":"H*ta+F","reg":"H*r"},"constraints":["ot != tmp","abs(ot - tmp) >= 15"],"options":[{"key":"a","text":"Pay staff overtime, at {ot|money0}","ok":"ot < tmp","why":"Overtime: {H|int} × 1.5 × {r|money0} = {ot|money0}; the temp option costs {tmp|money0}.","mis":"Overtime is always the expensive choice."},{"key":"b","text":"Use the temp agency, at {tmp|money0}","ok":"tmp < ot","why":"Temp: {H|int} × {ta|money0} + {F|money0} = {tmp|money0}; overtime costs {ot|money0}.","mis":"Agencies always cost more."},{"key":"c","text":"Staff hours at the regular rate, at {reg|money0}","ok":"0","why":"Extra hours are paid at the overtime rate, so the regular-rate figure is not a real option.","mis":"Extra hours are paid at the normal rate.","acceptable":true},{"key":"d","text":"They cost the same, so either is fine","ok":"ot == tmp","why":"The totals are different; one option is clearly cheaper.","mis":"Similar rates mean similar totals."}],"lesson":"Compare full costs, including multipliers and one-time fees."},{"id":"extra-staff-for-deadline","level":"advanced","principle":"mat.extra-people-to-meet-deadline","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["{R|int} items are left, and they must be done in {t|int} hours. Each person finishes {k|int} items an hour, and {p|int} people are working."],"prompt":["How many more people are needed to finish on time?"],"vars":{"R":{"type":"int","min":180,"max":600,"step":10},"t":{"type":"choice","values":[3,4,5]},"k":{"type":"choice","values":[8,10,12]},"p":{"type":"choice","values":[2,3]}},"derive":{"need":"ceil(R/(k*t))","ans":"ceil(R/(k*t))-p","w1":"ceil(R/(k*t))","w2":"floor(R/(k*t))-p","w3":"ceil(R/k)-p"},"constraints":["ceil(R/(k*t)) - p >= 2","R % (k*t) != 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You will need {ans|int} more people.","ok":"1","why":"Total people needed = items ÷ (rate × hours), rounded up; subtract the people already working.","mis":"-"},{"key":"w1","text":"You will need {w1|int} more people.","ok":"0","why":"That is the total needed; some of them are already working.","mis":"The total is the number to add."},{"key":"w2","text":"You will need {w2|int} more people.","ok":"0","why":"Rounding down leaves the job unfinished at the deadline.","mis":"Round down to save money."},{"key":"w3","text":"You will need {w3|int} more people.","ok":"0","why":"This ignores the hours available.","mis":"Time does not affect staffing."}],"lesson":"Extra people = ceil(work ÷ (rate × time)) − people already working."},{"id":"tile-cost-with-waste","level":"advanced","principle":"mat.waste-boxes-cost","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A {a|int}-square-foot floor needs tile, plus 10 percent extra for waste. A box covers {c|int} square feet and costs {pr|money0}."],"prompt":["What will the boxes cost?"],"vars":{"a":{"type":"int","min":150,"max":420,"step":10},"c":{"type":"choice","values":[12,15,20]},"pr":{"type":"int","min":28,"max":55,"step":1}},"derive":{"boxes":"ceil(a*1.1/c)","ans":"ceil(a*1.1/c)*pr","w1":"ceil(a/c)*pr","w2":"floor(a*1.1/c)*pr","w3":"round2(a*1.1/c*pr)"},"constraints":["(a*11) % (c*10) != 0","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The boxes will cost {ans|money0}.","ok":"1","why":"Add 10 percent, divide by coverage, round up to whole boxes, then multiply by the price.","mis":"-"},{"key":"w1","text":"The boxes will cost {w1|money0}.","ok":"0","why":"This forgets the 10 percent waste.","mis":"Waste does not need to be bought."},{"key":"w2","text":"The boxes will cost {w2|money0}.","ok":"0","why":"This rounds the boxes down, so you run short.","mis":"Round to the nearest box."},{"key":"w3","text":"The boxes will cost {w3|money}.","ok":"0","why":"This prices part of a box; you can only buy whole boxes.","mis":"Stores sell partial boxes."}],"lesson":"Cost = whole boxes (after waste, rounded up) × price per box."},{"id":"coupon-percent-better","level":"advanced","principle":"mat.percent-coupon-wins-on-large-order","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["An order totals {P|money0}. You can use one coupon: {d|int} percent off, or {F|money0} off."],"prompt":["Which coupon saves more on this order?"],"vars":{"P":{"type":"int","min":120,"max":400,"step":10},"d":{"type":"choice","values":[10,15,20]},"F":{"type":"choice","values":[15,20,25,30]}},"derive":{"pctsave":"round2(P*d/100)"},"constraints":["pctsave > F + 2"],"options":[{"key":"a","text":"The {d|int} percent coupon, which saves {pctsave|money}","ok":"pctsave > F","why":"On a {P|money0} order, {d|int} percent is {pctsave|money}, more than {F|money0}.","mis":"-"},{"key":"b","text":"The {F|money0} coupon, which takes that amount off","ok":"F > pctsave","why":"{F|money0} is less than the {pctsave|money} the percent coupon saves on this order.","mis":"A fixed dollar amount always saves more."},{"key":"c","text":"Use both coupons together on the order","ok":"0","why":"Only one coupon can be used.","mis":"Coupons can always be combined."},{"key":"d","text":"Either one, since they save about the same","ok":"0","why":"The savings differ; calculate both to see which is larger.","mis":"Close-sounding offers are equal.","acceptable":true}],"lesson":"Turn percent savings into dollars before comparing."},{"id":"coupon-fixed-better","level":"advanced","principle":"mat.fixed-coupon-wins-on-small-order","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["An order totals {P|money0}. You can use one coupon: {d|int} percent off, or {F|money0} off."],"prompt":["Which coupon saves more on this order?"],"vars":{"P":{"type":"int","min":60,"max":140,"step":5},"d":{"type":"choice","values":[10,15,20]},"F":{"type":"choice","values":[20,25,30]}},"derive":{"pctsave":"round2(P*d/100)"},"constraints":["F > pctsave + 2"],"options":[{"key":"a","text":"The {d|int} percent coupon on this order","ok":"pctsave > F","why":"On this order, {d|int} percent is only {pctsave|money}, less than {F|money0}.","mis":"Percent coupons always save more."},{"key":"b","text":"The {F|money0} coupon, which beats the {pctsave|money} percent savings","ok":"F > pctsave","why":"{F|money0} off is more than {d|int} percent of {P|money0}, which is {pctsave|money}.","mis":"-"},{"key":"c","text":"Use both coupons together on the order","ok":"0","why":"Only one coupon can be used.","mis":"Coupons can always be combined."},{"key":"d","text":"Either one, since they save about the same","ok":"0","why":"The savings differ; calculate both to see which is larger.","mis":"Close-sounding offers are equal.","acceptable":true}],"lesson":"Which coupon wins depends on the order size; compute the dollar savings."},{"id":"job-offer-annual","level":"advanced","principle":"mat.compare-hourly-and-salary","rule":"personal-finance","kind":"decision","mode":["decision"],"facts":["Job A pays {r|money} an hour for 40 hours a week. Job B pays a salary of {S|money0} a year. Assume 52 working weeks."],"prompt":["Which job pays more per year?"],"vars":{"r":{"type":"choice","values":[16.5,17.25,18,19.5,21]},"S":{"type":"int","min":32000,"max":44000,"step":500}},"derive":{"ya":"r*40*52"},"constraints":["abs(ya - S) >= 600"],"options":[{"key":"a","text":"Job A, at {ya|money0} a year","ok":"ya > S","why":"{r|money} × 40 × 52 = {ya|money0}.","mis":"Hourly jobs always pay less."},{"key":"b","text":"Job B, at {S|money0} a year","ok":"S > ya","why":"Job A works out to {ya|money0} a year, so compare that with {S|money0}.","mis":"Salaries always pay more."},{"key":"c","text":"Job A, because {r|money} an hour sounds higher","ok":"0","why":"An hourly rate has to be converted to a yearly amount before comparing.","mis":"Bigger-sounding numbers are better."},{"key":"d","text":"They pay the same, so pick either","ok":"0","why":"The yearly totals are different.","mis":"Pay offers are always about equal.","acceptable":true}],"lesson":"Convert pay to the same time period before comparing."},{"id":"payment-plan-extra","level":"advanced","principle":"mat.true-cost-of-payment-plan","rule":"personal-finance","kind":"numeric","mode":["decision"],"facts":["A tool costs {P|money0} if paid now. A payment plan charges {m|int} monthly payments of {q|money0}."],"prompt":["How much more does the payment plan cost?"],"vars":{"P":{"type":"int","min":300,"max":900,"step":25},"m":{"type":"choice","values":[6,10,12]},"q":{"type":"int","min":30,"max":100,"step":5}},"derive":{"ans":"m*q-P","w1":"m*q","w2":"P-q","w3":"q"},"constraints":["m*q - P >= 20","m*q - P <= P/2","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The plan costs this much more: {ans|money0}.","ok":"1","why":"Total of the payments minus the cash price is the extra cost.","mis":"-"},{"key":"w1","text":"The plan costs this much more: {w1|money0}.","ok":"0","why":"That is the total of all payments, not the extra cost.","mis":"The total paid is the extra cost."},{"key":"w2","text":"The plan costs this much more: {w2|money0}.","ok":"0","why":"This subtracts one payment from the price.","mis":"One payment shows the difference."},{"key":"w3","text":"The plan costs this much more: {w3|money0}.","ok":"0","why":"That is one monthly payment.","mis":"The monthly payment is the cost."}],"lesson":"Extra cost of a plan = (number of payments × payment) − cash price."},{"id":"savings-months","level":"advanced","principle":"mat.months-to-reach-goal","rule":"personal-finance","kind":"numeric","mode":["decision"],"facts":["You want to save {G|money0} for a certification course. You already have {have|money0} and can save {s|money0} a month."],"prompt":["How many months until you reach the goal?"],"vars":{"G":{"type":"int","min":600,"max":1500,"step":50},"have":{"type":"int","min":100,"max":400,"step":25},"s":{"type":"choice","values":[75,90,120,150]}},"derive":{"ans":"ceil((G-have)/s)","w1":"ceil(G/s)","w2":"floor((G-have)/s)","w3":"round((G-have)/s, 1)"},"constraints":["(G-have) % s != 0","G > have + s","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"It will take {ans|int} months.","ok":"1","why":"Subtract what you have, divide by the monthly savings, and round up to whole months.","mis":"-"},{"key":"w1","text":"It will take {w1|int} months.","ok":"0","why":"This ignores the money you already have.","mis":"Start from zero every time."},{"key":"w2","text":"It will take {w2|int} months.","ok":"0","why":"Rounding down leaves you short of the goal.","mis":"Round to the nearest month."},{"key":"w3","text":"It will take {w3|dec1} months.","ok":"0","why":"Savings arrive in whole months, so round up.","mis":"Part of a month counts as a month of savings."}],"lesson":"Months needed = ceil((goal − current savings) ÷ monthly savings)."},{"id":"shipping-threshold","level":"advanced","principle":"mat.add-needed-item-for-free-shipping","rule":"calculate-and-compare","kind":"decision","mode":["decision"],"facts":["Your order totals {T|money0}. Shipping is {f|money0}, or free on orders of {F|money0} or more.","You also need a {x|money0} item next week."],"prompt":["What is the cheapest choice overall?"],"vars":{"T":{"type":"int","min":60,"max":90,"step":1},"f":{"type":"choice","values":[9,12,15]},"F":{"type":"choice","values":[75,100]},"x":{"type":"int","min":8,"max":25,"step":1}},"derive":{"nowpay":"T+f","add":"T+x","later":"T+f+x+f"},"constraints":["T < F","T + x >= F"],"options":[{"key":"a","text":"Add the item now and get free shipping, for {add|money0}","ok":"add < nowpay + x","why":"{T|money0} + {x|money0} reaches the free-shipping level, so you pay {add|money0} for both items.","mis":"-"},{"key":"b","text":"Pay shipping now, for {nowpay|money0}, and order the item next week","ok":"0","why":"That costs {nowpay|money0} now and more shipping later; adding the item now avoids both fees.","mis":"Ordering only what you need today is always cheapest."},{"key":"c","text":"Add extra items you do not need to be safe","ok":"0","why":"Buying items you do not need wastes money.","mis":"More items always mean more savings."},{"key":"d","text":"Pay shipping now and decide about the item later","ok":"0","why":"This pays a shipping fee you can avoid with an item you already need.","mis":"Deciding later saves money.","acceptable":true}],"lesson":"Count the costs you can avoid, not just today's total."},{"id":"markup-then-sale","level":"advanced","principle":"mat.markup-then-discount","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["An item costs the store {C|money0}. It is marked up {m|int} percent, then put on sale for {d|int} percent off the marked price."],"prompt":["What is the sale price?"],"vars":{"C":{"type":"int","min":20,"max":80,"step":4},"m":{"type":"choice","values":[40,50,60]},"d":{"type":"choice","values":[10,20,25]}},"derive":{"ans":"round2(C*(1+m/100)*(1-d/100))","w1":"round2(C*(1+(m-d)/100))","w2":"round2(C*(1+m/100))","w3":"round2(C*(1-d/100))"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"The sale price is {ans|money}.","ok":"1","why":"Apply the markup to the cost, then take the discount off the marked price.","mis":"-"},{"key":"w1","text":"The sale price is {w1|money}.","ok":"0","why":"This nets the percents, but the discount is taken from the higher marked price.","mis":"Percent changes can be combined by subtracting."},{"key":"w2","text":"The sale price is {w2|money}.","ok":"0","why":"This forgets the sale.","mis":"The marked price is the sale price."},{"key":"w3","text":"The sale price is {w3|money}.","ok":"0","why":"This takes the discount off the cost and forgets the markup.","mis":"Discounts apply to the store's cost."}],"lesson":"Apply percent changes one after another, each to the current price."},{"id":"tolerance-check","level":"advanced","principle":"mat.find-out-of-spec-measurement","rule":"compare-to-tolerance","kind":"pick","mode":["decision"],"facts":["A part must be {S|int} millimeters long, plus or minus {tol|dec1} millimeters.","You measure four parts: {m1|dec1}, {m2|dec1}, {m3|dec1} and {m4|dec1} millimeters."],"prompt":["Which part is out of spec?"],"vars":{"S":{"type":"int","min":40,"max":90,"step":1},"tol":{"type":"choice","values":[0.5,0.8]},"d1":{"type":"choice","values":[-0.3,0.2,0.4]},"d2":{"type":"choice","values":[-0.4,0.1,0.3]},"d3":{"type":"choice","values":[-0.2,0.3]},"d4":{"type":"choice","values":[-1.1,1,1.2]}},"derive":{"m1":"S+d1","m2":"S+d2","m3":"S+d3","m4":"S+d4"},"constraints":["abs(d1) < tol","abs(d2) < tol","abs(d3) < tol","abs(d4) > tol","d1 != d2","d2 != d3","d1 != d3"],"options":[{"key":"a","text":"The part measuring {m1|dec1} mm","ok":"abs(m1-S) > tol","why":"{m1|dec1} is within {tol|dec1} of {S|int}.","mis":"Any difference from the target is a defect."},{"key":"b","text":"The part measuring {m2|dec1} mm","ok":"abs(m2-S) > tol","why":"{m2|dec1} is within {tol|dec1} of {S|int}.","mis":"Any difference from the target is a defect."},{"key":"c","text":"The part measuring {m3|dec1} mm","ok":"abs(m3-S) > tol","why":"{m3|dec1} is within {tol|dec1} of {S|int}.","mis":"Any difference from the target is a defect."},{"key":"d","text":"The part measuring {m4|dec1} mm","ok":"abs(m4-S) > tol","why":"{m4|dec1} differs from {S|int} by more than {tol|dec1}.","mis":"-"}],"lesson":"A measurement is in spec if it is within the tolerance of the target."},{"id":"reorder-point","level":"advanced","principle":"mat.reorder-point","rule":"apply-stated-policy","kind":"numeric","mode":["decision"],"facts":["You use about {u|int} {supply.plural} a day. A new order takes {L|int} days to arrive, and policy is to keep {s|int} extra as safety stock."],"prompt":["At what stock level should you reorder?"],"vars":{"u":{"type":"int","min":6,"max":20,"step":1},"L":{"type":"int","min":3,"max":7,"step":1},"s":{"type":"int","min":10,"max":40,"step":5}},"derive":{"ans":"u*L+s","w1":"u*L","w2":"u+L+s","w3":"u*(L+s)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"Reorder when stock reaches {ans|int} items.","ok":"1","why":"Reorder when stock covers the days until delivery plus the safety stock.","mis":"-"},{"key":"w1","text":"Reorder when stock reaches {w1|int} items.","ok":"0","why":"This forgets the safety stock.","mis":"Safety stock is optional."},{"key":"w2","text":"Reorder when stock reaches {w2|int} items.","ok":"0","why":"This adds the numbers instead of multiplying daily use by days.","mis":"All the numbers get added."},{"key":"w3","text":"Reorder when stock reaches {w3|int} items.","ok":"0","why":"This multiplies the safety stock by daily use.","mis":"Everything gets multiplied by daily use."}],"lesson":"Reorder point = daily use × lead time + safety stock."},{"id":"commute-net-hourly","level":"advanced","principle":"mat.net-hourly-after-costs","rule":"personal-finance","kind":"numeric","mode":["decision"],"facts":["A job pays {r|money0} an hour for {h|int} hours a week. Commuting costs {c|money0} a day for {d|int} days a week."],"prompt":["What does the job pay per hour after commuting costs?"],"vars":{"r":{"type":"int","min":15,"max":22,"step":1},"h":{"type":"choice","values":[20,25,30,40]},"c":{"type":"choice","values":[6,8,10,12]},"d":{"type":"choice","values":[4,5]}},"derive":{"ans":"round2((r*h - c*d)/h)","w1":"r","w2":"r-c","w3":"round2(r - c*d)"},"constraints":["round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"After commuting, the job pays {ans|money}.","ok":"1","why":"Subtract the week's commuting cost from the week's pay, then divide by the hours.","mis":"-"},{"key":"w1","text":"After commuting, the job pays {w1|money}.","ok":"0","why":"This ignores the commuting cost.","mis":"Costs of getting to work do not matter."},{"key":"w2","text":"After commuting, the job pays {w2|money}.","ok":"0","why":"This subtracts a full day's commute from each hour.","mis":"Daily costs apply to every hour."},{"key":"w3","text":"After commuting, the job pays {w3|money}.","ok":"0","why":"This subtracts the whole week's commute from each hour.","mis":"Weekly costs come out of each hour."}],"lesson":"Net hourly pay = (weekly pay − weekly work costs) ÷ weekly hours."},{"id":"break-even","level":"advanced","principle":"mat.break-even-units","rule":"calculate-and-compare","kind":"numeric","mode":["decision"],"facts":["A school fundraiser costs {F|money0} to set up. Each item sells for {p|money0} and costs {v|money0} to make."],"prompt":["How many items must be sold to cover the setup cost?"],"vars":{"F":{"type":"int","min":120,"max":400,"step":20},"p":{"type":"int","min":8,"max":15,"step":1},"v":{"type":"int","min":2,"max":6,"step":1}},"derive":{"ans":"ceil(F/(p-v))","w1":"ceil(F/p)","w2":"floor(F/(p-v))","w3":"ceil(F/v)"},"constraints":["F % (p-v) != 0","p - v >= 3","round2(ans) != round2(w1)","round2(ans) != round2(w2)","round2(ans) != round2(w3)","round2(w1) != round2(w2)","round2(w1) != round2(w3)","round2(w2) != round2(w3)"],"options":[{"key":"ans","text":"You must sell {ans|int} items.","ok":"1","why":"Each sale earns the price minus the cost to make it; divide the setup cost by that and round up.","mis":"-"},{"key":"w1","text":"You must sell {w1|int} items.","ok":"0","why":"This ignores what each item costs to make.","mis":"The selling price is all profit."},{"key":"w2","text":"You must sell {w2|int} items.","ok":"0","why":"Rounding down leaves the setup cost not quite covered.","mis":"Round to the nearest item."},{"key":"w3","text":"You must sell {w3|int} items.","ok":"0","why":"This divides by the cost to make, not the profit per item.","mis":"Cost per item decides the break-even."}],"lesson":"Break-even quantity = setup cost ÷ (price − cost per item), rounded up."}]},{"skill":"mathematics","engine":"numeric","framework":"numeric-decision","contexts":"any","requires":["supply","area"],"setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}."],"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","numbers-oracle-verified"],"notes":"Answers are calculated from generated numbers; distractors are named calculation misconceptions; policies (overtime, tip pool, reorder) are stated in the scenario. Verified by tests/compose-numeric-oracle.test.js."},"id":"mat-check-calcs","family":"mathematics.cx-checking-calculations","familyName":"Checking calculations in documents","concepts":["mathematics:basic-calculations","mathematics:job-task-math"],"configs":[{"id":"invoice-line","level":"beginner","principle":"mat.doc-quantity-times-price","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["{Lead|the} asks you to check this order summary before it is sent."],"prompt":["Which line contains the calculation error?"],"title":["Order summary"],"docType":"note","vars":{"q1":{"type":"int","min":3,"max":9,"step":1},"e1":{"type":"choice","values":[4,6,8]},"q2":{"type":"int","min":2,"max":6,"step":1},"e2":{"type":"choice","values":[5,7,9]}},"derive":{"t1":"q1*e1","t2":"q2*e2","bad":"q1+e1","tot":"q1*e1+q2*e2"},"constraints":["q1+e1 != q1*e1"],"lines":[{"id":"h","text":"{supply.plural|cap}: order for the {area}","fine":"A heading, no calculation."},{"id":"l1","text":"{q1|int} boxes at {e1|money0} each = {bad|money0}","bad":true,"why":"{q1|int} × {e1|money0} is {t1|money0}; the line adds instead of multiplying."},{"id":"l2","text":"{q2|int} rolls at {e2|money0} each = {t2|money0}","fine":"{q2|int} × {e2|money0} = {t2|money0} is correct."},{"id":"to","text":"Deliver to: the {area}","fine":"Delivery information, no calculation."}],"lesson":"Check each line total: quantity × price."},{"id":"timesheet","level":"beginner","principle":"mat.doc-hours-sum","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check your timesheet before you submit it."],"prompt":["Which line contains the calculation error?"],"title":["Weekly timesheet"],"docType":"note","vars":{"a":{"type":"int","min":4,"max":8,"step":1},"b":{"type":"int","min":4,"max":8,"step":1},"c":{"type":"int","min":4,"max":8,"step":1},"k":{"type":"choice","values":[1,2]}},"derive":{"tot":"a+b+c","bad":"a+b+c+k"},"constraints":[],"lines":[{"id":"mon","text":"Monday: {a|int} hours","fine":"A recorded day."},{"id":"tue","text":"Tuesday: {b|int} hours","fine":"A recorded day."},{"id":"wed","text":"Wednesday: {c|int} hours","fine":"A recorded day."},{"id":"tot","text":"Total: {bad|int} hours","bad":true,"why":"{a|int} + {b|int} + {c|int} = {tot|int}, not {bad|int}."}],"lesson":"Add every entry and check the total."},{"id":"change-log","level":"beginner","principle":"mat.doc-change-subtraction","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check the cash log before closing."],"prompt":["Which line contains the calculation error?"],"title":["Cash log"],"docType":"note","vars":{"t1":{"type":"int","min":11,"max":18,"step":1},"t2":{"type":"int","min":21,"max":38,"step":1},"k":{"type":"choice","values":[1,2]}},"derive":{"c1":"20-t1","c2":"50-t2","bad":"50-t2+k"},"constraints":[],"lines":[{"id":"r1","text":"Sale {t1|money0}, paid $20, change {c1|money0}","fine":"20 − {t1|int} = {c1|int}."},{"id":"r2","text":"Sale {t2|money0}, paid $50, change {bad|money0}","bad":true,"why":"50 − {t2|int} = {c2|int}, not {bad|int}."},{"id":"note","text":"Drawer counted by two people.","fine":"A procedure note, no calculation."}],"lesson":"Check each subtraction when making change."},{"id":"overtime-doc","level":"intermediate","principle":"mat.doc-overtime-rate","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this pay summary. The workplace pays 1.5 times the rate for hours over 40."],"prompt":["Which line contains the calculation error?"],"title":["Pay summary"],"docType":"note","vars":{"h":{"type":"int","min":42,"max":48,"step":1},"r":{"type":"int","min":14,"max":20,"step":1}},"derive":{"reg":"40*r","ot":"(h-40)*1.5*r","otb":"(h-40)*r","tot":"40*r+(h-40)*1.5*r","oth":"h-40"},"constraints":[],"lines":[{"id":"hrs","text":"Hours worked: {h|int}","fine":"The recorded hours."},{"id":"reg","text":"Regular pay: 40 × {r|money0} = {reg|money0}","fine":"Correct."},{"id":"ot","text":"Overtime pay: {oth|int} × {r|money0} = {otb|money0}","bad":true,"why":"Overtime is paid at 1.5 times the rate; it should be {ot|money}."},{"id":"note","text":"Rate: {r|money0} an hour.","fine":"The stated rate."}],"lesson":"Overtime hours use 1.5 times the regular rate."},{"id":"sale-tax-doc","level":"intermediate","principle":"mat.doc-tax-on-sale-price","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this receipt. Tax is added to the sale price."],"prompt":["Which line contains the calculation error?"],"title":["Receipt"],"docType":"note","vars":{"pr":{"type":"int","min":40,"max":120,"step":10},"d":{"type":"choice","values":[10,20,25]},"t":{"type":"choice","values":[5,8]}},"derive":{"sale":"pr*(1-d/100)","tax":"round2(pr*(1-d/100)*t/100)","taxb":"round2(pr*t/100)"},"constraints":["round2(pr*t/100) != round2(pr*(1-d/100)*t/100)"],"lines":[{"id":"orig","text":"Original price: {pr|money0}","fine":"Starting price."},{"id":"disc","text":"{d|int} percent off: sale price {sale|money}","fine":"Correct sale price."},{"id":"tax","text":"Tax at {t|int} percent: {taxb|money}","bad":true,"why":"Tax should be on the sale price: {tax|money}. This taxes the original price."},{"id":"thanks","text":"Thank you for shopping with us.","fine":"No calculation."}],"lesson":"Tax is calculated on the price actually paid."},{"id":"waste-doc","level":"intermediate","principle":"mat.doc-waste-allowance","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this materials estimate."],"prompt":["Which line contains the calculation error?"],"title":["Materials estimate"],"docType":"note","vars":{"a":{"type":"int","min":100,"max":300,"step":10},"c":{"type":"choice","values":[20,25]}},"derive":{"need":"a*1.1","bx":"ceil(a*1.1/c)","bxb":"ceil(a/c)"},"constraints":["ceil(a*1.1/c) != ceil(a/c)"],"lines":[{"id":"area","text":"Floor area: {a|int} square feet","fine":"Given."},{"id":"waste","text":"With 10 percent waste: {need|dec1} square feet","fine":"{a|int} × 1.1 is correct."},{"id":"boxes","text":"Boxes at {c|int} square feet each: {bxb|int}","bad":true,"why":"{need|dec1} ÷ {c|int}, rounded up, is {bx|int} boxes. This used the area without waste."},{"id":"who","text":"Prepared for {lead|the}.","fine":"No calculation."}],"lesson":"Use the total with waste when counting boxes."},{"id":"net-pay-doc","level":"advanced","principle":"mat.doc-percent-deduction","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this pay stub before you file it."],"prompt":["Which line contains the calculation error?"],"title":["Pay stub"],"docType":"note","vars":{"g":{"type":"int","min":500,"max":900,"step":20},"t":{"type":"choice","values":[10,12,15]},"f":{"type":"choice","values":[10,20]}},"derive":{"tax":"g*t/100","taxb":"t*10","net":"g-g*t/100-f"},"constraints":["t*10 != g*t/100"],"lines":[{"id":"gross","text":"Gross pay: {g|money0}","fine":"Given."},{"id":"tax","text":"Tax withheld ({t|int} percent): {taxb|money0}","bad":true,"why":"{t|int} percent of {g|money0} is {tax|money}."},{"id":"park","text":"Parking: {f|money0}","fine":"A flat deduction."},{"id":"rate","text":"Pay period: one week","fine":"No calculation."}],"lesson":"A percent deduction is the rate times the gross pay."},{"id":"reorder-doc","level":"advanced","principle":"mat.doc-reorder-point","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this inventory note. Policy: reorder at daily use × delivery days + safety stock."],"prompt":["Which line contains the calculation error?"],"title":["Inventory note"],"docType":"note","vars":{"u":{"type":"int","min":5,"max":15,"step":1},"L":{"type":"int","min":3,"max":6,"step":1},"s":{"type":"int","min":10,"max":30,"step":5}},"derive":{"ans":"u*L+s","bad":"u*L"},"constraints":[],"lines":[{"id":"use","text":"Daily use: {u|int}","fine":"Given."},{"id":"lead","text":"Delivery time: {L|int} days","fine":"Given."},{"id":"safe","text":"Safety stock: {s|int}","fine":"Given."},{"id":"rp","text":"Reorder point: {bad|int}","bad":true,"why":"Policy adds the safety stock: {u|int} × {L|int} + {s|int} = {ans|int}."}],"lesson":"Apply every part of a stated formula."},{"id":"budget-summary","level":"advanced","principle":"mat.doc-percent-of-budget","rule":"find-calculation-error","kind":"find","mode":["find"],"facts":["Check this budget summary before it goes to {lead|the}."],"prompt":["Which line contains the calculation error?"],"title":["Budget summary"],"docType":"note","vars":{"B":{"type":"choice","values":[500,800,1000]},"S":{"type":"int","min":100,"max":400,"step":20}},"derive":{"pct":"S*100/B","left":"B-S","badpct":"(B-S)*100/B"},"constraints":["(S*100) % B == 0","S*2 != B"],"lines":[{"id":"bud","text":"Budget: {B|money0}","fine":"Given."},{"id":"spent","text":"Spent: {S|money0}","fine":"Given."},{"id":"left","text":"Remaining: {left|money0}","fine":"{B|int} − {S|int} is correct."},{"id":"pct","text":"Percent spent: {badpct|pct}","bad":true,"why":"{S|money0} ÷ {B|money0} is {pct|pct} spent; this is the percent remaining."}],"lesson":"Check that a percent describes the quantity its label names."}]},{"id":"pro-client-meeting","skill":"professionalism","family":"professionalism.cx-client-meeting","familyName":"Getting ready to meet a client","framework":"competing-priorities","concepts":["professionalism:punctuality-attendance","professionalism:appearance","professionalism:etiquette","professionalism:self-representation"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. In fifteen minutes you are meeting a {client} for the first time.","As {role|a} at {workplace|a}, you have a first meeting with a new {client} at 10 a.m."],"pressure":["{coworker3} says {client.plural} do not care about the small stuff.","You are already feeling rushed."],"detail":["The meeting will be in the front office.","{Lead|the} will join for the last few minutes."],"tiers":{"1":"Letting someone know you will be late comes before anything else.","2":"Meeting the dress code shows respect for the {client} and the workplace.","3":"Preparation shows the {client} you take their time seriously.","4":"Your full attention belongs to the {client} during the meeting.","5":"Small courtesies matter once the basics are covered."},"issues":[{"id":"late","tier":1,"rule":"communicate-delay-early","principle":"pro.notify-before-being-late","fact":["You are running about ten minutes behind for the meeting."],"clear":["You already messaged the {client} that you would be ten minutes late."],"done":"the {client} already knows you will be late","short":"running ten minutes late","action":"Let the {client} know now that you are running ten minutes late.","brief":"tell the {client} you will be late","reason":"A quick heads-up respects the {client}'s time and keeps the first impression positive.","lesson":"If you will be late, let people know before the start time.","shortcut":[{"text":"Arrive when you can and apologize at the start.","brief":"apologize when you arrive","why":"An apology after the fact does not give the {client} the chance to plan.","mis":"Apologizing later is as good as warning ahead."}]},{"id":"dress","tier":2,"rule":"follow-dress-code","principle":"pro.meet-stated-dress-code","fact":["The workplace dress code calls for closed-toe shoes, and you are wearing sandals."],"short":"the dress-code problem","action":"Change into the closed-toe shoes the dress code calls for.","brief":"change into closed-toe shoes","reason":"Following the dress code shows respect and represents the workplace well.","lesson":"Follow your workplace's dress code, especially when meeting others.","shortcut":[{"text":"Keep the sandals, since the {client} will not look at your feet.","brief":"keep the sandals","why":"The dress code applies whether or not anyone notices.","mis":"Rules only matter if someone notices."}],"clear":["You changed into closed-toe shoes before leaving home."],"done":"you are already wearing closed-toe shoes"},{"id":"prep","tier":3,"rule":"prepare-in-advance","principle":"pro.review-before-meeting","fact":["You have not looked at the {client}'s request since it arrived last week."],"clear":["You reviewed the {client}'s request and made notes this morning."],"done":"you already reviewed the request","short":"not having reviewed the request","action":"Spend a few minutes reviewing the {client}'s request before the meeting.","brief":"review the request","reason":"Knowing the request shows the {client} you are prepared and respect their time.","lesson":"Prepare before meetings so you can represent the workplace well.","shortcut":[{"text":"Ask the {client} to explain the request again from the start.","brief":"have the {client} explain it again","why":"Asking a {client} to repeat what they already sent suggests you did not prepare.","mis":"Clients expect to repeat themselves."}]},{"id":"phone","tier":4,"rule":"give-full-attention","principle":"pro.silence-phone-in-meeting","noProceed":true,"fact":["Your phone keeps buzzing with personal texts."],"short":"the buzzing phone","action":"Silence your phone and put it away for the meeting.","brief":"silence and put away your phone","reason":"Checking a phone in a meeting signals the {client} is not your priority.","lesson":"Give people your full attention by putting your phone away.","shortcut":[{"text":"Keep the phone on the table so you can glance at urgent texts.","brief":"keep the phone on the table","why":"Glancing at texts during a meeting is distracting and disrespectful.","mis":"Quick glances at a phone go unnoticed."}]},{"id":"name","tier":5,"rule":"show-courtesy","principle":"pro.ask-for-name-again","noProceed":true,"fact":["You have forgotten the {client}'s name, though it is on the meeting invite."],"short":"the forgotten name","action":"Check the meeting invite for the name before you go in.","brief":"check the invite for the name","reason":"Using someone's name correctly is a basic courtesy that makes a good impression.","lesson":"Small courtesies, like using names correctly, build professional relationships.","shortcut":[{"text":"Avoid using the {client}'s name during the meeting.","brief":"avoid using the name","why":"Avoiding the name can feel cold when the invite has it.","mis":"Avoiding a name is as good as remembering it."}]}],"proceed":{"text":"Greet the {client} warmly and start the meeting on time.","why":"You are prepared, dressed appropriately and on time, so the meeting can start.","lesson":"Preparation and punctuality let you make a strong professional impression."},"generic":[{"text":"Ask {coworker} to take the meeting so you can relax.","why":"The meeting is yours. Handing it off without reason is unprofessional.","mis":"Avoiding pressure is a good reason to hand off work."},{"text":"Start the meeting with a joke about how hectic your morning was.","why":"Opening with your own stress makes the meeting about you instead of the {client}.","mis":"Complaining about your day builds rapport."}],"overcaution":[{"text":"Ask {lead|the} to run the whole meeting instead of you.","why":"You are ready. Handing the meeting over is unnecessary.","mis":"Supervisors should run every client meeting."}],"process":{"setup":["You have a first meeting with a new {client} at {workplace|the} this morning."],"because":{"prep":["You have not looked at the {client}'s request yet."],"dress":["Your shoes do not meet the dress code."]},"steps":[{"id":"review","text":"Review the request and make notes","issue":"prep"},{"id":"shoes","text":"Change into closed-toe shoes","issue":"dress"},{"id":"arrive","text":"Arrive at the meeting room a few minutes early","core":true},{"id":"silence","text":"Silence your phone","core":true},{"id":"greet","text":"Greet the {client} and start the meeting","core":true}],"rel":[["review","arrive","Preparation comes before you go to the meeting."],["shoes","arrive","You change before you go."],["arrive","greet","You need to be there before you greet the {client}."],["silence","greet","Silence your phone before the meeting starts."],["review","greet","Your notes are for the meeting."]],"alternatesReviewed":true,"lesson":"Prepare, meet the dress code, arrive early, silence distractions, then begin."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Dress code stated as workplace policy."}},{"id":"pro-office-etiquette","skill":"professionalism","family":"professionalism.cx-everyday-etiquette","familyName":"Everyday workplace etiquette","framework":"communication-failure","concepts":["professionalism:etiquette","professionalism:self-representation"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}.","You are {role|a} at {workplace|a}, in the middle of a normal workday."],"detail":["It is a busy afternoon.","Several coworkers are working nearby."],"issues":[{"id":"replyall","tier":1,"rule":"communicate-professionally","principle":"pro.no-personal-reply-all","onlyLevels":["beginner"],"fact":["You are about to reply-all to a message sent to the whole company with a personal joke."],"short":"the reply-all joke","action":"Reply only to the person you meant, or skip the reply.","reason":"A reply-all joke fills everyone's inbox and may not land well with people who do not know you.","lesson":"Think about who will read a message before you send it.","shortcut":[{"text":"Send it to everyone, since a joke will lighten the day.","why":"Hundreds of people did not ask for the joke, and some may find it unprofessional.","mis":"Everyone appreciates humor at work."}]},{"id":"speaker","tier":2,"rule":"respect-shared-space","principle":"pro.no-speakerphone-in-shared-area","onlyLevels":["beginner"],"fact":["You need to take a long personal call, and coworkers are working right next to you."],"short":"the personal call in a shared area","action":"Step somewhere private to take the call.","reason":"A long personal call in a shared space distracts coworkers.","lesson":"Respect shared spaces by keeping personal calls private.","shortcut":[{"text":"Take the call on speaker so you can keep working.","why":"Speakerphone in a shared area disturbs everyone nearby.","mis":"Multitasking on a call is efficient."}]},{"id":"online","tier":3,"rule":"represent-workplace-well","principle":"pro.keep-complaints-off-social-media","onlyLevels":["beginner"],"fact":["After a frustrating day, you start writing a public post complaining about a {client} by name."],"short":"the public complaint about a {client}","action":"Delete the post and talk the frustration over privately instead.","reason":"A public complaint about a named {client} reflects on you and your workplace, and it can hurt the {client}.","lesson":"What you post publicly represents you and your workplace.","shortcut":[{"text":"Post it, since it is your own account.","why":"Your own account is still public, and naming a {client} can harm them and your workplace.","mis":"Personal accounts have nothing to do with work."}]},{"id":"borrow","tier":4,"rule":"show-courtesy","principle":"pro.ask-before-borrowing","onlyLevels":["beginner"],"fact":["You need a stapler, and the only one is on {coworker}'s desk while {coworker} is away."],"short":"borrowing from an absent coworker","action":"Borrow it, then return it right away with a quick note saying thanks.","reason":"A short, open borrow with a note is courteous; keeping it or hiding the borrow is not.","lesson":"Treat coworkers' things with courtesy: ask or tell, and return them quickly.","shortcut":[{"text":"Take it to your desk and keep it for the week.","why":"Keeping a coworker's things without asking is inconsiderate.","mis":"Shared items belong to whoever needs them."}]},{"id":"gossip","tier":5,"rule":"avoid-gossip","principle":"pro.decline-gossip","onlyLevels":["beginner"],"fact":["{coworker2} starts gossiping about why another coworker was called into a meeting."],"short":"the gossip","action":"Change the subject or say you would rather not guess about it.","reason":"Gossip spreads rumors and damages trust. Politely stepping away keeps you professional.","lesson":"Stay out of workplace gossip.","shortcut":[{"text":"Join in, since everyone is curious.","why":"Speculating about a coworker spreads rumors that can hurt them.","mis":"Gossip is harmless if everyone does it."}]},{"id":"meeting","tier":6,"rule":"respect-others-time","principle":"pro.join-meeting-on-time","onlyLevels":["beginner"],"fact":["A team meeting starts in two minutes, and you are about to start a long personal call."],"short":"the meeting about to start","action":"Save the call for your break and go to the meeting on time.","reason":"Arriving late to meetings wastes others' time and looks unreliable.","lesson":"Be on time for meetings; personal business can wait for breaks.","shortcut":[{"text":"Make the call and slip into the meeting late.","why":"Arriving late interrupts the meeting and shows little respect for the team.","mis":"Being a few minutes late does not matter."}]},{"id":"dresscode","tier":7,"rule":"follow-dress-code","principle":"pro.follow-uniform-policy","onlyLevels":["beginner"],"fact":["The uniform policy says to wear your name badge, and you left yours in your car."],"short":"the missing name badge","action":"Get your name badge from the car before your shift starts.","reason":"The badge is part of the uniform policy and helps people know who you are.","lesson":"Follow uniform and badge policies every shift.","shortcut":[{"text":"Work without it, since everyone knows who you are.","why":"The policy applies every shift, and {client.plural} do not know you.","mis":"Policies only matter for new people."}]}],"proceed":{"text":"Go ahead, since nobody else will be bothered.","why":"In each case, other people are affected, so going ahead without thinking is not professional.","lesson":"Professional etiquette means considering how your actions affect others."},"generic":[{"text":"Ask {coworker3} whether it is okay and do whatever they say.","why":"A coworker's opinion does not replace your own judgment about etiquette.","mis":"If a coworker approves, it must be fine."},{"text":"Complain to {lead|the} about how stressful the day has been.","why":"Venting to the lead does not address the situation in front of you.","mis":"Stress excuses unprofessional choices."}],"doc":{"type":"email","title":["Your email to a new {client}"],"intro":["You are about to email a new {client} for the first time. Check the message first."],"lesson":"Professional emails are courteous, clear and represent the workplace well.","lines":[{"id":"greet","text":"Dear Ms. Alvarez,","fine":"A respectful greeting.","bad":[{"id":"greet-casual","level":"beginner","text":"Hey there buddy,","why":"A first message to a {client} should open respectfully.","principle":"pro.doc-casual-greeting"}]},{"id":"intro","text":"My name is {coworker}, and I will be your contact at {workplace|the}.","fine":"Introduces the writer clearly.","bad":[{"id":"intro-none","level":"beginner","text":"Anyway, here is the stuff you need.","why":"Skipping any introduction leaves the new {client} unsure who is writing.","principle":"pro.doc-no-introduction"}]},{"id":"meet","text":"Our meeting is confirmed for Tuesday at 10 a.m.","fine":"Confirms the details.","bad":[{"id":"meet-casual","level":"beginner","text":"hey, see u tues at like 10 or whatever","why":"Slang and missing capitalization are too casual for a first message to a {client}.","principle":"pro.doc-overly-casual"}]},{"id":"bring","text":"Please bring any photos of the work you would like done.","fine":"Clear, polite request.","bad":[{"id":"bring-demand","level":"beginner","text":"Bring photos, or do not bother coming.","why":"The line is rude and could drive the {client} away.","principle":"pro.doc-rude-demand"}]},{"id":"sign","text":"Best regards, {coworker}","fine":"A professional sign-off.","bad":[{"id":"sign-emoji","level":"intermediate","text":"Can't wait!!! 🎉🎉 Love ya","why":"Overly familiar language is not appropriate for a first message to a {client}.","principle":"pro.doc-overly-familiar-close"}]},{"id":"complaint","text":"Feel free to call if anything changes.","fine":"Invites contact.","bad":[{"id":"complaint-vent","level":"advanced","needs":["intro"],"text":"Honestly, things here have been chaotic lately, so bear with us.","why":"Complaining about your workplace to a new {client} represents it poorly.","principle":"pro.doc-complains-about-workplace"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Etiquette situations are beginner-only single decisions."}},{"id":"raw-delay-email","skill":"reading-and-writing","family":"reading-and-writing.cx-writing-a-delay-notice","familyName":"Writing a clear delay notice","framework":"communication-failure","concepts":["reading-and-writing:clarity","reading-and-writing:tone-and-audience","reading-and-writing:conventions"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You are writing an email to tell a {client} that their {deliverable} will be late.","As {role|a} at {workplace|a}, you are drafting a message to a {client} about a delay with their {deliverable}."],"pressure":["The {client} has asked about it three times today.","{coworker3} says to just send something quickly."],"detail":["The draft is about 150 words long.","You are writing it on the shared computer."],"tiers":{"1":"The facts in the message have to be right before anything else.","2":"The reader has to be able to understand the words.","3":"A calm, polite tone keeps the relationship intact.","4":"The key information belongs at the start.","5":"Proofreading is the last step once the content is right."},"issues":[{"id":"date","tier":1,"rule":"verify-before-writing","principle":"raw.confirm-facts-before-sending","fact":["You are not sure of the new date the {deliverable} will be ready."],"clear":["{Lead|the} confirmed that the new date is Thursday."],"done":"the new date was already confirmed","short":"the unconfirmed new date","action":"Confirm the new date with {lead|the} before putting it in the email.","brief":"confirm the new date","reason":"A wrong date in writing creates a second broken promise. Confirming it first keeps the message accurate.","lesson":"Confirm the facts before you put them in writing.","shortcut":[{"text":"Write a date that seems likely and fix it later if needed.","brief":"write a likely date","why":"A guessed date in writing is a promise you may not keep.","mis":"Written dates can be changed easily later."}]},{"id":"jargon","tier":2,"rule":"write-for-audience","principle":"raw.plain-words-for-client","fact":["Your draft uses the team's shorthand codes, which the {client} will not know."],"short":"the shorthand codes","action":"Replace the shorthand with plain words the {client} will understand.","brief":"replace shorthand with plain words","reason":"The {client} cannot act on a message they cannot understand.","lesson":"Write in words your reader knows.","shortcut":[{"text":"Keep the codes, since they are more precise.","brief":"keep the codes","why":"Precision does not help if the reader cannot decode it.","mis":"Technical wording is always clearer."}]},{"id":"tone","tier":3,"rule":"adjust-tone","principle":"raw.calm-polite-tone","fact":["Your draft sounds irritated, because the {client} has asked about the order three times."],"short":"the irritated tone","action":"Revise the draft so it sounds calm and polite.","brief":"make the tone calm and polite","reason":"The {client}'s questions are reasonable. An irritated tone damages the relationship.","lesson":"Match your tone to a respectful professional relationship.","shortcut":[{"text":"Keep the tone, since the {client} needs to stop asking.","brief":"keep the irritated tone","why":"An irritated tone may make the {client} more upset, not less.","mis":"Showing frustration makes people stop asking."}]},{"id":"buried","tier":4,"rule":"organize-for-reader","principle":"raw.lead-with-key-information","fact":["The ready date and what happens next are buried in the fourth paragraph."],"short":"the buried key information","action":"Move the new date and next step into the first two sentences.","brief":"move the key facts to the top","reason":"Readers look for the key facts first. Putting them up front makes the message clear at a glance.","lesson":"Put the most important information first.","shortcut":[{"text":"Leave it, since the {client} will read the whole thing.","brief":"leave the order as is","why":"Many readers skim. Buried facts get missed.","mis":"Readers read every word carefully."}]},{"id":"proof","tier":5,"rule":"proofread","principle":"raw.proofread-before-sending","noProceed":true,"fact":["You have not proofread the draft yet."],"short":"the unproofread draft","action":"Proofread the email for spelling and grammar before you send it.","brief":"proofread before sending","reason":"Errors distract the reader and make the message look careless.","lesson":"Proofread before sending anything a customer will read.","shortcut":[{"text":"Send it now and correct any errors in a follow-up.","brief":"send now and correct later","why":"A follow-up correction draws more attention to the mistakes.","mis":"Errors do not matter if you fix them later."}],"clear":["You already proofread the draft twice."],"done":"the draft was already proofread"}],"proceed":{"text":"Send the email to the {client}.","why":"The message is accurate, clear and polite, so it is ready to send.","lesson":"Send a message once it is accurate, clear and suited to the reader."},"generic":[{"text":"Call the {client} and say you will email something eventually.","why":"A vague promise adds nothing. The {client} needs the actual information.","mis":"Contacting someone is the same as informing them."},{"text":"Ask {coworker2} to write and send it under your name.","why":"Someone else writing under your name is misleading and avoids your job.","mis":"It does not matter who writes a message."}],"overcaution":[{"text":"Ask {lead|the} to rewrite the whole email before you send it.","why":"The email is ready. A full rewrite delays the {client}'s answer.","mis":"Supervisors should rewrite every message."}],"doc":{"type":"email","title":["Draft: update on your {deliverable}"],"intro":["Check this draft before it goes to the {client}."],"prompt":["Which line needs to be fixed before sending?","Which line is the problem?"],"lesson":"Clear customer emails lead with the facts, use plain words, keep a polite tone and follow writing conventions.","lines":[{"id":"open","text":"Your {deliverable} will be ready Thursday, two days later than planned.","fine":"Leads with the key fact."},{"id":"why","text":"A part we needed arrived late from our supplier.","fine":"Gives a short, plain reason.","bad":[{"id":"why-jargon","level":"intermediate","text":"The delay is due to a BO on SKU 44-B per the PO.","why":"Abbreviations the {client} does not know make the reason unclear.","principle":"raw.doc-jargon"}]},{"id":"sorry","text":"We are sorry for the inconvenience.","fine":"A polite apology.","bad":[{"id":"sorry-irritated","level":"beginner","text":"As we have told you several times, these things take time.","why":"The tone is irritated and talks down to the {client}.","principle":"raw.doc-irritated-tone"}]},{"id":"next","text":"We will call you Thursday morning when it is ready.","fine":"States the next step clearly."},{"id":"grammar","text":"Please let us know if you have any questions.","fine":"A clear, correct close.","bad":[{"id":"grammar-errors","level":"beginner","text":"please let us no if you has any questions","why":"Spelling, grammar and capitalization errors make the message look careless.","principle":"raw.doc-convention-errors"}]},{"id":"date2","text":"Thank you for your patience.","fine":"A courteous close.","bad":[{"id":"date2-conflict","level":"advanced","needs":["open"],"text":"Your {deliverable} should be ready by Monday at the latest.","why":"This contradicts the opening line, which says Thursday. Conflicting dates confuse the reader.","principle":"raw.doc-conflicting-dates"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Clarity, audience, tone and conventions."}},{"id":"raw-reading-procedure","skill":"reading-and-writing","family":"reading-and-writing.cx-reading-a-procedure","familyName":"Reading a written procedure carefully","framework":"conflicting-instructions","concepts":["reading-and-writing:interpret-documents"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You are about to follow a written procedure for {task|the} for the first time.","As {role|a} at {workplace|a}, you have been handed a written procedure for {task|the}."],"pressure":["{coworker3} says nobody actually reads the whole procedure.","{Lead|the} wants the task done before lunch."],"detail":["The procedure is three pages long.","It is printed on colored paper."],"tiers":{"1":"When two documents disagree, find out which one is current first.","2":"A warning section has to be read in full before you start.","3":"An unknown term can change what a step means.","4":"The revision date tells you whether the copy is current."},"issues":[{"id":"conflict","tier":1,"rule":"resolve-conflicting-documents","principle":"raw.ask-which-document-is-current","fact":["The printed procedure and the copy posted on the wall give different steps for the same part."],"short":"the two conflicting versions","action":"Ask {lead|the} which version is current before you continue.","brief":"ask which version is current","reason":"Following the wrong version could mean doing the task incorrectly. The lead knows which one is current.","lesson":"When documents conflict, find out which is current before acting.","shortcut":[{"text":"Follow whichever version seems easier.","brief":"follow the easier version","why":"Easier is not the same as current or correct.","mis":"The simplest instructions are the right ones."}]},{"id":"warning","tier":2,"rule":"read-warnings-fully","principle":"raw.read-skipped-warning","fact":["You skimmed the procedure and skipped a boxed section labeled \"Caution.\""],"short":"the caution box you skipped","action":"Go back and read the caution section in full before starting.","brief":"read the caution section fully","reason":"Caution sections hold the information most likely to prevent mistakes or injuries.","lesson":"Read warnings and cautions in full before starting a task.","shortcut":[{"text":"Start the task and read the caution if something goes wrong.","brief":"read it only if something goes wrong","why":"The caution is meant to prevent problems, not explain them afterward.","mis":"Warnings are only needed when trouble starts."}]},{"id":"term","tier":3,"rule":"clarify-unknown-term","principle":"raw.look-up-unknown-term","fact":["Step 4 uses a term you do not know."],"clear":["The glossary on the last page explains the term."],"done":"the glossary already explains the term","short":"the unknown term","action":"Check the glossary or ask {coworker} what the term means.","brief":"find out what the term means","reason":"Guessing at a term can change what the step means.","lesson":"Clarify words you do not know before acting on instructions.","shortcut":[{"text":"Guess what it means from the rest of the sentence.","brief":"guess from context","why":"A wrong guess can mean doing the step incorrectly.","mis":"Context always makes a term's meaning clear."}]},{"id":"revision","tier":4,"rule":"check-document-currency","principle":"raw.check-revision-date","fact":["The procedure has a revision date from three years ago."],"clear":["The revision date shows it was updated last month."],"done":"the procedure is already confirmed as current","short":"the old revision date","action":"Ask {lead|the} whether a newer version of the procedure exists.","brief":"ask if there is a newer version","reason":"Procedures change. An old copy may be missing current steps.","lesson":"Check that a document is current before relying on it.","shortcut":[{"text":"Follow it as written, since procedures rarely change.","brief":"follow it as written","why":"Three years is a long time. Steps may have changed.","mis":"Old documents are as reliable as new ones."}]}],"exclusive":[["conflict","revision"]],"proceed":{"text":"Follow the procedure step by step.","why":"The procedure is current, clear and complete, so following it carefully is the right move.","lesson":"When a procedure is current and understood, follow it step by step."},"generic":[{"text":"Ask {coworker2} to just show you instead of reading anything.","why":"Watching once may miss steps the written procedure covers.","mis":"Watching is always better than reading."},{"text":"Skip to the last page to see what the end result looks like and go from there.","why":"Skipping the steps risks missing what each one requires.","mis":"Knowing the result is enough to do a task."}],"overcaution":[{"text":"Ask {lead|the} to read the whole procedure aloud to you first.","why":"The procedure is clear and current. Having it read aloud wastes the lead's time.","mis":"Instructions are only safe if a supervisor reads them out."}],"doc":{"type":"procedure","title":["Procedure: {task}"],"intro":["You are checking this procedure before it is reprinted."],"prompt":["Which line is unclear or wrong?","Which line is the problem?"],"lesson":"Clear procedures use exact wording, keep steps in order and agree with themselves.","lines":[{"id":"rev","text":"Revised: this month. Replaces all earlier versions.","fine":"Shows the document is current."},{"id":"s1","text":"Step 1: Gather the items listed on the checklist.","fine":"Clear and specific."},{"id":"s2","text":"Step 2: Check each item against the checklist before starting.","fine":"Clear verification step.","bad":[{"id":"s2-vague","level":"beginner","text":"Step 2: Do the usual checks, more or less.","why":"\"The usual checks, more or less\" is too vague to follow.","principle":"raw.doc-vague-step"}]},{"id":"s3","text":"Step 3: Record the start time in {record|the}.","fine":"Specific and actionable.","bad":[{"id":"s3-vague","level":"beginner","text":"Step 3: Write down the time somewhere.","why":"\"Somewhere\" is vague; the procedure should name where to record it.","principle":"raw.doc-vague-location"}]},{"id":"s4","text":"Step 4: Complete the task, then record the finish time.","fine":"Clear order of actions.","bad":[{"id":"s4-order","level":"intermediate","text":"Step 4: Record the finish time, then complete the task.","why":"You cannot record a finish time before the task is finished.","principle":"raw.doc-impossible-order"}]},{"id":"s5","text":"Step 5: Return all items to their places.","fine":"Clear closing step.","bad":[{"id":"s5-oldversion","level":"advanced","needs":["rev"],"text":"Note: for Step 3, keep using last year's version of this procedure.","why":"The top line says this revision replaces all earlier versions, so pointing to last year's version contradicts it.","principle":"raw.doc-contradicts-revision-note"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Interpreting documents. Conflicting copies and an old revision date overlap, so they are exclusive."}},{"id":"div-team-project","skill":"respect-for-diversity","family":"respect-for-diversity.cx-inclusive-team-project","familyName":"Planning an inclusive team project","framework":"consequences","concepts":["respect-for-diversity:individual-differences","respect-for-diversity:collaborating","respect-for-diversity:own-bias"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You are helping {lead|the} organize a team project day next month.","As {role|a} at {workplace|a}, you are planning a team project day with three coworkers."],"pressure":["{coworker3} says it is too much work to plan around everyone.","{Lead|the} wants the plan by Friday."],"detail":["The project day will include a working lunch.","The team has six members."],"tiers":{"1":"A remark that demeans a coworker needs a response in the moment.","2":"A plan that shuts someone out has to be fixed before anything else.","3":"Scheduling should let everyone take part.","4":"Assumptions about a person should be checked by asking them.","5":"Drawing out every voice improves the plan once access is settled."},"issues":[{"id":"joke","tier":1,"rule":"address-disrespect","principle":"div.respond-to-demeaning-joke","fact":["During the planning meeting, {coworker3} jokes about the way {coworker2} speaks."],"short":"the demeaning joke","action":"Say calmly that the joke is not okay, and check in with {coworker2}.","brief":"say the joke is not okay and check on {coworker2}","reason":"Letting a demeaning joke pass tells the target it is acceptable. A calm response supports the coworker and sets a respectful norm.","lesson":"Respond calmly when a coworker is mocked; silence signals approval.","shortcut":[{"text":"Laugh along so the meeting does not get awkward.","brief":"laugh along to keep things light","why":"Laughing along joins in the disrespect and leaves the coworker unsupported.","mis":"Avoiding awkwardness is more important than addressing disrespect."}]},{"id":"access","tier":2,"rule":"remove-barrier","principle":"div.choose-accessible-location","fact":["{coworker} uses a wheelchair, and the planned meeting room is up a flight of stairs."],"clear":["The project day was already moved to a ground-floor room."],"done":"the project day was already moved to an accessible room","short":"the room {coworker} cannot reach","action":"Suggest moving the project day to a room everyone can reach.","brief":"suggest an accessible room","reason":"A plan that a teammate cannot physically join shuts them out. Choosing an accessible room includes everyone.","lesson":"Plan events so every team member can take part fully.","shortcut":[{"text":"Plan for {coworker} to join by video from downstairs.","brief":"have {coworker} join by video","why":"Video from another floor leaves {coworker} outside the group when an accessible room would include them.","mis":"Offering a lesser alternative is the same as including someone."}]},{"id":"date","tier":3,"rule":"check-schedule-with-team","principle":"div.check-date-against-observances","fact":["The planned date falls on a religious holiday that {coworker2} observes."],"clear":["{coworker2} checked the calendar and confirmed the date works."],"done":"the date was already checked with {coworker2}","short":"the date conflict with {coworker2}'s holiday","action":"Suggest checking possible dates with the whole team before choosing one.","brief":"check possible dates with the team","reason":"Picking a date some people cannot attend leaves them out. Checking dates is a simple way to respect everyone.","lesson":"Respect differences in how people observe holidays when scheduling team events.","shortcut":[{"text":"Keep the date and let {coworker2} decide whether to come.","brief":"keep the date anyway","why":"Keeping a date that conflicts with a coworker's observance puts them in an unfair position.","mis":"Team events should not change for one person."}]},{"id":"assume","tier":4,"rule":"ask-dont-assume","principle":"div.ask-instead-of-assuming","fact":["You realize you planned to give {coworker} only the note-taking without asking what they would prefer."],"short":"your assumption about {coworker}'s role","action":"Ask {coworker} which part of the project they would like to take on.","brief":"ask {coworker} which part they want","reason":"Assigning roles based on assumptions can limit people unfairly. Asking respects their skills and choices.","lesson":"Notice your assumptions about people and check them by asking.","shortcut":[{"text":"Keep the plan, since note-taking is probably easiest for {coworker}.","brief":"keep the note-taking plan","why":"Deciding what is easiest for someone without asking is the assumption to avoid.","mis":"You know what suits others without asking."}]},{"id":"voice","tier":5,"rule":"invite-contribution","principle":"div.invite-stated-preference","fact":["{coworker} has mentioned preferring to be asked directly before sharing ideas in a group."],"short":"{coworker}'s preference to be asked","action":"Invite {coworker} by name to share ideas for the project.","brief":"invite {coworker} by name to share ideas","reason":"People share ideas in different ways. Respecting a stated preference brings in ideas the team would otherwise miss.","lesson":"Adapt how you draw out ideas to the people on your team.","shortcut":[{"text":"Wait for {coworker} to speak up like everyone else.","brief":"wait for {coworker} to speak up","why":"{coworker} told the team what works for them. Ignoring it loses their ideas.","mis":"Everyone should contribute in the same way."}]}],"proceed":{"text":"Move ahead with the plan the team agreed on and share it with {lead|the}.","why":"The plan includes everyone and nothing else needs addressing, so it is ready to go to the lead.","lesson":"Once a plan works for everyone, move it forward."},"generic":[{"text":"Plan everything yourself to save the team the trouble of discussing it.","why":"Planning alone leaves out the perspectives that make a team plan work for everyone.","mis":"Collaboration slows things down."},{"text":"Choose whatever the majority of the team wants and move on.","why":"Going with the majority without checking can leave some teammates unable to take part.","mis":"Majority rule is always fair."}],"overcaution":[{"text":"Survey every person at {workplace|the} before finalizing anything.","why":"The plan already works for the team. Surveying everyone delays it without need.","mis":"Asking more people always makes a plan more inclusive."}],"doc":{"type":"email","title":["Draft invitation: team project day"],"intro":["You drafted this invitation to the team. Check it before sending."],"lesson":"Inclusive messages make it easy for everyone to take part and avoid assumptions.","lines":[{"id":"what","text":"We are planning a team project day to reorganize the work area.","fine":"Clear purpose."},{"id":"where","text":"It will be in the ground-floor training room, which has step-free access.","fine":"Shares accessibility information up front.","bad":[{"id":"where-stairs","level":"intermediate","text":"It will be in the upstairs storage room; everyone can manage the stairs.","why":"Assuming everyone can use stairs excludes people with mobility needs.","principle":"div.doc-assumes-everyone-can-use-stairs"}]},{"id":"dates","text":"Please reply with any dates that do not work for you.","fine":"Invites schedule conflicts before choosing a date.","bad":[{"id":"dates-fixed","level":"beginner","text":"The date is set, so do not bother replying about conflicts.","why":"Refusing to hear about conflicts can exclude people who cannot attend.","principle":"div.doc-ignores-conflicts"}]},{"id":"food","text":"Lunch is provided; let me know about any food needs.","fine":"Invites people to share dietary needs.","bad":[{"id":"food-ignore","level":"beginner","text":"Lunch is pizza for everyone; no other options.","why":"Not asking about food needs can leave some teammates unable to eat.","principle":"div.doc-ignores-food-needs"}]},{"id":"roles","text":"Tell me which part of the project you would like to take on.","fine":"Lets people choose roles.","bad":[{"id":"roles-assigned","level":"advanced","needs":["what"],"text":"I have already given the heavy lifting to the guys and the decorating to everyone else.","why":"Assigning work by gender is a stereotype. People should choose roles based on their skills and preferences.","principle":"div.doc-gender-based-roles"}]},{"id":"tone","text":"Everyone's ideas are welcome.","fine":"A welcoming close.","bad":[{"id":"tone-normal","level":"beginner","text":"Please keep your ideas normal so we do not waste time.","why":"Calling some ideas not normal discourages people with different perspectives from speaking up.","principle":"div.doc-discourages-different-ideas"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","no-stereotypes"],"notes":"Defects name stereotyped behavior only so students can identify it; no group is characterized."}},{"id":"div-serving-everyone","skill":"respect-for-diversity","family":"respect-for-diversity.cx-serving-everyone","familyName":"Serving people with different needs","framework":"safest-action","concepts":["respect-for-diversity:individual-differences","respect-for-diversity:valuing-differences","respect-for-diversity:own-bias"],"contexts":"any","requires":["area"],"setup":["You work as {role|a} at {workplace|a}, and you are the first person {client.plural} see when they come in.","As {role|a} at {workplace|a}, you are helping {client.plural} at the front of the {area}."],"pressure":["Several more {client.plural} are waiting.","{coworker3} says to keep things moving fast."],"detail":["It is a busy morning.","The {area} was just cleaned."],"tiers":{"1":"A barrier that could hurt someone or keep them out comes first.","2":"Communication has to work before service can.","3":"Choices should be offered, not assumed.","4":"Small courtesies, like a name said right, follow the bigger needs.","5":"A disrespectful comment from a coworker can be addressed once the {client} is served."},"issues":[{"id":"ramp","tier":1,"rule":"remove-barrier","principle":"div.clear-access-route","fact":["A {client} who uses a cane is waiting outside because boxes are blocking the ramp."],"short":"the blocked ramp","action":"Clear the boxes off the ramp right away and offer the {client} help coming in.","brief":"clear the ramp and offer help","reason":"A blocked ramp keeps the {client} out and could cause a fall. Clearing it fixes both problems.","lesson":"Keep access routes clear so everyone can get in safely.","shortcut":[{"text":"Tell the {client} to come in through the side door with the steps.","brief":"send the {client} to the stepped door","why":"Steps are harder for someone with a cane. The ramp exists so everyone has a safe way in.","mis":"Any entrance is as good as another."}]},{"id":"language","tier":2,"rule":"adapt-communication","principle":"div.use-interpretation-line","fact":["A {client} speaks limited English and looks confused, and {workplace|the} has a phone interpretation line."],"short":"the language barrier","action":"Offer the phone interpretation line so the {client} can be served clearly.","brief":"offer the interpretation line","reason":"The interpretation line lets the {client} understand and be understood. Using it shows respect and prevents mistakes.","lesson":"Use the tools available to communicate clearly with people who speak other languages.","shortcut":[{"text":"Repeat your explanation more loudly and slowly.","brief":"repeat it louder and slower","why":"Volume does not overcome a language barrier and can feel disrespectful.","mis":"Speaking louder helps people understand another language."}],"clear":["The interpretation line is already connected, and the {client} is following along."],"done":"the interpretation line is already connected"},{"id":"assume","tier":3,"rule":"ask-dont-assume","principle":"div.offer-choice-not-assumption","fact":["You notice you were about to steer an older {client} away from the self-service screen without asking."],"short":"your assumption about the {client}","action":"Offer both the screen and in-person help, and let the {client} choose.","brief":"offer both options and let them choose","reason":"Assuming what someone can do because of their age is a bias. Offering choices treats them as an individual.","lesson":"Offer choices instead of deciding for people based on assumptions.","shortcut":[{"text":"Handle everything for the {client}, since that is probably easier for them.","brief":"handle everything for them","why":"Deciding for someone based on age is the assumption to avoid.","mis":"Helping without asking is always kind."}]},{"id":"name","tier":4,"rule":"show-courtesy","principle":"div.ask-name-pronunciation","noProceed":true,"fact":["You are not sure how to pronounce the {client}'s name on the paperwork."],"short":"the name you are unsure how to say","action":"Politely ask the {client} how to say their name.","brief":"ask how to say the name","reason":"Asking shows respect. Guessing or avoiding the name can feel dismissive.","lesson":"When unsure how to say someone's name, ask politely.","shortcut":[{"text":"Avoid using the {client}'s name at all so you do not get it wrong.","brief":"avoid saying the name","why":"Avoiding someone's name can feel cold. A polite question solves the problem.","mis":"Avoiding a name is more respectful than asking."}]},{"id":"comment","tier":5,"rule":"address-disrespect","principle":"div.address-coworker-mockery","fact":["Once the {client} leaves, {coworker3} imitates the {client}'s accent."],"short":"{coworker3}'s mocking comment","action":"Tell {coworker3} privately that mocking how someone speaks is not okay.","brief":"tell {coworker3} privately it is not okay","reason":"Mocking {client.plural} creates a disrespectful workplace even when they are not present. A private word addresses it directly.","lesson":"Speak up about disrespect toward the people you serve, even when they are not present.","shortcut":[{"text":"Ignore it, since the {client} did not hear the comment.","brief":"ignore it since the {client} left","why":"Disrespect is not acceptable just because the target cannot hear it. It shapes how the team treats people.","mis":"A comment is harmless if the person never hears it."}],"onlyLevels":["beginner"]}],"proceed":{"text":"Help the {client} the way you would help anyone, and complete the visit.","why":"Nothing stands in the way of good service here, so helping the {client} as usual is right.","lesson":"Respect shows in consistent, attentive service for every person."},"generic":[{"text":"Ask {coworker2} to take over this {client} because the visit feels awkward.","why":"Handing off someone because of a difference in need or background treats them unequally.","mis":"Passing someone to a coworker avoids problems."},{"text":"Rush through the visit so the waiting {client.plural} do not get upset.","why":"Rushing one person because others are waiting gives them worse service.","mis":"Speed matters more than each person's experience."}],"process":{"setup":["You are {role|a} at {workplace|a}, helping a {client} at the front of the {area}."],"because":{"ramp":["Boxes have been left on the ramp to the entrance."],"language":["The {client} you are helping speaks limited English."]},"steps":[{"id":"clear","text":"Move the boxes off the ramp","issue":"ramp"},{"id":"greet","text":"Greet the {client} and ask how you can help","core":true},{"id":"line","text":"Connect to the interpretation line","issue":"language"},{"id":"help","text":"Help with the request","core":true},{"id":"confirm","text":"Confirm the {client} has what they need","core":true}],"rel":[["clear","greet","The {client} needs to be able to get in first."],["greet","line","Greeting first shows you are there to help, then you bring in the interpreter."],["line","help","The request has to be understood before you can help with it."],["greet","help","You find out the request before helping."],["help","confirm","You confirm after helping."]],"alternatesReviewed":true,"lesson":"Remove barriers, communicate in a way that works, help, and confirm."},"review":{"status":"approved","checks":["no-jurisdiction-claims","no-stereotypes"],"notes":"Interpretation line stated as a workplace resource. Age assumption is framed as the student's own bias to check."}},{"id":"tea-team-project","skill":"teamwork","family":"teamwork.cx-team-project-roles","familyName":"Getting a team project organized","framework":"process-dependency","concepts":["teamwork:expectations-roles-goals","teamwork:team-communication","teamwork:respect-contributions"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. You and three coworkers have two weeks to update {document|the} for the whole team.","As {role|a} at {workplace|a}, you are one of four people assigned to update {document|the} together."],"pressure":["{coworker3} says it will be faster if everyone just starts on something.","The first week is almost over."],"detail":["The team meets on Tuesdays.","The project has its own shared folder."],"tiers":{"1":"A team cannot work toward a goal it has not defined.","2":"Clear roles prevent wasted and missing work.","3":"Duplicate work should be sorted out as soon as it is found.","4":"A teammate falling behind needs a supportive check-in.","5":"Recognizing contributions keeps a team motivated."},"issues":[{"id":"goal","tier":1,"rule":"clarify-goal","principle":"tea.define-shared-goal","fact":["The team is not sure what the finished {document} needs to include."],"clear":["{Lead|the} gave the team a written list of what the finished {document} must include."],"done":"the team already has a written list of requirements","short":"the unclear goal","action":"Suggest asking {lead|the} for a clear list of what the finished work must include.","brief":"ask {lead|the} what the finished work must include","reason":"A team that is unsure of the goal may build the wrong thing. A clear list keeps everyone aimed at the same result.","lesson":"Make sure the team agrees on the goal before dividing up the work.","shortcut":[{"text":"Let each person decide what the {document} should include.","brief":"let each person decide","why":"Four separate ideas of the goal produce work that does not fit together.","mis":"Everyone will naturally aim for the same result."}]},{"id":"roles","tier":2,"rule":"agree-roles","principle":"tea.assign-clear-roles","fact":["Nobody has agreed who is doing which part."],"clear":["The team already wrote down who is doing each part."],"done":"roles were already written down","short":"the undecided roles","action":"Suggest the team agree on who does each part and write it down.","brief":"agree on and write down roles","reason":"Without agreed roles, some parts get done twice and others not at all.","lesson":"Agree on roles and write them down so every part has an owner.","shortcut":[{"text":"Start on whichever part looks most interesting to you.","brief":"start on the most interesting part","why":"Picking your favorite part without agreement risks duplicate or missing work.","mis":"Interest is a good way to split up work."}]},{"id":"overlap","tier":3,"rule":"communicate-overlap","principle":"tea.resolve-duplicate-work","fact":["You discover that {coworker} has been working on the same section as you."],"short":"the duplicated section","action":"Tell {coworker} right away and agree on who keeps that section.","brief":"agree with {coworker} on who keeps it","reason":"Duplicate work wastes effort. Sorting it out quickly frees one of you for another part.","lesson":"Raise overlapping work right away so the team can rebalance.","shortcut":[{"text":"Keep going so your version is the better one.","brief":"race to finish your version","why":"Competing on the same section wastes both people's time and creates friction.","mis":"Competition produces the best work on a team."}]},{"id":"behind","tier":4,"rule":"support-teammate","principle":"tea.check-in-with-teammate","fact":["{coworker2} has not started a part that two other people are waiting on."],"short":"{coworker2}'s unstarted part","action":"Check in with {coworker2} privately to ask how it is going and whether help is needed.","brief":"check in with {coworker2} and offer help","reason":"{coworker2} may be stuck or overloaded. A supportive check-in solves the problem without blame.","lesson":"When a teammate is behind, check in and offer help before assuming the worst.","shortcut":[{"text":"Complain to the rest of the team that {coworker2} is slowing everyone down.","brief":"complain about {coworker2}","why":"Complaining behind someone's back damages trust and does not get the part started.","mis":"Pointing out a slow teammate fixes the delay."}]},{"id":"credit","tier":5,"rule":"recognize-contribution","principle":"tea.recognize-teammate-idea","noProceed":true,"fact":["{coworker3}'s suggestion is what made the plan work, but nobody has said so."],"short":"{coworker3}'s unrecognized idea","action":"Point out {coworker3}'s contribution when the team next meets.","brief":"credit {coworker3} at the next meeting","reason":"Recognizing contributions shows respect and encourages people to keep offering ideas.","lesson":"Recognize teammates' contributions openly.","shortcut":[{"text":"Leave it unsaid, since good ideas are just part of the job.","brief":"leave it unsaid","why":"Unrecognized contributions discourage people from sharing ideas.","mis":"Recognition is unnecessary on a team."}]}],"proceed":{"text":"Keep working on your part and share progress at the next team meeting.","why":"The goal and roles are clear, so steady work on your part and regular updates are what the team needs.","lesson":"Once goals and roles are clear, do your part and keep the team informed."},"generic":[{"text":"Do the whole project yourself to make sure it is done right.","why":"Taking over shuts teammates out and is not sustainable.","mis":"The best way to ensure quality is to do it all yourself."},{"text":"Wait for {lead|the} to notice any problems with the team.","why":"Team members share responsibility for raising problems.","mis":"Only a supervisor should deal with team problems."}],"overcaution":[{"text":"Call an extra meeting to review the roles again.","why":"The roles are already written down. Another meeting takes time from the work.","mis":"More meetings make a team work better."}],"process":{"setup":["You are part of a four-person team at {workplace|the} updating {document|the}."],"because":{"goal":["The team is unsure what the finished work should contain."],"behind":["One part that others depend on has not been started."]},"steps":[{"id":"goal","text":"Get a clear list of requirements from {lead|the}","issue":"goal"},{"id":"roles","text":"Agree on who does each part","core":true},{"id":"work","text":"Work on the parts","core":true},{"id":"checkin","text":"Check in with anyone who is stuck","issue":"behind"},{"id":"combine","text":"Combine the parts and review them together","core":true}],"rel":[["goal","roles","You divide work once you know what the whole needs."],["roles","work","Everyone needs a role before starting."],["work","checkin","Check-ins happen while the work is in progress."],["checkin","combine","Every part has to be done before combining."],["work","combine","Parts are combined after they are done."]],"alternatesReviewed":true,"lesson":"Define the goal, assign roles, support each other through the work, then combine."},"doc":{"type":"chat","title":["Team chat: {document} project"],"intro":["You are reviewing the team's planning chat before the next meeting."],"lesson":"Good team communication sets clear roles and deadlines, and treats everyone's work with respect.","lines":[{"id":"goal","text":"{coworker}: Here is the list from {lead|the} of what the {document} must include.","fine":"Shares the goal with the team."},{"id":"roles","text":"{coworker2}: I will take sections 1 and 2; you take 3, and {coworker3} takes 4.","fine":"Clear roles with an owner for each section.","bad":[{"id":"roles-vague","level":"beginner","text":"{coworker2}: Let us all just work on whatever and see how it turns out.","why":"Without roles, work gets duplicated or missed.","principle":"tea.doc-no-roles"}]},{"id":"due","text":"{coworker3}: Drafts due Thursday so we have Friday to combine.","fine":"A shared deadline with time to combine."},{"id":"help","text":"{coworker}: If anyone gets stuck, post here and someone will help.","fine":"Invites people to ask for help.","bad":[{"id":"help-alone","level":"beginner","text":"{coworker}: If you get stuck, figure it out yourself.","why":"Discouraging requests for help leaves teammates stuck and slows the team.","principle":"tea.doc-discourages-help"}]},{"id":"feedback","text":"{coworker2}: Section 4 is solid; one table could use a heading.","fine":"Specific, respectful feedback.","bad":[{"id":"feedback-harsh","level":"intermediate","text":"{coworker2}: Section 4 is useless, so I am rewriting it myself.","why":"Dismissing a teammate's work and taking it over is disrespectful and damages the team.","principle":"tea.doc-dismisses-teammate-work"}]},{"id":"late","text":"{coworker3}: I will have section 4 done by Thursday as planned.","fine":"Confirms the agreed deadline.","bad":[{"id":"late-silent","level":"advanced","needs":["due"],"text":"{coworker3}: I will start section 4 sometime next week.","why":"Drafts are due Thursday. Starting next week breaks the team's plan without discussing it.","principle":"tea.doc-ignores-shared-deadline"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Team roles and communication."}},{"id":"tea-short-staffed","skill":"teamwork","family":"teamwork.cx-covering-for-absence","familyName":"Covering when the team is short-staffed","framework":"competing-priorities","concepts":["teamwork:share-responsibility","teamwork:team-communication","teamwork:respect-contributions"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}. A coworker called out sick, and the team is covering the extra work.","As {role|a} at {workplace|a}, you are working a shift where the team is one person short."],"pressure":["{coworker3} says everyone should just look after their own work today.","It is a busier day than usual."],"detail":["The absent coworker usually works the morning shift.","{Lead|the} is in the office."],"tiers":{"1":"A task that needs two people for safety cannot be done alone.","2":"Work that nobody owns needs an owner right away.","3":"You need to know where the work stands before picking it up.","4":"Frustration about staffing is best channeled toward a fix.","5":"Thanking teammates matters once the work is covered."},"issues":[{"id":"twoperson","tier":1,"rule":"control-hazard-first","principle":"tea.no-solo-two-person-task","fact":["A task the posted procedure says needs two people is due, and only you are free."],"short":"the two-person task","action":"Hold off on the two-person task until someone can help, and tell {lead|the}.","brief":"wait for a second person and tell {lead|the}","reason":"The procedure requires two people for safety. Telling the lead lets them find a second person.","lesson":"Never do a two-person task alone to cover a gap; get help instead.","shortcut":[{"text":"Do the two-person task alone, carefully, since everyone else is busy.","brief":"do it alone carefully","why":"Being careful does not replace the second person the procedure requires.","mis":"Being short-staffed justifies skipping safety rules."}]},{"id":"dropped","tier":2,"rule":"take-ownership","principle":"tea.claim-uncovered-task","fact":["Nobody has picked up {task|the}, which the absent coworker usually does."],"clear":["{coworker} already took on {task|the} for today."],"done":"{coworker} already took on the task","short":"the uncovered task","action":"Offer to take {task|the} and tell the team so nobody doubles up.","brief":"take on the task and tell the team","reason":"Shared responsibility means someone steps up. Telling the team prevents two people doing it.","lesson":"When work is left uncovered, offer to own it and tell the team.","shortcut":[{"text":"Assume someone else will notice it and pick it up.","brief":"assume someone else will do it","why":"When everyone assumes someone else will do it, nobody does.","mis":"Uncovered work will get picked up by someone."}]},{"id":"handoff","tier":3,"rule":"get-status-first","principle":"tea.check-where-work-stands","fact":["You do not know where the absent coworker left off on an open order."],"clear":["The absent coworker left detailed handoff notes on the open order."],"done":"the handoff notes already explain where things stand","short":"not knowing where the order stands","action":"Check the handoff log or ask {lead|the} where the order stands.","brief":"check where the order stands","reason":"Starting without knowing the status risks redoing or skipping steps.","lesson":"Find out where shared work stands before you pick it up.","shortcut":[{"text":"Start the order over from the beginning to be safe.","brief":"start the order over","why":"Restarting may duplicate finished steps and waste materials.","mis":"Starting over is always the safe choice."}]},{"id":"grumble","tier":4,"rule":"channel-frustration","principle":"tea.constructive-response-to-complaint","noProceed":true,"fact":["{coworker2} complains loudly that the team always gets stuck covering."],"short":"{coworker2}'s frustration","action":"Acknowledge the frustration and suggest raising staffing with {lead|the} later.","brief":"acknowledge it and suggest raising it later","reason":"The frustration may be fair. Pointing it toward a real conversation helps more than arguing or piling on.","lesson":"Respond to team frustration by acknowledging it and steering toward a fix.","shortcut":[{"text":"Join in the complaining so {coworker2} knows you agree.","brief":"join in the complaining","why":"Piling on lowers morale and does not change staffing.","mis":"Agreeing with complaints builds team spirit."}]},{"id":"thanks","tier":5,"rule":"recognize-contribution","principle":"tea.thank-teammate-who-covered","noProceed":true,"fact":["{coworker3} stayed late yesterday so the team could finish."],"short":"{coworker3}'s extra effort","action":"Thank {coworker3} for staying late to help the team.","brief":"thank {coworker3} for staying late","reason":"Thanking teammates for extra effort shows respect and keeps people willing to help.","lesson":"Notice and thank teammates who go beyond their share.","shortcut":[{"text":"Say nothing, since covering is just part of the job.","brief":"say nothing about it","why":"Unacknowledged extra effort can leave teammates feeling taken for granted.","mis":"Thanks are unnecessary for expected work."}]}],"proceed":{"text":"Pitch in on the shared work and keep the team updated on what you are covering.","why":"The work is covered and nothing else needs handling, so pitching in and communicating is the teamwork the day needs.","lesson":"On short-staffed days, pitch in and keep everyone informed."},"generic":[{"text":"Do only your usual tasks, since the extra work is not your job.","why":"Team members share responsibility when someone is out.","mis":"You are only responsible for your own tasks."},{"text":"Take a long break, since the day is already behind.","why":"Disappearing on a short-staffed day puts more on everyone else.","mis":"If the day is behind anyway, a long break does not matter."}],"overcaution":[{"text":"Ask {lead|the} to assign every single task before you do anything.","why":"The work is already covered. Waiting for full assignments wastes time.","mis":"Nothing should be done without a supervisor's assignment."}],"process":{"setup":["Your team at {workplace|the} is one person short today."],"because":{"dropped":["One of the absent coworker's tasks has no owner today."],"handoff":["The absent coworker's open order is partly done."]},"steps":[{"id":"huddle","text":"Meet briefly with the team to split up the work","core":true},{"id":"claim","text":"Claim the uncovered task","issue":"dropped"},{"id":"status","text":"Find out where the open order stands","issue":"handoff"},{"id":"work","text":"Work through your share","core":true},{"id":"update","text":"Update the team at the end of the shift","core":true}],"rel":[["huddle","claim","Claiming happens as the team splits the work."],["claim","work","You claim the task before working on it."],["status","work","You need the status before continuing the order."],["huddle","work","The team splits work before starting."],["work","update","The update reports what was done."]],"alternatesReviewed":true,"lesson":"Split the work, claim what is uncovered, find where things stand, then update the team."},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Two-person requirement stated as a posted procedure."}},{"id":"wet-shift-commitments","skill":"work-ethic","family":"work-ethic.cx-shift-commitments","familyName":"Keeping commitments on a difficult morning","framework":"competing-priorities","concepts":["work-ethic:dependability","work-ethic:accountability","work-ethic:accepting-consequences"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}, and your shift starts at 8 a.m.","You are {role|a} at {workplace|a}. It is 7:30 a.m., and your shift starts at 8."],"pressure":["{coworker3} texts that the morning is going to be busy.","You know the team is short-staffed today."],"detail":["It is a Monday.","You packed your lunch the night before."],"tiers":{"1":"Your health and the health of others come first.","2":"The team needs to know about a delay before the shift starts.","3":"A missed commitment needs a new, realistic plan right away.","4":"Repairing trust with a coworker you affected comes before discussing your own consequence.","5":"Accepting a consequence well comes after the day's commitments are handled."},"issues":[{"id":"sick","tier":1,"rule":"follow-call-out-policy","principle":"wet.call-out-when-sick","onlyLevels":["beginner"],"fact":["You woke up with a fever, and the call-out policy says to call {lead|the} at least an hour before your shift."],"short":"your fever","action":"Call {lead|the} now, as the policy says, and stay home to recover.","reason":"Calling in early, as the policy asks, gives the lead time to find coverage, and staying home protects your coworkers.","lesson":"When you are sick, follow the call-out policy early so the team can plan.","shortcut":[{"text":"Come in anyway so nobody thinks you are unreliable.","why":"Working with a fever can spread illness and lower the quality of your work. Following the policy is the dependable choice.","mis":"Showing up no matter what is always the dependable choice."}]},{"id":"late","tier":2,"rule":"communicate-delay-early","principle":"wet.warn-before-being-late","fact":["A traffic jam means you will reach work about 20 minutes after your shift starts."],"clear":["You already called {lead|the} to say you will be 20 minutes late."],"done":"you already let {lead|the} know you will be late","short":"your late arrival","action":"Let {lead|the} know right away that you will be about 20 minutes late.","brief":"tell {lead|the} you will be 20 minutes late","reason":"A quick warning lets the lead cover your duties until you arrive. Dependable people communicate before a problem, not after.","lesson":"If you will be late, tell your supervisor before your shift starts.","shortcut":[{"text":"Drive faster and hope to arrive close to on time.","brief":"drive faster and hope","why":"Rushing adds risk and may still leave you late with no warning given.","mis":"Making up time is better than admitting you will be late."}]},{"id":"overdue","tier":3,"rule":"renew-missed-commitment","principle":"wet.own-overdue-task","fact":["The report you promised {lead|the} by yesterday afternoon is still not finished."],"short":"the overdue report","action":"Tell {lead|the} the report is not done and give a realistic finish time.","brief":"tell {lead|the} it is late and give a finish time","reason":"Admitting the miss and giving a realistic new time lets the lead plan. Silence leaves them guessing.","lesson":"When you miss a commitment, say so and set a realistic new one.","shortcut":[{"text":"Wait until {lead|the} asks about the report before mentioning it.","brief":"wait until {lead|the} asks about it","why":"Waiting to be asked hides the problem and makes it look like you hoped nobody would notice.","mis":"If nobody asks, a missed deadline does not need mentioning."}]},{"id":"mistake","tier":4,"rule":"own-mistake","principle":"wet.own-error-that-affected-coworker","fact":["An error you made yesterday caused {coworker} an hour of extra work this morning."],"clear":["You already apologized to {coworker} for yesterday's error."],"done":"you already apologized to {coworker}","short":"your error that cost {coworker} time","action":"Own the error, apologize to {coworker}, and explain how you will prevent it.","brief":"own the error and apologize to {coworker}","reason":"Taking responsibility repairs trust, and a prevention plan shows the error will not repeat.","lesson":"Own your mistakes openly and show how you will prevent them.","shortcut":[{"text":"Say nothing, since {coworker} already fixed it.","brief":"say nothing about the error","why":"Staying quiet leaves your coworker feeling taken for granted and leaves the cause unaddressed.","mis":"Once a mistake is fixed, it is best not to bring it up."}]},{"id":"consequence","tier":5,"rule":"accept-consequence","principle":"wet.accept-consequence-constructively","noProceed":true,"fact":["{Lead|the} told you that because of a late report last week, you will cover this Saturday's shift."],"short":"the Saturday shift you were assigned","action":"Accept the Saturday shift and ask how to avoid the same problem in future.","brief":"accept Saturday and ask how to do better","reason":"Accepting a fair consequence without argument shows maturity, and asking how to improve turns it into progress.","lesson":"Accept fair consequences calmly and use them to improve.","shortcut":[{"text":"Argue that the late report was not really your fault.","brief":"argue it was not your fault","why":"Arguing about a consequence for a real lapse damages trust. Accepting it and improving builds it back.","mis":"Arguing a consequence shows you care about fairness."}]}],"proceed":{"text":"Start your shift as planned and work through your task list.","why":"Nothing in the situation needs extra attention, so the dependable move is to start on time and get to work.","lesson":"Dependability is mostly showing up ready and doing the work as planned."},"generic":[{"text":"Blame the busy schedule when {lead|the} asks about any problems.","why":"Blaming circumstances avoids responsibility and does not fix anything.","mis":"Explaining a problem away is the same as dealing with it."},{"text":"Take an extra-long break later to make up for the stressful morning.","why":"A stressful morning does not change your schedule. Extra break time leaves the team short.","mis":"A hard morning earns extra time off."}],"overcaution":[{"text":"Call {lead|the} to confirm your schedule again before you leave home.","why":"Nothing in the situation calls for a check-in. Calling to confirm a known schedule takes the lead's time for no reason.","mis":"Checking in more always shows dependability."}],"process":{"setup":["You are {role|a} at {workplace|a}, getting ready for a shift that starts at 8 a.m."],"because":{"late":["You realize you will not make it in time for the start of your shift."],"overdue":["A report you promised {lead|the} is past due."],"mistake":["Your error yesterday made extra work for {coworker}."]},"steps":[{"id":"call","text":"Call {lead|the} about arriving late","issue":"late"},{"id":"arrive","text":"Arrive and clock in","core":true},{"id":"list","text":"Review today's task list","core":true},{"id":"apologize","text":"Apologize to {coworker} in person","issue":"mistake"},{"id":"renew","text":"Give {lead|the} a new report deadline","issue":"overdue"},{"id":"start","text":"Start the first task","core":true}],"rel":[["call","arrive","The warning only helps if it comes before you arrive late."],["arrive","list","You review the list once you are at work."],["arrive","apologize","An in-person apology happens once you are there."],["list","renew","Looking at the day's tasks shows when the report can realistically be finished."],["renew","start","The lead should know the new deadline before you dive into other work."],["list","start","You need to know the day's tasks before starting them."]],"alternatesReviewed":true,"lesson":"Communicate early, show up, plan the day, and repair any missed commitments."},"doc":{"type":"email","title":["Your message to {lead|the}"],"intro":["You are about to email {lead|the} about the overdue report. Check the message first."],"lesson":"Accountable messages admit the problem, avoid excuses and blame, and give a realistic plan.","lines":[{"id":"admit","text":"I did not finish the report by yesterday afternoon as I promised.","fine":"Admits the missed commitment plainly.","bad":[{"id":"admit-blame","level":"beginner","text":"The report is late because {coworker} never sent me the numbers on time.","why":"Blaming a coworker avoids responsibility, especially when the commitment was yours.","principle":"wet.doc-blames-coworker"}]},{"id":"why","text":"I underestimated how long the second section would take.","fine":"Gives an honest reason without excuses."},{"id":"plan","text":"I will have it to you by 2 p.m. today.","fine":"A specific, realistic new deadline.","bad":[{"id":"plan-vague","level":"intermediate","text":"I will try to get it to you sometime soon.","why":"A vague promise does not let the lead plan. A specific, realistic time is needed.","principle":"wet.doc-vague-new-deadline"}]},{"id":"hours","text":"I have two hours free this morning to work on it.","fine":"Shows the new deadline is realistic."},{"id":"unrealistic","text":"That leaves time to check it before I send it.","fine":"Plans for quality, not just speed.","bad":[{"id":"unrealistic-rush","level":"advanced","needs":["hours","plan"],"text":"I will finish all of it in the next 20 minutes, and you can have it by 8:30.","why":"The message says the work needs about two hours and promises 2 p.m. A 20-minute promise contradicts both and will likely be missed.","principle":"wet.doc-unrealistic-promise"}]},{"id":"prevent","text":"Next time I will check in with you as soon as I see a deadline slipping.","fine":"Explains how the problem will be prevented.","bad":[{"id":"prevent-none","level":"beginner","text":"These things happen, so I would not worry about it.","why":"Brushing off a missed commitment suggests it will happen again. A prevention plan shows accountability.","principle":"wet.doc-dismisses-problem"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Call-out timing is stated as workplace policy. Sick state is beginner-only because it replaces the rest of the day."}},{"id":"wet-quality-under-pressure","skill":"work-ethic","family":"work-ethic.cx-quality-under-pressure","familyName":"Keeping quality up on repetitive work","framework":"consequences","concepts":["work-ethic:diligence","work-ethic:accountability"],"contexts":"any","setup":["You work as {role|a} at {workplace|a}, finishing a large batch of similar work today. Each piece needs a final check.","As {role|a} at {workplace|a}, you are working through a long, repetitive batch, and each piece must be checked before it moves on."],"pressure":["{coworker3} says nobody ever looks closely at this work anyway.","The daily target is posted on the board."],"detail":["You are about halfway through the batch.","The work area is quiet this afternoon."],"tiers":{"1":"A required check is part of the job, not an optional extra.","2":"Work you know is flawed must not move on.","3":"You cannot check against a standard you are unsure about.","4":"A missed target should be explained, not hidden by rushing.","5":"Managing your focus matters, but not ahead of real quality problems."},"issues":[{"id":"skip","tier":1,"rule":"keep-required-step","principle":"wet.keep-final-check","noProceed":true,"fact":["{coworker} shows you how to skip the final check to finish the batch much faster."],"short":"the shortcut that skips the final check","action":"Keep doing the final check on every piece, as the procedure requires.","brief":"keep checking every piece","reason":"The check is there because errors happen. Skipping it puts the quality of the whole batch at risk.","lesson":"Diligence means doing every required step, even when a shortcut is offered.","shortcut":[{"text":"Skip the check on the simple pieces to save time.","brief":"skip the check on simple pieces","why":"Simple pieces can still have errors. The procedure requires the check on every piece.","mis":"Easy work does not need checking."}]},{"id":"flaw","tier":2,"rule":"stop-wrong-work","principle":"wet.hold-flawed-work","fact":["You discover that several pieces you finished earlier all have the same flaw."],"short":"the flawed pieces","action":"Set the flawed pieces aside, fix them, and tell {lead|the} what happened.","brief":"set aside and fix the flawed pieces","reason":"Holding back flawed work protects the next person in line, and telling the lead lets them check for a wider problem.","lesson":"When you find flaws in your own work, stop them, fix them and say so.","shortcut":[{"text":"Send the pieces along, since the next person will probably catch it.","brief":"send them along anyway","why":"Passing on work you know is flawed shifts your responsibility to someone else and risks it reaching a {client}.","mis":"Someone further along will catch the problem."}]},{"id":"standard","tier":3,"rule":"clarify-standard","principle":"wet.clarify-quality-standard","fact":["You are not sure whether a small scratch counts as a defect."],"clear":["{Lead|the} showed you this morning exactly which scratches count as defects."],"done":"you were already shown the standard for scratches","short":"the unclear scratch standard","action":"Ask {lead|the} what the standard is for small scratches.","brief":"ask {lead|the} about the scratch standard","reason":"You cannot check work properly against a standard you are unsure of. A quick question makes every check reliable.","lesson":"Know the quality standard before you judge your work against it.","shortcut":[{"text":"Decide for yourself that small scratches do not matter.","brief":"decide scratches do not matter","why":"Guessing at the standard may let defects through or waste good pieces. The lead can tell you.","mis":"Your own judgment is the standard."}]},{"id":"behind","tier":4,"rule":"communicate-delay-early","principle":"wet.explain-missed-target","fact":["You are behind the daily target because a tricky piece took extra care."],"clear":["{Lead|the} already knows you are behind and said quality comes first."],"done":"{lead|the} already knows you are behind","short":"being behind the target","action":"Tell {lead|the} you are behind and why, while keeping the quality up.","brief":"tell {lead|the} you are behind and why","reason":"The lead can adjust plans if they know. Rushing to hide the gap would trade quality for appearances.","lesson":"Explain a missed target honestly instead of rushing to hide it.","shortcut":[{"text":"Rush the rest so the count looks right by the end of the day.","brief":"rush the rest to hit the count","why":"Rushing invites errors in the remaining work. Explaining the delay is better than hiding it.","mis":"Hitting the number matters more than how the work is done."}]},{"id":"focus","tier":5,"rule":"manage-own-focus","principle":"wet.refocus-on-repetitive-work","noProceed":true,"fact":["The work is repetitive, and you notice your attention starting to drift."],"short":"your drifting attention","action":"Take your scheduled break now, then come back and refocus on each piece.","brief":"take your break and refocus","reason":"Drifting attention is when errors creep in. A scheduled break restores focus without skipping any work.","lesson":"Notice when your focus slips and use breaks to stay careful.","shortcut":[{"text":"Watch videos on your phone while you work to stay awake.","brief":"watch videos while you work","why":"Splitting attention makes errors more likely, not less.","mis":"Distractions help you get through boring work."}]}],"proceed":{"text":"Keep working steadily through the batch, checking each piece.","why":"Nothing in the situation needs attention, so steady, careful work is what the job calls for.","lesson":"Diligent work is steady, careful and complete, even when it is repetitive."},"generic":[{"text":"Ask {coworker2} to check your pieces for you while you take a break.","why":"The checks are your responsibility. Handing them off adds to a coworker's load without reason.","mis":"Responsibility for quality can be passed to whoever is free."},{"text":"Mark the batch as finished now and complete the last pieces tomorrow.","why":"Recording unfinished work as finished makes the record false.","mis":"It is fine to report work as done if you plan to finish it."}],"overcaution":[{"text":"Ask {lead|the} to inspect every piece before you continue.","why":"Nothing in the situation calls for an extra inspection. It would stall the batch and take the lead's time.","mis":"Supervisor checks are always better than your own."}],"process":{"setup":["You are {role|a} at {workplace|a}, working through a large batch where each piece is checked before it moves on."],"because":{"standard":["You are unsure what counts as a defect."],"flaw":["Some pieces from earlier turned out to share a flaw."]},"steps":[{"id":"ask","text":"Ask {lead|the} which scratches count as defects","issue":"standard"},{"id":"make","text":"Finish the next piece","core":true},{"id":"inspect","text":"Inspect the piece against the standard","core":true},{"id":"hold","text":"Pull aside any piece that fails","issue":"flaw"},{"id":"log","text":"Record the piece in the batch count","core":true}],"rel":[["ask","inspect","You need the standard before you can inspect against it."],["make","inspect","A piece is inspected once it is finished."],["inspect","hold","Only an inspection shows which pieces fail."],["hold","log","Failed pieces are pulled before the count is recorded."],["inspect","log","Only inspected pieces go into the count."]],"alternatesReviewed":true,"lesson":"Know the standard, finish, inspect, hold back failures, then record the count."},"doc":{"type":"note","title":["End-of-day batch report"],"intro":["You are about to hand {lead|the} this batch report. Check it first."],"lesson":"An accountable report is accurate about what was done, checked and held back.","lines":[{"id":"count","text":"Pieces finished: 120 of the 150 target.","fine":"States the result honestly against the target."},{"id":"checked","text":"All 120 pieces received the final check.","fine":"Confirms the required step was done.","bad":[{"id":"checked-skip","level":"beginner","text":"I skipped the final check on the simple pieces to save time.","why":"The check is required on every piece. Skipping it puts quality at risk.","principle":"wet.doc-skipped-required-check"}]},{"id":"held","text":"Six pieces had the same flaw and are set aside for rework.","fine":"Reports flawed work held back.","bad":[{"id":"held-sent","level":"beginner","text":"Six pieces had a flaw, but I sent them on, since the next station usually catches problems.","why":"Known flaws should be held back, not passed on for someone else to catch.","principle":"wet.doc-passed-on-flaws"}]},{"id":"reason","text":"I fell behind because one piece needed extra care.","fine":"Explains the shortfall honestly."},{"id":"total","text":"That leaves 114 good pieces ready to move on.","fine":"Correctly subtracts the held pieces.","bad":[{"id":"total-wrong","level":"advanced","needs":["count","held"],"text":"That leaves all 120 pieces ready to move on.","why":"Six of the 120 were set aside for rework, so only 114 are ready. The total contradicts the report.","principle":"wet.doc-total-ignores-held-pieces"}]},{"id":"tomorrow","text":"I will finish the last 30 tomorrow morning.","fine":"Gives a plan for the remaining work.","bad":[{"id":"tomorrow-done","level":"intermediate","text":"I marked the batch finished so the board looks right; the last 30 can wait.","why":"Marking unfinished work as finished makes the record false.","principle":"wet.doc-false-finished"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims"],"notes":"Diligence and accountability; numbers in the report are internally consistent (120 - 6 = 114)."}},{"id":"saf-powered-equipment","skill":"workplace-safety","family":"workplace-safety.cx-powered-equipment","familyName":"Before running powered equipment","framework":"safest-action","concepts":["workplace-safety:safety-guidelines","workplace-safety:identify-hazards"],"contexts":"any","requires":["powered","area"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asks you to use {powered|the} for the next job.","You are {role|a} at {workplace|a}, and your next job needs {powered|the}."],"pressure":["{coworker} reminds you that {client.plural} are waiting on this job.","{coworker} says the job needs to be finished within the hour."],"detail":["The {area} was swept at the start of the shift.","Most of the team is on break."],"tiers":{"1":"Anything that could shock or injure someone comes before other work.","2":"The posted rule has to be met before you operate the equipment.","3":"Running at a wrong setting can ruin the job or the equipment.","4":"Settling who uses shared equipment comes before workspace improvements."},"issues":[{"id":"cord","tier":1,"rule":"control-hazard-first","principle":"saf.damaged-electrical-equipment","fact":["The power cord on {powered|the} is frayed, and bare wire shows near the plug.","You notice bare wire showing through a frayed spot on the cord of {powered|the}."],"clear":["{Lead|the} replaced the frayed cord on {powered|the} this morning and tested it."],"done":"the cord was already replaced and tested","short":"the damaged cord","action":"Keep {powered|the} switched off, tag it out of service, and report the cord to {lead|the}.","reason":"Exposed wire can shock or burn someone. Taking the equipment out of service and reporting it controls the hazard before anyone uses it.","lesson":"Damaged electrical equipment comes out of service and gets reported before anyone uses it.","shortcut":[{"text":"Wrap the frayed spot with tape and use {powered|the} carefully for this one job.","why":"Tape is not an approved repair, and the damaged cord can still shock someone. Equipment with a damaged cord should not be used.","mis":"A quick patch makes damaged equipment safe enough for one job.","brief":"tape the frayed cord and use it carefully"},{"text":"Use {powered|the} for now and mention the cord at the end of your shift.","why":"Using it now exposes you to the hazard, and waiting to report leaves it in use for others.","mis":"A hazard can wait to be reported if the job is urgent."}],"brief":"tag out {powered|the} and report the cord"},{"id":"training","tier":2,"rule":"meet-stated-requirement","principle":"saf.trained-operators-only","fact":["You have not been trained on {powered|the}, and a posted rule says only trained staff may run it."],"clear":["You completed the required training on {powered|the} last week."],"done":"you have already completed the training","short":"the missing training","action":"Ask {lead|the} for training, or for a trained coworker to run the job, before starting.","reason":"The posted rule limits the equipment to trained staff. Getting training or a trained operator keeps you within the rule and avoids injuries from unfamiliar equipment.","lesson":"Operate equipment only after the training the workplace requires.","shortcut":[{"text":"Watch a short online video about {powered|the} and then run it yourself.","why":"A video is not the training the posted rule requires, and unfamiliar equipment is a common cause of injuries.","mis":"Watching someone else use equipment is the same as being trained.","brief":"watch a video and run it yourself"}],"brief":"ask {lead|the} for training or a trained operator"},{"id":"setting","tier":3,"rule":"verify-before-acting","principle":"saf.confirm-conflicting-setting","fact":["The job sheet lists a setting higher than the maximum printed on {powered|the}."],"clear":["{Lead|the} rechecked the job sheet setting this morning and confirmed it is within the limit."],"done":"the setting was already confirmed","short":"the conflicting setting","action":"Check with {lead|the} which setting is correct before you begin.","reason":"The two numbers conflict, and running above the printed limit could damage the equipment or the work. Confirming the right setting first prevents that.","lesson":"When instructions and equipment limits disagree, confirm before you run anything.","shortcut":[{"text":"Use the higher setting from the job sheet, since it is the newest instruction.","why":"The equipment's printed maximum is a limit, not a suggestion. Going over it can cause damage or injury.","mis":"The newest instruction always overrides equipment limits.","brief":"use the higher job-sheet setting"}],"brief":"confirm the correct setting with {lead|the}"},{"id":"shared","tier":4,"rule":"coordinate-shared-resource","principle":"saf.coordinate-shared-equipment","fact":["{coworker} also needs {powered|the} this afternoon for a rush job."],"short":"the scheduling conflict with {coworker}","action":"Talk with {coworker} and {lead|the} to agree on who uses {powered|the} first.","reason":"Two people need the same equipment. Agreeing on the order with the lead avoids a rushed handoff and keeps the most urgent job moving.","lesson":"Settle conflicts over shared equipment by agreeing on the order, not by racing for it.","shortcut":[{"text":"Start using {powered|the} right away so you get it before {coworker} does.","why":"Racing for shared equipment leads to rushed work and friction, and it may delay the more urgent job.","mis":"Whoever starts first should get shared equipment.","brief":"start right away to beat {coworker} to it"}],"brief":"agree with {coworker} on who goes","clear":["{coworker} already agreed that you can use {powered|the} first today."],"done":"the order of use was already agreed"},{"id":"layout","tier":5,"rule":"suggest-improvement-after","principle":"saf.suggest-safer-layout","fact":["Getting ready for {powered|the} takes extra trips, because its supplies are stored across the {area}."],"short":"the awkward supply layout","action":"Finish the job as usual, then suggest storing the supplies closer to {powered|the}.","reason":"The layout wastes time but does not stop safe work today. Suggesting the change afterward improves things without disrupting the job.","lesson":"Note small improvements and suggest them once the current work is done.","shortcut":[{"text":"Rearrange the whole {area} yourself before starting the job.","why":"Moving everything without asking delays today's job and may disrupt how others work. Suggest the change instead.","mis":"Fixing the workspace on your own is better than suggesting it.","brief":"rearrange the whole {area} yourself"}],"brief":"finish the job and suggest moving the supplies","noProceed":true}],"proceed":{"text":"Start the job with {powered|the}, following the usual operating steps.","why":"Nothing in the situation blocks the work, and the required conditions are met. Starting now keeps the job on schedule.","lesson":"When the equipment, training and instructions all check out, go ahead and work as trained."},"generic":[{"text":"Leave the job for the next shift without telling {lead|the} why.","why":"Leaving work undone without an explanation hands the job, and any problem, to someone who does not know about it.","mis":"Work you are unsure about can be left for someone else."},{"text":"Skip the pre-use check, since {powered|the} worked fine yesterday.","why":"Damage can happen at any time. The pre-use check is how you catch it before someone is hurt.","mis":"Equipment that worked yesterday is safe today."}],"overcaution":[{"text":"Wait for {lead|the} to inspect {powered|the} personally before you touch it.","why":"Nothing in the situation calls for another inspection, so waiting only holds up work that is ready to go.","mis":"Waiting for a supervisor is always the safest choice."}],"process":{"setup":["You are {role|a} at {workplace|a}. {Lead|the} asks you to complete a job on {powered|the} today."],"steps":[{"id":"inspect","text":"Check {powered|the} for damage"},{"id":"train","text":"Complete training on {powered|the}","issue":"training"},{"id":"confirm","text":"Confirm the correct setting with {lead|the}","issue":"setting"},{"id":"agree","text":"Agree with {coworker} on who goes first","issue":"shared"},{"id":"run","text":"Run the job","core":true},{"id":"clean","text":"Switch off and clean up the work area","core":true}],"rel":[["train","inspect","Training is where you learn what a proper check looks like."],["inspect","run","Damage has to be found before the equipment is used, not after."],["train","run","The posted rule requires training before anyone operates it."],["confirm","run","The setting must be settled before the job starts."],["agree","run","You need to know it is your turn before starting."],["run","clean","Clean-up happens once the equipment is switched off after the job."]],"alternatesReviewed":true,"lesson":"Get trained, checked and cleared before running equipment, and clean up after it is switched off."},"doc":{"type":"procedure","title":["Posted rules for {powered|the}"],"intro":["{Lead|the} asks you to review the posted rules for {powered|the} before they are reprinted."],"lesson":"Equipment rules work only when every line keeps people away from live hazards.","lines":[{"id":"who","text":"Only staff who have been trained on {powered|the} may operate it.","fine":"Limiting equipment to trained staff is a standard safety rule.","bad":[{"id":"who-anyone","level":"intermediate","text":"Anyone who has seen {powered|the} used may operate it.","why":"Watching is not training; only trained staff should operate it.","principle":"saf.doc-untrained-operators"}]},{"id":"check","text":"Before each use, check the cord, plug and switches for damage.","fine":"A check before each use catches damage before it hurts someone.","bad":[{"id":"check-skip","level":"beginner","text":"Skip the damage check if {powered|the} was already used earlier today.","why":"Damage can happen during any use, so the check belongs before every use.","principle":"saf.doc-precheck-every-use"}]},{"id":"damage","text":"If you find damage, switch it off, tag it out of service, and tell {lead|the}.","fine":"Tagging out and reporting keeps damaged equipment from being used.","bad":[{"id":"damage-finish","level":"beginner","text":"If you find damage, finish your current job first, then tell {lead|the}.","why":"Using equipment you know is damaged puts you at risk. It comes out of service as soon as damage is found.","principle":"saf.doc-stop-on-damage"}]},{"id":"hands","text":"Keep hands clear of moving parts while it is running.","fine":"Distance from moving parts prevents caught or cut hands.","bad":[{"id":"hands-jam","level":"beginner","text":"Reach in to clear small jams while it is running to save time.","why":"Reaching into running equipment is how hands get caught. It must be stopped and unplugged first.","principle":"saf.doc-no-reaching-in"}]},{"id":"unplug","text":"Unplug it before cleaning it or clearing a jam.","fine":"Unplugging removes power completely while hands are near the parts.","bad":[{"id":"unplug-switch","level":"intermediate","text":"Turning the switch off is enough before cleaning; unplugging is optional.","why":"A switch can be bumped back on. Unplugging removes power completely while your hands are near the parts.","principle":"saf.doc-unplug-not-switch"}]},{"id":"spark","text":"Report any shock, spark or burning smell to {lead|the} right away.","fine":"Sparks and burning smells signal a fault that needs action now.","bad":[{"id":"spark-log","level":"intermediate","text":"Write down any sparks or burning smells in the log at the end of the shift.","why":"A spark or burning smell is an electrical fault happening now. Waiting until the end of the shift leaves it in use.","principle":"saf.doc-report-fault-now"}]},{"id":"new","text":"New staff watch a trained coworker complete a job before their own training session.","fine":"Watching first is a reasonable part of training, as long as the training itself is completed.","bad":[{"id":"new-alone","level":"advanced","needs":["who"],"text":"New staff may run it on their own after watching a coworker complete one job.","why":"This contradicts the rule that only trained staff may operate it. Watching one job is not training.","principle":"saf.doc-contradicts-training-rule"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","safe-procedures-only"],"notes":"Training requirement is stated as a posted workplace rule. Actions follow common tag-out-and-report practice; no regulatory claims."}},{"id":"saf-chemical-task","skill":"workplace-safety","family":"workplace-safety.cx-chemical-cleaning","familyName":"Cleaning with a workplace chemical","framework":"safest-action","concepts":["workplace-safety:safety-data-sheets","workplace-safety:ppe","workplace-safety:emergency-protocols","workplace-safety:universal-precautions"],"contexts":"any","requires":["chemical","ppe","area"],"setup":["You work as {role|a} at {workplace|a}. {Lead|the} asks you to clean the {area} with {chemical|the}.","As {role|a} at {workplace|a}, your next task is cleaning the {area} with {chemical|the}."],"pressure":["{coworker3} says the area has to be ready in ten minutes.","{coworker3} says everyone skips the gear for quick jobs."],"detail":["The {area} is empty right now.","The cleaning cart is already stocked with rags."],"tiers":{"1":"Someone who has been exposed to a chemical needs help before anything else.","2":"The protective gear the label calls for goes on before the chemical is opened.","3":"You cannot use a product safely if you do not know what it is.","4":"Read the safety information for an unfamiliar chemical before using it.","5":"Running low on supplies can be reported once the job is done safely."},"issues":[{"id":"splash","tier":1,"rule":"emergency-response","principle":"saf.eyewash-and-alert","fact":["{coworker} just splashed {chemical|the} near the eyes and is rubbing them."],"short":"{coworker}'s chemical splash","action":"Get {coworker} to the eyewash station and alert {lead|the} right away.","brief":"get {coworker} to the eyewash and alert {lead|the}","reason":"Chemical in the eyes needs flushing immediately. Getting help fast limits the injury.","lesson":"When someone is exposed to a chemical, start first aid and get help immediately.","shortcut":[{"text":"Hand {coworker} a dry towel and finish cleaning before checking in.","brief":"hand over a towel and keep cleaning","why":"A towel does not flush the chemical out, and waiting lets the injury get worse.","mis":"A minor splash can wait until the job is done."}]},{"id":"gear","tier":2,"rule":"wear-required-gear","principle":"saf.ppe-before-chemical","fact":["The label on {chemical|the} calls for {ppe}, and the supply bin for them is empty."],"clear":["{Lead|the} restocked {ppe} in the supply bin this morning, and you have them on."],"done":"you already have the required gear on","short":"the missing protective gear","action":"Get {ppe} from {lead|the} or the supply room before opening it.","brief":"get the protective gear","reason":"The label lists the gear because the chemical can harm skin or eyes. The gear goes on before the bottle is opened.","lesson":"Wear the protective gear a chemical's label calls for before you use it.","shortcut":[{"text":"Work quickly without the gear so your contact time is short.","brief":"work quickly without gear","why":"A short contact time does not prevent burns or splashes. The gear is required.","mis":"Working fast makes protection unnecessary."}]},{"id":"unlabeled","tier":3,"rule":"identify-before-use","principle":"saf.no-unlabeled-chemicals","fact":["The spray bottle you were handed has no label, and {coworker2} thinks it holds {chemical|the}."],"clear":["{Lead|the} labeled the bottle and confirmed it holds {chemical|the}."],"done":"the bottle was already labeled and confirmed","short":"the unlabeled bottle","action":"Set the unlabeled bottle aside and ask {lead|the} to identify it.","brief":"set it aside and have it identified","reason":"Without a label, you cannot know the contents or the right precautions. Using it on a guess risks the wrong protection or a dangerous mix.","lesson":"Never use a chemical from an unlabeled container.","shortcut":[{"text":"Smell the bottle to check whether it really is {chemical|the}.","brief":"smell it to check","why":"Smelling an unknown chemical can harm you and does not reliably identify it.","mis":"You can identify chemicals by their smell."}]},{"id":"sds","tier":4,"rule":"read-safety-information","principle":"saf.read-sds-before-first-use","fact":["You have never used {chemical|the} before and do not know its hazards."],"clear":["You reviewed the safety data sheet for {chemical|the} during training last week."],"done":"you already reviewed the safety data sheet","short":"not knowing the chemical's hazards","action":"Read the safety data sheet for {chemical|the} before you start.","brief":"read the safety data sheet","reason":"The safety data sheet explains the hazards, the protection needed and what to do in an emergency.","lesson":"Read the safety data sheet before using an unfamiliar chemical.","shortcut":[{"text":"Ask {coworker3} how they use it and skip the safety data sheet.","brief":"ask a coworker instead","why":"A coworker's habit may skip precautions. The safety data sheet is the reliable source.","mis":"Experience replaces the safety data sheet."}]},{"id":"low","tier":5,"rule":"report-after","principle":"saf.report-low-supply","noProceed":true,"fact":["The bottle of {chemical|the} is almost empty, and there is no backup on the shelf."],"short":"the nearly empty bottle","action":"Finish the job safely, then tell {lead|the} the chemical needs restocking.","brief":"finish safely, then report the low stock","reason":"Reporting low stock keeps the next person from running out. It does not need to interrupt safe work.","lesson":"Report low safety and cleaning supplies so they get restocked.","shortcut":[{"text":"Water down what is left so it lasts longer.","brief":"water it down to stretch it","why":"Changing the strength can make the chemical ineffective or unsafe; the label sets the mix.","mis":"Diluting a cleaner just makes it last longer."}]}],"proceed":{"text":"Put on {ppe} and clean following the label directions.","why":"The chemical is identified, its hazards are known and the gear is ready, so the job can go ahead.","lesson":"Use chemicals only with the label's directions and the gear it calls for."},"generic":[{"text":"Mix {chemical|the} with another cleaner so it works faster.","why":"Mixing chemicals can create dangerous fumes. Never mix products unless the label says to.","mis":"Two cleaners together work better."},{"text":"Leave the cleaning for the next shift without telling anyone.","why":"Leaving the job undone without telling anyone hands the problem to someone who does not know about it.","mis":"Unfinished work explains itself."}],"overcaution":[{"text":"Wait for {lead|the} to watch you do the whole cleaning.","why":"Everything checks out, so waiting for supervision only delays a job you are ready to do.","mis":"Supervision makes every job safer."}],"process":{"setup":["You are {role|a} at {workplace|a}, about to clean the {area} with {chemical|the}."],"because":{"unlabeled":["The bottle you were given has no label."],"sds":["This is the first time you will use this product."],"gear":["The protective gear bin is empty."]},"steps":[{"id":"ident","text":"Have {lead|the} identify the bottle","issue":"unlabeled"},{"id":"read","text":"Read the safety data sheet","issue":"sds"},{"id":"get","text":"Collect the protective gear from the supply room","issue":"gear"},{"id":"wear","text":"Put on {ppe}","core":true},{"id":"clean","text":"Clean the surfaces as the label directs","core":true},{"id":"store","text":"Close and store the bottle, then wash your hands","core":true}],"rel":[["ident","read","You need to know the product before you can find its safety data sheet."],["ident","clean","An unidentified product is never used."],["read","wear","The safety data sheet tells you which gear to wear."],["get","wear","You need the gear before putting it on."],["wear","clean","Gear goes on before the chemical is used."],["clean","store","Store and wash up after cleaning."]],"alternatesReviewed":true,"lesson":"Identify, read, gear up, clean, then store and wash up."},"doc":{"type":"procedure","title":["Chemical safety rules for the {area}"],"intro":["You are reviewing these posted chemical rules before they are reprinted."],"lesson":"Chemical rules protect people only when every line matches the label and safety data sheet.","lines":[{"id":"read","text":"Read the label and safety data sheet before using a new chemical.","fine":"Knowing the hazards comes first.","bad":[{"id":"read-spill","level":"beginner","text":"You only need the safety data sheet if a chemical spills.","why":"The safety data sheet is for before use, not just emergencies.","principle":"saf.doc-sds-only-for-spills"}]},{"id":"gear","text":"Wear {ppe} whenever you handle {chemical|the}.","fine":"Required gear stated plainly.","bad":[{"id":"gear-quick","level":"beginner","text":"Gear is optional for jobs that take under five minutes.","why":"Injuries can happen in seconds; the gear is always required.","principle":"saf.doc-gear-optional"}]},{"id":"mix","text":"Never mix {chemical|the} with other products.","fine":"Prevents dangerous reactions.","bad":[{"id":"mix-bleach","level":"beginner","text":"Mix {chemical|the} with bleach for tough stains.","why":"Mixing chemicals can release dangerous gases.","principle":"saf.doc-mix-chemicals"}]},{"id":"label","text":"Keep every container labeled with what is inside.","fine":"Labels prevent mix-ups.","bad":[{"id":"label-reuse","level":"intermediate","text":"Pour leftovers into any empty bottle to use later.","why":"Unlabeled or wrongly labeled containers lead to dangerous mistakes.","principle":"saf.doc-unlabeled-container"}]},{"id":"eyes","text":"If a chemical gets in someone's eyes, use the eyewash station and alert {lead|the}.","fine":"Correct first response.","bad":[{"id":"eyes-rest","level":"intermediate","text":"If a chemical gets in someone's eyes, have them rest until it stops stinging.","why":"Eyes need flushing right away; resting lets the chemical keep causing harm.","principle":"saf.doc-wrong-eye-first-aid"}]},{"id":"where","text":"Safety data sheets are kept in the binder by the door.","fine":"Tells workers where to find them.","bad":[{"id":"where-locked","level":"advanced","needs":["read"],"text":"Safety data sheets are kept locked in {lead|the}'s office.","why":"Workers must read the sheet before use, so it has to be where they can reach it.","principle":"saf.doc-sds-inaccessible"}]}]},"review":{"status":"approved","checks":["no-jurisdiction-claims","policy-stated-in-scenario","safe-procedures-only"],"notes":"Follows label and SDS guidance; no regulatory claims. Eyewash response stated as general first aid."}}]}; }(typeof self !== "undefined" ? self : this));
